export default [{"id":3,"question":"أولًا: أرجو منك أن تدعو لي بالفقه في الدين.ثانيًا: في بعض الأحيان أُصلي في الغرفة، فإذا حضر عندي بعضُ الزملاء يلومونني على ذلك، ويُريدون أن أُصلي بحيث لا يراني أحدٌ، فأرجو منك التَّوضيح؟","title":"هل الأفضل صلاة النافلة خفيةً عن الناس؟","answer":"الجواب: أولًا: رزقنا الله وإياك الفقه في الدين، وأصلح لنا جميعًا القلوب والأعمال، يقول النبيُّ ﷺ: مَن يُرد الله به خيرًا يُفقهه في الدين، فمَن رزقه الله الفقهَ في الدين فقد أراد به خيرًا، وهذا يحتاج إلى طلبٍ وجدٍّ ونشاطٍ، وسؤال الله التَّوفيق سبحانه وتعالى، وإلى العمل بالعلم.\nأما الصلاة في الغرفة: فإن كانت نافلةً؛ فالحمد لله أمرها واسع، تُصلي في غرفتك، وإذا كان وحدك ما عندك أحدٌ يكون أحسن وأكمل في الإخلاص، فإذا جاء عندك أحدٌ فليكن الحديثُ معه والمُذاكرة، فإذا ذهب الناسُ فاحمد ربَّك واجتهد في العبادة: من القراءة، والصلاة، وغير ذلك.\nأما الفريضة: فالواجب عليك أن تحضرها مع المسلمين، وليس لك أن تُصلي وحدك، لا في الغرفة، ولا في غيرها، بل يجب عليك أن تُصلي مع جماعة المسلمين، وأن تُجيب: حيَّ على الصلاة، حيَّ على الفلاح، كما قال النبيُّ ﷺ: مَن سمع النِّداء فلم يأتِ فلا صلاةَ له إلَّا من عذرٍ أخرجه ابن ماجه، والدَّارقطني، وابن حبان، والحاكم بإسنادٍ على شرط مسلم.\nوقال عليه الصلاة والسلام للأعمى الذي قال له: يا رسول الله، ليس لي قائدٌ يُلائمني إلى المسجد، فهل لي من رخصةٍ أن أُصلي في بيتي؟ فقال له عليه الصلاة والسلام: هل تسمع النِّداء بالصلاة؟ قال: نعم، قال: فأجب، هذا يدل على وجوب الإجابة والصلاة مع المسلمين، وتحريم التأخُّر عن صلاة الجماعة، لا في الحجرة، ولا في غير الحجرة.\nوقد همَّ ﷺ أن يحرق على المُتخلِّفين بيوتهم كما في \"الصحيحين\".\nوقال عبدُالله بن مسعودٍ : \"مَن سرَّه أن يلقى الله غدًا مسلمًا فليُحافظ على هؤلاء الصَّلوات الخمس حيث يُنادَى بهنَّ، فإنَّ الله شرع لنبيه سننَ الهدى، وإنهن من سنن الهدى، ولو أنَّكم صليتُم في بيوتكم كما يُصلي هذا المُتخلِّف في بيته لتركتم سنةَ نبيكم، ولو تركتم سنةَ نبيكم لضللتم -وفي لفظٍ: لكفرتم- ولقد رأيتنا وما يتخلَّف عنها –يعني: الصلاة في جماعةٍ- إلا منافقٌ معلوم النِّفاق\".\nهذا يدل على أنَّ التَّخلف عن الجماعة من دلائل النِّفاق ولا حول ولا قوة إلا بالله، فيجب الحذر من صفات المُنافقين، ويجب الاجتهاد في التَّخلق بأخلاق المؤمنين فيما أوجب الله عليهم.","link":"https://binbaz.org.sa/fatwas/2748/هل-الافضل-صلاة-النافلة-خفية-عن-الناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0253.mp3","categories":["صلاة التطوع"]},{"id":633,"question":"الركعتين عند الإحرام سُنة؟","title":"ما حكم الركعتين عند الإحرام؟","answer":"الجواب: إذا توضأ صلى ركعتي الوضوء. أما الجمهور: يرون أنها سُنة مطلقًا، لكن الأفضل أنه إذا توضأ يصلي ركعتين سنة الوضوء.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6520/ما-حكم-الركعتين-عند-الاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/maram201 - 03 - .mp3","categories":["صلاة التطوع","الإحرام"]},{"id":657,"question":"هل صلاة ركعتين بعد القدوم من السفر من ذوات الأسباب، وهل تصلى وقت النهي وهل يوافق من صلاها في المنزل أم يلزم في المسجد فقط؟","title":"حكم صلاة ركعتين عند القدوم من السفر","answer":"الجواب: السنة أن يصليها في المسجد إذا قدم،  يقصد واحدًا من المساجد ويصلي ركعتين، والأقرب أنه إذا صادف بعد العصر أنها من ذوات الأسباب. لكن النبي ﷺ كان يقدم ضحى، إذا تيسر له ضحى أو في الليل يكون أحسن أو في الظهر، وإذا لم يتيسر ذلك إلا بعد صلاة العصر فالظاهر أنها من ذوات الأسباب.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6688/حكم-صلاة-ركعتين-عند-القدوم-من-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/maram226 - 01 -  Start.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":734,"question":"هل يجوز التَّنفل في صورة الفرض في الصلاة: كأن يُصلي قبل العصر أربعًا على صورة الفرض، أي: بتشهدين وسلام واحد، أو بتشهدٍ واحد، سواء كان ذلك بالليل أو بالنهار؟ نرجو ذكر الدليل على الجواز أو المنع.","title":"حكم التنفل بأكثر من ركعتين بسلام واحد","answer":"الجواب: المشروع للمؤمن أن يُصلي ثنتين ثنتين في الليل والنهار، هكذا كان النبيُّ يفعل عليه الصلاة  والسلام، وقال عليه الصلاة والسلام: صلاة الليل مثنى مثنى متفق على صحَّته، وفي اللفظ الآخر قال: صلاة الليل والنهار مثنى مثنى رواه الإمام أحمد وأهل السنن بإسنادٍ صحيحٍ، فذكر الليل والنهار جميعًا، وكانت عادته أن يُصلي ثنتين ثنتين عليه الصلاة والسلام، في الليل والنهار، فهذا هو المشروع.\nوقد أجاز بعضُ أهل العلم أن يُصلي أربعًا جميعًا في النهار، ولكن الصواب والذي دلَّت عليه السنة: أنَّ الصلاة مثنى مثنى في النافلة، مثنى مثنى في الليل والنهار، هذا هو المشروع، وفي الليل لا يجوز؛ لأن الأحاديث ثابتةٌ لا مطعنَ فيها: صلاة الليل مثنى مثنى متفق على صحته، لكن يجوز في الليل أن يسرد ثلاثًا بتسليمٍ واحدٍ، وقعدةٍ واحدةٍ، ويجوز أن يسرد خمسًا بقعدةٍ واحدةٍ وسلامٍ واحدٍ لا بأس، وتر، أما أن يُصلي أربعًا جميعًا أو ستًّا جميعًا أو ثمان جميعًا ويُسلِّم منها؛ فهذا لم يرد في السنة.\nوينبغي للمؤمن أن يتقيد بالسنة، ويُصلي مثنى مثنى، إلا إذا أوتر بثلاثٍ أو خمسٍ أو سبعٍ أو تسعٍ جميع فلا بأس، كما فعله النبيُّ ﷺ، لكن إذا أوتر بسبعٍ جلس في السادسة وتشهد التَّشهد الأول، ثم قام إلى السابعة، وإن أوتر بتسعٍ جلس في الثامنة للتَّشهد الأول، وقام للتاسعة، هذا جاء في الوتر خاصةً، وإن سرد السبع كالخمس ولم يجلس إلا في الأخيرة فلا بأس، جاء هذا وهذا عن النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/20607/حكم-التنفل-باكثر-من-ركعتين-بسلام-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0545حكم التنفل في صورة الفرض في الصلاة فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":829,"question":"ما حكم تحيَّة المسجد؟ وما الصيغة الصحيحة التي وردت عن رسول الله ﷺ في الصلاة والسلام عليه؟","title":"حكم تحية المسجد وصيغة الصلاة والتسليم","answer":"الجواب: تحيَّة المسجد سنة مؤكدة في جميع الأوقات، حتى في أوقات النَّهي على الصحيح، مَن دخل بعد العصر أو بعد الصبح فليس له أن يجلس حتى يُؤدي هاتين الركعتين، هذه هي السنة، إذا كان على طهارةٍ.\nأما صيغة الصلاة على النبي ﷺ: فهذه معروفة في الأحاديث، اقرأها عند قوله جلَّ وعلا: إِنَّ اللَّهَ وَمَلَائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56]، وكذلك في الأحاديث الواردة في الصلاة، فقد ذكرها أهلُ العلم وبسطوها: حديث كعب بن عجرة، وحديث أبي هريرة، وحديث أبي حميدٍ السَّاعدي، وحديث أبي مسعودٍ الأنصاري، أجمعها: اللهم صلِّ على محمدٍ وعلى آل محمدٍ، كما صليتَ على إبراهيم وعلى آل إبراهيم، إنك حميدٌ مجيدٌ، اللهم بارك على محمدٍ وعلى آل محمدٍ، كما باركتَ على إبراهيم وعلى آل إبراهيم، إنك حميدٌ مجيدٌ، وجاء في بعض الروايات ما هو أنقص من هذا.\nفإذا صلَّى المؤمنُ بنوعٍ منها مما صحَّ عن النبي ﷺ فقد حصل المطلوبُ، وكان هذا في الصلاة وخارجها، لكن في الصلاة يجب أن تُؤدى هذه الصلاة في التشهد الأخير عند جمعٍ من أهل العلم، وقال آخرون أنها سنة، والقول بأنها واجبة قولٌ قويٌّ؛ لأن الرسول أمر بذلك عليه الصلاة والسلام في التشهد الأخير قبل الدعاء، ثم يدعو بعد ذلك: يستعيذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال، ويدعو بما تيسَّر، ثم يُسلِّم، أما التشهد الأول فليست واجبةً فيه.\nواختلف أهل العلم: هل تُشرع أم لا تُشرع في التَّشهد الأول؟\nوالأرجح أنها تُشرع، الأرجح أنه يُستحب له أن يُصلي في التشهد الأول، ثم ينهض إلى الثالثة قبل الدعاء، وإذا اختصرها كما يختصرها في الحديث: في ذكر النبي ﷺ، وعند ذكر الأحاديث: ﷺ، اللهم صلِّ عليه وسلّم، عليه الصلاة والسلام، فلا بأس بذلك؛ لحصول المقصود من قوله جلَّ وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56]، وإن أتى بها كاملةً كما جاء في الأحاديث كان ذلك أكمل، ولكن لتردد ذكر النبي ﷺ في الأحاديث عند الرواية يختصر الناس على أقلِّها لاختصار الوقت.","link":"https://binbaz.org.sa/fatwas/20862/حكم-تحية-المسجد-وصيغة-الصلاة-والتسليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0657حكم تحية المسجد؟وماهي الصيغة الصحيحة في الصلاة والسلام على النبي صلى الله وعليه وسلم؟ ابن باز.mp3","categories":["الأدعية والأذكار","صلاة التطوع"]},{"id":1020,"question":"ما جزاء تارك السنة بعد الصلاة؟","title":"ما النصيحة لمن يترك السُّنَن بعد الصلاة؟","answer":"الجواب: السنة نافلة ما هي فريضة، فإذا صلَّى الفرائض فليس عليه شيءٌ، لو أنَّ إنسانًا يُصلي الظهر فقط، والعصر فقط، والمغرب فقط، والعشاء فقط، والفجر فقط، ولم يُصلِّ النوافلَ فلا شيء عليه، لكنه ترك خيرًا عظيمًا، وترك سُننًا عظيمةً، فيها خيرٌ عظيمٌ يُؤجره الله عليها، وتجبر ما قد يقع من نقصٍ في فرائضه، لكن ليس عليه إثمٌ.\nوالأفضل أن يُصلي مع هذه الفرائض اثنتي عشرة ركعة، كان يُحافظ عليها النبيُّ ﷺ نافلةً، وهي: أربعٌ قبل الظهر بتسليمتين، وثنتان بعد الظهر، وثنتان بعد المغرب، وثنتان بعد العشاء، وثنتان قبل صلاة الفجر، هذه يُقال لها: السنن الرَّواتب، اثنتا عشرة ركعة. والوتر أقلّه واحدة بعد العشاء، أو في آخر الليل، أو في وسط الليل، بعد العشاء إلى آخر الليل، واحدة، وإن زاد فهو أفضل، إن أوتر بثلاثٍ أو بخمسٍ أو بسبعٍ، وأفضل ذلك إحدى عشرة أو ثلاث عشرة، وإن زاد فأوتر بأكثر من ذلك ولو بمئةٍ فلا بأس عليه؛ لأن الليل كله محلُّ عبادةٍ، لكن يُصلي مثنى مثنى، ويُوتر بواحدةٍ كما قال عليه الصلاة والسلام: صلاة الليل مثنى مثنى، فإذا خشي أحدُكم الصبحَ صلَّى ركعةً واحدةً تُوتر له ما قد صلَّى، فيُصلي ما تيسر: ثنتين، ثنتين، ثم يُوتر بواحدةٍ قبل الصُّبح.","link":"https://binbaz.org.sa/fatwas/21056/ما-النصيحة-لمن-يترك-السنن-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0852ما جزاء تارك السنة بعد الصلاة؟ ابن باز فتاوى المحاضرات.mp3","categories":["صلاة التطوع","نصائح وتوجيهات"]},{"id":1170,"question":"إذا أخذ الإنسانَ النومُ فتأخَّر عن صلاة الفجر، هل يُصلي السنة الراتبة قبل الفريضة أم العكس؟","title":"هل يبدأ بالراتبة من فاتته صلاة الفجر؟","answer":"الجواب:\nنعم، يُصلي السنة الراتبة إذا ما استيقظ إلا بطلوع الشمس يُصلي السنة الراتبة ثم يُصلي الفريضة، النبيُّ ﷺ لما نام عن الصلاة في بعض أسفاره ولم يستيقظ إلا بعد أن مسَّهم حرُّ الشمس، استيقظوا، فصلَّى كما كان يُصلي، أمر بالأذان وصلَّى السنة الراتبة، وصلَّى صلاة الفريضة، وجهر فيها كما كان يُصليها في وقتها عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/21226/هل-يبدا-بالراتبة-من-فاتته-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1168إذا فاتت صلاة الفجر هل يصلي سنة الفجر قبل أم بعد؟ ابن باز فتاوى.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":1381,"question":"هل يُسَنُّ المداومة على ركعتي الضحى؟","title":"هل صلاة الضحى سُنَّة مؤكَّدة؟","answer":"الجواب:\nنعم المداومة عليها سُنَّة، والنبي ﷺ أوصى بها أبا هريرة وأبا الدرداء وغيرهما.\nس: سُنَّة مؤكَّدة؟\nج: نعم سُنَّة مؤكَّدة.\nس: من قوله ﷺ؟\nج: سُنة من قوله ﷺ وفعلها بعض الأحيان، ولكن أوصى بها وأكّد عليها عليه الصلاة والسلام، ولعله ترك المواظبة عليها لئلا يشق على أمته، تقول عائشة كما في بعض ما رواه مسلم: كان يصلي الضحى أربعًا ويزيد ما شاء الله، وفي بعض الروايات عنها أنها ما رأته يصليها إلا أن يجيء من مَغِيبِه.\nس: ما ورد شيء في قراءتها؟\nج: لا، ما تيسر.\nس: ضبطها مِن متى إلى متى؟\nج: من ارتفاع الشمس إلى وقوف الشمس، كله ضحى.","link":"https://binbaz.org.sa/fatwas/21474/هل-صلاة-الضحى-سنة-موكدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في صلاة الضحى.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":1400,"question":"شاب عمره سبعة عشر يقول لا أستطيع أن أقوم الليل إلا جالسًا؟","title":"ما حكم الصلاة نافلة جالساً؟","answer":"الجواب:\nيصلي جالسًا، النبي ﷺ كان يصلي جالسًا في آخر حياته ﷺ، والنافلة يجوز أن تصلي جالسًا، لكن على النصف، إذا كان مع القدرة يكون على النصف، وأما مع العجز أجر كامل.\nس: إذا كان يستطيع لكن مع اعتماده على شيء؟\nج: كذلك يعتمد، في الفريضة المريض يعتمد ويقوم.\nس: هل يكون تركها أولى في النافلة، أحسن الله إليك؟\nج: في النافلة لا يتكلَّف، يصلي على الأريح له وأكثر شوقًا للعبادة والرغبة فيها.","link":"https://binbaz.org.sa/fatwas/21493/ما-حكم-الصلاة-نافلة-جالسا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصلاة نافلة جالساً.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":1403,"question":"قدم إلى المسجد في حلقة ذكر بعد صلاة الفجر هل يصلي التحية أفضل أم يجلس؟","title":"حكم تحية المسجد لمن دخله لحلقة بعد الفجر؟","answer":"الجواب:\nيصلي التحية ثم يجلس، مثل لو جاء والإمام يخطب خطبة الجمعة يصلي التحية ثم يجلس، كذلك إذا جاء وفي المسجد حلقة علم يصلي التحية ثم يجلس في الحلقة.\nس: أليس وقت نهي؟\nج: ولو في وقت النهي، تحية المسجد تُفعل في كل وقت.","link":"https://binbaz.org.sa/fatwas/21496/حكم-تحية-المسجد-لمن-دخله-لحلقة-بعد-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من أتى إلى المسجد بعد صلاة الفجر في حلقة ذكر هل يصلي تحية المسجد أو يجلس.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":1551,"question":"السنة في العصر يا شيخ؟","title":"حكم المداومة على صلاة أربع قبل العصر","answer":"الجواب:\nالأفضل أن يُصلِّي أربعًا قبلها: رحم الله امرءًا صلَّى أربعًا قبل العصر.\nس: هل على سبيل الدوام أم على سبيل..؟\nج: إذا داوم كان أفضل؛ حتى تحصل له الرحمة رحم الله امرءًا صلَّى أربعًا قبل العصر.\nس: إذن يُداوم عليها؟\nج: إذا تيسَّر، مستحب.","link":"https://binbaz.org.sa/fatwas/21652/حكم-المداومة-على-صلاة-اربع-قبل-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المداومة على صلاة أربع قبل العصر.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":1610,"question":"رجلٌ ما صلَّى السُّنن الرواتب قبل الظهر، فصلاهم بعد الظهر، فيقول: هل...؟","title":"هل يُشرع قضاءُ السُّنَن القبلية بعد الفرض؟","answer":"الجواب:\nيُصليها بعد الظهر، كان النبيُّ ﷺ إذا لم يُصلها قبلُ صلَّاها بعد، يُصلي راتبة الظهر التي قبلها والتي بعدها.","link":"https://binbaz.org.sa/fatwas/21714/هل-يشرع-قضاء-السنن-القبلية-بعد-الفرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فاتته السنن القبلية قبل الفريضة فهل له أن يصليها بعد الفريضة.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":1800,"question":"إطالة النافلة في المسجد ما رأيك فيها؟","title":"ما حكم إطالة النافلة في المسجد؟","answer":"الجواب:\nما فيه بأس، إذا رأى المصلحة في ذلك ونشط عليها فلا بأس، لا يهم، لكن يكون مخلصًا لله، والحمد لله.","link":"https://binbaz.org.sa/fatwas/21908/ما-حكم-اطالة-النافلة-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم إطالة النافلة في المسجد.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":1844,"question":"الذي يدخل كل يوم المنزل ويُصلي ركعتين باستمرار، هل هذا من البدعة؟","title":"حكم اعتياد صلاة ركعتين عند دخول المنزل","answer":"الجواب:\nيُصلِّي مئة ركعة في البيت أو ألفًا، ما يُخالف.\nس: يعني ليس من البدعة؟\nج: لا، يُصلي ما شاء ويُكثر، لكن ما هو بعد العصر، ولا بعد الفجر، ما هو في أوقات النَّهي.  بعد ارتفاع الشمس وقبل العصر والضحى والظهر والليل كله.","link":"https://binbaz.org.sa/fatwas/21953/حكم-اعتياد-صلاة-ركعتين-عند-دخول-المنزل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اعتاد على أن يدخل كل يوم المنزل ويُصلي ركعتين باستمرار.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":1991,"question":"إذا بقي عليه ركعة من الراتبة يقطعها؟","title":"ماذا يفعل مَنْ يصلي الراتبة وأقيمت الصلاة؟","answer":"الجواب:\nيقطعها نعم، إلا إذا كان قد ركع الركوع الثاني، انتهت.\nس: بعضهم يقول أن الرسول ﷺ يقول: فلا صلاة ولم يقل: \"ولا بعض صلاة\" وهو في بعض الصلاة؟\nالشيخ: الركعة تسمى صلاة.","link":"https://binbaz.org.sa/fatwas/22107/ماذا-يفعل-من-يصلي-الراتبة-واقيمت-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إذا أقيمت الصلاة فلا صلاة.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":2099,"question":"هل تُجْزِئ سنة الفجر في الضُّحى مع نية ركعتي الضُّحى؟","title":"حكم قضاء سنة الفجر في وقت الضُّحى","answer":"الجواب:\nهو مخير: إن شاء قضاها بعد صلاة الفجر، وإن شاء قضاها بعد ارتفاع الشمس.\nس: هل تكون من سنة الضُّحى؟\nج: لا، سنة الضُّحى غير سنة الفجر.","link":"https://binbaz.org.sa/fatwas/22217/حكم-قضاء-سنة-الفجر-في-وقت-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تُجْزِئ سنة الفجر في الضُّحى.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2159,"question":"الصواب في تحية المسجد بعد صلاة العصر؟","title":"حكم تحية المسجد بعد العصر وخطبة الجمعة","answer":"الجواب:\nمثل غيرها، فالنبي ﷺ قال: إذا دخل المسجدَ فلا يجلس حتى يُصلّي ركعتين.\nس: نعم، بعض الناس يقولون: ليس هذا بصواب؟\nج: بعض أهل العلم يمنعها في وقت النَّهي، لكن الصَّواب أنها جائزةٌ، مأمورٌ بها دائمًا، ولهذا لما دخل رجلٌ والإمام يخطب يوم الجمعة قال: \"قم فصلِّ ركعتين\"، والإمام يخطب.\nس: إذا دخل الشخص وجلس مباشرةً، هل عليه إثم؟\nج: يُعَلَّم ويُقال له: قم صَلِّ ركعتين، مثلما أمر النبيُّ، فقد أمر النبيُّ مَن جلس فقال: قم فصلِّ ركعتين.\nس: وإذا أبى؟\nج: إذا علَّمته السنة يكفي، ولا تُضاربه.\nس: بالنسبة لهذا السؤال: هذا الشخص إذا دخل يوم الجمعة والإمام يخطب وجلس هل أقول له: قم؟\nج: تقول له: قم، فالسنة لك يا أخي أن تُصلي ركعتين، بالكلام الطيب.\nس: ما يكون من اللغو؟\nج: إذا كان الإمام يخطب تشير له إشارةً.\nس: إشارة باليد؟\nج: نعم، ولا تتكلم، أما الخطيب فله أن يتكلم.\nس: واجبة ؟\nج: سنة مُؤَكَّدة عند العلماء.","link":"https://binbaz.org.sa/fatwas/22280/حكم-تحية-المسجد-بعد-العصر-وخطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تحية المسجد بعد صلاة العصر، والإمام يخطب يوم الجمعة.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2191,"question":"أربع ركعات بعد صلاة العصر تجوز صلاتها لفعله ﷺ تارةً، هل تجوز غيرها؟","title":"حكم التنفُّل بعد صلاة العصر","answer":"الجواب:\nلا، هذا خاص بالنبي ﷺ. رحم الله امرأً صلَّى أربعًا قبل العصر، أما بعدها فلا؛ فهذا من خصائص النبي ﷺ.\nس: وبعد هذه الأربع هل يجوز أن يتنفَّل بأي تنفُّلٍ آخر؟\nج: أربع ماذا؟\nس: التي قبل الصلاة.\nج: لو تنفَّل ليس هناك بأس، فليس المقصد النَّهي.\nس: هذا مهمومٌ اشتدَّ همُّه، فقال: أُريد أن أُصلي ركعتين بعد صلاة العصر تطبيقًا لقوله تعالى: وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلَاةِ [البقرة:45]؟\nج: لا يُصلي بعد العصر، ويمكنه أن يُصليها بعد المغرب، أو بعد العشاء، أو بعد الظهر، فهناك أوقات واسعة والحمد لله.\nس: لا تُعتبر ضرورة؟\nج: لا.","link":"https://binbaz.org.sa/fatwas/22314/حكم-التنفل-بعد-صلاة-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الأربع ركعات بعد صلاة العصر.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2395,"question":"سنة الجمعة البعدية بعد ذكر قول شيخ الإسلام أنها تُفعل بعد الصلاة في المسجد أربع ركعات وفي البيت ركعتين دليل التخصيص؟","title":"هل الأفضل لسنة الجمعة أربع ركعات مطلقًا؟","answer":"الجواب:\nلا، الأفضل أربع ركعات مطلقًا، بعضهم يستدل بأن النبي ﷺ كان يصلي في بيته ركعتين، لكن ما يدل على ترك الأربع، الأفضل أربع مطلقًا حتى في البيت؛ لأن الرسول ﷺ قال: من كان مصليًا فليصلي بعدها أربعًا، وفي الحديث الآخر: إذا صليتم الجمعة فصلوا بعدها أربعًا هذا عام يعم البيت ويعم المسجد، كون النبي ﷺ صلاها في بيته ركعتين يدل على أن الأمر مُخَفَّف مُيَسَّر، والحمد لله.","link":"https://binbaz.org.sa/fatwas/22520/هل-الافضل-لسنة-الجمعة-اربع-ركعات-مطلقا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سنة الجمعة البعدية.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":2412,"question":"سنة الجمعة البعدية الأفضل في البيت؟","title":"هل تُؤدى سُنة الجمعة البعدية في البيت؟","answer":"الجواب:\nأفضل في البيت، وإن صلاها في المسجد فلا بأس، لكن الأفضل أربع كما في الحديث الآتي: من كان مصليًا بعد الجمعة فليصل بعدها أربعًا إن صلاها في البيت فلا بأس، وإن صلاها في المسجد فلا بأس، وفي البيت أفضل، وإن صلاها في المسجد فالحمد لله الأمر واسع.","link":"https://binbaz.org.sa/fatwas/22539/هل-تودى-سنة-الجمعة-البعدية-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سنة الجمعة البعدية الأفضل في البيت.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":2413,"question":"لو خفف النافلة، لو ثقلها ما يتسع إلا لتسليمة واحدة، أقول: لو أتى قبل الظهر، والوقت يسير، لو ثقل الركعتين، ما وسع إلا الركعتين، ولو خفف لوسع الأربع، يخفف أو...؟","title":"حكم قضاء راتبة الظهر والتخفيف فيها","answer":"الجواب:\nالوقت واسع يا ولدي بعد أذان الظهر الوقت واسع.\nس: لو جاء متأخرًا؟\nالشيخ: يصلي ما تيسر، ويصلي الباقي بعد الصلاة، يكملها بعد الصلاة، يصلي ثنتين قبل الصلاة وأربعًا بعد الصلاة حتى يصير الجميع ستًّا، وإن صلى قبلها أربع وبعدها أربع فهو أفضل وأفضل، والنبي ﷺ قال: مَن حافظ على أربع قبل الظهر وأربع بعدها حَرَّمه الله تعالى على النار.\nس: هل يُخَفِّف يا شيخ أوْ لا يُخَفِّف؟\nالشيخ: التخفيف لا بأس به، التخفيف لا يضر مع الطمأنينة، وإذا قرأ بالقصار مثل: قل هو الله أحد، والعصر؛ فكله طيب، والحمد لله.","link":"https://binbaz.org.sa/fatwas/22540/حكم-قضاء-راتبة-الظهر-والتخفيف-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سنة الظهر القبلية.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2414,"question":"سنة الضحى هل يستمر عليها كل يوم؟","title":"هل يُشرع المداومة على صلاة الضحى؟","answer":"الجواب:\nدائمًا سنة، دائمة كل يوم، أقلها ركعتان ولا حد لأكثرها: أربع، ثمان، عشر، مائة، ما يخالف، أقلها ركعتان.","link":"https://binbaz.org.sa/fatwas/22541/هل-يشرع-المداومة-على-صلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المداومة على صلاة الضحى.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2415,"question":"الأفضل للإنسان أن يصلي قبل الظهر أربعًا أم ثنتين؟","title":"ما الأفضل في عدد ركعات الراتبة قبل الظهر؟","answer":"الجواب:\nأربعًا قبل الظهر راتبة، تسليمتين، هذا هو الأفضل، هذا هو الكمال كما قالت عائشة رضي الله عنها: كان النبي ﷺ لا يدع أربعًا قبل الظهر.\nس: إذا صلى ثنتين أحيانًا؟\nالشيخ: لا بأس، لكن أربع أفضل، داوم على أربع.","link":"https://binbaz.org.sa/fatwas/22542/ما-الافضل-في-عدد-ركعات-الراتبة-قبل-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة أربعًا قبل الظهر.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2416,"question":"بالنسبة لمن جلس في مصلاه ثم صلى ركعتين كتبت له حجة وعمرة، هل يصلي بعدها ثنتين سنة الضحى وإلا تكفي؟","title":"ما أفضل وقت لصلاة الضحى؟","answer":"الجواب:\nإن صلاها زيادة فلا بأس، وإن أقلها ركعتان، وإن صلى أربعًا وإلا ثمان كله طيب..... يصلي الضحى في بيته، إذا اشتد الضحى أفضل زيادة، إذا اشتد الضحى الساعة عشر وما حولها يعني قبل الظهر بساعة ساعتين أفضل، وذيك سنة الضحى أقلها ركعتان، إن صلاها الشروق تسمى سنة الضحى، ويسميها العامة سنة الإشراق.","link":"https://binbaz.org.sa/fatwas/22544/ما-افضل-وقت-لصلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أفضل وقت لصلاة الضحى.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2421,"question":"قولهم: يصلي ركعتي الفجر إذا سمع النداء. ما يذكر ترديد الأذان؟","title":"ما وقت أداء راتبة الفجر؟","answer":"الجواب:\nالأذان يعني: أذان الفجر الأخير الذي قبل الإقامة.\nس: الرسول ﷺ صلى ولم يردد خلف المؤذن؟\nالشيخ: لا، بعد الأذان بعدما يؤذن بطلوع الصبح يصليهما عليه الصلاة السلام، كان يصليهما بعد الأذان وبعد طلوع الفجر، التأكد من طلوع الصبح. أما إجابة المؤذن فهي قبل ذلك، المؤذن يُجاب، السُّنة أن يجاب المؤذن سواء في البيت أو في المسجد أو في الطريق أو في أي مكان، يجيب المؤذن، الرسول ﷺ يقول: إذا سمعتم المؤذن فقولوا مثلما يقول  سواء سمعه في المسجد أو في البيت أو في الطريق أو في السفر أو في الطائرة أو في أي مكان.","link":"https://binbaz.org.sa/fatwas/22549/ما-وقت-اداء-راتبة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/يردد الأذان أم يصلي ركعتي الفجر.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2422,"question":"بالنسبة لمن لم يتمكن من السُّنة قبل الصلاة (راتبة الفجر)؟","title":"ما الأفضل في وقت قضاء راتبة الفجر؟","answer":"الجواب:\nيصليها بعد، إذا لم يتمكن قبل الصلاة، الركعتين يصليهما بعد الصلاة أو بعد طلوع الشمس، والأفضل بعد ارتفاع الشمس.\nس: هل يأتي بالأذكار قبل؟\nالشيخ: يأتي بالأذكار قبل، الأذكار كلها قبل، لكن الأفضل أن يؤديها بعد ارتفاع الشمس.","link":"https://binbaz.org.sa/fatwas/22550/ما-الافضل-في-وقت-قضاء-راتبة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/لم يتمكن من أداء السنة قبل الصلاة.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2425,"question":"سنة الظهر القبلية لو نسيها أو تأخر عنها؟","title":"حكم مَن نَسِي سُنَّة الظهر القبلية أو تأخّر عنها","answer":"الجواب:\nيصليها بعد الظهر.\nس: يصلي ثمان بعد الظهر؟\nج: ثمان أو ست اللي تيسر.\nس: تنتفي بالسفر؟\nج: تسقط بالسفر أفضل.\nس: هناك من أفتى أنها تُقضى بعد صلاة العصر؟\nج: لا، الصواب ما تقضى؛ لأن الرسول ﷺ سُئل عن ذلك فقال: لا.\nس: قال فعله ﷺ؟\nج: هذا خاص به، سألته أم سلمة: أفنقضيهما إذا فاتتا؟ قال: لا.\nس: يعني هذا نص؟\nج: خاص به عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/22553/حكم-من-نسي-سنة-الظهر-القبلية-او-تاخر-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم من نسي سنة الظهر القبلية أو تأخر عنها.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2426,"question":"من صلى الأربع بتسليمة واحدة؟","title":"حكم صلاة النافلة الرباعية بتسليمة واحدة","answer":"الجواب:\nما ينبغي، يقول ﷺ: صلاة الليل والنهار مثنى مثنى يعني ثنتين ثنتين، هذا كالأمر.\nس: وصلاته صحيحة؟\nج: إن شاء الله صحيحة؛ لأنه قول جمع من أهل العلم، بعض الروايات قد توهم ذلك، لكن السُّنة أن يتحرى ثنتين ثنتين.","link":"https://binbaz.org.sa/fatwas/22554/حكم-صلاة-النافلة-الرباعية-بتسليمة-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم صلاة الأربع بتسليمة واحدة.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2427,"question":"الأربع قبل الظهر والأربع بعد الظهر: من تكاسل عنها مرة هل يكون له هذا الفضل (الوارد فيها)؟","title":"هل يحصل فضلُ سُنَن الظهر لو تركها أحيانًا؟","answer":"الجواب:\nنافلة ما عليه شيء، هي نوافل ما عليه شيء.\nس: يكون له هذا الفضل من أنه يدخل الجنة؟\nالشيخ: الجنة معلّقة بفعل ما أوجب الله وترك ما حرم الله، المؤمن موعود بالجنة وإن لم يصل النوافل، لكن إذا صلى النوافل تكون درجته أعلى من السابقين.","link":"https://binbaz.org.sa/fatwas/22555/هل-يحصل-فضل-سنن-الظهر-لو-تركها-احيانا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تكاسل عن النوافل القبيلة والبعدية.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2440,"question":"قول أنس: كان يرانا نصليهما فلم يأمرنا ولم ينهنا (للركعتين قبل المغرب)؟","title":"معنى قول أنس في الركعتين قبل المغرب","answer":"الجواب:\nخفي عليه الأمر؛ لأنه أمر: صلوا قبل المغرب لكن خفي على أنس حديث عبدالله بن مغفل، خفي على أنس.","link":"https://binbaz.org.sa/fatwas/22569/معنى-قول-انس-في-الركعتين-قبل-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصلاة قبل المغرب ركعتين.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2442,"question":"سُنة الجمعة أيهما أفضل في البيت أو في المسجد؟","title":"هل الأفضل لسُنة الجمعة البيت أم المسجد؟","answer":"الجواب:\nالنوافل كلها في البيت أفضل، وإن صلاها في المسجد فلا بأس، كلها الأفضل في البيت، النبي ﷺ قال: أفضل صلاة المرء في بيته إلا المكتوبة.\nس: ما الفرق بين سنة الجمعة في أن يصلي في المسجد أربعًا وفي البيت ركعتين، هل هذا التفريق صحيح؟\nالشيخ: الأصل مثل ما أخبر النبي ﷺ: مَنْ كان مُصَلِّيًا بعد الجمعة فليصل بعدها أربعًا السنة أربع، هذا السنة، الكمال أربع في البيت أو في المسجد؛ لقوله ﷺ: من كان مصليا بعد الجمعة فليصل بعدها أربعًا، وفي اللفظ الآخر: إذا صليتم بعد الجمعة فصلوا بعدها أربعًا رواه مسلم.\nس: هذا الأمر يدل على الوجوب؟\nالشيخ: لا، مَنْ كان مُصَلِّيًا.","link":"https://binbaz.org.sa/fatwas/22571/هل-الافضل-لسنة-الجمعة-البيت-ام-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أين تؤدى سنة الجمعة في البيت أو في المسجد.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":2443,"question":"إذا كان الشخص في درس ثم ذهب إلى دورة المياه وعاد هل يعيد تحية المسجد؟","title":"هل يعيد تحية المسجد من خرج ثم عاد إليه؟","answer":"الجواب:\nيأتي بتحية المسجد إذا راح وتطهر وجاء، يصلي تحية المسجد، سنة الوضوء وسنة التحية جميعًا.","link":"https://binbaz.org.sa/fatwas/22572/هل-يعيد-تحية-المسجد-من-خرج-ثم-عاد-اليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/خرج من المسجد ثم عاد فهل يعيد تحية المسجد.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2448,"question":"قوله: فلْيَجْعَل لبيته نصيبًا مِنْ صلاته؟","title":"معنى حديث \"فلْيَجْعَل لبيته نصيبًا من صلاته\"","answer":"الجواب:\nسُنَّة مُسْتَحَبة، نافلة مستحبة، ولهذا قال: أفضل صلاة المرء في بيته أفضل.","link":"https://binbaz.org.sa/fatwas/22577/معنى-حديث-فليجعل-لبيته-نصيبا-من-صلاته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/فليجعل لبيته نصيبا من صلاته.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":2449,"question":"الصلاة بين الأذان والإقامة كيف تُؤدى يوم الجمعة...؟","title":"هل لصلاة الجمعة راتبة قبلها؟","answer":"الجواب:\nالجمعة ما لها راتبة قبلها، يصلي ما تيسّر قبلها، يصلي ثنتين أو أربع أو ثمان أو عشر، ما لها حد محدود، يصلي ما تيسر، أقلها ثنتان قبل الجمعة، ما لها راتبة قبلها، يصلي ما تيسر، يصلي أربع هذا الأفضل بتسليمتين.","link":"https://binbaz.org.sa/fatwas/22578/هل-لصلاة-الجمعة-راتبة-قبلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للجمعة راتبة قبلها.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":2461,"question":"هل سنة الإشراق تدخل في سنة الضحى؟","title":"هل تدخل سنة الإشراق في سنة الضحى؟","answer":"الجواب:\nنعم، تكفي عن سنة الضحى، سنة الضحى من ارتفاع الشمس قيد رمح إلى وقوف الشمس، لكن أفضلها إذا اشتد الضحى، يقول النبي ﷺ: صلاة الأوابين حين ترمض الفصال يعني حين يشتد الحر، إذا اشتد الضحى هذا أفضل، وإن بَكَّر بها فلا بأس.","link":"https://binbaz.org.sa/fatwas/22590/هل-تدخل-سنة-الاشراق-في-سنة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/سنة الإشراق تدخل في سنة الضحى.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2465,"question":"ما هو صارف الوجوب لتحية المسجد؟","title":"هل تحية المسجد واجبة أم مستحبة؟","answer":"الجواب:\nقوله ﷺ للذي سأله عن الصلوات الخمس هل علي غيرها ؟ قال: لا إلا أن تطوّع هذا حجة الجمهور.\nس: الأمر بتحية المسجد ما يكون متأخرًا عن قول الرسول ﷺ؟\nالشيخ: محتمل، على كل حال المؤمن لا يدعها، المؤمن يصليها والحمد لله، لا يدعها، لا يتساهل إذا دخل المسجد يصلي ركعتين.\nس: من خرج من المسجد ثم بعد يسير من الوقت بدا له أن يعود؟\nالشيخ: يصلي التحية، أو راح يتوضأ خرج يتوضأ يصلي ركعتين للتحية وللوضوء.\nس: لكن لو خرج بغير نية العودة ثم بدا له أن يعود؟\nالشيخ: إذا دخل يصلي ركعتين.","link":"https://binbaz.org.sa/fatwas/22594/هل-تحية-المسجد-واجبة-ام-مستحبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صارف الوجوب لتحية المسجد.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2466,"question":"(الضحى) قبل صلاة الظهر بربع ساعة، هذا آخر وقت؟","title":"ما أول وقت صلاة الضحى وآخره؟","answer":"الجواب:\nإذا زالت الشمس بدأ الوقت قبل الظهر ولو قبل الأذان، إذا زالت الشمس دخل وقت الظهر، وزوالها: ميولها إلى جهة المغرب، هذا زوالها، إن انصرفت إلى جهة المغرب هذا هو الزوال.\nس: وصلاة الإشراق؟\nالشيخ: هي صلاة الضحى مبكرة.\nس: حديث النبي ﷺ: أنه إذا صل الصبح ثم جلس يذكر الله تكتب له حجة وعمرة تامة؟\nالشيخ: هذه صلاة الضحى، صلاة الضحى مبكرة.\nس: الحديث ثابت؟\nالشيخ: لا بأس به، له طرق جيدة.","link":"https://binbaz.org.sa/fatwas/22595/ما-اول-وقت-صلاة-الضحى-واخره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أول وقت صلاة الضحى وآخره.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2467,"question":"(تحية المسجد) وقت النهي يصليها؟","title":"هل تُصلّى تحية المسجد في أوقات النهي؟","answer":"الجواب:\nولو في وقت النهي، على الصواب، الصواب ما لها وقت نهي، صلاة الكسوف كذلك ما لها وقت نهي.","link":"https://binbaz.org.sa/fatwas/22596/هل-تصلى-تحية-المسجد-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تصلى تحية المسجد في أوقات النهي.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":2468,"question":"مَن قال ببدعية المواظبة على الضحى؟","title":"حكم القول ببدعية المواظبة على الضحى","answer":"الجواب:\nما أحد يقول هذا، لكن بعض الناس يقول: تركها أفضل لأن الرسول ﷺ ما واظب عليها، ولكن الرسول شرع المواظبة عليها، أكّد عليها بقوله.","link":"https://binbaz.org.sa/fatwas/22597/حكم-القول-ببدعية-المواظبة-على-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل المواظبة على الضحى بدعة.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2497,"question":"المتنفل هل له أن يطيل السجود أكثر من إطالته للقيام؟","title":"حكم إطالة سجود النافلة أكثر من القيام؟","answer":"الجواب:\nلا، تكون صلاته معتدلة، يقول البراء: رمَقْت صلاة النبي ﷺ فوجدت قيامه فركوعه فاعتداله بعد الركوع فسجدته فجلسته بين السجدتين قريب من السواء، تكون صلاته معتدلة متقاربة.\nس: هل يُنكر على من فعل ذلك؟\nالشيخ: الأمر واسع، لا، ما في إنكار، الأمر واسع، ما في تشديد.","link":"https://binbaz.org.sa/fatwas/22627/حكم-اطالة-سجود-النافلة-اكثر-من-القيام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/إطالة السجود أكثر من إطالته للقيام.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2589,"question":"كثير من الناس يدخل يوم الجمعة والإمام يخطب ولا يصلون تحية المسجد؛ فهل للإمام أن يُنْكر...؟","title":"حكم تحية المسجد أثناء خطبة الجمعة","answer":"الجواب: لا، السُّنة يصلون، من دخل والإمام يخطب يصلي التحية، والإمام عليه أن ينبِّههم، ولهذا لما رأى النبي رجلًا دخل ولم يصل التحية قال: قم فصل ركعتين، وهو في الخطبة عليه الصلاة والسلام.\nس: لكن هم كُثر هل يُنَبّه كل واحد يدخل؟\nالشيخ: لا، يُنَبِّه بالعموم ويَعرِفون إن شاء الله..... يقول: من دخل فليصل ركعتين، من دخل المسجد فليصل ركعتين، ولو كان الإمام يخطب ينبِّههم؛ حتى يبلغ أمر الله.","link":"https://binbaz.org.sa/fatwas/22722/حكم-تحية-المسجد-اثناء-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة تحية المسجد والإمام يخطب يوم الجمعة.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":2658,"question":"هل يجوز صلاة الاستخارة بعد العصر؟","title":"هل تجوز صلاة الاستخارة بعد العصر؟","answer":"الجواب: لا، وقتها واسع، أوقات النهي لا؛ لأن وقتها واسع، صلاة الاستخارة وقتها واسع.\nس: ... لأسباب تطرأ؟\nالشيخ: إذا اضطُر إلى ذلك، إذا كان الحادث في العصر ولا يتيسر تأخيره؛ تصير مِن ذوات الأسباب.","link":"https://binbaz.org.sa/fatwas/22794/هل-تجوز-صلاة-الاستخارة-بعد-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة الاستخارة بعد العصر.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2715,"question":"ركعتان بين صلاة العشاء وصلاة التراويح، هل الأفضل الإنسان يسبح أو يصلي ركعتين؟","title":"ما الأفضل من التطوّع بين العشاء والتراويح؟","answer":"الجواب: سنة العشاء أول قبل التراويح، التهجد بعد نافلة العشاء، بعد الراتبة. يصلي العشاء ثم الراتبة ثم يتهجد في الليل التراويح أو غيرها.\nس: هل الأفضل يسبّح أو يقوم يؤدي هاتين الركعتين؟\nالشيخ: بعد ما يفرغ من الأذكار يصلي الراتبة، هذه السنة، السنة أولاً يأتي بالأذكار الشرعية، ثم يصلي الراتبة.\nس: حتى إذا تقدم الإمام وصلى التراويح؟\nالشيخ الإمام لا يتقدم إلا بعد ما يصلى الناس النافلة.","link":"https://binbaz.org.sa/fatwas/22857/ما-الافضل-من-التطوع-بين-العشاء-والتراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الأفضل التسبيه أم صلاة ركعتين بين صلاة العشاء وصلاة التراويح.mp3","categories":["صلاة التطوع","الوتر وقيام الليل"]},{"id":2857,"question":"سنة الضحى قبل الذهاب إلى العمل، أو يؤديها في العمل؟","title":"حكم أداء سنة الضحى في العمل؟","answer":"الجواب: إذا أداها قبل العمل أحسن، إذا كان بعد ارتفاع الشمس أحسن في بيته، وفي العمل يشتغل بالعمل.","link":"https://binbaz.org.sa/fatwas/23010/حكم-اداء-سنة-الضحى-في-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أداء سنة الضحى في العمل.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2913,"question":"قال: ويجزئ من ذلك ركعتان. هل هي أقَلُّها يعني؟","title":"ما أقل عدد ركعات صلاة الضحى؟","answer":"الجواب: هذا أقل شيء نعم، ولو صلى أربعًا وإلا ست وإلا ثمان وإلا عشر، كله طيب، كل الضحى محل عبادة. حديث عمرو بن عبسة قال ﷺ: إذا صليت الصبح فأمسك عن الصلاة حتى ترتفع الشمس، ثم صل فإن الصلاة مشهودة محضورة حتى تقف الشمس يعني حتى وقوف الشمس.\nس: يشرع له المداومة، أحسن الله إليك؟\nالشيخ: نعم السنة المداومة.","link":"https://binbaz.org.sa/fatwas/23069/ما-اقل-عدد-ركعات-صلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أقل صلاة الضحى ركعتين.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":2918,"question":"شخص يصلي نافلة، يقول: هل يجوز أن أرفع صوتي فيها؟","title":"حكم رفع الصوت وخفضه في النوافل","answer":"الجواب: في الليل نعم.\nس: في النهار؟\nالشيخ: لا، السنة الإخفات، صلاة النهار إخفات، إلا صلاة الفجر والجمعة.\nس: يقول أريد أن أراجع؟\nالشيخ: لا، السنة الإخفات، كان النبي ﷺ يُخْفِت في نوافل النهار.\nس: وإذا صلى مع واحد جماعة يجوز له الجهر في النهار؟\nالشيخ: لا، السنة الإخفات.","link":"https://binbaz.org.sa/fatwas/23074/حكم-رفع-الصوت-وخفضه-في-النوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/رفع الصوف في نافلة الليل والإخفات في نافلة النهار.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":3201,"question":"أفاض ابن القيم في زاد المعاد في سُنِّيَّة ركعتي الضحى، هل هي سُنّة؟","title":"هل ركعتا الضحى سُنَّة مؤكّدة؟","answer":"الجواب: سُنَّة مؤكّدة.\nس: هل تكون مستمرة أم إذا كانت غِبًّا؟\nالشيخ: مستمرة.","link":"https://binbaz.org.sa/fatwas/23364/هل-ركعتا-الضحى-سنة-موكدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ركعتي الضحى سنة مؤكدة.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":3436,"question":"لو اتخذ بعض الناس عادة إذا أراد أن يصلي الضحى دعا معه رجلًا أو رجلين؟","title":"حكم تَحَرِّي الجماعة في صلاة الضحى","answer":"الجواب: ما أعرف له أصلًا، لكن إذا صادف لا بأس. أما كونه يتحرّى ذلك ما أعرف له أصلًا، إنما زار النبي ﷺ جدة أنس فصلى بهم، وصَفَّ اليتيمُ، وأنسٌ خلفه، والعجوز مِن ورائهم، وزار عتبان لما دعاه ليتخذ مصلى فصلى في المحل الذي أراده عتبان.","link":"https://binbaz.org.sa/fatwas/23610/حكم-تحري-الجماعة-في-صلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تحري دعوة رجل، أو رجلين ليصلي معه الضحى.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":3439,"question":"هاتان الركعتان سنة لمن صلى (أي: اللتين صلاهما خُبَيْبٌ قبل موته)؟","title":"حكم الركعتين اللتين صلاهما خُبَيْبٌ قبل موته","answer":"الجواب: لا شك أنها مستحبة، يختم حياته بالصلاة؛ لأن الرسول ما أنكرها، ولم يبلغنا أنه أنكرها، فعلها خُبَيْبٌ، واشتهرت.\nس: ولمن قتل ظلمًا يا شيخ؟\nالشيخ: إذا صلى ركعتين حسن، يختم حياته بصلاة.","link":"https://binbaz.org.sa/fatwas/23614/حكم-الركعتين-اللتين-صلاهما-خبيب-قبل-موته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قول خبيب ذروني أركع ركعتين، فما حكم الركعتين.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":3455,"question":"لو أنهم رفقة فهل لهم أن يصلوا جماعة؟","title":"حكم وموضع سُنَّة القدوم من السفر","answer":"الجواب: ما أعلم مانعًا، وإن صلى كل واحد ركعتين فلا بأس، وإن صلوها جماعة فلا بأس، يعني جماعة لعارض لا أعلم حرجًا في ذلك.\nس: إذا كان القدوم بعد العصر مثلًا؟\nالشيخ: الأحوط أن يتحرى غير وقت النهي، يتحرى الضحى، أو الظهر، أو الليل، هذا هو الأحوط؛ لأنه في يده الأمر.\nس: أحسن الله إليك لو كان المسجد مغلقًا، وصلى في البيت يكون أدرك السنة؟\nالشيخ: الله أعلم.\nس: صلى في مصلاه؟\nالشيخ: لا، المسجد، السنة في المسجد.\nس: هل هذا يدل على جواز قضاء الدين في المسجد؟\nالشيخ: لا بأس به.","link":"https://binbaz.org.sa/fatwas/23632/حكم-وموضع-سنة-القدوم-من-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كان النبي إذا قدم من سفر يبدأ بالمسجد يصلي فيه ركعتين، فإذا كانوا رفقة.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":3480,"question":"لو خصّص أحد الناس مكانًا في بيته، مكانًا معينًا يتنفّل فيه دائمًا؟","title":"حكم تخصيص مكان معين في البيت للتنفّل","answer":"الجواب: لا بأس، مثل ما فعل عتبان بن مالك، وطلب من النبي ﷺ أن يصلي فيه؛ حتى يصلي فيه إذا دعت الحاجة النافلة، أو فاتته الصلاة، أو حصل مانع.","link":"https://binbaz.org.sa/fatwas/23657/حكم-تخصيص-مكان-معين-في-البيت-للتنفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تخصيص مكانا معينا في بيته يتنفل فيه دائمًا.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":3504,"question":"النوافل لا تُقضى مطلقًا...؟","title":"حكم ووقت قضاء النوافل والسنن الرواتب","answer":"الجواب: سنة الظهر لا تُقضى بعد العصر. س: بقية النوافل؟ ج: تُقضى في وقتها.  سنة الظهر قبلها تُقضى بعدها. سنة الفجر تُقضى بعدها.  سنة العشاء في الليل كله، لكن قبل نصف الليل أولى. س: من صلى العصر وذكر أنه لم يصل سنة الفجر؟ الشيخ: سُنَّةٌ فات محلها.","link":"https://binbaz.org.sa/fatwas/23684/حكم-ووقت-قضاء-النوافل-والسنن-الرواتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسائل في فوات السنة الراتبة.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":3521,"question":"الصحيح في وقت النهي بعد الفجر وبعد العصر: يبدأ بدخول الوقت والأذان، أو يبدأ بفعل الصلاة؟","title":"متى يبدأ وقت النهي بعد الفجر والعصر؟","answer":"الجواب: العصر بفعل الصلاة. والفجر بطلوع الفجر، إلا سنة الفجر.","link":"https://binbaz.org.sa/fatwas/23702/متى-يبدا-وقت-النهي-بعد-الفجر-والعصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يبدأ وقت النهي بعد الفجر وبعد العصر.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":3552,"question":"كل النوافل يجوز أن تُصلى جماعة؟","title":"هل تجوز صلاة جميع النوافل في جماعة؟","answer":"الجواب: مثل الضحى، ومثل صلاة التهجد في الليل، كلها إذا فعلها جماعة لا بأس بعض الأحيان، ما هو براتب. س: بقية النوافل إذا كانت لتعليم الأهل؟ الشيخ: ما بلغنا شيء، الرواتب يصليها وحده. س: لتعليم الأهل، هل يجوز أن يصلي معهم النوافل؟ الشيخ: لا مانع ليعلمهم.","link":"https://binbaz.org.sa/fatwas/23734/هل-تجوز-صلاة-جميع-النوافل-في-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة النوافل جماعة.mp3","categories":["صلاة التطوع","صلاة الجماعة"]},{"id":3566,"question":"صلاة النافلة أفضل في البيت مطلقًا حتى في مكة؟","title":"هل صلاة النافلة أفضل بالبيت حتى في مكة؟","answer":"الجواب: حتى في مكة، مكة كلها حرم مضاعفة الصلاة فيها، مضاعفة.\nس: ويصليها في البيت أيضاً؟\nالشيخ: نعم.\nس: هذا ما يشمل التراويح...؟\nالشيخ: هذا يعم الجميع، لكن هذا في حياته ﷺ؛ لأنه يخشى أن تفرض عليهم، فلما توفي أُمِن الفرض.","link":"https://binbaz.org.sa/fatwas/23748/هل-صلاة-النافلة-افضل-بالبيت-حتى-في-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة النافلة أفضل في البيت مطلقًا.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":3584,"question":"صلاة الاستخارة هل هي من ذوات الأسباب؟","title":"هل صلاة الاستخارة من ذوات الأسباب؟","answer":"الجواب: قد تكون بعض الأحيان، وإلا ما هي من ذوات الأسباب، قد يمكن يؤجلها إلى أوقات غير أوقات النهي؛ لأن وقتها واسع، يصليها في غير وقت النهي.","link":"https://binbaz.org.sa/fatwas/23766/هل-صلاة-الاستخارة-من-ذوات-الاسباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل صلاة الاستخارة من ذوات الأسباب.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":3607,"question":"إذا كان يصلي ويتنفل كثيرًا وبعد كل تسليمة يأتي لمكان ؟","title":"حكم الانتقال من مكان لآخر في صلاة النافلة","answer":"الجواب: ما له أصل.\nس: حديث المغيرة بن شعبة: أيعجز أحدكم إذا صلى أن يتقدم أو يتأخر أو يمنة أو يسرة؟\nالشيخ: ضعيف.\nس: فعل ابن عمر، أحسن الله إليكم؟\nالشيخ: هذا من اجتهاده.\nس: عفا الله عنك، من استدل بهذا يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا بأن الإنسان يصلي بعدة أماكن؟\nالشيخ: لا ما لها أصل، يصلي في مكانه، العبادات ما هي بالاختيار ولا الرأي، العبادات بالنصوص.\nس: الأفضل يصلي في مكانه بعد الفريضة؟\nالشيخ: في مكانه وإلا يروح بيته أفضل.","link":"https://binbaz.org.sa/fatwas/23789/حكم-الانتقال-من-مكان-لاخر-في-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الانتقال من المكان حال التنفل.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":3617,"question":"هل للإنسان أن يستمر مصليا إلى دخول الخطيب أو ...؟","title":"متى ينتهي وقت التطوع قبل خطبة الجمعة؟","answer":"الجواب: له أن يصلي مائة أو ألف حتى يدخل الخطيب، الحمد لله، محل صلاة إلى دخول الخطيب، ما في وقت نهي.","link":"https://binbaz.org.sa/fatwas/23799/متى-ينتهي-وقت-التطوع-قبل-خطبة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة التطوع قبل الجمعة.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":3628,"question":"قوله -عفا الله عنك-: والتي ينامون عنها أفضل؟","title":"ما معنى \"والتي ينامون عنها أفضل\"؟","answer":"الجواب: يعني صلاة آخر الليل أفضل، لكن جمع الناس في أول الليل أيسر عليهم أسهل عليهم.\nس: لكن ما يفهم منها عدم التجميع؟\nالشيخ: معناه أن صلاة آخر الليل لو فعلوها أفضل.","link":"https://binbaz.org.sa/fatwas/23812/ما-معنى-والتي-ينامون-عنها-افضل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/معنى والتي ينامون عنها أفضل.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":3783,"question":"في واقعنا الآن أكثر المساجد مُغلقة، فهل يُصلي في بيته؟","title":"ما السُّنة في الركعتين للقادم من السفر؟","answer":"الجواب: الظاهر حسن إن شاء الله، إذا صلَّى في بيته حسن، ما لا يُدرك كله لا يُترك جلُّه.\nس: ما تكون من ذوات الأسباب؟\nج: ما هو الظاهر.\nس: قوله \"الضُّحى\" قيد؟\nج: ما هو بقيدٍ، لو قدم الظهر أو في الليل كله واحد.\nس: ما تكون من ذوات الأسباب؟\nج: ما هو بظاهر، يعني: يستطيع أن يُؤخِّر القدوم، أو يُؤجّل القدوم، يستطيع [أن] يُؤخِّر وقت العصر، يُؤخره للمغرب، والفجر يُؤخره حتى تطلع الشمس.\nس: يعني قبل الدخول في البيت، هاتان الركعتان قبل أن يدخل بيته؟\nج: نعم، هكذا كان النبيُّ يقصد المسجد يُصلي ثم يجلس للناس عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/23980/ما-السنة-في-الركعتين-للقادم-من-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كان النبي إذا قدم من سفر ضحى دخل المسجد فصلى ركعتين، وقال ادخل، فصلِّ ركعتين.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":3969,"question":"الثماني ركعات التي صلاها الرسول ﷺ: سنة الضحى ولا صلاة الفتح؟","title":"هل صحت السُّنة في صلاة الفتح؟","answer":"الجواب: بعض أهل العلم سماها صلاة الفتح، وبعضهم قال: إنها سنة الضحى، والأقرب أنها تابعة لهذا وهذا، صلاة الضحى سنة وقربة، ويسن لمن فتح الله عليه أن يفعلها كفعله ﷺ، فعله ﷺ يفعل هذه الركعات شكرًا لله عز وجل على ما منّ به من الفتح.","link":"https://binbaz.org.sa/fatwas/24197/هل-صحت-السنة-في-صلاة-الفتح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة الفتح.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":4260,"question":"التسنُّن قبل الجمعة كم ركعة؟","title":"كم عدد ركعات التسنُّن قبل الجمعة؟","answer":"الجواب: ما في حد محدود يصلي ثنتين أو أربع أو عشر أو مئة، النبي قال: وصلى ما قُدر له، يعني ما كتب الله له.","link":"https://binbaz.org.sa/fatwas/24530/كم-عدد-ركعات-التسنن-قبل-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/التسنن قبل الجمعة.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":4263,"question":"من فاتته صلاة الضحى هل له أن يصليها بعد الظهر؟","title":"هل لمن فاتته الضحى أن يصليها بعد الظهر؟","answer":"الجواب: الظاهر أنها سنة فات محلها، لكن الظهر يصلي ما تيسر، ما هو بالضحى، بعد الظهر كله صلاة إذا صلى، صلى ما تيسر، وسنة الضحى فات محلها، الضحى كله محل صلاة بعد ارتفاع الشمس إلى وقوف الشمس، والظهر كله محل صلاة إلى أن تصلي العصر، والمغرب محل صلاة، والليل كله محل صلاة.","link":"https://binbaz.org.sa/fatwas/24533/هل-لمن-فاتته-الضحى-ان-يصليها-بعد-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من فاتته صلاة الضحى، هل له أن يصليها بعد الظهر.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":4356,"question":"حكم تغيير المكان في السنة الراتبة؟","title":"حكم تغيير المكان في السنة الراتبة","answer":"الجواب: الأمر واسع في الفريضة أو غيرها، الأمر واسع، ما في شيء ثابت.\nس: يعني ليس بسنة يا شيخ.\nج: ما في شيء ثابت.","link":"https://binbaz.org.sa/fatwas/24633/حكم-تغيير-المكان-في-السنة-الراتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تغيير المكان في السنة الراتبة.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":4473,"question":"حديث زيد بن أسلم - كان أصحابُ رسول الله ﷺ يتحدَّثون في المسجد وهم على غير وضوءٍ- ما يُحتجُّ به على أنَّ تحية المسجد ليست واجبةً؟","title":"هل تحية المسجد واجبة؟","answer":"الجواب: الجمهور على أنها غير واجبةٍ بغير هذا الدليل، في الحديث: هل عليَّ غيرها؟ قال: لا، إلا أن تطوع، والذي عليه حدث كيف يُصلي؟ معذور، أقول: المُحْدِث معذور، كيف يُصلي؟","link":"https://binbaz.org.sa/fatwas/24751/هل-تحية-المسجد-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تحية المسجد.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":4502,"question":"السنن الرواتب هل تُقضى؟","title":"هل يُشرع قضاء السنن الرواتب؟","answer":"الجواب: مع الصلاة، مع الفريضة، أما وحدها لا، لا تُقضى إلا سنة الفجر فقط، إذا فاتته سُنَّ له القضاء، أما إذا فاتته الفريضةُ مع سنتها مثل: الظهر، قضاها معها، مثل: المغرب، ومثل: العشاء.","link":"https://binbaz.org.sa/fatwas/24782/هل-يشرع-قضاء-السنن-الرواتب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تُقضى السنن الرواتب.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":4508,"question":"سنة الفجر تكون بعد الأذان الأول؟","title":"متى تؤدى سنة الفجر؟","answer":"الجواب: بعد الأخير، بعد الأذان الذي هو على طلوع الفجر.","link":"https://binbaz.org.sa/fatwas/24788/متى-تودى-سنة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى تكون سنة الفجر.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":4510,"question":"هل الأولى للإمام أن يُصلي السنة الراتبة في البيت؟","title":"هل السُّنة للإمام أن يُصلي الراتبة في البيت؟","answer":"الجواب: السنة أنه يُؤديها في البيت كما [كان] النبيُّ يفعل، يُؤديها ثم يأتي وكل النوافل كلها في البيت أفضل، كما قال النبيُّ ﷺ: أفضل صلاة المرء في البيت إلا المكتوبة، إلا النافلة التي شرع الله لها جماعة: كالتراويح، وصلاة الكسوف، والاستسقاء، هذه جماعة مشروعة تُصلَّى في الصحراء، أما النافلة التي ليس لها جماعة فالأفضل في البيت.","link":"https://binbaz.org.sa/fatwas/24790/هل-السنة-للامام-ان-يصلي-الراتبة-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل للإمام أن يُصلي السنة الراتبة في البيت.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":4585,"question":"ركعتان بعد العشاء، هي ركعتا السنة؟","title":"هل الركعتان بعد العشاء هما السنة الراتبة؟","answer":"الجواب: هذه السنة الراتبة؛ راتبة العشاء. أما الإيتار فيكون بعد ذلك، يُصلِّي ثنتين ويُوتر بواحدةٍ، أو يُصلي واحدةً فقط لا بأس، لو صلَّى بعد الراتبة ركعةً واحدةً تمَّ له الوتر، وإن زاد صلَّى ثلاثًا أو خمسًا أو أكثر زاد أجره.","link":"https://binbaz.org.sa/fatwas/24872/هل-الركعتان-بعد-العشاء-هما-السنة-الراتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المقصود بقوله في الحديث وركعتين بعد العشاء.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":4595,"question":"الركعتان اللتان تكونان بعد طلوع الشمس هل ينوي بهما الضُّحى؟","title":"ركعتا الشروق هل ينوي بهما الضُّحى؟","answer":"الجواب: ولو ما نواها هي صلاة الضُّحى، لكن إذا صلَّى ركعات أخرى إذا اشتدَّ الضحى كان أفضل، وقد صلَّى النبي ثمانِ ركعات، فإذا صلَّى ثمانٍ أو ستًّا أو أربعًا هذا أفضل.\nس: وحديث أن أجرها كحجة وعمرةٍ؟\nج: لا بأس به، طرقه جيدة.","link":"https://binbaz.org.sa/fatwas/24884/ركعتا-الشروق-هل-ينوي-بهما-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ركعتا الشروق هل ينوي بهما الضُّحى.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":4601,"question":"صلاة الوضوء من ذوات الأسباب؟","title":"هل صلاة الوضوء من ذوات الأسباب؟","answer":"الجواب: نعم، هذا هو الأقرب والله أعلم، إذا كان ما قصد ذلك، إنما توضَّأ لحاجةٍ.","link":"https://binbaz.org.sa/fatwas/24890/هل-صلاة-الوضوء-من-ذوات-الاسباب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل صلاة الوضوء من ذوات الأسباب.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":4652,"question":"صلاة ركعتين للإحرام لها أصل؟","title":"ما حكم صلاة ركعتين للإحرام؟","answer":"الجواب: ... عموم حديث: إنه أتاني آتٍ من ربي فقال: صلِّ في هذا الوادي، النبي صلَّى فيه، صلَّى الظهر وأحرم وركب في حجة الوداع، فإذا وافق فريضةً كفت الفريضة، وأما إذا كان ما هو بوقت فريضةٍ وتوضَّأ فسنة الوضوء تكفي؛ أخذًا بالعموم: صلِّ في هذا الوادي المبارك.","link":"https://binbaz.org.sa/fatwas/24942/ما-حكم-صلاة-ركعتين-للاحرام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل لصلاة ركعتين للإحرام أصل.mp3","categories":["الإحرام","صلاة التطوع"]},{"id":4731,"question":"صلاة النبي ﷺ الضُّحى في مكة وهو مسافر ألا يدل هذا على جواز صلاة النافلة مطلقًا في السفر؟","title":"هل يجوز صلاة النافلة في السفر؟","answer":"المسلم مُتَّبع، لا مبتدع، المسلم عليه الاتباع والاقتداء، النبي صلَّى الضحى يُصلي الضحى، أوتر في الليل يُوتر في الليل، تهجد في الليل في السفر يتهجد في السفر، ترك راتبة الظهر والمغرب والعشاء نترك، صلَّى راتبة الفجر نُصليها في السفر، نحن مُتَّبعون، الله جلَّ وعلا قال: قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ [آل عمران:31]، وقال سبحانه: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21]، ما فعله نفعل، وما ترك تركنا، هذه السنة.","link":"https://binbaz.org.sa/fatwas/25041/هل-يجوز-صلاة-النافلة-في-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/صلاة النبي الضُّحى في مكة وهو مسافر هل يدل على جواز صلاة النافلة مطلقًا في السفر.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":4770,"question":"من دخل المسجد وصلى الوتر ركعة تغني عن تحية المسجد؟","title":"هل يجزئ الوتر بركعة عن تحية المسجد؟","answer":"لا ما تغني، تحية المسجد ركعتين والوتر ركعة، ما يكفي، يصلي تحية المسجد ثم يصلي الوتر إن كان عليه وتر.","link":"https://binbaz.org.sa/fatwas/25132/هل-يجزى-الوتر-بركعة-عن-تحية-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجزئ الوتر بركعة عن تحية المسجد.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":4852,"question":"هل تُشرع المُحافظة على الركعتين اللَّتين قبل المغرب؟","title":"هل تُشرع المُحافظة على الركعتين قبل المغرب؟","answer":"أفضل.\nس: يُحافظ عليها دائمًا؟\nج: النبي عليه الصلاة والسلام قال: صلُّوا قبل المغرب، صلُّوا قبل المغرب ثم قال: لمن شاء فليست لازمةً، ولكنها لمن شاء.","link":"https://binbaz.org.sa/fatwas/25305/هل-تشرع-المحافظة-على-الركعتين-قبل-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المُحافظة على الركعتين قبل المغرب.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":4853,"question":"هل صلاة الاستخارة من ذوات الأسباب؟","title":"هل الاستخارة من ذوات الأسباب فتُصلى وقت النهي؟","answer":"لا، قد يتسع الوقت لغيره، وقد لا تكون ضرورةً، لكن لو كانت ضرورةً تصير من ذوات الأسباب، لو كان التأخيرُ ما فيه حيلة.","link":"https://binbaz.org.sa/fatwas/25309/هل-الاستخارة-من-ذوات-الاسباب-فتصلى-وقت-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل صلاة الاستخارة من ذوات الأسباب.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":4854,"question":"مَن قال أنَّ الدعاء في صلاة الاستخارة قبل السلام أفضل من الدّعاء بعد السلام؟","title":"هل يكون دعاء الاستخارة قبل السلام أم بعده؟","answer":"جاء في الحديث: يُصلِّي ركعتين، ثم يقول، فالدّعاء يكون بعد صلاة ركعتين.","link":"https://binbaz.org.sa/fatwas/25310/هل-يكون-دعاء-الاستخارة-قبل-السلام-ام-بعده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى يكون دعاء الاستخارة قبل السلام أو بعده.mp3","categories":["صلاة التطوع","الأدعية والأذكار"]},{"id":4925,"question":"أحيا ليله أي أن النبي ﷺ كان لا ينام ليالي العشر؟","title":"ما معنى \"أحيا ليله\" في الحديث؟","answer":"إيه هذا معناه؛ أنه كان يحيي ليله بالقراءة والصلاة والدعاء.","link":"https://binbaz.org.sa/fatwas/25443/ما-معنى-احيا-ليله-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما معنى أحيا ليله في الحديث.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":5282,"question":"ما حكم تحية المسجد في وقت النهي هل هي واجبة أم مستحبة؟","title":"ما حكم تحية المسجد في وقت النهي؟","answer":"الجواب: تحية المسجد سُنة في جميع الأوقات، تحية المسجد ركعتان في كل وقت على الصحيح، ليس لها وقت نهي، حتى ولو كان الإمام يخطب، إذا دخل يوم الجمعة والإمام يخطب لا يجلس حتى يصلي ركعتين.[1]","link":"https://binbaz.org.sa/fatwas/30920/ما-حكم-تحية-المسجد-في-وقت-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 002.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":5499,"question":"إمام يُصلي بالناس التراويح، وقام للثالثة، وسبَّحوا خلفه، لكنه قام وأتى برابعةٍ ثم سلَّم، ولم يسجد سجود سهو، قال: هذه نافلة، ولا يضركم كوننا صلينا أربعًا بسلامٍ واحدٍ.مع أنه ابتداءً ما عوّد الجماعة، ولا نوّى من أول الصَّلاة؟","title":"ما حكم صلاة النافلة أربعًا بسلامٍ واحدٍ؟","answer":"الجواب: هذا قول بعض الفقهاء؛ يقولون: تمم رابعةً، لكن السُّنة مثلما قال ﷺ: صلاة الليل مثنى مثنى، أما إذا قام إلى ثالثةٍ وسبَّحوا به يجلس ويسجد للسَّهو، هذا هو السُّنة، وأما إذا كمَّل أربعًا فهو قول بعض أهل العلم، وهو قول مرجوح، لكن الأمر سهل إن شاء الله. س: طيب، النية، الآن هم ابتدأوا الصلاة على أنها ركعتان؟ ج: السُّنة أنه قام ونبَّهوه يعود، أو تنبه يعود، ويسجد للسهو، يقرأ التَّحيات ويُكمل، ثم يسجد للسهو، هذا هو المعتمد، وهو الذي دلَّت عليه الأحاديث: صلاة الليل مثنى مثنى، لكن لو كمَّل أربعًا ما نقول: بطلت، فيه خلاف بين أهل العلم كبير. س: ولو بدأ بالفاتحة؟ ج: ولو بدأ بالفاتحة يعود ويجلس، مثل: لو قام إلى ثالثةٍ في الفجر، أو في الجمعة، ولو بدأ بالفاتحة يعود ويجلس إذا نبَّهوه. س: عمله هذا ما يُنكر عليه؟ ج: يُعلَّم السُّنة.[1]","link":"https://binbaz.org.sa/fatwas/31409/ما-حكم-صلاة-النافلة-اربعا-بسلام-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 013.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":5655,"question":"هل صلاة الاستخارة تكون عند التَّردد بين أمرين، أم عند العزم على أمرٍ واحدٍ؟","title":"هل تكون الاستخارة عند العزم على أمر أم التَّردد؟","answer":"الجواب: صلاة الاستخارة تكون عند الاشتباه، إذا عزم على الأمر، أو تردد بين أمرين، عزم على السَّفر وعنده اشتباه، أو على الزواج من امرأةٍ وعنده تردد، أو ما أشبه ذلك، فيُصلِّي ركعتين، ثم يستخير الله في ذلك بما أشكل عليه.[1]","link":"https://binbaz.org.sa/fatwas/31692/هل-تكون-الاستخارة-عند-العزم-على-امر-ام-التردد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 001.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":5662,"question":"ما صفة صلاة النَّافلة على الرَّاحلة في هذا الوقت؟","title":"ما صفة صلاة النَّافلة على الرَّاحلة؟","answer":"الجواب: يُصلي على الراحلة، يقرأ وهو جالس، ويركع وهو جالس في الهواء، ويسجد وهو جالس في الهواء، كما كان النبي يفعل في السَّفر، يفعل هذا في السفر. وهكذا في السيارة، وهكذا في القطار، وفي الطائرة، وفي الباخرة. أما إذا استطاع أن يسجد في السيارة، أو في القطار، أو في الباخرة، أو في الطائرة، إن كان في محلٍّ واسعٍ واستطاع أن يسجد وأن يقف فعل ذلك في الفريضة خاصةً، أما النافلة فيجوز أن يُصلي وهو جالس؛ لأنَّ النافلة لا يجب فيها القيام، لكن الجالس على النِّصف من أجر صلاة القائم في النافلة، أمَّا الفريضة فلا بدَّ أن يُصلي قائمًا. فإذا دعت الحاجةُ إلى الصلاة في الطائرة: جاء الوقت وهو في الطائرة، أو في الباخرة، أو في السيارة، وجاء الوقت، فإنه يُصلي على حسب حاله، لكن في السيارة يستطيع أن يُوقف السيارة ويُصلي على الأرض، كالدَّابة، أما في الطائرة فلا حيلةَ له، فإذا خشي أن يفوت الوقتُ صلَّى فيها على جهة سيره، يدور مع القبلة حيث دارت الطائرة، ويُصلي جالسًا: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16].[1]","link":"https://binbaz.org.sa/fatwas/31699/ما-صفة-صلاة-النافلة-على-الراحلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 008.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":5999,"question":"شكرًا لسماحة الشيخ، ونفعنا الله بعلمه، وجزاه الله خير الجزاء، ووردت إلينا تسعة وثلاثون سؤالًا إلى الآن، نترك لسماحة الشيخ الإجابة على ما تيسر منها:أول هذه الأسئلة حسب وروده إلينا: بسم الله الرحمن الرحيم: إذا دخل الرجل المسجد قبل الغروب، فهل يتسنن، أم لا؟","title":"حكم التنفل قبل غروب الشمس","answer":"الجواب: إذا دخل الإنسان المسجد قبل غروب الشمس، أو دخل المسجد قبل طلوع الشمس بعد صلاة الفجر، فهذه الأوقات يقال لها: أوقات النهي عن الصلاة، والرسول ﷺ نهى عن الصلاة بعد الصبح حتى تطلع الشمس، ونهى عن الصلاة بعد العصر حتى تغيب الشمس، تواترت، بهذا الأحاديث عن رسول الله -عليه الصلاة والسلام- ووجب على المسلمين الأخذ بها، وأن يكفوا عن الصلاة بعد الصبح إلى ارتفاع الشمس، وبعد العصر إلى مغيب الشمس.  لكن هناك صلوات لها أسباب، ليست صلاة عادية، بل لها أسباب، أما الصلوات التي ليس لها أسباب فهذا محرم فعلها في أوقات النهي، كونه يقول: أصلي بدون سبب بعد العصر، أو بعد الصبح، أو بعد ارتفاع الشمس، فهذا ممنوع، أو عند قيام الشمس عند وقوفها قبيل الزوال هذا ممنوع. لكن هناك صلوات لها أسباب مثل: الطواف، صلاة الطواف الذي طاف بالكعبة بعد العصر، أو بعد الصبح، ومثل صلاة الكسوف، لو كسفت الشمس بعد العصر، ومثل صلاة الجنازة بعد العصر، وبعد الصبح، ومثل تحية المسجد إذا دخل المسجد بعد الصبح، وبعد العصر، وذهب بعض أهل العلم إلى أن هذه الصلاة مثل غيرها تمنع قال: لا تفعل، ولو أنها ذوات أسباب لا تفعل في أوقات النهي؛ أخذًا بالعموم الذي سمعتم. وقال آخرون من أهل العلم: لا حرج في الصلاة ذات الأسباب، لا حرج فيها أن تؤدى في أوقات النهي إذا كان لها سبب مثل: الصلوات التي سمعتم، مثل: صلاة الطواف، طاف إنسان في الكعبة، في مكة، طاف بعد العصر فهل يصلي؟ نعم الصواب: يصلي؛ لأنها ذات أسباب، ما صلاها هكذا من دون سبب، بل طاف، والطواف سبب، فيصلي ركعتين. كذلك صلاة الكسوف، كذلك تحية المسجد إذا دخل المسجد قبل غروب الشمس يصلي ركعتين، ثم يجلس، هذا هو الأفضل، والأقوى، والأصح. لأن الرسول ﷺ أمر بهذه الصلوات، وقال -عليه الصلاة والسلام-: يا بني عبد مناف لا تمنعوا أحدًا طاف بهذا البيت، وصلى أية ساعة شاء من ليل، أو نهار خرجه الإمام أحمد، وأهل السنن بإسناد صحيح .  وقال في الخسوف: فإذا رأيتم ذلك؛ فصلوا، وادعوا خسوف الشمس، والقمر، ولم يقل إلا وقت النهي.  وكذلك قال: إذا دخل أحدكم المسجد؛ فلا يجلس حتى يصلي ركعتين فهو جاء يصلي المغرب، أو جاء ليجلس في المسجد قبل طلوع الشمس؛ ليقرأ، أو ليستريح، وهو على وضوء يصلي ركعتين؛ لأنها ذات أسباب، أو قدرت جنازة بعد العصر، أو بعد الصبح، يصلي عليها كما هو العمل، يصلي على الجنازة؛ لأن تأخيرها غير مشروع، وتعجيلها مشروع، أو إنسان توضأ ليقرأ بعد العصر، وتوجه إلى المسجد ليقرأ القرآن، أو ليمس المصحف؛ فالوضوء له صلاة، وصلاته من ذوات الأسباب. فهذه الصلوات التي ذكرنا يقال لها: ذوات الأسباب، والصحيح فيها: أنه لا بأس بفعلها، وأنها مستثناة، خارجة من العموم، فلا بأس أن يصلي ركعتين تحية المسجد بعد العصر على الصحيح، ولا بأس أن يصلي بعد الطواف إذا طاف بعد العصر، أو بعد الصبح في مكة، ولا بأس أن يصلي صلاة الخسوف إذا خسفت الشمس بعد العصر، هذا هو الصواب. ولو ترك؛ لا حرج لو جلس في المسجد، ولم يصلها، أو ما صلوا الكسوف، أو طاف بعد العصر، وأخر الصلاة إلى بعد المغرب، لا حرج في ذلك، لا بأس، لكن المبادرة في ذلك، وصلاة تحية المسجد، وصلاة الطواف، وصلاة الكسوف في وقتها هذا هو الأفضل، هذا هو الصواب، وتكون أحاديث النهي عامة، وهذه الصلوات التي جاء فيها الحديث خاصة مستثناة.  ويلحق بذلك صلاة الجماعة إذا فاتت المسلم، إذا صلى جماعة، ثم جاء إلى مكان لم يصلوا، فصلى معهم، فهذه من ذوات الأسباب، لو صليت مع إخوانك في مسجد من المسجد، العصر، ثم ذهبت إلى الدرس في مسجد آخر، أو لحاجة تريدها في مسجد آخر، فدخلت المسجد، وإذا هم يصلون، فتصلي معهم، ولا تقل هذا بعد العصر، لا أصلي معهم، أو الفجر لا صل معهم، النبي ﷺ أمر الذين يدركون وقتًا يؤخرون فيه الأمراء الصلاة، قال: صل الصلاة لوقتها، فإن أدركتها معهم؛ فصل معهم، فإنها لك نافلة، ولا تقل: صليت، فلا أصلي، فهذا يدل على أنه إذا صلى في أي مسجد، ثم جاء إلى مسجد آخر لحاجة، ووجدهم يصلون العصر، أو الفجر؛ فإنه يصلي معهم، ولا يقل: صليت فلا أصلي، فتكون له نافلة، هذه أيضًا نوع خامس من ذوات الأسباب المستثناة من أحاديث النهي. وصلاة الوضوء أيضًا نوع سادس، فالصواب في هذه المسائل: أن ذوات الأسباب يعفى عنها، ولا بأس أن تؤدى في أوقات النهي، وأنها مستثناة من العموم في أرجح قولي العلماء.  السؤال: النفل المطلق هو الممنوع؟ الجواب: النفل المطلق هو الممنوع نعم. السؤال: إذا كان في المسجد، ثم انتقض وضوءه، وعاد؟ الجواب: يصلي تحية المسجد، وصلاة الوضوء أيضًا، فيجتمع له سنتان: سنة الوضوء، وسنة تحية المسجد. السؤال: هو كان جالس في المسجد؟ الجواب: ولو إذا دخل هذا دخولًا جديدًا، وكذلك بعض الناس قد يشتبه عليه خاصة كثير بعد المغرب، إذا كان جالس قبل الغروب في المسجد، ثم أذن المؤذن؛ فالأفضل أن يصلي ركعتين بعد الأذان، كان أصحاب النبي ﷺ يفعلون ذلك في عهده -عليه الصلاة والسلام- جاء هذا في عدة أحاديث صحيحة عن رسول الله، عليه الصلاة والسلام.  فالصحابة كانوا إذا أذن المؤذن للمغرب؛ قاموا، وصلوا ركعتين قبل الإقامة إذا كانوا جالسين في المسجد ينتظرون، ثم أذن المؤذن؛ فالأفضل، والسنة أن الجالسين يقومون بعد الأذان، ويصلون ركعتين، هذه تخفى على كثير من الناس، ويظن أنها غير مشروعة، وقد قيل لعقبة بن عامر الصحابي الجليل، أمير مصر في ذلك، فقال: إنها سنة كنا نفعلها في عهد النبي ﷺ فقال له السائل: ما يمنعنك الآن؟ قال: الشغل. وثبت في صحيح مسلم عن أنس  أن أصحاب النبي كانوا يفعلونها، فإذا أذن المؤذن وهم جالسون؛ قاموا، فأدوا ركعتين قبل صلاة المغرب، وهكذا بقية الصلوات إذا أذن المؤذن للظهر، أو للعصر، أو للعشاء وأنت جالس؛ تقوم تصلي ركعتين في الفجر، سنة في الفجر، في الظهر، الراتبة إذا كنت ما أديتها، وإذا كنت أديت الراتبة؛ صليت ركعتين؛ لأن النبي -عليه الصلاة والسلام- قال: بين كل أذانين صلاة، بين كل أذانين صلاة، بين كل أذانين صلاة والعصر كذلك. السؤال: والجمعة يا شيخ؟ الجواب: الجمعة لا، إذا أذن الأذان الأخير؛ يجلس يستمع الخطبة، لكن إذا دخل وهو يخطب؛ يصلي ركعتين، وقد أمر بها النبي ﷺ أمر من دخل أن يصلي ركعتين، ولو أن الإمام يخطب، لكن لا يطول فيهما يتجوز.","link":"https://binbaz.org.sa/fatwas/1372/حكم-التنفل-قبل-غروب-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_330.mp3","categories":["أوقات النهي","صلاة التطوع"]},{"id":6047,"question":"إذا دخلت إلى مسجد قبل أذان المغرب، فهل يجوز أن أصلي، حيث سمعت من البعض يقولون: لا يجوز الركوع بعد الأذان؟","title":"حكم أداء تحية المسجد قبل أذان المغرب","answer":"الجواب: إذا دخل الإنسان المسجد بعد صلاة العصر، أو بعد صلاة الصبح، إذا دخل المسجد، ويريد أن يجلس فيه ليقرأ، أو ليستريحش؛ فإنه يصلي ركعتين، هذا هو الأفضل تحية المسجد، وإن جلس كما قال جماعة من العلماء؛ فلا بأس، فلا حرج. لا ينبغي في هذا التشديد، ولا النزاع، من جلس؛ فلا حرج، ومن صلى ركعتين إذا دخل المسجد بعد صلاة العصر، أو بعد صلاة الصبح فهو أفضل؛ لأنها تحية المسجد؛ ولأنها من ذوات الأسباب، وذوات الأسباب الأرجح فيها أنها تجوز وقت النهي، مثل صلاة الطواف في مكة إذا طاف؛ صلى ركعتين، ومثل صلاة الكسوف إذا كسفت الشمس بعد العصر؛ الأفضل يصلى صلاة الكسوف. كذلك إذا دخل المسجد بعد العصر، أو بعد الصبح؛ الأفضل أن يصلي ركعتين، ثم يجلس، هذا هو الأفضل؛ لقول النبي ﷺ: إذا دخل أحدكم المسجد؛ فلا يجلس حتى يصلي ركعتين وهذا عام، يعم ما بعد صلاة العصر، ويعم ما بعد صلاة الصبح، وهذا هو الأرجح من قولي العلماء، رحمهم الله.","link":"https://binbaz.org.sa/fatwas/1453/حكم-اداء-تحية-المسجد-قبل-اذان-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_381.mp3","categories":["أوقات النهي","صلاة التطوع"]},{"id":6074,"question":"يقولون في البدع حسنة، وسيئة، يستدلون بقول عمر  عند التراويح: \"نعمت البدعة هذه\" فما رأيكم في هذا التقسيم؟","title":"معنى قول عمر بن الخطاب: «نعمت هذه البدعة»","answer":"الجواب: ذهب بعض أهل العلم إلى أن البدع تنقسم إلى أقسام خمسة، وأنها تدخلها الأحكام الخمسة: التحريم، والوجوب، والكراهة، والاستحباب، والإباحة، ذهب إلى هذا جماعة، وأنكر هذا آخرون من أهل العلم، وقالوا: ليس في البدعة تقسيم، بل كلها ضلالة، وهكذا قال قائد المسلمين، وإمامهم كل بدعة ضلالة. وليس لأحد أن يخالفه فيقول: لا، ما هي بكلها ضلالة، هذا جرأة على الرسول ﷺ لا يجوز فعلها، والنبي -عليه الصلاة والسلام- قال: كل محدثة بدعة، وكل بدعة ضلالة هكذا قال -عليه الصلاة والسلام- وبين، فلا يجوز لنا، ولا لغيرنا أن نقول: إن البدعة فيها ضلالة، وفيها غير ضلالة، بل كلها ضلالة، وهي ما أحدثه الناس في الدين، كله ضلالة، وما يحتجون به على التقسيم لا حجة لهم فيه.  فالأشياء التي احتجوا بها على البدعة الواجبة من نقط المصاحف، وتشكيل المصاحف، ومن بناء المساجد كل هذا ليس من البدع، بل هذا أمر الله به، ورسوله، أمر الله ببناء المساجد، وأمر بالعناية بالقرآن، وحفظ القرآن، وتلاوته، فما أعان على هذا؛ فهو داخل في الأمر بالحفظ، والعناية. والمقصود: أن ما ذكروه ليس من باب البدع، بل هو من باب الدين، ومن باب حفظ الدين، ومن باب التعاون على البر، والتقوى. وأما قول عمر  لما رأى الناس اجتمعوا على صلاة التراويح بأمره، كان الناس في عهد النبي ﷺ يصلون فرادى، وجماعات، فصلى بهم النبي ﷺ ليال، وجمعهم، صلى بهم قيامًا -عليه الصلاة والسلام- ثلاث ليال، ثم ترك ذلك، وقال: إني أخشى أن تفرض عليكم صلاة الليل وكان شفيقًا على أمته، عليه الصلاة والسلام.  فلما توفي ﷺ شغل الصديق -رضي الله عنه وأرضاه- أهل الردة، وشغل بهم الصحابة -رضي الله عنهم وأرضاهم- فلما جاءت خلافة عمر؛ صار أفرغ لذلك، ومدته طويلة، فنظر في جمع الناس على إمام واحد، بدل ما كانوا يصلون أوزاعًا في المسجد، فجمعهم على إمام واحد، وأمر أُبيًّا أن يصلي بهم، فلما خرج ذات ليلة، ونظر إليهم، قال: \"نعمت هذه البدعة\"سماها بدعة من جهة اللغة، لا من جهة الدين؛ لأن البدعة في اللغة ما كان على غير مثال سابق. فالمعنى: أنهم كانوا في السابق يصلون أوزاعًا، ولم يجتمعوا على إمام واحد، فلما جمعهم؛ قال: \"نعمت البدعة\" التي فعلها هو لهم؛ ليجتمعوا، ويتعاونوا على البر، والتقوى، ولأن الرسول ما استمر عليها، إنما فعلها ثلاث، ثم ترك، فلهذا قال عمر هذه المقالة، فهي مقالة له من جهة اللغة، مقصوده من جهة اللغة، لا من جهة الأمر الشرعي، فليست بدعة من جهة الأمر الشرعي، بل هي سنة، وقربة، فعلها الرسول ﷺ وفعلها الخلفاء الراشدون، عمر، ومن بعده، وفعلها أصحاب النبي ﷺ وفعلها المسلمون، وحث عليها النبي ﷺ قال: من قام رمضان إيمانًا، واحتسابًا؛ غفر له ما تقدم من ذنبه وقال: من قام مع الإمام يعني في رمضان حتى ينصرف؛ كتب له قيام ليلة فدل على شرعية القيام، وأنه يكون له إمام، وجماعة، فليس من البدعة في شيء.","link":"https://binbaz.org.sa/fatwas/1487/معنى-قول-عمر-بن-الخطاب-نعمت-هذه-البدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_417.mp3","categories":["صلاة التطوع","البدع والمحدثات"]},{"id":6083,"question":"يقولون في البدع حسنة، وسيئة، يستدلون بقول عمر  عند التراويح: \"نعمت البدعة هذه\" فما رأيكم في هذا التقسيم؟","title":"معنى قول عمر بن الخطاب: «نعمت هذه البدعة»","answer":"الجواب: ذهب بعض أهل العلم إلى أن البدع تنقسم إلى أقسام خمسة، وأنها تدخلها الأحكام الخمسة: التحريم، والوجوب، والكراهة، والاستحباب، والإباحة، ذهب إلى هذا جماعة، وأنكر هذا آخرون من أهل العلم، وقالوا: ليس في البدعة تقسيم، بل كلها ضلالة، وهكذا قال قائد المسلمين، وإمامهم كل بدعة ضلالة. وليس لأحد أن يخالفه فيقول: لا، ما هي بكلها ضلالة، هذا جرأة على الرسول ﷺ لا يجوز فعلها، والنبي -عليه الصلاة والسلام- قال: كل محدثة بدعة، وكل بدعة ضلالة هكذا قال -عليه الصلاة والسلام- وبين، فلا يجوز لنا، ولا لغيرنا أن نقول: إن البدعة فيها ضلالة، وفيها غير ضلالة، بل كلها ضلالة، وهي ما أحدثه الناس في الدين، كله ضلالة، وما يحتجون به على التقسيم لا حجة لهم فيه.  فالأشياء التي احتجوا بها على البدعة الواجبة من نقط المصاحف، وتشكيل المصاحف، ومن بناء المساجد كل هذا ليس من البدع، بل هذا أمر الله به، ورسوله، أمر الله ببناء المساجد، وأمر بالعناية بالقرآن، وحفظ القرآن، وتلاوته، فما أعان على هذا؛ فهو داخل في الأمر بالحفظ، والعناية. والمقصود: أن ما ذكروه ليس من باب البدع، بل هو من باب الدين، ومن باب حفظ الدين، ومن باب التعاون على البر، والتقوى. وأما قول عمر  لما رأى الناس اجتمعوا على صلاة التراويح بأمره، كان الناس في عهد النبي ﷺ يصلون فرادى، وجماعات، فصلى بهم النبي ﷺ ليال، وجمعهم، صلى بهم قيامًا -عليه الصلاة والسلام- ثلاث ليال، ثم ترك ذلك، وقال: إني أخشى أن تفرض عليكم صلاة الليل وكان شفيقًا على أمته، عليه الصلاة والسلام.  فلما توفي ﷺ شغل الصديق -رضي الله عنه وأرضاه- أهل الردة، وشغل بهم الصحابة -رضي الله عنهم وأرضاهم- فلما جاءت خلافة عمر؛ صار أفرغ لذلك، ومدته طويلة، فنظر في جمع الناس على إمام واحد، بدل ما كانوا يصلون أوزاعًا في المسجد، فجمعهم على إمام واحد، وأمر أُبيًّا أن يصلي بهم، فلما خرج ذات ليلة، ونظر إليهم، قال: \"نعمت هذه البدعة\"سماها بدعة من جهة اللغة، لا من جهة الدين؛ لأن البدعة في اللغة ما كان على غير مثال سابق. فالمعنى: أنهم كانوا في السابق يصلون أوزاعًا، ولم يجتمعوا على إمام واحد، فلما جمعهم؛ قال: \"نعمت البدعة\" التي فعلها هو لهم؛ ليجتمعوا، ويتعاونوا على البر، والتقوى، ولأن الرسول ما استمر عليها، إنما فعلها ثلاث، ثم ترك، فلهذا قال عمر هذه المقالة، فهي مقالة له من جهة اللغة، مقصوده من جهة اللغة، لا من جهة الأمر الشرعي، فليست بدعة من جهة الأمر الشرعي، بل هي سنة، وقربة، فعلها الرسول ﷺ وفعلها الخلفاء الراشدون، عمر، ومن بعده، وفعلها أصحاب النبي ﷺ وفعلها المسلمون، وحث عليها النبي ﷺ قال: من قام رمضان إيمانًا، واحتسابًا؛ غفر له ما تقدم من ذنبه وقال: من قام مع الإمام يعني في رمضان حتى ينصرف؛ كتب له قيام ليلة فدل على شرعية القيام، وأنه يكون له إمام، وجماعة، فليس من البدعة في شيء.","link":"https://binbaz.org.sa/fatwas/1487/معنى-قول-عمر-بن-الخطاب-نعمت-هذه-البدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_417.mp3","categories":["صلاة التطوع","البدع والمحدثات"]},{"id":6093,"question":"إذا دخل الرجل المسجد، وأقيمت الصلاة، وهو قد صلى، ولكن الصلاة هي المغرب، فهل يعيد، أم لا؟ حيث قال بعض العلماء: إن المغرب لا تعاد؛ لأنها وتر، إلا إذا شفعها الرابعة، فهل هذا صحيح؟","title":"حكم شفع صلاة المغرب لمن صلاها نافلة","answer":"الجواب: هذا نعم قاله بعض أهل العلم: أن الوتر في المغرب لا تعاد وترًا، ولكن تعاد شفعًا، ولكن الصحيح أنها تعاد كما هي، وأن هذا القول لا وجه له، النبي -عليه الصلاة والسلام- لما حذر من أمراء يؤخرون الصلاة عن أوقاتها، قال لأبي ذر، ولغيره: صل الصلاة لوقتها، فإن أدركتها معهم؛ فصل، فإنها لك نافلة، ولا تقل صليت فلا أصلي.  فإذا صلى الإنسان في مسجده، أو في بيته لعذر، ثم صادف مسجدًا لحاجة .. يصلي، فإنه يصلي معهم، ولا يقول: صليت فلا أصلي، بل يصلي معهم، ولا يقول: صليت فلا أصلي، بل يصلي معهم، ولو كانت المغرب يصلي معهم، ولا يزيد شيئًا، يصلي معهم، ويسلم معهم؛ عملا بأمر النبي -عليه الصلاة والسلام- قال: صل معهم فإنها لك نافلة ولم يقل: إذا كانت المغرب؛ فزد ركعة، قال: صليت معهم، والرسول يعلم أن المغرب إحدى الصلوات الخمس، فلم يقل لمن أدرك الصلاة مع الجماعة: صل المغرب معهم، وزد فيها ركعة، فلما أطلق؛ دل ذلك على أنه يصلي معهم، كما يصلون، ولا يزيد فيها شيئًا.","link":"https://binbaz.org.sa/fatwas/1499/حكم-شفع-صلاة-المغرب-لمن-صلاها-نافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_429.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":6505,"question":"ما حكم صلاة التسابيح، وما هي الأسباب لصحتها، وبطلانها إذا كانت غير صحيحة؟","title":"ما سبب القول ببطلان صلاة التسابيح؟","answer":"الجواب: اختلف العلماء في أحاديث التسابيح، والصواب: أنه ليس بصحيح، وأنه شاذ، مخالف للأحاديث الصحيحة المعروفة عن النبي ﷺ في صلاة النافلة، الصلاة التي شرع الله لعباده في ركوعهاـ وسجودها، وغير ذلك، ولهذا الصواب: قول من قال بعدم صحته، وقد أورده ابن الجوزي في الموضوعات.","link":"https://binbaz.org.sa/fatwas/2256/ما-سبب-القول-ببطلان-صلاة-التسابيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_879.mp3","categories":["الحكم على الأحاديث","صلاة التطوع"]},{"id":6711,"question":"ما حكم دخول المسجد في وقت غروب الشمس، هل يصلي، أم لا؛ لأن بعض الإخوان ينهون عن أصله، ويقولون فيه نهي؟","title":"حكم صلاة تحية المسجد في أوقات النهي","answer":"الجواب:  إذا دخل قبل غروب الشمس في المسجد غير صلاة المغرب، أو دخل المسجد قبل طلوع الشمس؛ لأجل يستريح، أو لأجل يقرأ، أو يحضر الدرس؛ فالأفضل له أن يصلي ركعتين، وإن جلس أخذًا بما جاء من أحاديث النهي عن الصلاة قبل طلوع الشمس، وقبل غروبها؛ فلا بأس عليه، لأن كثيرًا من أهل العلم قالوا: إن أحاديث النهي ينبغي تقديمها على أحاديث الرخصة.  فالصواب: أن هذه الرخصة مقدمة؛ لأنها من ذوات الأسباب، فإن صلى ركعتين قبل غروب الشمس، وقبل طلوعها لو دخل؛ فهذا أفضل على الصحيح، وإن جلس؛ فلا حرج عليه إن شاء الله.","link":"https://binbaz.org.sa/fatwas/2597/حكم-صلاة-تحية-المسجد-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1093.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":6973,"question":"وبعض الإخوة يقول بعض الأحيان يحدث عندي ضيق في صدري بدون سبب حتى أنني لا أستطيع أن أستقر في محل واحد، فماذا أفعل، وماذا تنصحونني؟","title":"ذكر الله دواء لضيق الصدر","answer":"الجواب: الَّذِينَ آمَنُوا وَتَطْمَئِنُّ قُلُوبُهُمْ بِذِكْرِ اللَّهِ أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ [الرعد:28] عليك بذكر الله -جل وعلا- إذا أحسست بالضيق؛ فعليك بذكر الله: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، ولا حول ولا قوة إلا بالله، سبحان الله وبحمده سبحان الله العظيم، لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيء قدير، تكثر من هذا، من قراءة القرآن، تتعوذ بالله من الشيطان يزول، الحمد لله.","link":"https://binbaz.org.sa/fatwas/2893/ذكر-الله-دواء-لضيق-الصدر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1341.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":7140,"question":"يقول أحد الإخوة الحاضرين: إن ابن القيم يقول في زاد المعاد الجزء الأول: إن صلاة الضحى ليست فيها حديث صحيح، وحديث أبي هريرة خاص به، هل هذا صحيح جزاكم الله خيرًا؟","title":"ما جواب من يقول بعدم صحة أحاديث الضحى؟","answer":"الجواب:\n\nلا أذكر هذا في كلام ابن القيم، لا أذكره، وإن كان قال هذا؛ فهو خطأ، وليس ابن القيم معصومًا ولا غيره من العلماء، ليسوا معصومين، وما أظنه يقول هذا؛ لأن النبي ﷺ أوصى أبا الدرداء، وأوصى أبا هريرة بثلاث: بصيام ثلاثة أيام من كل شهر، وركعتي الضحى، وأن يوتر قبل النوم، وليست هذه خاصة بهما، النبي ﷺ إذا أوصى واحدًا فهي وصية للجميع، ما هو خاص بالواحد، وهكذا قال لمعاذ: اتق الله حيثما كنت، واتبع السيئة الحسنة تمحها، وخالق الناس بخلق بحسن هل هذا خاص بمعاذ، أو خاص بأبي ذر؟ لا، وقال لمعاذ: إذا صليت قل في دبر كل صلاة: اللهم أعني على ذكرك وشكرك وحسن عبادتك.\n\nوقال العلماء: هذا عام، ليس خاصًا بمعاذ، وهكذا غير ذلك، قال لابن عباس -رضي الله عنهما-: احفظ الله؛ يحفظك، احفظ الله؛ تجده تجاهك ... الحديث، وليس هذا خاصًا بابن عباس، فهكذا وصية النبي ﷺ لأبي هريرة، ولأبي الدرداء، وصية للجميع، وليس خاصا بهما.\n\nوهكذا قوله في حديث أبي ذر لما ذكر السلاميات، وما عليها من الصدقات قال: ويكفي من ذلك ويجزئ منه ركعتان تركعهما من الضحى هذا عام للأمة كلها.","link":"https://binbaz.org.sa/fatwas/3156/ما-جواب-من-يقول-بعدم-صحة-احاديث-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1514.mp3","categories":["الحكم على الأحاديث","صلاة التطوع"]},{"id":7215,"question":"هل يجوز لي أن أصلي النوافل بعدما صليت الوتر بعد صلاة العشاء، علمًا بأن أحد الإخوان قال لي: لا يجوز أن تصلي بعدما أوترت، واحتج بحديث: اجعلوا آخر صلاتكم وترًا نرجو الإيضاح؟","title":"صلاة النوافل بعد صلاة العشاء","answer":"الجواب:\n\nالأفضل أن يختم صلاته بالوتر في الليل كما قاله النبي ﷺ: اجعلوا آخر صلاتكم من الليل وترًا لكن لا بأس أن يصلي بعد الوتر، إنما هذا على سبيل الأفضلية. \n\nوالنبي ﷺ ثبت عنه أنه صلى بعد الوتر، كان يصلي ركعتين بعد الوتر عليه الصلاة والسلام، هذا يدل على جواز أن يصلي بعد الوتر، وألا حرج في ذلك؛ ففعله يبين الجواز.\n\nالسؤال: يشفعها يا شيخ؟\n\nالجواب: يصلي ركعتين بعد الوتر، هذه الشفع، الركعتين شفع، والوتر بقى، ولا يحتاج شيء، الوتر بقى لا يغيره، وإذا صلى ركعتين بعد الوتر؛ فلا بأس، أو صلى في أول الليل، أو أوتر في أول الليل، ثم قام في آخر الليل وصلى ما تيسر، ما يحتاج إلى أن يشفع الوتر، بل الوتر الأول كافي، النبي -عليه الصلاة والسلام- قال: لا وتران في ليلة.","link":"https://binbaz.org.sa/fatwas/3280/صلاة-النوافل-بعد-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1605.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":7462,"question":"هنا رسالة من السودان وردت من الأخ المخلص محمد علي عبد الله، يقول فيها: إنه تعود أن يصلي نفل بعد المغرب ست ركعات، يقول: ولكني أصليهم بسورة الفاتحة فقط، هل هذا يجوز أم لا؟","title":"حكم صلاة ست ركعات بعد المغرب؟","answer":"الجواب: المشروع بعد المغرب ركعتان فقط الراتبة، فمن صلى بعدها زيادة ستاً أو ثماناً أو عشراً أو أكثر فلا حرج عليه، لكن بعض الناس قد يظن أن للست خصوصية، وهذا لا أصل له، ولم يثبت في حديث عن النبي ﷺ يدل على ذلك وإن اعتاده بعض الناس، فالست ليس لها خصوصية، و ليس لها أصل يعتمد عليه في الأحاديث الصحيحة، ولكن من فعلها لمزيد الخير ولمزيد العبادة، صلى ستاً أو ثماناً بعد المغرب أو عشراً فلا حرج عليه، ليس في حد محدود، بين العشاءين محل صلاة ومحل عبادة، ولكن الراتبة فقط ركعتان، التي كان يحافظ عليها النبي ﷺ ركعتان فقط، هذه الراتبة، فمن زاد وصلى أكثر من ذلك فلا حرج عليه ولا بأس عليه. المقدم: لكن تجزئ بسورة الفاتحة فقط؟\nالشيخ: يجزئ بسورة الفاتحة نعم، لو صلى بالفاتحة فقط أجزأت؛ لكن الأفضل أن يقرأ مع الفاتحة ما تيسر: آية أو آيتين أو سورة قصيرة، هذا هو الأفضل. نعم.","link":"https://binbaz.org.sa/fatwas/4180/حكم-صلاة-ست-ركعات-بعد-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_001/00104.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":7566,"question":"هذه الرسالة وردت للبرنامج من الأخ أحمد محمد الصادق من جدة العمارية، يقول: ما حكم صلاة السجود في الليل، نرجو الإفادة عن ذلك؟","title":"فضل السجود","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: هذا السؤال فيه إجمال، وهو ما حكم صلاة السجود في الليل؟\nيحتمل أن مراده بذلك يعني ما حكم الصلاة التي يكثر فيها السجود ولا تطول فيها القراءة، ويحتمل أنه أراد معنى آخر لم أفهمه، فإن كان يسأل عن الأول فقد جاء عن النبي ﷺ ما يدل على شرعية الإكثار من الصلوات وأنها من أسباب دخول الجنة، وأن العبد ما سجد سجدة إلا رفعه الله بها درجة، وفي حديث ربيعة بن كعب الأسلمي قال: قلت يا رسول الله! لما قال له الرسول ﷺ: سل -كان يخدم النبي صلى الله عليه وسلم- قال: أسألك مرافقتك في الجنة، فقال: أعني على نفسك بكثرة السجود يعني: بكثرة الصلاة. \nفكثرة الصلاة يلزم منها كثرة السجود، والسجود فيه خشوع لله وتعظيم لله عز وجل، فهو من أسباب رفع الدرجات وحط الخطيئات، ومن أسباب دخول الجنة والنجاة من النار، ومن أسباب حصول الشفاعة من النبي ﷺ لصاحبه إذا كان موحداً مسلماً، وصح عنه عليه الصلاة والسلام أنه قال: أما الركوع فعظموا فيه الرب، وأما السجود فاجتهدوا في الدعاء فقمن أن يستجاب لكم يعني: حري أن يستجاب لكم، رواه مسلم في الصحيح، وقال أيضاً عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء، فهذا يدل على أن السجود له شأن، وأن العبد أقرب ما يكون من ربه في حال سجوده؛ لأن السجود حالة خضوع، حالة ذل لله وانكسار بين يديه سبحانه وتعالى، يضع وجهه الذي هو أشرف أعضائه الظاهرة يضعه في الأرض خاضعاً لربه، مطمئناً خاشعاً، يرجو ثوابه ويخشى عقابه، فهو في هذه الحالة في غاية الذل والانكسار، فهو أقرب ما يكون إلى الله جل وعلا، ولهذا قال عليه الصلاة والسلام: أقرب ما يكون العبد من ربه وهو ساجد فأكثروا الدعاء، فدل ذلك على أن الدعاء في السجود دعاء مطلوب، وأن صاحبه حري بالإجابة، وصح عنه ﷺ في حديث ثوبان: أن العبد إذا ما سجد لله سجدة إلا رفعه الله بها درجة وحط بها عنه خطيئة، فينبغي الإكثار من الصلوات في الليل، وفي النهار، كالضحى، والظهر، وفي الليل بين العشاءين، وبعد العشاء، وفي جوف الليل، وفي آخر الليل، كل هذه أوقات عظيمة ينبغي فيها الإكثار من الصلاة ولاسيما في الليل، فإن الليل الصلاة فيه أفضل من الصلاة في النهار، وأقرب إلى الخشوع وهدوء القلب، كما يقول جل وعلا: إِنَّ نَاشِئَةَ اللَّيْلِ هِيَ أَشَدُّ وَطْئًا وَأَقْوَمُ قِيلًا [المزمل:6]، الصلاة في الليل لها شأن، والإنسان فيها أقرب ما يكون إلى الخشوع والذل بين يدي الله، ولاسيما في جوف الليل وفي آخر الليل، فينبغي الإكثار من الصلوات في الليل وفي النهار، ويختمها في الليل بالوتر، إذا صلى ما كتب الله له من الصلوات ختمها بالوتر، وأفضل ما يكون إحدى عشرة ركعة أو ثلاثة عشر ركعة كفعل النبي عليه الصلاة والسلام، وإن صلى أقل من ذلك كخمس أو سبع فلا بأس، النبي صلى الله عليه وسلم كان يتنوع في صلاته، ربما أوتر بخمس، وربما أوتر بسبع، ربما أوتر بتسع، ربما أوتر بإحدى عشرة وهو الأغلب، وربما أوتر بثلاث عشرة، فالأمر في هذا واسع، وإن صلى في الليل عشرين ركعة، أو ثلاثين ركعة، أو أربعين ركعة، أو مائة ركعة وختم بالوتر، فكل هذا لا بأس به. \nالنبي ﷺ سئل عن صلاة الليل فقال: مثنى مثنى، فلم يحد حداً عليه الصلاة والسلام، ما قال عشر ولا عشرين بل أطلق، فالإنسان يصلي في الليل ما بدا له ولو مائة ركعة، لكن من دون مشقة على نفسه مع الرفق بنفسه، ومع الطمأنينة وعدم العجلة، ثم يختم بالوتر، ولهذا قال عليه الصلاة والسلام: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعة واحدة وتر وله ما قد صلى، فيصلي ما كتب الله له في الليل، ولا يسهر بل ينام ويصلي، هذه السنة حتى لا يتعب في النهار، وحتى يتفرغ لأعماله النهارية وعباداته النهارية، فيصلي ما كتب الله له في الليل، في أول الليل، أو في جوفه، أو في آخره، والآخر أفضل إذا تيسر، ثم يوتر بواحدة ركعة واحدة، هذا هو الأفضل. نعم.","link":"https://binbaz.org.sa/fatwas/4571/فضل-السجود ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_016/01601.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":7567,"question":"سؤاله الثاني يقول: ما حكم صلاة الضحى، هل هي سُنة أم واجبة؟ أفيدونا جزاكم الله خير الجزاء، ونتمنى لكم التوفيق؟","title":"هل صلاة الضحى سُنة أم واجبة؟","answer":"الجواب: صلاة الضحى سنة وليست بواجبة الرسول ﷺ لما سئل عن الصلوات الخمس الظهر والعصر والمغرب والعشاء والفجر؟ قال السائل: هل علي غيرها؟ قال له النبي ﷺ: لا إلا أن تطوع ليس عليه غير الخمس في اليوم والليلة إلا أن يطوع، فصلاة الضحى والرواتب التي مع الصلوات الخمس، وصلاة الليل كلها مستحبة، حتى الوتر مستحب على الصحيح، الوتر سنة مؤكدة وليس بواجب عند جمهور أهل العلم. نعم.","link":"https://binbaz.org.sa/fatwas/4572/هل-صلاة-الضحى سنة-ام-واجبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_016/01602.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":7571,"question":"هذه الرسالة من المستمع من حوطة بني تميم من زيد عبد العزيز القرش، يقول: أرجو الإجابة على سؤالي هذا، وهو: إذا تأخر الواحد عن صلاة الفجر مع الجماعة بسبب نوم أو غيره، فمتى تكون ركعتي السنة قبل أو بعد صلاة الفجر، ولكم شكري وخالص تحياتي؟","title":"ما وقت قضاء سنة الفجر لمن فاتته؟","answer":"الجواب: إذا تأخر الإنسان عن الجماعة في صلاة الفجر ولم يدرك الجماعة فإنه يبدأ بالسنة الراتبة يصليها ثم يصلي الفريضة، النبي ﷺ لما نام ذات ليلة عن صلاة الفجر في السفر ولم يوقظه إلا حر الشمس، صلى النبي الراتبة ثم صلى الفجر عليه الصلاة والسلام، وأمر بالأذان والإقامة كالعادة، فالإنسان إذا فاتته صلاة الفجر فلم يستيقظ إلا بعدما صلى الناس، أو جاء إلى المسجد وقد صلى الناس فإنه يصلي الراتبة ثنتين ركعتين ثم يصلي الفريضة، هذا هو السنة، ولو أخرها وصلاها بعد الصلاة أو بعد طلوع الشمس فلا بأس، ولكن الأولى والأفضل أن يبدأ بها كما بدأ بها النبي ﷺ لما فاتته الصلاة في بعض أسفاره، وإذا صلى مع الجماعة جاء وهم يصلون صلى معهم وهو ما صلى الراتبة فإنه يصليها بعد الصلاة إن شاء، أو يصليها بعد ارتفاع الشمس وهو أفضل، لأنه جاء بهذا حديث وبهذا حديث، فهو مخير، إن شاء صلاها بعد صلاة الفجر في المسجد أو في بيته، وإن شاء صلاها بعد ارتفاع الشمس، كل ذلك بحمد الله موسع، وكل ما جاء به حديث جيد عن النبي عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/4577/ما-وقت-قضاء-سنة-الفجر-لمن-فاتته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_016/01607.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":7583,"question":"فضيلة الشيخ! هذه الرسالة التي بين يدينا من المرسل فائز سعيد غرمان الشهري، من بني شهر تنومة، قرية آل علبة، يقول في رسالته: نرجو الاستفسار عما يلي:إذا دخل الرجل في المسجد قبل أذان المغرب بشيء قليل، هل يجوز له أن يتسنن ركعتين قبل الأذان أو يجلس حتى يؤذن المؤذن، أم يقف واقف حتى يؤذن المؤذن، فإن البعض من الناس يقول: ما يجوز الركوع قبل أذان المغرب، والبعض من الناس يقول: لا يجوز الجلوس حتى تصلي ركعتين تحية للمسجد، نرجو الإفادة وفقكم الله؟","title":"ما الذي يُستثنى في أوقات النهي عن الصلاة؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد ثبت عن رسول الله عليه الصلاة والسلام أنه قال: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين، رأى رجلاً جلس يوم الجمعة ولم يصل فأمره أن يقوم يصلي ركعتين، فهذا يدل على تأكد هاتين الركعتين في حق من دخل المسجد. \nواختلف العلماء فيمن دخل في أوقات النهي؛ مثل بعد العصر، أو عند غروب الشمس، أو بعد صلاة الفجر، هل يصلي هاتين الركعتين أم يجلس؟ على قولين للعلماء، أصحهما وأرجحهما: أنه يصليهما، يصليهما ولو في وقت النهي؛ لأنهما من ذوات الأسباب، ولهذا شرع النبي صلى الله عليه وسلم أداءهما عند دخول المسجد، فإذا دخل المسجد بعد العصر أو بعد الصبح أو عند غروب الشمس فالأفضل أن يصليهما ثم يجلس، هذا هو الأفضل، وإن جلس ولم يصلهما فلا حرج؛ لأنهما سنة نافلة وليست واجبة عند عامة أهل العلم، فهي سنة وليست واجبة، فإن جلس فلا حرج، وإن صلاهما فهو أفضل، عملاً بهذا الحديث الصحيح. \nأما أحاديث النهي عن الصلاة بعد العصر وبعد الصبح فهي عامة يستثنى منها تحية المسجد، ويستثنى منها ذوات الأسباب، مثل صلاة الطواف في مكة إذا طاف بعد العصر لا بأس يصلي بصلاة الطواف، ومثل صلاة الكسوف لو كسفت الشمس بعد العصر، فالسنة أن يصلي المسلمون صلاة الكسوف بعد العصر؛ لأنها من ذوات الأسباب، فهذا هو الراجح، وإن جلس فلا حرج، ولا ينبغي في مثل هذا التنازع والمخالفة، بل ينبغي في هذا التسامح، فمن صلى فقد أحسن، ومن جلس فلا حرج عليه خروجاً من خلاف العلماء. نعم.","link":"https://binbaz.org.sa/fatwas/4636/ما-الذي-يستثنى-في-اوقات-النهي-عن-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_019/01901.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":7602,"question":"أحسنتم، هذه الأسئلة موجهة لسماحتكم يقول: سماحة الشيخ عبد العزيز بن عبد الله بن باز الرئيس العام لإدارات البحوث العلمية والإفتاء والدعوة والإرشاد المحترم، يقول: أرجو من سماحتكم أن تجيبوني على هذه الأسئلة في نور على الدرب، ما حكم شرب ماء يسير في صلاة النافلة، ونرجو أن يكون ذلك مدعم بالدليل؟","title":"حكم الشرب أثناء صلاة النافلة","answer":"الجواب: أما شرب الماء في صلاة الفريضة فهو ممنوع وهكذا الأكل، فإن الصلاة فيها شغل عن الأكل والشرب وكلام الناس، والواجب الطمأنينة فيها والإقبال عليها، أما في النافلة فأجاز هذا بعض الناس.. بعض أهل العلم ومنعه آخرون، ويروى عن عبد الله بن الزبير رضي الله عنهما أنه كان يشرب في صلاة النافلة ؛ لأنه كان يطيل الصلاة ويطيل التهجد، ولا أعلم دليلاً واضحاً في إجازة شرب الماء في الصلاة، فالصلاة فيها شغل، فالذي يظهر لي والله أعلم أن ترك ذلك أولى وأحوط في النافلة، كما يترك في الفريضة، والنافلة في الحكم كالفريضة، إلا ما خصه الدليل، ولا أعلم دليلاً واضحاً من كتاب أو سنة يدل على جواز شرب الماء في النافلة، فالذي أرى لإخواني ترك ذلك، كما يجب ترك ذلك في الفريضة، والله سبحانه وتعالى أعلم.","link":"https://binbaz.org.sa/fatwas/4655/حكم-الشرب-اثناء-صلاة-النافلة ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_021/02102.mp3","categories":["صلاة التطوع"]},{"id":7711,"question":"طيب يقول في سؤاله الثالث والأخير: إذا لم يتمكن المصلي لضيق الوقت أن يصلي سنة صلاة الفجر، فهل تجب صلاتها بعد الفرض، شاكرين لكم .. ؟","title":"متى تُقضى سنة الفجر لمن فاتته؟","answer":"الجواب: إذا كان منفردًا أو إمامًا أمكنه أن يصلي الراتبة، يصليها قبل الفريضة، أما إذا كان مثلاً المأموم فاتته الصلاة الفريضة أو جاء والإمام قد أقام الصلاة فإنه يدخل معهم في الصلاة ثم يصليها بعد الصلاة، يصلي الراتبة بعد الصلاة، وإن شاء أخّرها إلى ارتفاع الشمس، كل هذا جاءت به السنة، والأفضل تأخيرها إلى ارتفاع الشمس، لكن قد يخشى نسيانها، فإذا صلاها بعد الصلاة سنة الفجر فلا بأس، فقد ثبت عنه صلى الله عليه وسلم أنه رأى رجل يصلي بعد الفجر فقال: أتصلي الصبح أربعاً؟ فقال: يا رسول الله! إنها سنة الفجر لم أصلها قبْل، فسكت عنه عليه الصلاة والسلام، والحديث لا بأس به، وقد جاء عنه الأمر بتأخيرها إلى بعد ارتفاع الشمس، فكل هذا سنة، إن صلاها بعد الصلاة فلا بأس لئلا ينساها، وإن أخرها وصلاها بعد ارتفاع الشمس فلا بأس، كله طيب. \nالمقدم: نعم. هذه الرسالة وردت من المستمع عبد الكريم من الخفجي يسأل ... \nالشيخ: معي هنا شيء ينبغي التنبيه عليه، وهو أن الإنسان قد ينام ولا يستيقظ إلا قُرب الشمس فإنه في هذه الحالة يصلي الراتبة قبل، ولو أنه (مصيِّف)، مثل الإنسان غلبه النوم ما سمع الساعة أو ما عنده من يوقظه فقام قد فاته الوقت، قد فاته يعني الجماعة، فإنه يصلي الراتبة حتى ولو بعد طلوع الشمس، لو ما قام إلا بعد طلوع الشمس يصلي السنة ركعتين أولاً ثم يصلي الفجر، هكذا لما نام النبي صلى الله عليه وسلم عن صلاة الفجر في بعض أسفاره ولم يستيقظ إلا بعد الشمس، قام صلى الله عليه وسلم، فأمر بلال فأذن وصلى كما يصنع كل يوم عليه الصلاة والسلام، صلى الراتبة ثم صلى الفريضة بالناس، هكذا السنة، إذا استيقظ النائم وفاتته صلاة الجماعة أو استيقظ بعد طلوع الشمس فإنه يصلي على حاله الأولى، يصلي سنة الفجر أول ثم يصلي الفريضة، ولا يؤخر السنة. نعم.","link":"https://binbaz.org.sa/fatwas/4910/متى-تقضى-سنة-الفجر-لمن-فاتته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_030/03005.mp3","categories":["صلاة التطوع"]},{"id":7731,"question":"من السودان وردت هذه الرسالة من حمد مسعود فضل السيد يقول: ما حكم الجهر في صلاة النوافل بالليل؟ وإذا سها وجهر في ركعة فما الحكم؟","title":"حكم الجهر في صلاة الليل","answer":"الجواب: السنة الجهر، في صلاة الليل السنة الجهر في النافلة والفريضة، يجهر في المغرب في الأولى والثانية، في العشاء في الأولى والثانية، ويسر في الثالثة من المغرب ويسر في الثالثة والرابعة من العشاء، أما النوافل فالسنة فيها الجهر لكن جهراً لا يؤذي أحداً ولا يشق على أحد، فإذا كان بقربه مصلون أو نوام أو قراء فإنه يجهر جهراً لا يؤذيهم ولا يشق عليهم ولا يشوش عليهم، وقد خرج صلى الله عليه وسلم على قوم يصلون في المسجد ويرفعون أصواتهم فقال لهم ﷺ: كلكم يناجي الله فلا يؤذ بعضكم بعضاً، المقصود أنه إذا جهر يتحرى الجهر الخفيف الذي لا يتأذى به مصلي ولا قارئ ولا نائم، وهكذا من كان في المساجد يقرأ، في المساجد ينبغي له أن يلاحظ عدم التشويش على من حوله، فيقرأ قراءة خفيفة ليس فيها تشويش على من حوله من المصلين والقراء، بعض الناس في المساجد في الجمع وغير الجمع يجهر جهراً يشوش على من حوله وهذا لا ينبغي، أقل أحواله الكراهة، فينبغي في مثل هذا أن يراعي القاري عدم التشويش على من حوله من المصلين والقراء سواء كان في صلاة الليل في بيته أو في المساجد هذه هي السنة. نعم.","link":"https://binbaz.org.sa/fatwas/4930/حكم-الجهر-في-صلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_032/03206.mp3","categories":["صلاة التطوع","القراءة في الصلاة"]},{"id":7802,"question":"هذه رسالة وردت من دهوك من العراق يقول: يرجو أن تعرض هذه على سماحتكم يقول: وأرجو أيضاً أن تزودونا بعنوان البرنامج.عنوان البرنامج -يا أخ- هو إذاعة المملكة العربية السعودية.. الرياض.. برنامج نور على الدرب.يقول في رسالته: السلام عليكم ورحمة الله وبركاته ونحن جماعة المسلمين نستفيد من برنامجكم تمام الفائدة، أرجو من الله لنا ولكم التوفيق والسداد وأدامكم الله على طريق الحق، يقول: إنني أصلي سنة الضحى ولكن بعض الأيام أنسى فلا أصليها فهل علي ذنب حيث انشغالي بأمور البيت المنزلية تنسيني من الصلاة في بعض الأيام؟","title":"حكم صلاة الضحى","answer":"الجواب: سنة الضحى كسبها سنة ليست فريضة بل نافلة يستحب للمؤمن أن يصلي صلاة الضحى ركعتين أو أكثر من ذلك كما أوصى به النبي ﷺ وكما فعله أيضاً عليه الصلاة والسلام، لكن لو تركها الإنسان عمداً أو شغل عنها فلا قضاء عليه ولا إثم عليه؛ لأنها نافلة بحمد الله، من صلاها فله أجر ومن تركها فلا إثم عليه، ومن حافظ عليها فله أجر، ومن لم يحافظ عليها فليس عليه شيء، الأمر في هذا -بحمد الله- واسع. نعم.","link":"https://binbaz.org.sa/fatwas/5155/حكم-صلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_050/05005.mp3","categories":["صلاة التطوع"]},{"id":7816,"question":"هذا سائل يقول سماحة الشيخ: أسأل عن الصلاة الرباعية التي قبل صلاة الظهر والرباعية التي بعدها، ما فضل هذه الراتبة؟ وإذا صليت قبل الصلاة أربع بتسليمة واحدة هل ذلك جائز أم لا؟","title":"أحكام الصلاة قبل الظهر وبعدها","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nالسنة قبل الظهر أربع ركعات راتبة، كان النبي يداوم عليها ﷺ، تقول عائشة رضي الله عنها: كان النبي ﷺ لا يدع أربعاً قبل الظهر وثنتين بعدها، فالسنة أن يصلي أربعاً قبل الظهر بتسليمتين، وبعدها تسليمة، وإن صلى بعدها أربعاً فهو أفضل؛ لقوله ﷺ: من حافظ على أربع قبل الظهر وأربع بعدها حرمه الله على النار، هذا هو الأفضل أربعاً قبلها وأربعاً بعدها بتسليمتين، وجمعهما في تسليمة واحدة مكروه.\nفالسنة أن يصلي الأربع بتسليمتين قبلها وبعدها؛ لقوله ﷺ: صلاة الليل والنهار مثنى مثنى، هذا هو السنة، وهكذا قبل العصر يصلي أربعاً بتسليمتين، هذا هو الأفضل؛ لقوله ﷺ: رحم الله امرأً صلى أربعاً قبل العصر يعني: ثنتين ثنتين، وهكذا يصلي بعد العشاء ثنتين وبعد المغرب ثنتين؛ لفعله ﷺ، وقبل الفجر ثنتين.\nوإذا صلى بين العشاءين ركعات كثيرة أو في الليل فليس لها حد محدود؛ لأنها محل عبادة محل تطوع، لكن الأفضل في الليل إحدى عشرة أو ثلاثة عشرة يسلم من كل ثنتين ويوتر بواحدة، هذا هو الأفضل.\nوإن صلى أربعين أو مثلاً خمسين أو مائة أو أكثر وأوتر بواحدة فلا بأس؛ لقوله ﷺ: صلاة الليل مثنى مثنى ولم يحدد، لكن الأفضل الاقتصار على ما فعله ﷺ وهو ثلاث عشرة أو إحدى عشرة ﷺ، في رمضان وفي غيره.\nالمقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/5182/احكام-الصلاة-قبل-الظهر-وبعدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_051/05101.mp3","categories":["صلاة التطوع"]},{"id":7852,"question":"أيضاً يقول في رسالته: لقد دخلت المسجد بعد صلاة العصر، بل وقرابة غروب الشمس وأخذت في تحية المسجد فثار علي بعض الحضور جزاهم الله عني خيراً حتى أوشكت أن أجلس وأقطع تحية المسجد، فما رأيكم في ذلك، وفقكم الله؟","title":"حكم صلاة تحية المسجد وذوات الأسباب في أوقات النهي","answer":"الجواب: إذا دخل المسلم المسجد بعد صلاة الفجر ليجلس فيه ليقرأ أو ليستريح، أو دخل المسجد بعد صلاة العصر، أو قرب المغرب لينتظر صلاة المغرب فهو مخير على الصحيح من أقوال العلماء إن شاء صلى التحية وهو أفضل، وإن شاء جلس، ولا ينبغي في هذا النزاع ولا أن يثار عليه، بل ينبغي لمن جهل أن يتعلم، وأحاديث تحية المسجد أحاديث صحيحة، وصلاة تحية المسجد من ذوات الأسباب، والنبي عليه الصلاة والسلام قال: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين، ولما رأى رجلاً يوم الجمعة دخل ولم يصلهما أمره أن يقوم فيصليهما، وكان يخطب النبي ﷺ فرآه دخل المسجد يوم الجمعة ولم يصلهما فأمره أن يقوم فيصليهما، فدل ذلك على تأكدهما، وقد اختلف العلماء في ذلك، فمنهم من أجاز ذلك في وقت النهي، ومنهم من كره ذلك، والصواب أنه لا حرج في ذلك، الصواب والأرجح من قولي العلماء أنه لا حرج في تحية المسجد، بل الأفضل أن يأتي بهما ركعتين، هذا هو الأفضل أن يصلي تحية المسجد ولو كان قبيل الغروب ثم يجلس، هذا هو الأفضل، وإن جلس ولم يصلهما فلا حرج في ذلك، ولا ينبغي في هذا النزاع ولا التشديد بل الأمر واسع، الأكثرون قالوا يجلس، وجماعة من العلماء قالوا الأفضل أنه يصليهما للأحاديث الصحيحة في ذلك، وهذا هو الأرجح أنه يصليهما؛ حرصاً على أداء السنة، ولأنه بهذا لا يشابه الكفار إنما صلاهما أخذاً بالسنة، بخلاف الذي جالس يقوم يصلي لا، لا ما يجوز يصلي في وقت النهي، لكن هذا دخل المسجد فهو يصليهما لأنها تحية المسجد، فلا حرج عليه بل هو الأفضل، وهكذا لو طاف بعد العصر في مكة بالكعبة، أو طاف بعد الصبح قبل طلوع الشمس أو عند طلوعها فإنه يصلي ركعتي الطواف؛ لأنها من ذوات الأسباب، هذا هو الأرجح، وهكذا لو كسفت الشمس مع طلوعها، أو كسفت بعد العصر فالأفضل أنها تصلى صلاة الكسوف؛ لأنها من ذوات الأسباب؛ لقول النبي ﷺ: إذا رأيتم ذلك -أي الكسوف- فصلوا وادعوا، ولم يقل إلا في وقت النهي، فدل ذلك على أن ذوات الأسباب مثل صلاة الطواف، مثل صلاة الكسوف، مثل تحية المسجد، هذه تصلى ولو في وقت النهى على الأرجح، ونسأل الله للجميع التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/5251/حكم-صلاة-تحية-المسجد-وذوات-الاسباب-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_054/05405.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":7971,"question":"الرسالة الأولى: هي رسالة سعد صالح الفجري ،يقول في رسالته: بعض الناس يؤدي ركعتين قبل المغرب مستنداً: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين، والبعض الآخر لا يصلي بل يجلس مستنداً أن هذا وقت نهي لا تجوز الصلاة فيه، نرجو أن توضحوا لنا هذا الأمر بالتفصيل جزاكم الله منا خيراً، وخاصة أن المسلمين في شك من هذا الأمر وفي اختلاف، وفقكم الله؟","title":"حكم الصلاة في أوقات الكراهة لسبب","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فقد ثبت عن النبي الكريم عليه الصلاة والسلام أنه قال: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين وثبت عنه عليه الصلاة والسلام أيضاً أنه نهى عن الصلاة بعد الصبح حتى ترتفع الشمس، وعن الصلاة بعد العصر حتى تغيب الشمس، فلهذا اختلف أهل العلم في هذه المسألة، هل يصلي تحية المسجد في العصر والصبح أم لا؟\nوالصواب: أنه يصليهما وأنهما غير داخلتان في النهي، فالركعتان اللتان يأتي بهما داخل المسجد غير داخلتين في النهي، هذا هو الصواب وهذا هو الأرجح؛ لأن أحاديث النهي عامة مخصوصة فقد استثني منها صلاة الجماعة لمن فاتته الجماعة فإنه يصلي مع الناس الجماعة، من صلى الجماعة في مسجد آخر أو في بيته ظناً أن الجماعة قد فاتته ثم جاء فإنه يصلي مع الناس العصر والفجر ولو كان قد صلى، وهذا مستثنى بالنص.\nكذلك صلاة الطواف في وقت العصر وفي وقت الصبح، الصحيح أنها لا بأس بها؛ لقول النبي ﷺ: لا تمنعوا أحداً طاف بهذا البيت وصلى أية ساعة شاء من ليل أو نهار فصلاة التحية مثل ذلك -تحية المسجد- مثل هذا، فإذا دخل المسجد بعد صلاة العصر أو قبيل الغروب فالأفضل أنه يصلي ركعتين ثم يجلس، ومن جلس فلا حرج عليه، من جلس ولم يصل فلا حرج عليه لقوة الخلاف، ولكن لا ينبغي الإنكار من بعضهم على بعض، بل ينبغي في هذا التساهل والتسامح، فمن صلاهما إذا دخل قبل الغروب فهو أفضل، لكونها من ذوات الأسباب، ومن لم يصل ركعتين وجلس فلا حرج عليه، وهكذا الطواف من طاف بعد العصر، أو بعد صلاة الفجر، فصلى فهو أفضل، ومن أخر ركعتي الطواف حتى ارتفعت الشمس أو حتى غابت الشمس فلا حرج.\nوهكذا صلاة الكسوف لو كسفت الشمس بعد العصر أو طلعت كاسفة فالصواب أنه يشرع لها الصلاة، يشرع أن يصلي صلاة الكسوف في هذه الحالة، هذا هو الصواب وهذا هو الأرجح، ومن ترك ذلك فلا حرج عليه لقوة الخلاف في هذه المسألة.\nوبهذا يعلم المؤمن أن الأمر فيه سعة بحمد الله، وأنه لا ينبغي في مثل هذا التشديد والتنازع فالأمر في هذا واسع والحمد لله، من صلاهما -يعني: الركعتين ركعتي تحية المسجد- قبل غروب الشمس أو إذا دخل بعد صلاة الفجر فلا حرج عليه في ذلك وهو أفضل؛ لأنها من ذوات الأسباب؛ ولأنه في هذه الحال لا يقصد مشابهة المشركين، ومن جلس آخذاً بالنهي ولم يصل ركعتين فلا حرج عليه إن شاء الله والأمر في هذا واسع كما تقدم.\nالمقدم: بعض الناس يقول: إنه في وقت موسع ووقت مضيق في تحية المسجد مثلاً؟\nالشيخ: لا شك إن الوقت الموسع هو الذي بعد الصلاة قبل أن تصفر الشمس، فإذا اصفرت جاء الوقت المضيق، والصواب أنه لا حرج في صلاة التحية مطلقاً في المضيق والموسع، وهكذا صلاة الطواف، وهكذا صلاة الكسوف، هذا هو الصواب، ومن جلس ولم يصل ركعتين تحية المسجد فلا حرج كما تقدم لقوة الخلاف؛ ولأنه لا ينبغي بين أهل العلم وبين أهل الإيمان التنازع في مثل هذه الأمور؛ لأن كلاً من الطائفتين معه حجة ومعه دليل. نعم.","link":"https://binbaz.org.sa/fatwas/5520/حكم-الصلاة-في-اوقات-الكراهة-لسبب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_071/07101.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":8036,"question":"وأول ما نعرض من هذه الرسائل -يا فضيلة الشيخ- رسالة عبد الله الحميد الذي يسأل: عن أخذ الأجرة على تعليم القرآن الكريم؟","title":"أجرة الراقي ومعلم القرآن إعانة لا بأس بها","answer":"الجواب: الله سبحانه وتعالى أنزل القرآن الكريم ليعمل به وليتدبر ويتعقل كما قال عز وجل: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ [ص:29] ولم ينزله سبحانه للأكل به يقرأ ليعطى ويسأل به الناس، لا، إنما أنزل للعمل به وتعليمه الناس والأخذ بما فيه من الأوامر وترك النواهي، أنزل لهذا الأمر، ولهذا قال سبحانه: وَهَذَا كِتَابٌ أَنزَلْنَاهُ مُبَارَكٌ فَاتَّبِعُوهُ وَاتَّقُوا لَعَلَّكُمْ تُرْحَمُونَ [الأنعام:155] .. إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] الآية فهو أنزل ليعمل به ليتعقل ويتدبر ولم ينزل ليؤكل به وتطلب به الدنيا.\nلكن تعليم الناس للقرآن يحتاج إلى فراغ وإلى تعب وإلى صبر فجاز -على الصحيح- أن يعطى المعلم ما يعينه على ذلك، وليس هذا من التأكل بالقرآن ولكن هذا من الإعانة على تعليم القرآن، فإذا وجد من يعلم القرآن ويحتاج إلى مساعدة فلا بأس أن يعطى من بيت المال أو من أهل المحلة أو أهل القرية ما يعينه على ذلك، حتى يتفرغ وحتى يبذل وسعه في تعليم أبناء البلد أبناء القرية كتاب ربهم عز وجل، فهذا ليس من باب التأكل ولكن هو من باب الإعانة على هذا الخير العظيم حتى يتفرغ للتعليم وحتى يكفى المئونة.. حتى لا يحتاج إلى ضياع بعض الأوقات في طلب الرزق وطلب حاجة بيته وأهله، هذا كله من باب التعاون على البر والتقوى.\nوكذلك إذا قرأ على المريض يعطى أيضاً، إذا قرأ على المريض ورقاه فلا بأس أن يعطى لحديث: «إن أحق ما أخذتم عليه أجراً كتاب الله» ولقصة اللديغ الذي قرأ عليه بعض الصحابة واشترطوا جعلاً فأمضاه النبي عليه الصلاة والسلام.\nفالحاصل: أن إعطاء الطبيب الذي يقرأ على الناس الذي يعالج بالقراءة إعطائه شيء على هذا الأمر لا بأس به كما يعطى المعلم، وهذا كله من باب التعاون على ما ينفع الناس، فالمعلم ينفع الناس بتعليمهم وتوجيههم وإرشادهم، والذي يقرأ على المريض كذلك يحتاج إلى مساعدة حتى يتفرغ لهذا الأمر ويقرأ على هذا وهذا وهذا، وقد جعل الله في كتابه شفاء لمرض القلوب ومرض الأبدان، وإن كان أنزل في الأصل والأساس لإنقاذ القلوب وتطهيرها من الشرك والمعاصي وتوجيهها إلى الخير لكن الله جعل فيه سبحانه وتعالى أيضاً شفاء لأمراض الأبدان، جعل كتابه العظيم شفاء للقلوب شيء لكثير من أمراض الأبدان إذا استعمله المؤمن مخلصاً لله عز وجل عالماً أنه سبحانه هو الذي يشفي وأن بيده كل شفاء سبحانه وتعالى.\nفإذا أعطي المعلم ما يعينه وأعطي الراقي الذي يعالج الناس بالرقية ما يعينه فلا بأس بذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5651/اجرة-الراقي-ومعلم-القران-اعانة-لا-باس-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_080/08001.mp3","categories":["صلاة التطوع","الإجارة"]},{"id":8147,"question":"الأخت في الله (ف. ن. ح) من بلاد زهران بعثت بهذه الرسالة تقول فيها: هل صلاة الضحى تصلى كل يوم، وهل هي من السنن الرواتب أم لا؟","title":"مشروعية صلاة الضحى","answer":"الجواب: صلاة الضحى سنة مؤكدة، النبي أوصى بها عليه الصلاة والسلام، أوصى بعض أصحابه أوصى أبا هريرة و أبا الدرداء بصلاة الضحى، وكان يصليها بعض الأحيان عليه الصلاة والسلام، فهي سنة مؤكدة أوصى بها عليه الصلاة والسلام، فإذا تيسر للمؤمن والمؤمنة فعلها فهذا خير عظيم، ولكن غير لازمة، لو فعلها بعض الأحيان وتركها بعض الأحيان أو تركها بالكلية لا حرج، لكنها سنة مؤكدة مثل سنة الفجر.. سنة الظهر.. سنة المغرب.. سنة العشاء، كلها سنن مؤكدة فيها خير عظيم، ولكنها غير فريضة، لو تركها الإنسان لا يأثم، والأفضل تكون بعد ارتفاع النهار، إذا اشتد النهار وارتفع النهار قبل زوال الشمس بنص ساعة.. ساعة، المقصود أنه إذا ارتفع الضحى أفضل، وإن صلاها مبكراً بعد ارتفاع الشمس قيد رمح حصل المقصود، وكلما ... أخرها حتى يرتفع النهار فهو أفضل، ثنتين أو أربع ركعات أو ست ركعات أو ثمان ركعات، ليس لها حد، لكن أقلها ركعتان، وإذا صلى أكثر صلى أربع ركعات أو ست ركعات أو ثمان ركعات أو أكثر من هذا فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/5955/مشروعية-صلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_090/09007.mp3","categories":["صلاة التطوع"]},{"id":8185,"question":"شيخ عبد العزيز ألاحظ في بعض من رسائل السادة المستمعين أنهم يحملون ركعتي الاستخارة كثيراً من المسئولية حتى لو أقدموا على عمل فيه شيء من التحريم فمثلاً أخونا سعيد يوسف محمود من بيشة سبت العلايا بعث برسالة طويلة يقول فيها: أعرض عليكم أنني مغترب وتركت الأهل والوطن للبحث عن لقمة العيش وكنت أعمل في شركة وبعد فترة طلبت مني الشركة البحث عن كفيل للعمل لديه ونقل كفالتي لأنها سوف تقوم بتصفية الشركة وقد جلست مدة ثلاثة أشهر في البحث عن عمل آخر فلم أجد وأخيراً بعد جهد وعناء ومشقة حصلت عملاً في جهة معينة، وقبل أن أتقدم في هذا العمل استخرت الله وصليت ركعتي الاستخارة وقبل أن يتم نقل الكفالة على هذه الجهة كان أمامي عقبات كثيرة جداً وكنت متوقعاً عدم نقل الكفالة ولكن تسهلت الأمور بشكل لم أتوقعه وتم فعلاً نقل الكفالة وبعد أن استلمت العمل قال الناس: بأن العمل في مثل جهتك يعد حرام وطبعاً أنا لم أعرف ذلك نهائياً من قبل وأنا حالياً مستقيل من عملي في بلدي ومن هنا أنا لا أستطيع ترك هذا العمل أو نقل كفالة على عمل آخر بسبب ليس في يدي ولكن بسبب الأنظمة المتبعة بل السفر نهائياً إلى بلدي ما موقفي من هذا العمل وما رأي سماحتكم في ركعتي الاستخارة ولكن كلما أرجوه التكرم علي بإجابة واضحة جزاكم الله خيراً؟","title":"حكم العمل في مجال محرم للحاجة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا ريب أن المؤمن يبتلى في هذه الدنيا تارة بالأمراض وتارة بالحاجة والفقر وتارة بتعسر الأعمال التي تعينه على لقمة العيش وتارة بغير ذلك.\nفالواجب على المؤمن عند الابتلاء التحمل والصبر ولزوم الحق والحذر مما حرم الله  وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: عجباً لأمر المؤمن إن أمره كله له خير وليس ذلك لأحد إلا للمؤمن إن أصابته سراء شكر فكان خيراً له وإن أصابتهه ضراء صبر فكان خيراً له، فعليك يا أخي أن تشكر الله لما يسر من النعمة والسراء وأن تتحمل الصبر على ما يسوءك من قلة العمل أو صعوبة العمل أو صعوبة لقمة العيش أو غير هذا مما يسوء الإنسان لابد من الصبر والتحمل.\nوأما استخارتك في عمل اشتبه عليك أمره هل تعمله أو ما تعمله فلا بأس مشروعة الاستخارة في الأمور التي تشتبه كأن يريد السفر ويشتبه عليه السفر هل هو صالح أم لا فيستخير، أو يريد الزواج بامرأة من بني فلان فيستخير هل زواجه بها مناسب وطيب أم لا أو يريد معاملة إنسان في تجارة فيستخير هل معاملته مناسبة أم لا؛ لا بأس.\nهذا العمل الذي استخر فيه إذا كان قد اشتبه عليك ولم تعلم أنه مناسب واستخرت الله جل وعلا أن يشرح صدرك لما يرضيه وأن يسهل لك هذا الأمر إن كان صالحاً مباحاً فهذا لا بأس به، ثم إذا تبين لك بعد ذلك أن العمل غير صالح فلا مانع حينئذ من أن تستقيل وتؤثر ما عند الله بل يجب عليك ذلك ولكن بعد التثبت بعد سؤال أهل العلم بعد التبصر فإذا ظهر لك بالأدلة الشرعية أو بفتوى أهل العلم المعتبرين أن هذا العمل لا يجوز كالعمل في البنوك الربا وكالعمل في بيع الخمور وبيع التدخين أو حلق اللحى أو ما أشبه ذلك مما هو محرم فإذا عرفت أن العمل محرم فاترك العمل ويعطيك الله أبرك منه يقول الله سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا  ۝  وَيَرْزُقْهُ مِنْ حَيْثُ لا يَحْتَسِبُ [الطلاق:2-3] يقول سبحانه: وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4] وجاء عنه عليه الصلاة والسلام أنه قال: من ترك شيئاً لله وفي لفظ: من ترك شيء اتقاء الله عوضه الله خير منه فإذا كان هذا العمل اتضح لك بالأدلة الشرعية أو بفتوى أهل العلم المعتبرين أنه عمل لا يجوز فعليك أن تستقيل منه وتلتمس عملاً آخر ولا تقل: أنا ما أستطيع ليس لك أن تعيش من الحرام بل عليك أن تلتمس الحلال ولو سألت الناس عند الضرورة ولو سألت الناس عند الضرورة يقول النبي صلى الله عليه وسلم لـقبيصة بن مخارق لما سأله: يا قبيصة إن المسألة لا تحل إلا لأحد ثلاثة: رجل تحمل حمالة فحلت له المسألة حتى يصيبها ثم يمسك، ورجل أصابته جائحة -اجتاحت ماله- فحلت له المسألة حتى يصيب قواماً من العيش أو قال: سداداً من عيش ثم يمسك، ورجل أصابته فاقة -يعني حاجة- حتى يقول ثلاثة من ذوي الحجى قومه: لقد أصابت فلاناً فاقة فحلت له المسألة حتى يصيبها ثم يمسكوإذا كنت لست من أهل الغنى في السابق بل أنت من أهل الحاجة في السابق ولست من أهل الثروة فأنت أعلم بنفسك تحل لك المسألة من أجل الحاجة والفاقة ولو ما شهد لك ثلاثة ما دمت تعلم أنك من أهل الفاقة وأنه ليس عندك شيء يقوم بحالك فلا مانع من أن تسأل ذوي الخير ومن تظن أنهم يستجيبون إما لإعطائك من الزكاة وإما مما أعطاهم الله من المال حتى تجد ما يغنيك ولا تلح بل تسأل ما يسد الحاجة ومتى حصل لك ما يسد الحاجة كففت عن السؤال إلى وقت آخر تحتاج فيه مع طلب العمل والجد في طلب العمل وطلب الرزق بالوسائل والطرق التي تستطيعها مما أباح الله عز وجل.\nأما أنت تبقى في عمل محرم لأنك فقير فليس لك ذلك. وفق الله الجميع نعم.\nالمقدم: اللهم آمين. سماحة الشيخ إذا كان العمل يختلط حلاله بحرامه ما الحكم والحالة هذه؟\nالشيخ: ينظر في الأمر إن أمكنه أن يقتصر على الحلال ويميزه من الحرام يعمل بذلك، وإن كان لا يتمكن إلا من الحرام مع الحلال فعليه أن يستقيل ويبتعد.\nالمقدم: نفس الحكم السابق.\nالشيخ: نعم.\nالمقدم: بارك الله فيكم، جزاكم الله خيراً.\nالشيخ: وإياك.","link":"https://binbaz.org.sa/fatwas/5992/حكم-العمل-في-مجال-محرم-للحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_106/10601.mp3","categories":["صلاة التطوع"]},{"id":8378,"question":"نعود في هذه الحلقة إلى رسالة الأخت فاتن سعيد من الجمهورية العراقية بغداد، أختنا سبق أن عرضنا بعضًا من أسئلتها في حلقةٍ مضت، وها نحن نعود إلى بقية الأسئلة، تقول في سؤالها لهذه الحلقة، لدي كتاب يسمى: ضياء الصالحين، فيه جميع الصلوات والتسابيح والأدعية إلى آخر، بجميع الأيام والشهور، ولكل يومٍ توجد صلاة اليوم والليلة، وأنا أصليها جميعها دون استثناء، فهل ما جاء في هذا الكتاب صحيح؟ وهل صلاتي صحيحة، أفيدونا أفادكم الله؟","title":"ما المشروع من الذكر والنوافل في اليوم والليلة؟","answer":"الجواب: هذا الكتاب لم نقف عليه، ولا نعرف ما اشتمل عليه من الأحاديث الصحيحة أو غيرها، ولكن سنة الرسول ﷺ وضحت ما ينبغي أن يعمله المؤمن في ليله ونهاره، فقد صحت عن رسول الله ﷺ الأحاديث بما كان يعمل عليه الصلاة والسلام، وبما أمر الله به العباد وشرعه لهم، فمن ذلك: سنة الضحى، كان ﷺ يوصي الكثير من أصحابه بسنة الضحى، فهي سنةٌ مؤكدة، وربما صلاها وربما تركها عليه الصلاة والسلام، وقد صلاها يوم الفتح ثمان ركعات، وقالت عائشة رضي الله عنها: كان يصلي الضحى أربعاًً ويزيد ما شاء الله وأوصى أبا هريرة وأبا الدرداء بصلاة الضحى، وقال عليه الصلاة والسلام لما ذكر الصدقة عن السلاميات: وأن على كل سلامى من الناس صدقة، وأن بكل تسبيحة صدقة، وكل تحميدة صدقة، وكل تهليلة صدقة، وكل تكبيرة صدقة، وأمرر بمعروف صدقة، ونهي عن منكر صدقة .... إلى آخر الحديث، قال: ويكفي من ذلك ركعتان تركعهما من الضحى فصلاة الضحى مؤكدة وفيها خير عظيم، وأقلها ركعتان، فإذا صلى أربعاً أو ستاً أو ثمان، أو أكثر من ذلك، فكله خير.\nكذلك ما بعد الظهر كله محل صلاة، ويستحب له أن يصلي قبل الظهر أربعاً، وبعدها أربعاً، وهذا عام للرجال والنساء جميعاً، والراتبة أربع قبل الظهر وثنتان بعدها، هذه راتبة، أربع قبل الظهر وثنتان بعدها، كان يحافظ عليها النبي ﷺ، وقال عليه الصلاة والسلام: من صلى أربعاً قبل الظهر وأربعاً بعدها حرمه الله على النار فإذا صلى أربعاً قبلها وأربعاً بعدها، فهذا خير، وفيه فضل، كذلك في العصر، يقول عليه الصلاة والسلام: رحم الله امرأً صلى أربعاً قبل العصر، فصلاة أربع قبل العصر فيها فضل أيضاً.\nكذلك بين كل أذانين يصلي ركعتين: بين كل أذانين صلاة، بين كل أذانين صلاة، بين كل أذانين صلاة، ثم قال: لمن شاء لئلا يظن أنها واجبة، فيستحب أن يصلي بين الأذانين ما تيسر.\nوكذلك بعد المغرب ركعتان، يسن أن يصلي بعد المغرب ركعتين، وبعد العشاء ركعتين راتبة، كان النبي يحافظ عليها ﷺ، ثنتين بعد المغرب وثنتين بعد العشاء.\nوإذا صلى زيادة على ذلك، بين المغرب والعشاء، فكله خير، لو صلى مائة ركعة، كله خير، الحمد لله، وهكذا بعد العشاء كان يتهجد عليه الصلاة والسلام، ربما أوتر من أوله، وربما أوتر من وسطه، وربما أوتر من آخره، واستقر وتره ﷺ في آخر حياته عليه الصلاة والسلام في السحر يعني: في آخر الليل وهو أفضل، وقد قال عليه الصلاة والسلام: من خاف أن لا يقوم من آخر الليل فليوترر أوله، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل فالليل كله محل تهجد ومحل عبادة، وكان عليه الصلاة والسلام يصلي في الغالب إحدى عشرة ركعة في الليل، بعد العشاء، والغالب في آخر الليل، إحدى عشرة ركعة، يسلم من كل ثنتين عليه الصلاة والسلام، ويوتر بواحدة، وربما أوتر بثلاث عشرة، وربما أوتر بأقل من ذلك كالسبع والخمس، فالمؤمن مخير، وهكذا المؤمنة إن صلى واحدة أجزأت في الوتر بعد العشاء، وإن صلى ثلاث فهو أفضل، وإن صلى خمساً فهو أفضل، وهكذا.\nهذه الصلوات المشروعة في الليل والنهار من النافلة غير الفريضة، فأنت أيها الأخت في الله سمعت الآن ما جاءت به السنة عن رسول الله عليه الصلاة والسلام، في الصلوات النوافل، فإذا كنت تصلين مثل هذه الصلوات فهذا خير عظيم غير الفريضة. أما الفريضة فمعلومة: الظهر أربع والعصر أربع والمغرب ثلاث والعشاء أربع والفجر اثنتان، سوى السنة الراتبة، هذه الصلاة في الفريضة. أما القراءة فيستحب لك أن تقرئي القرآن كثيراً، مع التدبر، مع التعقل، يقول الله جل وعلا: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9] ويقول سبحانه: كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ مُبَارَكٌ لِيَدَّبَّرُوا آيَاتِهِ وَلِيَتَذَكَّرَ أُوْلُوا الأَلْبَابِ [ص:29] فيستحب لك الإكثار من القراءة بالتدبر والتعقل في الآيات التي تقرئينها، فإن فيه ذكر الجنة، ذكر النار، بيان أعمال الجنة، أعمال النار، بيان صفات المتقين، صفات الكافرين، صفات المنافقين، فالمؤمن يتدبر، وهكذا المؤمنة، فيعمل بصفات الأبرار والأخيار، ويبتعد عن صفات الأشرار والمنافقين، ويتذكر الجنة ويشتاق إليها ويعمل لها، وإذا سمع النار تعوذ بالله منها وابتعد عن أعمال أهلها، وإذا ختمت كل ثلاث أو كل سبع، هذا طيب، أو كل عشر، أو كل خمسة عشر، أو كل شهر، كله طيب. وينبغي أيضاً الإكثار من ذكر الله، والصلاة على النبي ﷺ في جميع الأوقات، الإكثار من ذكر الله: سبحان الله والحمد لله ولا إله إلا الله والله أكبر، ولا حول ولا قوة إلا بالله، سبحان الله وبحمده سبحان الله العظيم، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد يحيي ويميت وهو على كل شيءٍ قدير، يستحب الإكثار من هذا الذكر، كما كان النبي يفعل عليه الصلاة والسلام، والله يقول جل وعلا: يَا أَيُّهَا الَّذِينَ آمَنُوا اذْكُرُوا اللَّهَ ذِكْرًا كَثِيرًا ۝ وَسَبِّحُوهُ بُكْرَةً وَأَصِيلًا [الأحزاب:41-42] ويقول جل وعلا في كتابه العظيم: فَإِذَا قُضِيَتِ الصَّلاةُ فَانتَشِرُوا فِي الأَرْضِِ وَابْتَغُوا مِنْ فَضْلِ اللَّهِ وَاذْكُرُوا اللَّهَ كَثِيرًا لَعَلَّكُمْ تُفْلِحُونَ [الجمعة:10] ويقول لما عدد صفات المؤمنين، قال: وَالذَّاكِرِينَ اللَّهَ كَثِيرًا وَالذَّاكِرَاتِ أَعَدَّ اللَّهُ لَهُمْ مَغْفِرَةً وَأَجْرًا عَظِيمًا [الأحزاب:35] ويقول ﷺ: سبق المفردون، قيل: يا سول الله ما المفردون؟ قال: الذاكرون الله كثيراً والذاكرات.\nفالذكر لله أمره عظيم، وفضله كبير، وهكذا الإكثار من الصلاة والسلام على رسول الله عليه الصلاة والسلام، الله يقول جل وعلا: إِنَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيمًا [الأحزاب:56] ويقول عليه الصلاة والسلام: من صلى علي واحدة، صلى الله عليه بها عشراً وجاءه جبرائيل فبشره أن من صلى عليه واحدة، صلى الله عليه بها عشراً، ومن سلم عليه واحدة، سلم الله عليه بها عشراً. فهذا خير عظيم، صلى الله وسلم عليه وعلى آله وأصحابه وأتباعه بإحسان.\nهذا شيء مما جاء في الكتاب والسنة، من فضل الذكر، وفضل الصلاة على النبي ﷺ، وما يتعلق بالصلوات النافلة في الليل والنهار، نسأل الله أن يوفقنا وإياك وسائر المسلمين لما فيه الخير والصلاح والسعادة العاجلة والآجلة.","link":"https://binbaz.org.sa/fatwas/6227/ما-المشروع-من-الذكر-والنوافل-في-اليوم-والليلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_115/11502.mp3","categories":["صلاة التطوع","الأدعية والأذكار"]},{"id":8425,"question":"ما حكم من أتى بركعتين بعد صلاة الفجر؟ وهل تجب على من فاتته تحية دخول المسجد قبل الصلاة؟ ومتى وقتها؟","title":"حكم قضاء تحية المسجد","answer":"الجواب: التحية لا تقضى، تحية المسجد إذا جاء وهم يصلون كفته الفريضة، ولا حاجة إلى أن يقضي تحية المسجد، فالصلاة تقوم مقامها الفريضة، وإذا لم يصل الراتبة (سنة الفجر)، بأن جاء والإمام قد دخل في الصلاة فإنه مخير إن شاء صلاها بعد الصلاة، وإن شاء صلاها بعد ارتفاع الشمس، كما ثبت ذلك عن النبي عليه الصلاة والسلام، أعني السنة الراتبة التي تشرع قبل صلاة الفجر وهما ركعتان، إذا فاتت بأن جاء من بيته إلى المسجد وقد دخل الناس في الصلاة ولم يصلها في البيت، فإنه يصليها بعد الصلاة إذا شاء؛ فقد أقر النبي ﷺ من فعلها بعد الصلاة، وإن شاء أخرها حتى يصليها بعد ارتفاع الشمس، الأمر في هذا واسع والحمد لله، أما التحية فلا تقضى، تحية المسجد لا تقضى. نعم.","link":"https://binbaz.org.sa/fatwas/6309/حكم-قضاء-تحية-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11902.mp3","categories":["صلاة التطوع"]},{"id":8426,"question":"وحكم من أتى بركعتين بعد صلاة الفجر؟","title":"حكم صلاة ركعتين بعد صلاة الفجر","answer":"الجواب: فيه تفصيل: إن كان أتى بهما لأنهما سنة الفجر فلا بأس وهذا مشروع، أما أن يتطوع بركعتين بعد الفجر لا، غير مشروع، منهي عن ذلك. نعم.\nالمقدم: بارك الله فيك.","link":"https://binbaz.org.sa/fatwas/6310/حكم-صلاة-ركعتين-بعد-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_119/11903.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":8553,"question":"هذه رسالة وردت من الأخ خالد ناصر أبو بكر ، من جمهورية اليمن الديمقراطية يقول أولاً: هل على المرتد قضاء الصلاة أو الصيام إذا عاد إلى الإسلام وتاب إلى الله؟","title":"حكم قضاء المرتد ما فاته من صلاة وصيام بعد عودته","answer":"الجواب: ليس عليه قضاء، من تاب تاب الله عليه، إذا ترك الإنسان الصلاة أو أتى بناقض من نواقض الإسلام ثم هداه الله وتاب فإنه لا قضاء عليه، هذا هو الصواب من أقوال أهل العلم، الإسلام يجب ما قبله، والتوبة تهدم ما كان قبلها، قال الله سبحانه: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] فبين سبحانه أن الكافر إذا أسلم غفر الله له ما قد سلف، والنبي ﷺقال: التوبة تجب ما قبلها والإسلام يهدم ما كان قبله، فالحمد لله. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6636/حكم-قضاء-المرتد-ما-فاته-من-صلاة-وصيام-بعد-عودته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20609.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":8556,"question":"هذه رسالة وردت من الأخ خالد ناصر أبو بكر ، من جمهورية اليمن الديمقراطية يقول أولاً: هل على المرتد قضاء الصلاة أو الصيام إذا عاد إلى الإسلام وتاب إلى الله؟","title":"حكم قضاء المرتد ما فاته من صلاة وصيام بعد عودته","answer":"الجواب: ليس عليه قضاء، من تاب تاب الله عليه، إذا ترك الإنسان الصلاة أو أتى بناقض من نواقض الإسلام ثم هداه الله وتاب فإنه لا قضاء عليه، هذا هو الصواب من أقوال أهل العلم، الإسلام يجب ما قبله، والتوبة تهدم ما كان قبلها، قال الله سبحانه: قُلْ لِلَّذِينَ كَفَرُوا إِنْ يَنتَهُوا يُغْفَرْ لَهُمْ مَا قَدْ سَلَفَ [الأنفال:38] فبين سبحانه أن الكافر إذا أسلم غفر الله له ما قد سلف، والنبي ﷺقال: التوبة تجب ما قبلها والإسلام يهدم ما كان قبله، فالحمد لله. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/6636/حكم-قضاء-المرتد-ما-فاته-من-صلاة-وصيام-بعد-عودته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_206/20609.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":8730,"question":"أختنا تسأل سؤالاً آخر وتقول: ما هي الأوقات المستحبة لصلاة التطوع، وهل تجوز الصلاة قبل المغرب بساعة صلاة تطوع؟","title":"ما الأوقات المستحبة لصلاة التطوع؟","answer":"الجواب: كل الليل والنهار محل تطوع كل الليل والنهار، الله جل وعلا جعل الليل والنهار خلفة لمن أراد أن يذكر أو أراد شكوراً سبحانه وتعالى، كما قال  في كتابه العظيم: وَهُوَ الَّذِي جَعَلَ اللَّيْلَ وَالنَّهَارَ خِلْفَةً لِمَنْ أَرَادَ أَنْ يَذَّكَّرَ أَوْ أَرَادَ شُكُورًا [الفرقان:62].\nلكن يستثنى من ذلك أوقات النهي: ما بين صلاة الفجر إلى ارتفاع الشمس هذا وقت نهي عن الصلاة.\nكذلك ما بين صلاة العصر إلى غروب الشمس محل نهي عن الصلاة.\nكذلك عند قيامها قرب الظهر عند وقفة الشمس يعني عند توسطها كبد السماء وهي مدة قليلة، هذا وقت نهي أيضاً.\nأما بقية الأوقات مثل الضحى بعد ارتفاع الشمس إلى وقوف الشمس، بعد الظهر كل ما بين الظهر والعصر كله محل صلاة، الليل كله محل صلاة، فصلاة الضحى متأكدة وسنة مؤكدة، هكذا التهجد بالليل وبين العشاءين كله محل عبادة، فيه خير كثير وفضل كبير، لكن أوقات النهي لا يصلى فيها إلا لسبب كصلاة الطواف لمن طاف بعد العصر أو بعد الصبح يصلي صلاة الطواف، مثل سنة الوضوء لمن توضأ يصلي ركعتين سنة الوضوء ولو بعد العصر والصبح مثل لو كسفت الشمس بعد العصر شرع أن يصلى لها صلاة الكسوف في أصح قولي العلماء، مثل تحية المسجد لو دخل مسجد لأجل الدرس بعد العصر أو ليجلس فيه إلى الغروب سن له أن يصلي تحية المسجد، هذا مستثنى ويقال لها: ذوات الأسباب، هذا الصحيح أنها تستثنى ولا بأس بها في أوقات النهي على الصحيح من أقوال العلماء. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6883/ما-الاوقات-المستحبة-لصلاة-التطوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_135/13503.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":8863,"question":"شيخ عبدالعزيز بين كل فترة وأخرى، وبين كل آونة وآونة تعود إلينا هذه الوصية المزعومة والتي تصدر دائماً تحت اسم الشيخ أحمد حامل مفاتيح حرم رسول الله ﷺ، هذه الوصية تنتشر كما قلت وكلما غابت عادت، يقول في بدايتها هذه المرة: إنه كان في ليلة يقرأ القرآن في حرم رسول الله ﷺ وفي تلك الليلة غلبه النوم ورأى في نومه أن رسول الله ﷺ آت، وقال له: إنه قد مات في هذا الأسبوع أربعون ألفاً من الناس ومن غير الجان، إنهم ماتوا موتة الجاهليين.. ويستمر على هذا الأسلوب.الملاحظ أنه بأسلوب قريب من العامية، أرجو من سماحة الشيخ أن يتفضل بتنبيه الناس على هذه الوصية خاصة وعلى ما ماثلها جزاكم الله خيراً؟","title":"بطلان الوصية المنسوبة للشيخ أحمد حامل مفاتيح الحرم النبوي","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذه الوصية قد علمناها من دهر طويل، وهي كما ذكرتم في السؤال كلما ذهبت عادت وكلما نسيت بعثت، ولها مروجون من الناس في سائر أقطار الدنيا باسم خادم الحجرة النبوية، وتارة باسم حامل مفاتيح الحجرة النبوية أو المسجد النبوي، وله فيها عبارات وألفاظ متنوعة، ويقول: إن الرسول صلى الله عليه وسلم أتاه وقال له كذا وكذا، إنه مات أربعون ألفاً ميتة جاهلية، ويقول: إنه يطلع نجم حول الشمس وإنه متى طلع هذا النجم ترونه ولا تقبل الصلوات والعبادات بعد ذلك، ويقول: إن من جاءته هذه الوصية فأهملها وأضاعها يأثم إثماً كبيراً، ومن بلغته ولم ينشرها يخرج من رحمة الله، ويقول: من وزع منها خمساً وعشرين نسخة حصل له كذا وكذا وكذا.. إلى غير هذا من الخرافات، وهذه وصية باطلة لا أساس لها وليس هناك أحمد خادم حجرة النبي ﷺ، كل هذا كذب ، ليس هناك شخص يقال له أحمد وليس هناك وصية، وإنما هذه من كذب الكذابين، أناس يفترون الكذب ويكتبون مثل هذه الوصايا الباطلة وينسبونها إلى من شاءوا من الناس وكل ذلك لا أصل له، وقد سبق أن كتبنا في إبطال هذه الوصية كتابة من أكثر من عشر سنوات ووزعناها في الداخل والخارج بعدة لغات ليفهم المسلمون بطلانها وأنها لا أساس لها، وأن الواجب على من وقعت في يده أن يمزقها وأن يتلفها وينبه الناس على بطلانها.\nالمصحف الذي هو كلام الله  لو أن الإنسان ما كتبه ما عليه شيء ولا بأس عليه، وهذا يقول: من بلغته ولم ينشرها يخرج من رحمة الله!! هذا من أبطل الباطل.\nويقول: من كتب منها خمسة وعشرين نسخة ووزعها يحصل له كذا وكذا .. فوائد، وكذا وكذا وكذا، ومن أعرض عنها يفقد فوائد ويموت ولده وإلا يموت كذا، وإلا يموت كذا، وإلا يصيبه كارثة، كل هذا باطل، القرآن نفسه لو وزع منه مائة نسخة أو كذا وكذا فهو مأجور لكن لا يحصل له هذا الذي قال هذا الكذاب، ولا يكون عليه خطر لو لم يوزع، لو عاش الدهر كله ولم يوزع المصحف لا بأس عليه، للمصحف من يوزعه ومن يبيعه ومن ينشره بين الناس ولو أنه اشتراه من السوق وقرأ فيه ولم يوزعه فلا حرج عليه، ولو كتبه وقرأ فيه ولم يوزعه فلا حرج عليه، كيف بهذه الوصية المكذوبة الباطلة من لم يوزعها يكون عليه كذا وكذا!\nفالمقصود أن هذه الوصية باطلة ومكذوبة ولا أساس لها ولا يجوز اعتقاد هذا الكلام ولا يجوز توزيعها ولا نشرها بين الناس، بل يجب إتلافها والتنبيه على بطلانها، رزق الله الجميع العافية والهدى.\nالمقدم: الواقع سماحة الشيخ مصداقاً لما تفضلتم به أذكر أنني عرضت هذه الرسالة في نفس الفترة التي تفضلتم بتحديدها وهي ما يقرب من عشر سنوات، وقبل فترة أيضاً ناقشناها ونحن هنا في هذا البرنامج نحاربها فضلاً عن توزيعنا لها، وها نحن بحمد الله بصحة جيدة ونذهب ونعود إلى أعمالنا ونحن وأولادنا وأقاربنا وأموالنا بخير وعلى خير.\nالشيخ: الحمد لله، وهذا مثل ما تفضلتم كله واقع، ونحن نحاربها من عشرات السنين ولا رأينا إلا خيراً، كل هذا شيء باطل لا ينبغي التعلق به، نعم، نسأل الله العافية. نعم.\nالمقدم: لعله من المناسب سماحة الشيخ أن تتفضلوا بالتنبيه إلى خطر المطبوعات على العقيدة وعلى الأمن، وعلى أيضاً ما يخص أفكار الناس؟\nالشيخ: ينبغي لمن وجد مطبوعات تلصق بالجدران أو توزع بين الناس أن يسأل عنها أهل العلم وأن لا يعتمد عليها إلا عن بصيرة، إن كان من أهل العلم عرفها بحمد الله ونبه على بطلان الباطل وعلى صحة الصحيح، أما إن كان من العامة فلا ينبغي له أن يتقبل كل ما يوزع بين الناس، بل الواجب أن يسأل أهل العلم في بلاده وفي غير بلاده الذين يثق بهم ويعرف علمهم وفضلهم، يسألهم عما قد يقع في يده، وقد بلغني أن الرسالة التي توزع التي باسمي فيما يتعلق بالأذكار عقب الصلاة، بلغني أن بعض الناس كتب عليها من وزع منها كذا وكذا فله كذا، ومن نشر منها كذا وكذا فله كذا، وهذا كله باطل لا أصل له، ولم أكتب هذا وإنما كتبت بيان الذكر المحفوظ عن النبي عليه الصلاة والسلام بعد الصلوات، أما الزيادة على هذا من فعل كذا أو من نشرها أو من كتب منها كذا وكذا.\nفهذا إن كان وقع فهو باطل لا أساس له ولم أكتبه ولم أمر به، بل هذا من كذب الكذابين، ومن بهتان أهل الباطل نسأل الله العافية.\nوالحاصل أن هذه المسائل التي أشرت إليها وهي الملصقات والموزعات من رسائل وكتب والنشرات يجب الحذر منها، فلا يقبل منها إلا ما كان ثابتاً صحيحاً عن رسول الله عليه الصلاة والسلام مما يبينه أهل العلم العارفون بسنة الرسول عليه الصلاة والسلام، الله المستعان.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7018/بطلان-الوصية-المنسوبة-للشيخ-احمد-حامل-مفاتيح-الحرم-النبوي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_138/13801.mp3","categories":["صلاة التطوع","فتاوى متنوعة","مسائل متفرقة في العقيدة"]},{"id":8864,"question":"هنا رسالة وصلت إلى البرنامج من أحد الإخوة من البحرين يقول: (ط.ح.م.)، أخونا يقول: إذا فاتتني سنة الفجر فمتى أقضيها؟","title":"وقت قضاء سنة الفجر لمن فاتته","answer":"الجواب: إذا فاتت سنة الفجر فالمسلم مخير وهكذا المسلمة إن شاء صلاها بعد الصلاة، وإن شاء صلاها بعد ارتفاع الشمس وهو أفضل، وكل هذا ورد عن النبي ﷺ، ورد عنه أنه رأى من يصلي بعد الصلاة فأنكر عليه فقال: يا رسول الله! إنها سنة الفجر، فسكت عنه عليه الصلاة والسلام.\nوجاء عنه الأمر بقضائها بعد ارتفاع الشمس، وكل هذا بحمد لله سائغ، فمن صلاها بعد الصلاة فلا بأس، ومن أخرها حتى ترتفع الشمس فهو أفضل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7019/وقت-قضاء-سنة-الفجر-لمن-فاتته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_138/13802.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":9012,"question":"سمعت أن هناك صلاة نوافل راتبة وهي ثنتا عشرة ركعة، ومنها قبل الظهر وبعده وبعد المغرب، و هل التي تكون قبل الظهر معنى ذلك أنه بعد أذان الظهر أم قبل أن أصلي أم قبل الأذان، أفتوني في وقتها بالذات وعن هذه النوافل جزاكم الله خيراً؟","title":"ما السنن الرواتب؟ وما عدد ركعاتها؟","answer":"الجواب: الرواتب مثلما ذكرها السائل، الصواب: أنها اثنتا عشرة ركعة، منها: أربع قبل الظهر وثنتان بعد الظهر، وثنتان بعد المغرب وثنتان بعد العشاء، وثنتان قبل صلاة الصبح، هذه يقال لها: الرواتب، كان النبي ﷺ يحافظ عليها عليه الصلاة والسلام، وصح عنه عليه الصلاة والسلام أنه قال: من صلى ثنتي عشرة ركعة في يوم وليلة بني له بهن بيت في الجنة، وفي رواية: (تطوعاً)، وزاد الترمذي رحمه الله تفسير ذلك بهذه الرواتب: أربعاً قبل الظهر وثنتين بعدها، ثنتين بعد المغرب، ثنتين بعد العشاء، ثنتين قبل صلاة الصبح، فالمشروع للمؤمن والمؤمنة الحفاظ على هذه الرواتب حتى يقتدي بالرسول ﷺ في ذلك، ويتأسى به في ذلك عليه الصلاة والسلام، أربع قبل الظهر، يعني: بعد الزوال ولو قبل الأذان، ما دام زالت الشمس إذا صلاها حصل المطلوب، أو صلاها بعد الأذان، المشروع أن تكون قبل الفريضة يصليها قبل الفريضة تسليمتين وتسليمة بعدها، ويصلي ثنتين بعد المغرب وثنتين بعد العشاء، وثنتين قبل صلاة الصبح، هذه هي الرواتب. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7170/ما-السنن-الرواتب-وما-عدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_147/14705.mp3","categories":["صلاة التطوع"]},{"id":9138,"question":"السؤال الثاني في رسالة الأخ عبدالعزيز حسين إبراهيم سوداني مقيم بمدينة رابغ يقول فيه: إنني دائماً أشاهد عامة الناس بعد صلاة الفرض يغير محل صلاته ليصلي صلاة النفل، ما حكم ذلك؟ وما هو فضله، أفيدونا أفادكم الله؟","title":"حكم أداء النافلة في مكان آخر غير مكان الفريضة","answer":"الجواب: ثبت عن ابن عمر رضي الله تعالى عنهما ما يدل على أن الرسول ﷺ كان يفعل ذلك؛ لأجل تشهد له البقاع، ولحكم أخرى الله يعلمها ، فإذا غير مكانه فحسن، إذا تيسر يعني أن ينتقل من محل فريضة إلى محل آخر يتطوع فيه فهذا فعله النبي ﷺ، فيما ذكره ابن عمر عنه رضي الله تعالى عنهما، ولا بأس بذلك بل هو مستحب إذا تيسر ذلك. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7300/حكم-اداء-النافلة-في-مكان-اخر-غير-مكان-الفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23003.mp3","categories":["صلاة التطوع"]},{"id":9141,"question":"السؤال الثاني في رسالة الأخ عبدالعزيز حسين إبراهيم سوداني مقيم بمدينة رابغ يقول فيه: إنني دائماً أشاهد عامة الناس بعد صلاة الفرض يغير محل صلاته ليصلي صلاة النفل، ما حكم ذلك؟ وما هو فضله، أفيدونا أفادكم الله؟","title":"حكم أداء النافلة في مكان آخر غير مكان الفريضة","answer":"الجواب: ثبت عن ابن عمر رضي الله تعالى عنهما ما يدل على أن الرسول ﷺ كان يفعل ذلك؛ لأجل تشهد له البقاع، ولحكم أخرى الله يعلمها ، فإذا غير مكانه فحسن، إذا تيسر يعني أن ينتقل من محل فريضة إلى محل آخر يتطوع فيه فهذا فعله النبي ﷺ، فيما ذكره ابن عمر عنه رضي الله تعالى عنهما، ولا بأس بذلك بل هو مستحب إذا تيسر ذلك. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7300/حكم-اداء-النافلة-في-مكان-اخر-غير-مكان-الفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_230/23003.mp3","categories":["صلاة التطوع"]},{"id":9386,"question":"رسالة بتوقيع أحد الإخوة يقول: من شاب صالح، أخونا يقول: في فترة الشباب المبكر من العمر ارتكبت بعض المعاصي، وقد تبت إلى الله ولله الحمد وله الشكر، لكن لازال في نفسي شيء، وسمعت عن صلاة التوبة، أرجو أن تفيدوني نحو هذا جزاكم الله خيراً؟","title":"صفة صلاة التوبة","answer":"الجواب: التوبة تجب ما قبلها وتمحو ما قبلها والحمد لله، فلا ينبغي أن يكون في قلبك شيء من ذلك بل الواجب أن تحسن ظنك بربك وأن تعتقد أن الله جل وعلا تاب عليك إذا كنت صادقاً في توبتك؛ لأن الله يقول سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] فعلق الفلاح بالتوبة، ومن تاب فقد أفلح، وقال سبحانه: وَإِنِّي لَغَفَّارٌ لِمَنْ تَابَ وَآمَنَ وَعَمِلَ صَالِحًا ثُمَّ اهْتَدَىى[طه:82] وهو الصادق في خبره ووعده سبحانه وتعالى، وقال سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا عَسَى رَبُّكُمْ أَنْ يُكَفِّرَ عَنْكُمْ سَيِّئَاتِكُمْ وَيُدْخِلَكُمْ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الأَنْهَارُ [التحريم:8] الآية، و(عسى) من الله واجبة، فعليك أن تحسن ظنك بربك، وأن تعلم أنك تبت إذا كنت صادقاً في ذلك نادماً، وإياك والوساوس، والله جل وعلا يقول في الحديث الصحيح القدسي: أنا عند ظنن عبدي بي فينبغي أن تظن بالله خيراً، ويقول النبي ﷺ: لا يموتن أحدكم إلا وهو يحسن ظنه بالله فعليك بحسن الظن بالله.\nأما صلاة التوبة قد ثبت عن رسول الله عليه الصلاة والسلام من حديث الصديق  أنه قال: ما من عبد يذنب ذنباً ثم يتطهر فيحسنن الطهور ثم يصلي ركعتين ثم يتوب إلى الله من ذنبه إلا تاب الله عليه أو كما قال عليه الصلاة والسلام، فأنت قد تبت والحمد لله، وإن صليت وفعلت هذا مرة أخرى فلا بأس كله خير. نعم.\nالمقدم: إذاًَ صلاة التوبة صلاة مشروعة؟\nالشيخ: نعم.\nالمقدم: كيفيتها مرة أخرى شيخ عبد العزيز لو تكرمت؟\nالشيخ: ما من عبد يذنب ذنباً ثم يتطهر فيحسن الطهور ثم يصلي ركعتين ثم يستغفر الله إلا تاب الله عليه أو كما قال عليه الصلاة والسلام، وهذا أول حديث في مسند الصديق رضي الله عنه في مسند الصديق في مسند أحمد رضي الله عنه ورحمه، وهو حديث جيد لا بأس به من رواية علي عن الصديق . نعم.","link":"https://binbaz.org.sa/fatwas/7550/صفة-صلاة-التوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_157/15704.mp3","categories":["صلاة التطوع"]},{"id":9409,"question":"أخونا من ليبيا منذر يسأل أيضًا ويقول: هل تشرع صلاة الاستخارة مكررة أم تكفي مرة واحدة؟","title":"حكم تكرار صلاة الاستخارة","answer":"الجواب: تشرع مكررة حتى يطمئن قلبه وينشرح صدره لما يريد، ويستشير إخوانه الثقات المعروفين الذين يعتقد فيهم الخير، وأنهم يحبون له الخير يستشيرهم بعد الصلاة، يصلي ركعتين ويستخير ربه بما جاء في حديث جابر -والحديث معروف موجود في رياض الصالحين وغيره- ثم يستشير بعد الدعاء فإن انشرح صدره وإلا أعاد الصلاة وأعاد الاستشارة، وهكذا مرتين ثلاث أربع أكثر حتى يحصل له الطمأنينة والانشراح في الزواج أو في شراء بيت أو في سفر إلى بلد أو في إقامة شركة أو ما أشبهها من الأمور التي تشتبه عليه، فيستخير الله فيها ويستشير إخوانه الطيبين ثم يعمل ما يطمئن إليه قلبه وينشرح له صدره بعد الاستخارة وبعد الاستشارة. نعم.","link":"https://binbaz.org.sa/fatwas/7573/حكم-تكرار-صلاة-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_189/18905.mp3","categories":["صلاة التطوع"]},{"id":9433,"question":"وهذه رسالة وردت إلى البرنامج من محمد هاشم سعيد مصري يعمل باليمن يقول في رسالته: لقد وجدت في كتاب المجموعة المباركة تأليف عبده محمد باباً في فائدة تقول: عن رسول الله ﷺ أنه قال: من فاتته صلاة في عمره ولم يحصها فليقم في آخر جمعة من رمضان ويصلي أربع ركعات بتشهد واحد، يقرأ في الركعة الواحدة الفاتحة وسورة القدر عدد خمسة عشر مرة، وكذلك سورة الكوثر مثلها، ويقول في النية: نويت أن أصلي أربع ركعات كفارة لما فاتني من الصلاة فهل هذا صحيح أفتونا أثابكم الله؟","title":"ما صحة قضاء الصلوات في آخر جمعة من رمضان؟","answer":"الجواب: هذا لا أصل له، بل هو موضوع مكذوب، هذا ليس له أصل، بل هو من الكذب والباطل، وإذا فات الإنسان صلاة ولم يذكرها يتحرى، يتحراها ظهراً أو عصراً أو عشاءً أو مغرباً أو فجر، يتحراها يعمل بظنه ويصلي ما غلب على ظنه والحمد لله في أي وقت. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7608/ما-صحة-قضاء-الصلوات-في-اخر-جمعة-من-رمضان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23909.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":9517,"question":"له سؤال آخر يقول: أرى بعض الإخوة المصلين عندما يدخل المسجد في صلاة المغرب والشمس غاربة يصلي ركعتين فإذا قلت: لا تجوز الصلاة في هذا الوقت لأن الشمس تكون في هذه الحالة غاربة بين قرني شيطان قال لي: إنها تحية المسجد فهل يجوز له أن يصليها أم لا ؟","title":"حكم صلاة تحية المسجد قبل غروب الشمس","answer":"الجواب: إذا دخل المسلم المسجد العصر ليجلس حتى ينتظر المغرب فالسنة له أن يصلي ركعتين هذا هو الأفضل وهذا هو الصحيح من أقوال العلماء، لقول النبي ﷺ إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين بين الأذان والإقامة وهكذا في كل صلاة يسن أن يصلي ركعتين بين الأذان والإقامة . نعم .\nإلا الظهر فالأفضل أن يصلى أربعاً، إلا الظهر الأفضل أن يصلي قبلها أربعاً راتبة، ودخوله إذا كان بعد الغروب سنة أن يصلي ركعتين ما فيه خلاف، إن كان بعد الغروب يصلي ركعتين تحية المسجد وبين الأذان والإقامة، لكن الخلاف إذا كان قبل الغروب ما بعد غربت.\nالمقدم: ما مدى صحة هذا القول: أن الشمس تكون غاربة بين قرني شيطان؟\nالشيخ: هذا جاء في الحديث .... بين قرني شيطان وتغيب بين قرني شيطان أقول: جاء في الحديث أنها تطلع بين قرني شيطان وتغيب بين قرني شيطان وحينئذ يسجد لها الكفار، حينئذ يسجد لها الكفار ويعبدونها ويعظمونها عباد الشمس نسأل الله العافية. نعم.","link":"https://binbaz.org.sa/fatwas/7687/حكم-صلاة-تحية-المسجد-قبل-غروب-الشمس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_244/24406.mp3","categories":["صلاة التطوع"]},{"id":9620,"question":"تسأل أيضاً هذه السائلة، تقول: ما هي صفة صلاة الشكر، وصلاة الاستخارة؟","title":"هل توجد صلاة للشكر؟ وما صفة صلاة الاستخارة؟","answer":"الجواب: ما نعلم .. هناك صلاة للشكر، فيه سجود للشكر، أما صلاة للشكر ما نعرف ....، في صلاة التوبة، الإنسان إذا أذنب ذنباً، صلى ركعتين، وتاب إلى الله توبةً صادقة، مثلما يصلي في الركعات الأخرى، مثلما يصلي صلاة الضحى، تحية المسجد، صلاة الطواف، ركعتين يقرأ فيهما بالفاتحة وما تيسر من الآيات أو بعض السور، ويصلي كما يصلي بقية الصلوات، من ركوع وسجود وغير ذلك، هذا في صلاة التوبة.\nأما الشكر فله سجود، إذا بشر بشيء يسره بولد، بفتح قلعة للمسلمين، بانتصار المسلمين على عدوهم، بغير هذا مما يسره، سجد لله شكرًا، مثل سجود الصلاة، يقول: سبحان ربي الأعلى، سبحان ربي الأعلى، يدعو في السجود يعظم الله لا بأس، هذا مشروع فعله النبي عليه الصلاة والسلام.\nأما صلاة الاستخارة؛ فهي مثل بقية الصلوات أيضًا، ركعتين يقرأ فيهما بالفاتحة وما تيسر معها، وبعد السلام يدعو ربه، ويستخير ربه، ويقول: اللهم إني أستخيرك بعلمك ... إلى آخره، الدعاء المعروف، يرفع يديه ويدعو ربه، ويستخيره. نعم.","link":"https://binbaz.org.sa/fatwas/7787/هل-توجد-صلاة-للشكر-وما-صفة-صلاة-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_271/27108.mp3","categories":["صلاة التطوع"]},{"id":9625,"question":"الرسالة الثالثة في هذه الحلقة وردت من صالح بن عبد الله الحريب من وادي فاطمة الجموم، يسأل أولاً ويقول: هل سنة صلاة الظهر قبلها أم بعدها؟ وهل هي أربع أم اثنتين أفيدونا أفادكم الله؟","title":"ما سنة صلاة الظهر القبلية والبعدية وعدد ركعاتها؟","answer":"الجواب: ثبت عن النبي ﷺ: أنه كان يصلي في اليوم والليلة عشر ركعات، يواظب عليها: ثنتين قبل الظهر، وثنتين بعدها، وثنتين بعد المغرب، وثنتين بعد العشاء، وثنتين قبل صلاة الصبح رواه الشيخان البخاري ومسلم في الصحيحين، من حديث ابن عمر رضي الله تعالى عنهما.\nوثبت عن عائشة رضي الله عنها عن النبي ﷺ: أنه كان لا يدع أربعاً قبل الظهر رواه البخاري في الصحيح.\nفالأفضل أن يصلي المؤمن والمؤمنة أربعاً قبل الظهر وثنتين بعدها؛ لحديث عائشة رضي الله عنها، وإن صلى أربعاً بعد الظهر مع أربع قبلها كان أفضل؛ لما روى أهل السنن والإمام أحمد رحمهم الله، عن أم حبيبة رضي الله عنها، عن النبي ﷺ أنه قال: من صلى أربعاً قبل الظهر وأربعاً بعدها حرمه الله على النار وهذا فضل عظيم، وإن اكتفى بثنتين قبل الظهر وثنتين بعدها فلا بأس لحديث ابن عمر ، ولكن الأفضل أن يصلي المؤمن والمؤمنة أربعاً قبل الظهر أخذاً بالحديثين جميعاً، حديث عائشة وحديث ابن عمر رضي الله تعالى عنهما، وهذه تسمى الرواتب، وقد صح عنه ﷺ أنه قال: من صلى ثنتي عشرة ركعة في يومه وليلته بنى الله له بيتاً في الجنة خرجه مسلم في صحيحه، عن أم حبيبة رضي الله عنها، وخرجه الترمذي أيضاً وزاد: أربعاً قبل الظهر، وثنتين بعدها، وثنتين بعد المغرب، وثنتين بعد العشاء، وثنتين قبل صلاة الصبح.\nفهذه الأحاديث تدل على تأكيد هذه الرواتب وأنها متأكدة ومستحبة ينبغي المحافظة عليها وعدم تركها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7793/ما-سنة-صلاة-الظهر-القبلية-والبعدية-وعدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25004.mp3","categories":["صلاة التطوع"]},{"id":9627,"question":"أخيراً يقول: هل يجوز للإنسان إذا دخل المسجد قبل أذان المغرب أن يصلي ركعتين أم يجلس أفيدونا أفادكم الله؟","title":"هل تجوز تحية المسجد وقت النهي؟","answer":"الجواب: أوقات النهي معلومة وهي خمسة: من طلوع الفجر إلى طلوع الشمس، ومن طلوعها حتى ترتفع قيد رمح، وعند وقوفها قبل الظهر حتى تزول، وبعد صلاة العصر حتى تميل الشمس للغروب، وعند ميولها للغروب حتى تغيب، هذه خمسة، لكن ذوات الأسباب لا حرج في صلاتها، فإذا دخل المسجد بعد العصر أو بعد الصبح فالأفضل له أن يركع ركعتين تحية المسجد؛ لقول النبي ﷺ: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين متفق على صحته، وهكذا لو طاف بعد العصر في مكة طاف بالكعبة، فإنه يصلي ركعتي الطواف سواء كان بعد العصر أو بعد الصبح أو في أي وقت؛ لقول النبي ﷺ: لا تمنعوا أحداً طاف بهذا البيت وصلى أية ساعة شاء من ليل أو نهار وهكذا صلاة الكسوف، إن كسفت الشمس بعد العصر فإن السنة أن يصلوا في أصح قولي العلماء؛ لأنها من ذوات الأسباب. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7799/هل-تجوز-تحية-المسجد-وقت-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_250/25008.mp3","categories":["صلاة التطوع"]},{"id":9684,"question":"أولى رسائل هذه الحلقة وردت من أخت يمنية تقول في رسالتها: أنا سيدة أمية لا أعرف القراءة، ولا أحفظ من القرآن الكريم سوى قصار السور، وعندما يدخل شهر رمضان المبارك أصلي صلاة التسبيح طوال الشهر لمدة خمسة عشر سنة، أصليها وسمعت فتوى في برنامجكم هذا تقول: إن هذه الصلاة ليست مشروعة، وأنها بدعة فامتنعت عن هذه الصلاة لمدة عامين، ولكنني سمعت من أحد رجال الدين أن من صلاها في الأسبوع مرة أو في الشهر مرة أو في السنة مرة أو في عمره مرة أن له أجر كبير، وعندما يدخل شهر رمضان هذا العام عدت وصليتها الآن أرجو منكم توضيح ذلك أفادكم الله؟","title":"ما درجة أحاديث صلاة التسابيح؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد:\nفصلاة التسبيح ورد فيها بعض الأحاديث ولكن عند أهل التحقيق هي أحاديث ضعيفة لا تصح، فلا ينبغي فعلها، وما مضى باجتهادك فلك أجره إن شاء الله، أما المستقبل فننصح لك أن لا تفعلي؛ لأن أحاديث صلاة التسبيح غير صحيحة، بل هي شاذة مخالفة للأحاديث الصحيحة الثابتة عن رسول الله ﷺ في صفة الصلاة. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7892/ما-درجة-احاديث-صلاة-التسابيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_254/25401.mp3","categories":["صلاة التطوع"]},{"id":9721,"question":"وهذه رسالة وصلت إلى البرنامج من الأخ محمد بكري تحمل العديد من الأسئلة، يقول في سؤاله الأول: إنني أصلي صلاة الضحى والحمد لله باستمرار، وقد تعمدت أن أقرأ في الركعتين الأوليتين سورة: هَلْ أَتَى عَلَى الإِنسَانِ؛ وذلك لأنه فيها صفات أهل الجنة -وآمل من الله أن يجعلني منهم- وفي الركعة الثالثة أقرأ سورة الضحى؛ لأن الصلاة هي صلاة الضحى، وفي الركعة الرابعة أقرأ سورة الإخلاص؛ لأن فيها ذكر صفات الله العظيمة التي لا يشاركه فيها أحد، فهل يجوز الاستمرار على ذلك أم أنه يعتبر بدعة يجب أن أتركها أفيدونا أفادكم الله؟","title":"حكم المداومة على قراءة سور معينة في صلاة الضحى","answer":"الجواب: الأفضل أن لا تستمر في ذلك؛ لأن هذا شيء لا أصل له ولا دليل عليه وربما باعتياده تعتقد أنه كالشيء الواجب، فينبغي أن تفعل هذا تارة وهذا تارة، ولا تستمر على قراءة هذه السور فقط، وصلاة الضحى ليس لها ما يبرر أن تقرأ في صلاة الضحى، فإن قسم الله بالضحى شيء آخر غير ما يتعلق بصلاة الضحى إنما الله يقسم من خلقه بما يشاء  لكن يجوز للمؤمن أن يختار بعض السور وبعض الآيات يقرأ بها لكن مع اعتقاد ومع اعتقاده وإيمانه بأن هذا شيء ليس بلازم وأنه لا بأس أن يقرأ غيرها من الآيات والسور، فمع هذا الاعتقاد لا حرج لكن الأولى والأفضل أن لا تستمر على هذا الشيء بل تقرأ تارة كذا وتارة كذا حتى لا تعتاد هذا الشيء فتظن أنه لازم، والنفوس إذا اعتادت شيء يشق عليها فراقه و(قُلْ هُوَ اللَّهُ أَحَدٌ)، بالأخص لها شأن عظيم فإذا قرأها الإنسان محبة لها ولما فيها من صفات الله فهذا يرجى له الخير العظيم، وقد ثبت أن بعض الصحابة كانوا يقرءوا بها في صلاتهم بالناس فقال له بعض الصحابة: لماذا تلزمها ولا تكتفي بها؟ فقال: إنها صفة الرحمن وأنا أحب أن أقرأها، فبلغ النبي ﷺ ذلك فقال: أخبروه أن الله يحبه، وفي لفظ: حبك إياها أدخلك الجنة، فإذا قرأ الإنسان سورة الإخلاص لهذا المعنى أو آيات الجنة للشوق إلى الجنة أو آيات النار للحذر فهذا له خير عظيم لكن لا يلزم ذلك بل تارة وتارة حتى لا يعتاد الشيء الذي ليس بلازم، ثم أيضًا قبل أن ننتقل: السنة في الضحى ركعتان، هذا أقل شيء فإذا أراد أن يزيد فيصلي ركعتين ثم ركعتين ثم ركعتين لا يجمع أربع الجميع، الأفضل أن يصلي ركعتين بتسليم ثم ركعتين بتسليم، لأن الرسول عليه السلام قال: صلاة الليل والنهار مثنى مثنى، وكانت في عهد الرسول ﷺ يسلم من كل اثنتين في الليل والنهار فالأفضل أن تسلم من كل ثنتين تأسيًا بالنبي ﷺ وعملًا بقوله ﷺ: صلاة الليل والنهار مثنى مثنى، وهذه الزيادة: والنهار جيدة ولا بأس بها عند كثير من أهل العلم فسندها جيد. نعم.","link":"https://binbaz.org.sa/fatwas/7876/حكم-المداومة-على-قراءة-سور-معينة-في-صلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_195/19508.mp3","categories":["صلاة التطوع"]},{"id":9854,"question":"لها استفسار ثالث وأخير في رسالتها تقول فيه: إنني أصلي صلاة الضحى بعد صلاة الفجر أي: بعد شروق الشمس مباشرة، وأحيانًا أصليها قبل صلاة الظهر، فهل هذا صحيح؟","title":"أصلي الضحى بعد الشروق، وأحيانًا قبل الظهر، فهل هذا صحيح؟","answer":"الجواب: الأمر موسع في صلاة الضحى، يدخل وقتها عند ارتفاع الشمس قيد رمح إلى أن تقف الشمس عند الظهر كله وقت للضحى، والأفضل صلاتها بعد اشتداد الضحى إذا اشتد الضحى هذه صلاة الأوابين، إذا اشتد الضحى هذا هو الأفضل، ومن صلاها في أول الوقت بعد ارتفاع الشمس فلا بأس، الأمر بحمد الله واسع في هذا، فمن صلاها في أول الوقت فلا بأس، ومن صلاها في أثناء الوقت فلا بأس، ومن صلاها عند شدة الضحى فهذا هو الأفضل، والمهم المحافظة عليها والعناية بها، فإذا كان يشغل في آخر الوقت فيخشى أن لا يصليها بادر بها في أول الوقت حتى يدرك فضلها، وقد أوصى النبي ﷺ أبا هريرة وأبا الدرداء بصلاة الضحى، وقال عليه الصلاة والسلام: على كل سلامى من الناس صدقة، فبكل تسبيحة صدقة، وبكل تهليلة صدقة، وبكل تكبيرة صدقة، وبكل تحميدة صدقة، فأمر بالمعروف صدقة، ونهي عن المنكر صدقة، قال: ويكفي من ذلك ركعتان تركعهما من الضحى، فهذا يدل على فضل هاتين الركعتين وأن لهما شأنًا عظيمًا، وإذا صلى أربعًا أو ستًا أو ثمانًا أو أكثر فلا بأس، ولكن أقل من ذلك ركعتان من الضحى. نعم.\nالمقدم: جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8011/اصلي-الضحى-بعد-الشروق-واحيانا-قبل-الظهر-فهل-هذا-صحيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_198/19808.mp3","categories":["صلاة التطوع"]},{"id":9913,"question":"بارك الله فيكم ويقول أيضاً: هناك من يدخل والصلاة قد تقام ولكنه يعرف من الإمام أنه يطيل في الركعة الأولى فيصلي ركعتي الفجر قبل أن يدخل مع الإمام؟","title":"حكم صلاة سنة الفجر بعد إقامة الصلاة","answer":"الجواب: هذا لا يجوز وهذا يفعله بعض الناس بعض إخواننا من الباكستانيين والهنود وغيرهم وهذا خطأ، وإن كان قاله بعض أهل العلم لكنه خطأ مخالف للسنة، السنة للمأموم إذا دخل والإمام قد دخل في الصلاة أن يصف ولا يصلي راتبة الفجر ولا غيرها بل يصف مع الإمام، لما ثبت عنه ﷺ أنه قال: إذا أقيمت الصلاة فلا صلاة إلا المكتوبة خرجه الإمام مسلم في صحيحه.\nفالواجب على من دخل والإمام قد أقام الصلاة أنه يصلي مع الإمام ويؤجل السنة بعد الصلاة أو بعد طلوع الشمس، أما أن يصليها والإمام يصلي فهذا لا يجوز للحديث السابق وهو قوله ﷺ: إذا أقيمت الصلاة فلا صلاة إلا المكتوبة رواه مسلم في صحيحه، وفي رواية أحمد: فلا صلاة إلا التي أقيمت فالواجب على من دخل والإمام قد كبر في الصلاة أو قد أقيمت الصلاة أنه يبادر ويصف مع الناس، والنافلة الحمد لله أمرها واسع إذا صلاها بعد الصلاة أو بعد طلوع الشمس أو تركها هي نافلة، لكن الأفضل أن يصليها بعد الصلاة أو بعد ارتفاع الشمس، لأنها سنة راتبة فيها أجر عظيم. نعم.\nالمقدم: أثابكم الله.","link":"https://binbaz.org.sa/fatwas/8083/حكم-صلاة-سنة-الفجر-بعد-اقامة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_268/26804.mp3","categories":["صلاة التطوع"]},{"id":9929,"question":"أيضًا لها سؤال تقول فيه: ما هي صلاة الاستخارة؟","title":"ما هي صلاة الاستخارة؟","answer":"الجواب: صلاة الاستخارة ركعتان، إذا أراد الإنسان أمرًا يشك فيه ولا يعرف ما هو الأصلح فإنه ينظر في الأمر ويتأمل، فإن اتضح له أنه أمر مناسب ومفيد وليس عنده فيه ريب فلا حاجة إلى الاستخارة، وإن بقي عنده تردد وقد هم بهذا الأمر ويخشى أن تكون العاقبة غير صالحة فإنه يصلي ركعتين ثم يستخير الله جل وعلا بعد ذلك؛ لأن الإنسان لا يدري ما وراء الأمر الذي طلب من زواج بامرأة معينة أو شراء أرض أو سفر إلى كذا، فإذا هم بشيء من هذا أو أشباهه واشتبه عليه الأمر هل هو مناسب أو ما هو مناسب وهل الأصلح فعله أم عدم ذلك، يصلي ركعتين ثم يستخير ربه، ويقول: اللهم إني أستخيرك بعلمك وأستقدرك بقدرتك وأسألك من فضلك العظيم فإنك تعلم ولا أعلم وتقدر ولا أقدر وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر -ويسميه بعينه يعني سفري إلى كذا، أتزوج بفلانة، معاملة فلان، شراء الأرض الفلانية، أو تعمير الأرض الفلانية، أو ما أشبه ذلك- اللهم إن كنت تعلم أن هذا الأمر خير لي في ديني ودنياي ومعاشي وعاقبة أمري وآجله فقدره لي ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر شر لي في ديني ودنياي ومعاشي وعاقبة أمري فاصرفه عني واصرفني عنه وقدر لي الخير حيث كان ثم رضني به.\nهذه هي الاستخارة الشرعية يكل الأمر إلى الله سبحانه وتعالى ويسأله ما هو الأصلح يعني ليشرح صدره لما هو الأصلح. نعم.\nثم يستشير بعد ذلك، السنة له يستشير أحبابه ومن يثق بهم يستشيرهم في هذا الأمر هل يمضي فيه أو ما يمضي فيه، فإن انشرح صدره بعد الاستخارة والمشاورة مضى، وإن لم ينشرح صدره ترك. نعم.\nالمقدم: حزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8091/ما-هي-صلاة-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_199/19905.mp3","categories":["صلاة التطوع"]},{"id":10158,"question":"تسأل أختنا وتقول: نرجو من سماحتكم تفسير قول المصطفى ﷺ: من جلس يذكر الله بعد الفجر حتى تشرق الشمس فيصلي لله ركعتين لا يحدث فيهما نفسه بأمر من أمور الدنيا إلا كتب الله له أجر حجة وعمرة تامتين تامتين تامتين هل الركعتان هما ركعتا الضحى؟","title":"ركعتا الإشراق ودخولهما في صلاة الضحى","answer":"الجواب:\nنعم، يصدق عليهما أنهما صلاة الضحى، إذا جلس بعد الصلاة يذكر الله أو يقرأ القرآن أو يعلم العلم، ثم صلى ركعتين بعد ارتفاع الشمس حصل له هذا الخير العظيم. ولا أعلم أن فيهما: لا يحدث فيهما نفسه، هذه جاءت في حديث آخر إذا صلى ركعتين صلاة شرعية حصل له هذا الأجر، أما لفظ: لا يحدث فيهما نفسه هذا جاء في حديث آخر حديث عثمان  فيمن توضأ كوضوء النبي ﷺ ثم صلى ركعتين بعد الوضوء لا يحدث فيهما نفسه غفر الله له ما تقدم من ذنبه، هذا في سنة الوضوء. والمشروع في جميع الصلوات الإقبال على الصلاة وعدم تحديث النفس في جميع الصلوات النافلة والفريضة، المشروع فيها جميعاً أن يقبل المؤمن على صلاته وأن يخشع فيها ويحذر الاشتغال بحديث النفس، يجاهد نفسه في هذه الأمور حتى يفرغ قلبه للخشوع في صلاته والإقبال عليها، نافلة أو فريضة والفريضة أهم، قال تعالى: قَدْ أَفْلَحَ الْمُؤْمِنُونَ  ۝ الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ، وهذا يعم الصلاتين الفرض والنفل، لكن الفرض أهم وأعظم، فالواجب على المؤمن أن يعتني بصلاته، وأن يصلي صلاة تامة مطمئناً فيها، حتى يكون أداها كما شرعها الله، وإذا اجتهد في الخشوع كان أكمل، والخشوع يكون بخشوع القلب، خشوع الجوارح، وترك العبث يقبل بقلبه وقالبه، بقلبه وبدنه على الصلاة حتى يخشع لربه، وأقل ذلك الطمأنينة الواجبة، أقل شيء أن يطمئن في ركوعه وسجوده وجلوسه بين السجدتين واعتداله بعد الركوع لا بد من الطمأنينة فإن نقضها بطلت، إن نقضها ولم يطمئن فيها بطلت، وقد ثبت عن رسول الله ﷺ أنه رأى أعرابياً دخل المسجد فصلى ولم يتم صلاته فأمره أن يعيد الصلاة ثلاث مرات، لأنه ما أتقنها ما أكملها فقال الأعرابي: يا رسول الله والذي بعثك بالحق نبياً لا أحسن غيرها فعلمني، فقال له ﷺ: إذا قمت إلى الصلاة فأحسن الوضوء -يعني كمل الوضوء- ثم استقبل القبلة فكبر، ثم اقرأ ما تيسر معك من القرآن، وفي رواية أخرى: ثم اقرأ بأم القرآن يعني الفاتحة -، ثم اركع حتى تطمئن راكعاً، ثم ارفع حتى تعتدل قائماً، ثم اسجد حتى تطمئن ساجداً، ثم ارفع حتى تطمئن جالساً، ثم اسجد حتى تطمئن ساجداً، ثم افعل ذلك في صلاتك كلها هكذا علمه النبي ﷺ فالواجب على جميع المصلين العناية بهذا الأمر الطمأنينة وعدم النقض، والمشروع أن تكون الحالة أكمل بأن يخشع بقلبه وقالبه أهـ.","link":"https://binbaz.org.sa/fatwas/8333/ركعتا-الاشراق-ودخولهما-في-صلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_307/30715.mp3","categories":["صلاة التطوع"]},{"id":10167,"question":"أقوم أشهراً طويلة بالمواظبة على صلاة الوتر وأصلي بالليل ولا أترك سماع القرآن وقراءته والاستماع إلى الأشرطة الدينية، وتأتيني فترات أترك ذلك كله، أو لا أداوم عليه، وأتراخى قليلًا في ديني وذلك بعد الولادة وانقطاعي عن الصلاة وقراءة القرآن فترة النفاس، ثم أصحو من غفلتي وأعود للمواظبة، فماذا أفعل حتى لا أترك المواظبة على ديني جزاكم الله خيرا؟","title":"ما النصيحة لمن تفتر أحيانًا عن النوافل؟","answer":"الجواب: هذا لا حرج فيه لأنها نوافل، هذه لا حرج فيها، لكن نوصيك بالجد والمواظبة وسؤال الله العون والتوفيق في جميع الأحوال حتى لا يكون لك فترة، جاهدي وإلا فالإنسان محل النقص، ولكل شرة فترة، لكن الإنسان يجاهد، المؤمن يجاهد نفسه، والمؤمنة كذلك في لزوم الأعمال الصالحة والاجتهاد في أعمال الخير، والنبي عليه السلام يقول: إن أحب العمل إلى الله ما داوم عليه صاحبه وإن قل، فالمداومة على فعل الخير من الوتر في الليل والإكثار من قراءة القرآن والنوافل، والتسبيح والتهليل والتحميد والتكبير كل هذا مطلوب، فالمشروع للمؤمن والمؤمنة العناية بهذا الأمر والاستمرار فيه والإكثار منه، وإذا عرض بعض الفترات وبعض النقص فلا حرج فيه لأنها كلها نوافل والحمد لله.\nالمقدم: جزاكم الله خيراً وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/8338/ما-النصيحة-لمن-تفتر-احيانا-عن-النوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_277/27718.mp3","categories":["صلاة التطوع"]},{"id":10193,"question":"متى تبدأ وتنتهي صلاة الضحى وصلاة قيام الليل، والوقت بالساعة تقريبًا لو تكرمتم؟","title":"ما وقت كل من صلاة الضحى وقيام الليل؟","answer":"الجواب: الضحى تبتدي بارتفاع الشمس قيد رمح إلى قرب الزوال، ولكن الأفضل أن يصليها عند شدة الضحى لقوله ﷺ: صلاة الأوابين حين ترمض الفصال يعني: حين تشتد الرمضاء على أولاد الإبل، هذا هو الأفضل، وإن صلاها بعد ارتفاع الشمس قيد رمح حصلت السنة، وإذا كان قرب الزوال وقف عن ذلك؛ لأنها حينئذ تقف الشمس يسمى وقت الوقوف، وذكر النبي ﷺ أنها تسجر فيها جهنم، فالحاصل أنه عند قرب الزوال لا يصلي، هذا من أوقات النهي وهو وقت قصير نحو ربع ساعة أو ثلث ساعة تقريبًا قبل الزوال، قبل أن تميل إلى جهة المغرب يقال له: وقت الوقوف، فلا ينبغي له أن يتطوع في هذه الحالة بشيء من الصلاة، بل يمسك حتى تزول الشمس، يعني يمسك عن الصلاة تنفل حتى تزول الشمس عند قرب الزوال. نعم.\nالمقدم: يذكر ويطلب الوقت بالساعة تقريبًا لو تكرمتم.\nالشيخ: هذا يختلف على كل حال، الليل يختلف والنهار يختلف، فإذا كان بعد طلوع الشمس بربع ساعة تقريبًا ارتفعت الشمس، ربع ساعة تقريبًا تكون الشمس مرتفعة..\nالمقدم: هذا بالنسبة لصلاة الضحى.\nالشيخ: وإذا بقي على الظهر نحو نصف ساعة ينبغي التوقف احتياطًا عن الصلاة حتى تزول الشمس، أما في الليل فإذا غاب الشفق دخل وقت العشاء، الشفق الأحمر من المغرب، الشفق الأحمر هذا يكون في جهة المغرب جهة الغرب يعني، فإذا غاب وانتهى دخل وقت العشاء وخرج وقت المغرب، وإذا صلى العشاء دخل وقت التهجد، إذا صلى العشاء ولو مبكرًا ولو مجموعة مع المغرب كالمسافر والمريض، يعني: إذا صلاها جمعًا في السفر والمرض دخل وقت التهجد إلى طلوع الفجر، كله وقت تهجد، وإذا صلاها في الوقت دخل وقت العشاء ..... وقت التهجد بعد صلاة العشاء وبعد السنة الراتبة، يصلي سنتها ثنتين وبذلك يدخل وقت التهجد في أول الليل وفي وسطه وفي آخره، لكن كونه يصلي في آخر الليل في الثلث الأخير يكون أفضل، حتى يوافق النزول الإلهي. نعم.\nالمقدم: وآخر وقت التهجد؟\nالشيخ: طلوع الفجر، لكن من فاته ورده في الليل شرع له أن يصليه من النهار، الضحى من النهار شفعًا لا وترًا، يصلي إذا كان عادته ثلاث يصليها أربعًا تسليمتين، إذا كان عادته خمسًا صلاها ثلاث تسليمات ستًا، يعني يشفع من واحدة؛ لما ثبت عن عائشة رضي الله عنها قالت: كان النبي ﷺ إذا فاته ورده من الليل لمرض أو نوم صلى من النهار ثنتي عشرة ركعة، وكانت عادته في الغالب إحدى عشرة ركعة في الليل، إذا صلى في النهار صلاها ثنتي عشرة ركعة، يعني زاد ركعة شفعها، اللهم صل عليه.\nالمقدم: لأن النهار ليس فيه وتر.\nالشيخ: ليس محل وتر. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8356/ما-وقت-كل-من-صلاة-الضحى-وقيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_334/33410.mp3","categories":["صلاة التطوع","الوتر وقيام الليل"]},{"id":10368,"question":"بالنسبة لصلاة الظهر يوم الجمعة للمرأة التي اعتادت أن تصلي أربع ركعات قبل الظهر هل تصليها أيضًا يوم الجمعة؟","title":"حكم صلاة النافلة للمرأة قبل صلاة الظهر يوم الجمعة","answer":"الجواب: نعم تصلي ما شاءت تصلي أربعًا أو ثمانًا أو أكثر من ذلك ليس لها حد محدود، لا في يوم الجمعة ولا في غيرها، والرجل كذلك، يصلي ما قسم الله له، ركعتين أو يصلي أربع ركعات أو ست ركعات أو ثمان ركعات أو أكثر.\nلكن الأفضل أن يسلم من كل ثنتين، وهكذا الأنثى تسلم من كل ثنتين هذا هو الأفضل، لما روى الخمسة وهم أهل السنن وأحمد رحمة الله عليهم عن النبي ﷺ أنه قال: صلاة الليل والنهار مثنى مثنى هذا هو الأفضل، وأقل شيء ركعتان الضحى هذا هو الأفضل أقل المشروع ركعتان يركعهما من الضحى في الجمعة أو في غيرها. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8540/حكم-صلاة-النافلة-للمراة-قبل-صلاة-الظهر-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_339/33902.mp3","categories":["صلاة التطوع","الحيض والنفاس","قضايا المرأة"]},{"id":10404,"question":"السؤال الأخير الذي نعرضه لأخينا في هذه الحلقة يقول: إذا ذهبت إلى المسجد وانتهى المؤذن من الأذان وصلوا السنة القبلية ولم أدركها معهم بل قاموا لأداء صلاة الفرض، فهل يجوز أن أصلي السنة القبلية بعد الفرض، أم أصلي السنة البعدية وسقطت عني القبلية؟","title":"حكم قضاء السنن الراتبة","answer":"الجواب: المشروع لك تصليهما جميعًا القبلية والبعدية بعد الصلاة، إذا جئت في الظهر وقد أقيمت الصلاة فإنك تصلي مع المسلمين ثم إذا فرغت من الصلاة والأذكار تصلي السنة القبلية أربع ركعات والبعدية ركعتين، هذا هو المشروع، وقد روى الترمذي بإسناد جيد عن النبي ﷺ أنه فعل ذلك، في بعض الأحيان لم يصل القبلية إلا بعد الصلاة عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8577/حكم-قضاء-السنن-الراتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_340/34011.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":10474,"question":"رسالة من أحد الإخوة المستمعين ضمنها جمع من الأسئلة هو المستمع (أ. ع. ع. محمود ) في أحدها يقول: نرجو أن تحدثونا عن صلاة الرغيبة الفجر، هل نقرأ الفاتحة وسورة أخرى معها؟","title":"ما السنة في قراءة ركعتي الفجر؟","answer":"الجواب: السنة هي تسمى الراتبة راتبة الفجر، ومن سماها الرغيبة فهو اسم لا أعرف له أصلًا، المقصود سنة الفجر، وهي ركعتان تفعل في البيت أفضل وإن فعلها في المسجد فلا بأس، يقرأ فيهما الفاتحة وقل يا أيها الكافرون في الأولى، وفي الثانية: قل هو الله أحد مع الفاتحة، أو يقرأ فيهما آية البقرة في الأولى مع الفاتحة: قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا وَمَا أُنزِلَ إِلَى إِبْرَاهِيمَ وَإِسْمَاعِيلَ [البقرة:136] الآية، وفي الركعة الثانية بعد الفاتحة آية آل عمران: قُلْ يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا اللَّهَ [آل عمران:64] كل هذا فعله النبي ﷺ هذا وهذا، وهي سنة مؤكدة لكن فيها يشرع فيها التخفيف، وفي البيت أفضل، وإن صلاها في المسجد فلا بأس، وهي مشروعة للرجل والمرأة جميعاً، والمسافر والمقيم، للجميع. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8643/ما-السنة-في-قراءة-ركعتي-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_320/32009.mp3","categories":["صلاة التطوع","القراءة في الصلاة"]},{"id":10508,"question":"هل هناك فرق بين صلاة التطوع وصلاة النفل وصلاة الراتبة؟","title":"الفرق بين صلاة التطوع والنفل والراتبة","answer":"الجواب: كلها تطوع، النفل والراتبة كلها تطوع تسمى: تطوع، ما عدا الخمس الصلوات تسمى: تطوع، سواء صلاة ضحى أو وتر أو رواتب كلها تسمى: تطوع.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8683/الفرق-بين-صلاة-التطوع-والنفل-والراتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_282/28216.mp3","categories":["صلاة التطوع"]},{"id":10646,"question":"أحمد العبد الله من الرياض له مجموعة من الأسئلة، يقول في السؤال الأول: إذا صلى المسافر الجمعة هل تسقط عنه الراتبة، وإذا وصل هذا المسافر إلى بلد آخر هل تسقط عنه الرواتب وجهونا مأجورين؟","title":"حكم صلاة الراتبة في حق المسافر","answer":"الجواب: إذا صلى المسافر الجمعة يصلي معها أربع السنة، يصلي سنة الجمعة أربع ركعات تسليمتين، وإذا صلى قصرًا فليس لها راتبة السنة أن يصلي ثنتين فقط الظهر قصرًا، كان النبي ﷺ لا يصلي راتبة الظهر ولا المغرب ولا العشاء في السفر إنما الفجر فقط، أما إذا صلى مع الناس الجمعة أو الأوقات صلى الرواتب معهم.\nالمقدم: يقول: إذا وصل المسافر إلى بلد آخر تسقط الرواتب يا سماحة الشيخ؟!\nالشيخ: هذا على حسب الحال، إن كان أقام فيها أربعة أيام فأقل يصلي ثنتين، إلا إذا كان واحدًا فإنه يصلي مع الناس أربعًا، لا يصلي وحده؛ الجماعة واجبة، لكن إذا كانوا جماعة اثنين فأكثر وصلوا قصرًا سقطت عنهم الرواتب إلا سنة الفجر، وإلا التهجد بالليل والوتر، أما إذا كان واحد يصلي مع الناس لا يصلي وحده ولو أنه مسافر، إذا كان عنده جماعة يصلي مع الجماعة، يصلي أربعًا، لكن إذا كانوا جماعة مسافرين إن صلوا قصرًا سقطت عنهم الرواتب، أفضل، تركها أفضل، إلا سنة الفجر وإلا التهجد بالليل، فإن صلوا مع الناس جماعة مع المقيمين صلوا معهم أربعًا وصلوا الرواتب.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/8823/حكم-صلاة-الراتبة-في-حق-المسافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28508.mp3","categories":["صلاة التطوع","صلاة المسافر"]},{"id":10693,"question":"هل صحيح أن من السنة أن يغير المصلي مكانه الذي صلى فيه ليصلي النافلة؟","title":"حكم تحوُّل المصلي من مكان الفريضة لصلاة النافلة","answer":"الجواب: جاء في هذا حديث ضعيف، وجاء من فعل ابن عمر ، فالأمر فيه واسع، من فعله فلا بأس، ومن تركه فلا بأس. نعم.\nالمقدم: والأمر سواء بالنسبة للرجال والنساء؟\nالشيخ: نعم عام، الأمر واسع. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8855/حكم-تحول-المصلي-من-مكان-الفريضة-لصلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_330/33005.mp3","categories":["صلاة التطوع"]},{"id":10697,"question":"يقول في سؤاله الثاني: يقول العلماء: بأن السنة يثاب فاعلها، ولا يعاقب تاركها، هل هذا يعني جميع السنن، أو بعض السنن؟","title":"ثواب من حافظ على السنن","answer":"الجواب: هذا المراد به جميع السنن التي ليست بواجبة، يعني يثاب من فعلها مثل سنة الظهر، سنة الفجر، سنة المغرب، سنة الضحى، التهجد بالليل كل هذه سنن، من فعلها له أجر ومن تركها لا إثم عليه، هذا معناها.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8874/ثواب-من-حافظ-على-السنن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28520.mp3","categories":["صلاة التطوع"]},{"id":10892,"question":"لها سؤال ثاني السائلة الأخت (ح. ع) من البحرين تقول: هل يجوز لي أن أصلي في وقت النهي عندما أبادر للوضوء لقراءة القرآن، أو للدعاء خصوصًا في أيام الجمعة، وذلك بعد العصر، علمًا بأنني لا أتوضأ عمدًا بنية الصلاة، إنما أتوضأ للدعاء كما ذكرت؟ جزاكم الله خيرًا.","title":"حكم أداء سنة الوضوء في أوقات النهي","answer":"الجواب:  إذا توضأ الإنسان في وقت النهي يصلي سنة الوضوء، ليس لها وقت نهي، إذا توضأ بعد الفجر، أو بعد العصر يشرع له أن يصلي ركعتين سنة الوضوء، سواء كان رجلًا أو امرأة. وهكذا لو دخل المسجد بعد العصر، أو بعد الفجر شرع له أن يصلي تحية المسجد، وليس لها وقت نهي، وهكذا لو كسفت الشمس بعد العصر شرع للمسلمين أن يصلوا صلاة الكسوف بعد العصر، وليس لها وقت نهي؛ لأن هذه كلها من ذوات الأسباب، والصلاة التي لها أسباب تفعل في وقت النهي. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9069/حكم-اداء-سنة-الوضوء-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_286/28606.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":10900,"question":"هل يجوز أن أصلي السنة وأنا جالسة؟","title":"حكم صلاة النافلة جلوساً بغير عذر","answer":"الجواب:  لا حرج في ذلك، النافلة كلها لا حرج أن يصليها الإنسان جالسًا إن صلاها قائمًا فهو أفضل، وإن صلاها جالسًا من غير عذر فلا بأس، وهو على النصف من الأجر، نعم.. وكان النبي ﷺ يصلي في آخر حياته كثير من النوافل جالسًا -عليه الصلاة والسلام- نعم.","link":"https://binbaz.org.sa/fatwas/9084/حكم-صلاة-النافلة-جلوسا-بغير-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_360/36011.mp3","categories":["صلاة التطوع"]},{"id":11059,"question":"يسأل أيضًا عن صلاة الحاجة سماحة الشيخ: لو تكرمتم يطلب التوجيه بخصوصها، وهل ما ورد فيها يعتبر من الصحيح؟ جزاكم الله خيرًا.","title":"هل صح شيء في صلاة الحاجة؟","answer":"الجواب:  المعروف في الأحاديث صلاة التوبة وصلاة الاستخارة، -ويقال لها: صلاة الحاجة- صلاة التوبة إذا صلى ركعتين، ورفع يديه، ودعا ربه تائبًا نادمًا من ذنوبه، هذه من أسباب المغفرة، هكذا صلاة الاستخارة إذا هم بشيء، وأشكل عليه هل المصلحة الإقدام عليه، فإنه يستحب له أن يصلي ركعتين، ثم يدعو بعدهما يستخير بعدهما، يرفع يديه ويستخير يقول: اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنك تعلم ولا أعلم، وتقدر ولا أقدر، وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر يسميه باسمه، مثل الزواج من فلانة، أو شراء السلعة الفلانية، أو السفر إلى البلاد الفلانية، يبينه اللهم إن كنت تعلم أن هذا الأمر ويسميه خير لي في ديني ودنياي ومعاشي، وعاقبة أمري فيسره لي، ثم بارك لي فيه، وإن كنت تعلم أنه شر لي في ديني ودنياي ومعاشي وعاقبة أمري، فاصرفه عني، واصرفني عنه، وقدر لي الخير حيث كان ثم أرضني به يأتي بهذا الدعاء، أو بما يدل على معناه إذا كان لا يعرف هذا الدعاء، يسأل ربه أن الله يشرح صدره لهذا الأمر إن كان خيرًا، أو يصرفه عنه إن كان شرًا، هذه يقال لها: صلاة الاستخارة، يصلي ركعتين، ثم يدعو ربه بعد السلام، يرفع يديه في الشيء الذي يشك هل يفعله أم لا، يعني: يشك في المصلحة، شراء بيت عنده إشكال فيه، شراء سيارة، عنده تردد فيها، زواج بفلانة، عنده تردد، سفر إلى بلاد، عنده تردد يستخير، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9237/هل-صح-شيء-في-صلاة-الحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_367/36710.mp3","categories":["صلاة التطوع"]},{"id":11084,"question":"هذا السائل الذي رمز لاسمه بـ (أ. أ) يقول: سماحة الشيخ ما كيفية صلاة الاستخارة؟ وما هو الدعاء المطلوب، وهل يكون الدعاء أثناء صلاة الركعتين أم بعد الانتهاء منها؟ جزاكم الله خيرًا.","title":"ما كيفية صلاة الاستخارة ودعائها؟","answer":"الجواب:  صلاة الاستخارة أن يصلي ركعتين، ثم يدعو بعدها، ويستخير بما ورد عن النبي ﷺ بعد السلام يرفع يديه ويسأل، يقول: اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم؛ فإنك تعلم ولا أعلم، وتقدر ولا أقدر، وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر ويسميه، كأن يتزوج بفلانة، سفري إلى البلد الفلانية، تجارتي في هذا الشيء، يسميه خير لي في ديني ومعاشي وعاقبة أمري فيسره لي، ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر ويسميه باسمه شر لي في ديني ومعاشي وعاقبة أمري فاصرفه عني، واصرفني عنه، وقدر لي الخير حيث كان، ثم أرضني به هذه السنة في الاستخارة نعم.  المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9262/ما-كيفية-صلاة-الاستخارة-ودعاىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_289/28910.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":11088,"question":"له سؤال أخير، الأخ من السودان يقول: هل هناك من صلاة تسمى الأولى: صلاة التوبة، والأخرى تسمى: صلاة الحاجة؟ وما حكمهما في الشرع؟ مأجورين.","title":"حكم صلاتي التوبة والحاجة","answer":"الجواب:  صلاة التوبة هي إذا عرف أنه أذنب، وأراد أن يتوب فهو مخير، إن شاء تاب من دون صلاة خاصة، بل يتوب إلى الله ويندم ويكفي، وإن صلى صلاة قصد بها التوسل لقبول التوبة فلا بأس، النبي ﷺ أخبر أن من تطهر ثم صلى ركعتين، ممن أذنب ذنبًا، ثم تطهر وصلى ركعتين، ثم استغفر ربه غفر الله له، فصلاة الركعتين، ثم يدعو ربه، ويستغفر ويتوب إليه هذا من أسباب المغفرة، هذه يقال لها: صلاة التوبة، وصلاة الحاجة هي صلاة الاستخارة. نعم.","link":"https://binbaz.org.sa/fatwas/9266/حكم-صلاتي-التوبة-والحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_289/28914.mp3","categories":["صلاة التطوع"]},{"id":11107,"question":"إحدى الأخوات المستمعات تقول المرسلة ريـم: تسأل جمعًا من الأسئلة، من بينها سؤال عن صلاة الضحى، وعن وقتها، وعن عدد ركعاتها، جزاكم الله خيرًا.","title":"حكم صلاة الضحى وعدد ركعاتها وبيان وقتها","answer":"الجواب:  صلاة الضحى سنة مؤكدة، وقد أوصى بها النبي ﷺ جماعة من أصحابه، وقال -عليه الصلاة والسلام-: إن لكم بكل تسبيحة صدقة، وبكل تحميدة صدقة، وبكل تكبيرة صدقة، وبكل تهليلة صدقة، قال: وأمر بالمعروف صدقة، ونهي عن المنكر صدقة، ثم قال: ويكفي من ذلك ركعتان تركعهما من الضحى فهذا يدل على تأكدها، وهي ركعتان، وإن صلى أربعًا، أو أكثر كله طيب، والنبي ﷺ صلى ثمانًا صلاة الضحى لما دخل مكة، سبحة الضحى صلاها ثماني ركعات، يسلم من كل ثنتين.  فالمقصود: أن سنة الضحى مستحبة ومتأكدة دائمًا، وإن صلاها في بعض الأوقات، وترك في بعض الأوقات لا بأس، لكن الأفضل أن يحافظ عليها دائمًا، وأقلها ركعتان، ومن صلى أكثر فأجره أكثر، نعم.  المقدم: جزاكم الله خيرًا، تعيدون وقتها لو سمحتم؟ الشيخ: وقتها من ارتفاع الشمس قيد رمح إلى وقوف الشمس، هذا وقتها. المقدم: إلى وقوف الشمس يعني: إلى ما قبل الظهر.  الشيخ: قبيل الظهر بنصف ساعة، ثلث ساعة، وقوف الشمس يعني؛ لأن مدة الوقوف ليست طويلة، عند توسط الشمس في السماء، في كبد السماء هذا الوقوف. والأفضل إذا اشتد الحر، إذا ارتفع الضحى هذا أفضل أوقاتها، وإن صلاها مبكرًا بعد طلوع الشمس، بعد ارتفاع الشمس كفى ذلك، لكن الأفضل عند اشتداد الضحى، وذلك صلاة الأوابين، يعني: الرجاع إلى الله كثير العبادة، صلاتهم عند اشتداد الضحى، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9288/حكم-صلاة-الضحى-وعدد-ركعاتها-وبيان-وقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36806.mp3","categories":["صلاة التطوع"]},{"id":11113,"question":"بعد هذا رسالة وصلت إلى البرنامج من بريدة، باعثها أحد الإخوة المستمعين من رعايا دولة الباكستان الشقيقة، أخونا فهمت بعضًا من اسمه فريد، أما الاسم الآخر فلم أستطع قراءته، وكتب الرسالة بلهجته العربية المكسرة، فهمت من رسالته ما يلي:أصلي ركعتين من السنة قبل صلاة الفرض، ثم أصلي أربع ركعات فريضة، ثم أصلي ركعتين السنة، ثم أصلي نفلًا، وبعدها أصلي ثلاث ركعات الوتر، فهل ما أفعله صحيح؟ جزاكم الله خيرًا.","title":"أحكام السنن الرواتب والنوافل والوتر","answer":"الجواب:  نعم، السنة أن يصلي المؤمن ركعتين بين الأذان والإقامة، لقول النبي ﷺ: بين كل أذانين صلاة، بين كل أذانين صلاة، بين كل أذانين صلاة لمن شاء، فالركعتان بعد الأذان مستحبة بعد أذان المغرب، بعد أذان العشاء، وإذا صلى الفريضة صلى بعدها ركعتين الراتبة، ثم أوتر إذا أحب أن يوتر ثلاثًا، أو خمسًا أو أكثر، وإن أخر الوتر إلى آخر الليل فهو أفضل، إذا كان يطمئن إلى قيام آخر الليل، ويغلب على ظنه ذلك، وإلا فالسنة الإيتار في أول الليل بركعة، أو ثلاث، أو أكثر أخذًا بالحزم، لقول النبي ﷺ: من خاف أن لا يقوم من آخر الليل فليوتر أوله، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة وذلك أفضل. وكان النبي ﷺ يوتر أول الليل، ثم أوتر في وسط الليل، ثم استقر وتره في آخر الليل -عليه الصلاة والسلام- فهذا هو الأفضل لمن قدر، أما من يخاف أن لا يقوم فليوتر أول الليل. أما الظهر فإنه يصلي قبلها أربعًا، السنة أربع راتبة، يصلي قبلها تسليمتين أربعًا، والعصر كذلك يستحب أن يصلي قبلها أربعًا تسليمتين، وبعد الظهر أربعًا تسليمتين، الراتبة ركعتان بعدها، ولكن إذا صلى أربعًا بعدها فهو أفضل، لما روى أهل السنن عن أم حبيبة -رضي الله عنها- عن النبي ﷺ أنه قال: من حافظ على أربع قبل الظهر، وأربع بعدها حرمه الله على النار فهذا الحديث العظيم .... صحيح يدل على فضل الأربع قبلها وبعدها. أما الراتبة فهي أربع قبلها، وثنتان بعدها، لكن يستحب أن يزيد بعدها ثنتين حتى تصير أربعًا بعد الظهر، وقبل العصر أربعًا تسليمتين. أما المغرب والعشاء فيسن قبلهما ركعتان لعموم حديث: بين كل أذانين صلاة، بين كل أذانين صلاة ..، وإن صلى أكثر من ركعتين فلا بأس، وبعدهما ركعتان الراتبة بعد المغرب ركعتان تسليمة واحدة، بعد العشاء ركعتان تسليمة واحدة، كان النبي يحافظ عليها -عليه الصلاة والسلام- ثم الوتر بعد العشاء وبعد الراتبة، ولو صلى العشاء مع المغرب مجموعتين جمع تقديم كالمسافر، فإنه يوتر بعد صلاة العشاء، ولو في وقت المغرب؛ لأنه إذا صلى العشاء مجموعة في المغرب جمع تقديم فقد دخل وقت الوتر كالمريض والمسافر. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9284/احكام-السنن-الرواتب-والنوافل-والوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36802.mp3","categories":["صلاة التطوع"]},{"id":11217,"question":"هل الجمعة لها سنة أم سنة الضحى تكفي؟","title":"حكم الصلاة قبل الجمعة وبعدها","answer":"الجواب:  يستحب قبل الجمعة الإكثار من الركعات، بأن يصلي ما تيسر، وليست راتبة، لكن يسن ما يسر الله له؛ لأن النبي ﷺ قال: ثم ليصلي ما كتب الله له لم يعين شيئًا فليس لها راتبة قبلها، بل يصلي الإنسان ما تيسر ركعتين أو أربعًا أو ستًا أو ثمانًا أو أكثر، يسلم من كل ثنتين، وإن صلى من حين يصل إلى دخول الخطيب، كله طيب، كله حسن، يسلم من كل ثنتين، ولها راتبة بعدها وهي أربع، النبي  قال: من كان مصليًا بعد الجمعة فليصل بعدها أربعًا فالسنة أن يصلي أربعًا بتسليمتين بعد الجمعة في المسجد أو في البيت، والنبي  كان يصلي ثنتين في بيته، ولكنه أوصى من صلى يصلي أربعًا قال: من كان مصليًا بعد الجمعة فليصل بعدها أربعًا وقال: إذا صليتم بعد الجمعة فصلوا أربعًا هذا هو السنة، الأربع أفضل من الثنتين، سواء صليتها في البيت، أو في المسجد، وفق الله الجميع.  المقدم: اللهم آمين جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9402/حكم-الصلاة-قبل-الجمعة-وبعدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_373/37309.mp3","categories":["صلاة التطوع"]},{"id":11314,"question":"يقول: استنادًا لحديث بلال : ما توضأت إلا وصليت ركعتين بعد الوضوء، فأنا أتوضأ أحيانًا في أوقات نهي، مثال ذلك بعد صلاة العصر، أو بعد صلاة الفجر، أو عند غروب الشمس وعند طلوعها مثلًا، فهل عليَّ إثم إذا ما صليت ركعتي الوضوء؟ جزاكم الله خيرًا.","title":"حكم ركعتي الوضوء وصلاتها في أوقات النهي","answer":"الجواب:  المستحب الوضوء، المستحب الصلاة إذا توضأ الإنسان يصلي ركعتين سنة الوضوء في أي وقت ولو في وقت النهي؛ لأن الرسول ﷺ قال: من توضأ مثل وضوئي هذا ثم صلى ركعتين لا يحدث فيهما نفسه غفر له ما تقدم من ذنبه. فالمقصود أنه ﷺ كان إذا توضأ صلى ركعتين ورغب الناس في ذلك -عليه الصلاة والسلام- ويقال لها: سنة الوضوء، فلا مانع أن تصلى في وقت النهي وغيره لأنها سنة مؤكدة، نعم.","link":"https://binbaz.org.sa/fatwas/9505/حكم-ركعتي-الوضوء-وصلاتها-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_377/37716.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":11337,"question":"سماحة الشيخ، هذا السائل الذي رمز لاسمه بـ( سعد . ح) مصري ومقيم بالمملكة العربية السعودية يقول: ما هي كيفية صلاة الاستخارة، وما هو الدعاء المشروع، وهل يكون هذا الدعاء أثناء صلاة الركعتين أم بعد الانتهاء من الصلاة؟","title":"ما كيفية صلاة الاستخارة ودعائها؟","answer":"الجواب:  صلاة الاستخارة بينها النبي ﷺ وهي أنه يصلي ركعتين إن هم بأمر وأشكل عليه، يصلي ركعتين ثم بعد الصلاة يرفع يديه ويدعو بما دعا به النبي ﷺ وعلمه أمته: اللهم إني أستخيرك بعلمك وأستقدرك بقدرتك وأسألك من فضلك العظيم، فإنك تعلم ولا أعلم وتقدر ولا أقدر وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر ويسميه باسمه هذا السفر، هذا الزواج، وأشباه ذلك يسميهه هذا الأمر خير لي في ديني ومعاشي وعاقبة أمري فيسره لي ثم بارك لي فيه، وإن كنت تعلم أنه شر لي، في ديني ومعاشي وعاقبة أمري فاصرفه عني واصرفني عنه وقدر لي الخير حيث كان ثم أرضني به هذا هو الدعاء الشرعي في الاستخارة. يرفع يديه ويقول هذا الدعاء بعد الركعتين، في الضحى في الظهر في الليل أي وقت يفعله في الضحى في الظهر في الليل، ما فيه أوقات ...، وقت الاستخارة واسع يصلي ركعتين يطمئن فيهما ثم يقول هذا الدعاء بعد السلام، يرفع يديه ويحمد الله ويصلي على النبي ﷺ. هذه السنة يحمد الله أولًا، ويصلي على النبي ﷺ؛ لأن هذا من أسباب الإجابة ثم يقول: اللهم إني أستخيرك بعلمك وأستقدرك بقدرتك وأسألك من فضلك العظيم، فإنك تعلم ولا أعلم وتقدر ولا أقدر وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر ويسميه باسمه  السفر إلى كذا، زواجي من بنت فلان، شرائي الأرض الفلانية، الذي أشكل عليه وأحب فيه الاستخارة اللهم إن كنت تعلم أن هذا الأمر خير لي في ديني ومعاشي وعاقبة أمري فيسره لي ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر شر لي في ديني ومعاشي وعاقبة أمري فاصرفه عني واصرفني عنه وقدر لي الخير حيث كان ثم أرضني به نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9519/ما-كيفية-صلاة-الاستخارة-ودعاىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_292/29216.mp3","categories":["صلاة التطوع"]},{"id":11396,"question":"أثناء صلاة السنة تقام صلاة الجماعة، فهل أترك السنة، وأذهب إلى صلاة الجماعة، أم أكمل صلاة السنة؟ وفي حالة ترك صلاة السنة ما كيفية الخروج منها مأجورين؟","title":"حكم الدخول في الجماعة الثانية بنية النافلة","answer":"الجواب:  مادمت صليت الفريضة؛ الحمد لله يكفيك هذا، وإذا شرعت في صلاة النافلة؛ كملها، وليس هناك حاجة إلى قطعها للصلاة مع الجماعة الآخرين، وإن صليت معهم قبل أن تشرع في النافلة، صليت مع الجماعة الجديدة؛ فلا بأس، لكن هم ليسوا في حاجة إليك وإن صليت معهم؛ فلا بأس، أما إن كان واحدًا؛ صل معه حتى .... أنت وإياه جماعة، لقوله ﷺ لما دخل رجل وقد صلى الناس قال -عليه الصلاة والسلام-: من يتصدق على هذا فيصلي معه فإذا كان واحدًا، وقد فاتته الصلاة، فقمت صليت معه؛ حتى تكونا جميعًا جماعة؛ فهذا حسن. أما إذا كانوا جماعة؛ فأنت مخير إن صليت معهم؛ فلك أجر، وإن اشتغلت بالنافلة، أو خرجت؛ فلا بأس، ولهذا قال النبي ﷺ لأبي ذر لما ذكر أنه يأتي في آخر الزمان قوم يؤخرون الصلاة عن وقتها، قال النبي ﷺ: صل الصلاة لوقتها، فإن أقيمت وأنت في المسجد؛ فصل معهم؛ فإنها لك نافلة نعم.","link":"https://binbaz.org.sa/fatwas/9574/حكم-الدخول-في-الجماعة-الثانية-بنية-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29316.mp3","categories":["صلاة التطوع","صلاة الجماعة"]},{"id":11461,"question":"يسأل سماحتكم عن صلاة الضحى كم ركعة؟ وماذا يقول الإنسان عندما ينوي هل يقول: نويت أصلي صلاة الضحى؟ أم يقول قبل تكبيرة الإحرام؟ أي شيء آخر؟ أرشدوني جزاكم الله خيرًا.","title":"عدد ركعات الضحى","answer":"الجواب: صلاة الضحى سنة مؤكدة، رغب فيها النبي ﷺ وحث عليها، وأوصى بها جماعة من أصحابه  وأقلها ركعتان تسليمة واحدة، وإن صلى أربعًا، أو ستًا، أو ثمانًا، أو أكثر؛ كله خير، لكن أقلها ركعتان، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9642/عدد-ركعات-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38116.mp3","categories":["صلاة التطوع"]},{"id":11608,"question":"من عمان في المملكة الأردنية الهاشمية رسالة بعث بها أحد الإخوة يقول المرسل: أحمد سولد، يسأل ويقول: ما هي صلاة التسابيح؟ وما عدد ركعاتها؟ وما هو حكمها؟ وكيف تؤدى؟ وما هو ثوابها؟ جزاكم الله خيرًا.","title":"حكم صلاة التسابيح وبيان كيفيتها","answer":"الجواب:  صلاة التسبيح غير ثابتة .... جاءت من طرق كلها ضعيفة، لا تصح عن النبي ﷺ فلا يشرع العمل بها، ولا الدعوة إليها، ومن صحح حديثها فقد غلط، الواجب على المسلم أن يتمسك بالسنة المعروفة والعبادة الثابتة، ويترك ما خالف ذلك، وقد ثبت عن النبي ﷺ جميع ما فعله من الصلوات، النافلة والفريضة، فلم يصل صلاة التسبيح، ولم ينقل عنه أحد أنه صلى صلاة التسبيح، لا في الضحى، ولا في الليل، ولا في السفر، ولا في الحضر. فالواجب الإعراض عنها، وترك العمل بها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9791/حكم-صلاة-التسابيح-وبيان-كيفيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_388/38802.mp3","categories":["صلاة التطوع"]},{"id":11670,"question":"يقول أخونا: أرجو ذكر الرواتب والسنن التي تصلى قبل كل صلاة وبعدها؟","title":"ما الرواتب والسنن القبلية والبعدية للصلاة؟","answer":"الجواب:  الرواتب التي حافظ عليها النبي ﷺ مع الصلوات الخمس اثنتا عشرة ركعة -عليه الصلاة والسلام-: أربع قبل الظهر تسليمتين، وثنتان بعد الظهر تسليمة واحدة، وثنتان بعد المغرب، وثنتان بعد العشاء، وثنتان قبل صلاة الصبح، هذه اثنا عشر، كان يحافظ عليها النبي ﷺ في الحضر، أما في السفر كان يتركها إلا سنة الفجر -عليه الصلاة والسلام- كان يصليها في السفر والحضر، وكان يتهجد بالليل ويوتر بالليل في السفر والحضر -عليه الصلاة والسلام- ويستحب أربعًا قبل العصر، وليس من الرواتب، لكن قال فيها النبي ﷺ: رحم الله امرًأ صلى أربعًا قبل العصر ويشرع أيضًا لمن دخل المسجد أن يصلي تحية المسجد، وإذا وافقت الراتبة كفت الراتبة، من دخل المسجد بعد أذان الظهر، وصلى أربع ركعات؛ كفته عن الراتبة وعن تحية المسجد. وهكذا إذا دخل الفجر بعد الأذان وصلى سنة الفجر كفت عن تحية المسجد، وإذا نواهما جميعًا فلا بأس، ويستحب أيضًا بين كل أذانين صلاة، بين الأذان والإقامة، فلو كان صلى الراتبة بعد الزوال، وتأخر الأذان، ثم أذن؛ شرع له أن يصلي ركعتين بين الأذانين، زيادة على الراتبة التي تصلى بعد الزوال لكن قبل الأذان. وهكذا لو صلى الراتبة في البيت راتبة الفجر، ثم جاء إلى المسجد؛ شرع له أن يصلي ركعتين تحية المسجد، إذا كان وجد الإمام لم يدخل في الصلاة.  وهكذا إذا أذن المؤذن وهو في المسجد بعد أذان المغرب؛ شرع له أن يقوم .... يصلي ركعتين قبل الصلاة.  وهكذا إذا أذن المؤذن لصلاة العشاء وهو في المسجد؛ شرع له أن يصلي ركعتين قبل الصلاة، وإذا دخل بعد الأذان، وصلى تحية المسجد؛ كفت، وإن صلى زيادة؛ فلا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9856/ما-الرواتب-والسنن-القبلية-والبعدية-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_299/29904.mp3","categories":["صلاة التطوع"]},{"id":11740,"question":"تقول في سؤالها الأخير: من الأوقات المنهي عنها الصلاة بعد العصر، فأنا كان علي نذر، ثم إني صليت نذرًا، وقرأت جزئين من القرآن الكريم، وصليت بعد العصر، فقالت لي أختي: إن ذلك من الأوقات المنهي عنها، فقلت لها: إن ذلك نذر، وليس قضاء صلاة مفروضة، فهل يجب علي الإعادة، أو أن ما فعلته كان صحيحًا؟ جزاكم الله خيرًا.","title":"حكم من نذر أن يصلي في وقت نهي","answer":"الجواب:  الواجب عليك الإعادة؛ لأنه ما هو محل صلاة، بعد العصر وبعد الفجر ليس محل صلاة إلا ذوات الأسباب، الصلاة المشروعة فيه كالكسوف بعد العصر، تحية المسجد، صلاة الطواف، أما النذر فله أوقات أخرى في إمكانك أن تصلي في الليل الظهر والضحى، وإن كنت عينت الصلاة بعد العصر قلت: أصلي بعد العصر هذا نذر معصية عليك كفارة يمين عن هذه الصلاة؛ لأن نذر الصلاة بعد العصر وبعد الصبح نذر معصية؛ لأنه ليس وقت الصلاة، وقت نهي؛ فعليك كفارة اليمين، كفارة النذر كفارة اليمين، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9922/حكم-من-نذر-ان-يصلي-في-وقت-نهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_421/42114.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":11773,"question":"استخرت الله  في أمر، ثم حدثت والدي بأن الله قد اختار هذا، فهل تسقط الاستخارة بذلك؟","title":"حكم القول بعد الاستخارة: إن الله اختار لي هذا الأمر","answer":"الجواب:  ما دمت فعلتها انتهت، ما دمت فعلت الاستخارة، وانشرح صدرك؛ فلا مانع أن تخبر والدك بذلك، وتفعل ما شرح الله صدرك له، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9960/حكم-القول-بعد-الاستخارة-ان-الله-اختار-لي-هذا-الامر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_394/39422.mp3","categories":["صلاة التطوع"]},{"id":11808,"question":"بعد هذا سماحة الشيخ رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين ضمنها جمعًا من الأسئلة وهو من بني غازي في ليبيا، يقول: أسألكم لو تكرمتم عن مدى صحة الحديث الوارد في صلاة التسبيح إذ وجدت هذا الحديث في أكثر من كتاب، يقول بعد القراءة في كل ركعة: سبحان الله، والحمد لله، ولا إله إلا الله، ويستمر في سرد الحديث -سماحة الشيخ- ليسأل سماحتكم عن حكم صلاة التسبيح؟ جزاكم الله خيرًا.","title":"أحاديث صلاة التسابيح لا تصح","answer":"الجواب:  الحديث المذكور قد تتبعنا أسانيده، وكلام العلماء فيه؛ فاتضح من ذلك أنه غير صحيح، وأنه مخالف للأحاديث الصحيحة، وأن أسانيده كلها ضعيفة، فلا يعول عليه، والمشروع للمؤمن أن يصلي كما ثبت عن النبي ﷺ في الأحاديث الصحيحة من غير حاجة إلى التسبيحات التي جاءت فيه، يصلي كما فعل النبي ﷺ بالقراءة في حال القيام، والتسبيح في حال الركوع: سبحان ربي العظيم، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، وهكذا ربنا ولك الحمد في حال القيام إلى آخره، وهكذا التسبيح في السجود، سبحان ربي الأعلى، سبحان ربي الأعلى، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، سبوح قدوس رب الملائكة والروح، هذا هو الوارد، أما .... الزيادات التي في حديث التسبيح، هذه كلها غير صحيحة، ولا يعتمد عليها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9992/احاديث-صلاة-التسابيح-لا-تصح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_423/42310.mp3","categories":["صلاة التطوع","الحكم على الأحاديث"]},{"id":11829,"question":"يسألكم -يحفظكم الله- عن صلاة الضحى، وعن وقتها، وعدد ركعاتها، وكيف تؤدى، وهل يجب على الإنسان أن يقرأ فيها سورًا معينة، أم أي شيء من القرآن؟","title":"كيف تؤدى صلاة الضحى؟","answer":"الجواب:  صلاة الضحى سنة أوصى بها النبي ﷺ بعض أصحابه، وفعلها في بعض الأحيان -عليه الصلاة والسلام- وفعلها يوم الفتح، صلى ثمان ركعات الضحى يوم الفتح، فهي سنة مؤكدة. ووقتها ما بين ارتفاع الشمس قيد رمح إلى وقوف الشمس الضحى كله، وقتها ما بين ارتفاع الشمس قيد رمح إلى وقوف الشمس قبيل الظهر، فإذا صلاها في أول الوقت، أو في أثنائه؛ فقد أصاب السنة، لكن أفضلها عند اشتداد الضحى، إذا اشتد الحر، ورمضت الفصال كما قال ﷺ في الحديث الصحيح يقول ﷺ صلاة الأوابين حين ترمض الفصال يعني: حين يشتد حر الرمضاء على أولاد الإبل، فصلاتها في الضحى في ارتفاع الضحى أفضل، وإن صلاها بعد ارتفاع الشمس؛ فقد حصلت السنة. ويقرأ فيها ما تيسر سورًا، أو آيات ليس فيها شيء مخصوص، يقرأ فيها ما تيسر من الآيات، أو من السور. وأقلها ركعتان تسليمة واحدة، وإن صلى أربعًا، أو ستًا، أو ثمانًا، أو أكثر، يسلم من كل ثنتين؛ فكله حسن، والنبي ﷺ صلاها يوم الفتح، صلى ثماني ركعات، يسلم من كل ثنتين -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10014/كيف-تودى-صلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_395/39517.mp3","categories":["صلاة التطوع"]},{"id":11905,"question":"هل معنى: أن صلاة الليل والنهار مثنى مثنى أن الأربع الركعات القبلية قبل الظهر أصليها على ركعتين ركعتين؟","title":"تثنية صلاة النافلة في الليل والنهار","answer":"الجواب:  نعم نعم، تصلى ركعتين ركعتين في الليل والنهار، الرواتب وغير الرواتب، هذه السنة، لكن لو سرد في الوتر بالليل، سرد ثلاثًا جميعًا، أو خمسًا جميعًا، أو سبعًا جميعًا؛ فلا بأس، لكن كونه يصلي ثنتين ثنتين؛ فهذا هو الأفضل؛ لقوله ﷺ: صلاة الليل مثنى مثنى، فإذا خشي الصبح صلى ركعة واحدة، توتر له ما قد صلى لكن ثبت عنه ﷺ أنه أوتر بخمس جميعًا، وبثلاث جميعًا، أو بسبع جميعًا، سرد في بعض الأحيان لا بأس، لكن الأفضل دائمًا ثنتين ثنتين، هذا هو الأفضل، ثم يوتر بواحدة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10089/تثنية-صلاة-النافلة-في-الليل-والنهار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_426/42606.mp3","categories":["صلاة التطوع"]},{"id":11936,"question":"يقول: أفتونا في صلاة الضحى، في عدد ركعاتها، وعن القراءة فيها، والساعة التي تؤدى فيها، وهل لها تسبيح وتهليل؟ جزاكم الله خيرًا.","title":"صلاة الضحى.. حكمها وصفتها ووقتها","answer":"الجواب:  صلاة الضحى ركعتان، ومن زاد؛ صلاها أربعًا، أو أكثر، كله طيب، والنبي ﷺ أوصى أبا هريرة بركعتي الضحى، وأوصى أبا الدرداء كذلك بصلاة الضحى وقال ﷺ: يصبح على كل سلامى أحدكم صدقة، فكل تسبيحة صدقة، وكل تهليلة صدقة، وكل تحميدة صدقة، وكل تكبيرة صدقة، وأمر بمعروف صدقة، ونهي عن منكر صدقة ثم قال: ويكفي من ذلك ركعتان تركعهما من الضحى رواه مسلم في الصحيح. هذا يدل على عظم الفائدة لهاتين الركعتين، وإذا صلى تسليمتين أربع ركعات، أو ثلاث تسليمات ست ركعات، أو أربع تسليمات ثمان ركعات؛ كله طيب، ولو صلى أكثر، لو صلى عشرًا، عشرين، ثلاثين يسلم من كل ثنتين؛ كله طيب. فالضحى كلها محل صلاة حتى تقف الشمس، والنبي ﷺ قد يصلي أربعًا، وقد يزيد تقول عائشة -رضي الله عنها-: \"كان النبي ﷺ يصلي الضحى أربعًا ويزيد ما شاء الله\" وفي يوم فتح مكة صلى ثمان ركعات، يسلم من كل ثنتين -عليه الصلاة والسلام- ولو صلى أكثر؛ فلا بأس، كله طيب إلا إذا وقفت الشمس؛ يمسك عند قرب الظهر، قبل الظهر بربع ساعة، أو نصف ساعة، عند توسط الشمس، إذا توسطت في كبد السماء قبل أن تميل للمغرب هذا هو وقت المنع، وقت الوقوف، عند توسطها في السماء قبل أن تميل إلى المغرب؛ يقف، لا يصلي إلا ذوات الأسباب، كدخول المسجد إذا دخل قبل الظهر يصلي تحية المسجد، أو طاف قبل الظهر بمكة، بالكعبة يصلي سنة الطواف، أو كسفت الشمس قبيل الظهر يصلي صلاة الكسوف، أو بعد العصر يصلي صلاة الكسوف؛ لأنها من ذوات الأسباب. وليس لها قراءة مخصوصة، يقرأ ما تيسر، يقرأ الفاتحة وما تيسر معها، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، يسأل عن التسبيح والتهليل هل لها .... ؟ الشيخ: مثلها مثلها يسبح في الركوع سبحان ربي العظيم، وفي السجود سبحان ربي الأعلى، أما بعدها ما في شيء مخصوص، نعم. المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10120/صلاة-الضحى-حكمها-وصفتها-ووقتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_427/42713.mp3","categories":["صلاة التطوع"]},{"id":11997,"question":"متى تكون صلاة النافلة؟ وهل لها زمن محدد؟","title":"ما أوقات وقت صلاة النافلة؟","answer":"الجواب:  كل الليل والنهار صلاة نافلة، كل الليل والنهار صلاة نافلة، إلا بعد العصر حتى تغيب الشمس، وبعد الفجر حتى ترتفع الشمس، وعند قيامها عند الزوال، قبل الزوال بقليل حتى تزول، أوقات ثلاثة: بعد طلوع الفجر إلى ارتفاع الشمس، هذا واحد، عند قيامها وسط النهار؛ حتى تميل إلى الغروب إلى جهة الغرب، وهو زمن قصير وقوفها، الثالث: بعد صلاة العصر إلى غروبها، والباقي كله صلاة، الليل كله صلاة والنهار كله صلاة، ما عدا هذه الأوقات الثلاثة. المقدم: ما شاء الله.","link":"https://binbaz.org.sa/fatwas/10182/ما-اوقات-وقت-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43111.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":11998,"question":"إذا عرض للمرء عارض، وأراد أن يصلي، وصادف وقت نهي، كأن يدخل مسجدًا، أو أن يطوف بالبيت؟","title":"حكم صلاة ذوات الأسباب في أوقات النهي","answer":"الجواب: إن كان ذوات الأسباب؛ لا بأس. المقدم: ذوات الأسباب. الشيخ: إذا كان مثل صلاة الطواف، إذا طاف بعد صلاة العصر، أو تحية المسجد، إذا دخل المسجد قبل المغرب، يصلي تحية المسجد ركعتين، نعم، أو صلاة الكسوف، كسفت الشمس بعد العصر؛ لأنها من ذوات الأسباب، يصلون صلاة الكسوف بعد العصر. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10183/حكم-صلاة-ذوات-الاسباب-في-اوقات-النهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_431/43112.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":12043,"question":"ما هو الفرق بين صلاة التطوع، وصلاة النفل، وصلاة الراتبة؟","title":"الفرق بين صلاة التطوع والنفل والراتبة","answer":"الجواب:  كلها تطوع، النفل والراتبة والتطوع كلها واحد، الرواتب: الصلوات المشروعة مع الفرائض، كسنة الظهر، وسنة العصر، وسنة المغرب، وسنة العشاء، وسنة الفجر، الوتر كلها رواتب، كلها تطوع، صلاة الضحى تطوع، وصلاة الوضوء، من توضأ وصلى ركعتين؛ فهو تطوع، كل هذا يقال له: نافلة، ما عدا الخمس تطوع، ولهذا لما سئل النبي ﷺ سأله بعض الناس لما خبره عن الصلوات الخمس؛ قال له السائل: هل علي غيرها؟ قال: لا إلا أن تطوع. فالتطوع هو النفل، وهو ما زاد على الخمس: الظهر والعصر والمغرب والعشاء والفجر يقال له: تطوع، مثل: صلاة الضحى، الرواتب مع الفرائض، تحية المسجد، صلاة الليل، الوتر، صلاة الضحى، كلها تطوع، ويلحق بالخمس صلاة العيد، فهي فرض على الصحيح،. أما الجمعة فهي إحدى الخمس، صلاة الجمعة هي إحدى الخمس، فرض في يومها يعني: إحدى الصلوات الخمس، وأما صلاة الاستسقاء؛ فهي تطوع، صلاة الاستغاثة تطوع، تحية المسجد تطوع، صلاة الجنازة فرض كفاية، إذا قام بها من المسلمين سقطت عن البقية، إذا قام بها ولو واحد مكلف سقطت عن الباقين صلاة الجنازة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10228/الفرق-بين-صلاة-التطوع-والنفل-والراتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43312.mp3","categories":["صلاة التطوع"]},{"id":12085,"question":"المستمع خميس محمد علي أبو رائد يسأل ويقول: حدثوني عن ركعتي الضحى، وعن فضلها، جزاكم الله خيرًا، وهل إذا رأيت الناس يصلونها أنضم معهم؟ وجهوني جزاكم الله خيرًا.","title":"حكم صلاة الضحى وعدد ركعاتها","answer":"الجواب:  صلاة الضحى سنة قد أوصى بها النبي ﷺ بعض الصحابة، وكان يفعلها كثيرًا -عليه الصلاة والسلام- فهي سنة أقلها ركعتان، ومن صلاها أربعًا، أو أكثر؛ فلا بأس، وربما صلاها ثمان كما فعل يوم الفتح، صلى ثمان ركعات، عليه الصلاة والسلام.  فالمقصود أنها سنة في السفر والحضر، ومن تركها؛ فلا حرج عليه، ومن واظب عليها؛ فهو أفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10270/حكم-صلاة-الضحى-وعدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_435/43519.mp3","categories":["صلاة التطوع"]},{"id":12094,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول المرسلة: (ح. ن) أختنا ضمنت رسالتها بعض القضايا في إحداها تقول: أسألكم عن حكم صلاة التسبيح، ذلك أن إحدى صديقاتي قرأت في كتاب شيئًا عن فضلها، ونصحتها بأدائها، ونصحتني كذلك، فما هو توجيهكم؟ جزاكم الله خيرًا.","title":"ما حكم صلاة التسابيح وما فضلها؟","answer":"الجواب:  صلاة التسبيح ليست ثابتة، بل أحاديثها كلها ضعيفة، وكلها شاذة، ومخالفة للصلاة الشرعية المحفوظة عن النبي ﷺ فالذي أوصي به جميع المستمعين أن لا يشتغلوا بها، وأن يصلوا الصلاة المعتادة المعروفة عن النبي ﷺ، أما صلاة التسبيح فأحاديثها كلها غير صحيحة عند أئمة الحديث المعروفين بالإتقان والعناية بهذا الأمر، هذا هو الصواب، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10279/ما-حكم-صلاة-التسابيح-وما-فضلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_436/43608.mp3","categories":["صلاة التطوع","الحكم على الأحاديث"]},{"id":12138,"question":"تسأل سماحتكم عن السنن الرواتب، وإذا كان هناك أربع ركعات مثلًا قبل الظهر، أو قبل العصر، فهل أسلم من كل ركعتين؟ أم كيف يكون الحال؟ جزاكم الله خيرًا.","title":"السنن الرواتب وكيفية أدائها","answer":"الجواب: السنن الرواتب اثنتا عشرة ركعة: منها: أربع قبل الظهر تسليمتان، وثنتان بعدها تسليمة واحدة، ثنتان بعد المغرب تسليمة واحدة، ثنتان بعد العشاء تسليمة واحدة، ثنتان قبل صلاة الفجر تسليمة واحدة، كان النبي يحافظ عليها -عليه الصلاة والسلام- في الحضر، ويقول ﷺ: من صلى ثنتي عشر ركعة تطوعًا في يوم وليلة؛ بني له بهن بيت في الجنة. وجاء في حديث أم حبيبة تفسيرها اثنا عشر بهذه الركعات الرواتب، فمن حافظ عليها؛ فهو على خير عظيم، وفي هذا الحديث أنه موعود بالجنة، إذا صلاها في اليوم تطوعًا؛ بني له بهن بيت في الجنة، وهي كما تقدم: أربع قبل الظهر، يسلم من كل ثنتين، ثنتان بعد الظهر يعني: ركعتين، ركعتان بعد المغرب، ركعتان بعد العشاء، ركعتان قبل صلاة الصبح، هذه يقال لها: الرواتب. وإن صلى بعد الظهر أربعًا؛ كان أفضل؛ لقوله ﷺ: من حافظ على أربع قبل الظهر، وأربع بعدها؛ حرمه الله على النار لكنها ليست راتبة، أربع بعد الظهر، الراتبة ثنتان، فإذا زاد وصلى ثنتين عملًا بقول النبي ﷺ كان هذا خيرًا؛ لقوله ﷺ من حديث أم حبيبة بنت أبي سفيان أم المؤمنين -رضي الله عنها- أنها سمعت النبي يقول -عليه الصلاة والسلام-: من حافظ على أربع قبل الظهر، وأربع بعدها؛ حرمه الله على النار. ويستحب أيضًا أن يصلي أربعًا قبل العصر، ليست راتبة، لكن يستحب أن يصليها تسليمتين؛ لقوله ﷺ: رحم الله امرأً صلى أربعًا قبل العصر رواه أحمد والترمذي وجماعة بإسناد صحيح عن ابن عمر. ويستحب أيضا أن يصلي بين كل أذانين صلاة، بين أذان المغرب والإقامة، أذان العشاء والإقامة ركعتين، لقوله ﷺ: بين كل أذانين صلاة، بين كل أذانين صلاة، وقال في الثالثة: لمن شاء وقال: صلوا قبل المغرب، صلوا قبل المغرب، ثم قال: فلمن شاء وكان الصحابة  يصلون قبل المغرب ركعتين، بعد أذان المغرب ركعتين قبل أن تقام الصلاة، هذه سنة ليست رواتب، لكن سنة، أربع بعد الظهر سنة، وليست راتبة، الراتبة ثنتان، أربع قبل العصر تسليمتين سنة، لكن ليست راتبة، يعني: ما كان النبي ﷺ يواظب عليها، لكن إذا حافظ عليها المؤمن؛ لقول النبي ﷺ: رحم الله امرأ صلى أربعًا قبل العصر كان هذا أفضل ...... حافظ عليها قبل العصر عملًا بقول النبي ﷺ. هكذا إذا صلى بين المغرب، بين أذان المغرب والإقامة ركعتين، بين أذان العشاء والإقامة ركعتين كان هذا أفضل، وهكذا الضحى؛ لأن الضحى سنة، الضحى بعد ارتفاع الشمس إلى وقوفها، يصلي ركعتين، أو أربعًا أو أكثر، كان النبي يفعلها ﷺ بعض الأحيان، ووصى بها جماعة من الصحابة سنة الضحى، وهي مستحبة في السفر والحضر. وهكذا التهجد بالليل، كونه يتهجد بالليل بعد صلاة العشاء، يصلي ما يسر الله له، ويوتر بواحدة، يصلي ثلاثًا، أو خمسًا، أو سبعًا، أو تسعًا، أو إحدى عشر، أو ثلاث عشر، أو أكثر، يصلي ما تيسر له في أول الليل، أو في وسط الليل، أو في آخر الليل؛ تأسيًا بالنبي ﷺ فإنه كان يتهجد بالليل -عليه الصلاة والسلام- ويوتر بواحدة -عليه الصلاة والسلام- وكان ﷺ قد أوتر في أول الليل، وفي بعض الأحيان في وسط الليل، ثم استقر أخيرًا اجتهاده ووتره وتهجده في آخر الليل -عليه الصلاة والسلام- وهو الأفضل إذا تيسر، يقول النبي ﷺ: من خاف ألا يقوم من آخر الليل؛ فليوتر أوله، ومن طمع أن يقوم آخر الليل؛ فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل.  وأقل ذلك ركعة واحدة، أقل شيء ركعة واحدة، يوتر بها بعد العشاء، بعد سنة العشاء، وإن أوتر بثلاث؛ فهو أفضل، وإن أوتر بأكثر؛ فهو أفضل، يسلم من كل ثنتين. وكان النبي ﷺ في الغالب يتهجد بإحدى عشرة ركعة، يسلم من كل ثنتين، ويوتر بواحدة في آخر الليل، وربما صلى ثلاث عشرة، يسلم من كل ثنتين -عليه الصلاة والسلام- وهذا هو الأفضل، وإن سرد ثلاثًا جميعًا، ولم يجلس إلا في آخرها، أو خمسًا جميعًا، ولم يجلس إلا في آخرها؛ فلا حرج، فعله النبي ﷺ نوع من السنة، وإن سرد سبعًا كذلك لا بأس؛ لأن النبي ﷺ فعل هذا، سرد سبعًا جميعًا في بعض الليالي، وفي بعض الليالي يجلس في السادسة، ويتشهد التشهد الأول، ثم يقوم ويأتي بالسابعة، وإن سرد تسعًا جميعًا كذلك لا بأس، لكن يجلس في الثامنة، كان النبي ﷺ يجلس في الثامنة، ويتشهد التشهد الأول، ثم يقوم، ويأتي بالتاسعة. لكن الأفضل مثلما تقدم أنه يسلم من كل ثنتين، هذا هو الأفضل؛ تقول عائشة -رضي الله عنها-: كان النبي ﷺ يوتر، يصلي إحدى عشرة في الليل، يسلم من كل ثنتين، ويوتر بواحدة، وقال -عليه الصلاة والسلام-: صلاة الليل مثنى مثنى يعني: ثنتين ثنتين فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى هذا هو الأفضل. وإذا خاف ألا يقوم من آخر الليل مثلما تقدم يصلي أول الليل قبل أن ينام، يصلي ثلاثًا، أو خمسًا، أو أكثر، يسلم من كل ثنتين؛ احتياطاً، خوفًا ألا يقوم من باب الحزم، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10323/السنن-الرواتب-وكيفية-اداىها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_439/43907.mp3","categories":["صلاة التطوع"]},{"id":12140,"question":"ترجو من سماحتكم أن تحددوا وقت صلاة الضحى؟","title":"مشروعية صلاة الضحى ووقت فعلها","answer":"الجواب:  مثلما تقدم، صلاة الضحى تبدأ من ارتفاع الشمس قيد رمح، بعد طلوعها بنحو ربع ساعة تقريبًا تبدأ الصلاة، وتنتهي عند وقوف الشمس، إذا كانت الشمس في وسط السماء، لم تمل إلى الغروب، توسطت السماء، هذا الوقوف محل نهي عن الصلاة، وذلك الوقت تسجر فيه جهنم كما قاله النبي -صلى الله عليه وسلم- فينهى عن الصلاة فيه. لكن الأفضل أن يصلي الضحى إذا رمضت الفصال إذا اشتد الضحى إذا ارتفع الضحى، هذا هو الأفضل، وإن كان جالسًا في المسجد إلى طلوع الشمس؛ فالأفضل له أن يصلي ركعتين عند قيامه وخروجه بعد ارتفاع الشمس، أو في بيته إن جلس في بيته بعد الفجر، إذا انتهى وطلعت الشمس يصلى ركعتين، تكفي عن صلاة الضحى، وإن صلى بعد ذلك إذا اشتد الضحى فهذا من مزيد الخير، من مزيد الخير والفضل، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10325/مشروعية-صلاة-الضحى-ووقت-فعلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_439/43909.mp3","categories":["صلاة التطوع"]},{"id":12259,"question":"يقول: في صلاة المغرب بعض المصلين يصلون ركعتين قبل فرض المغرب، ويقولون: إنها سنة قبلية، والبعض الآخر لا يصلي سنةً قبلية، ويقولون: ليس هناك سنة قبل فرض المغرب،  هل توجد سنة؟ أو لا؟ وما الحكم فيما قيل؟ جزاكم الله خيرًا.","title":"حكم الصلاة بعد أذان المغرب قبل الفرض","answer":"الجواب:  ليس في المغرب سنة قبلية راتبة، ولكن الرسول ﷺ قال: صلوا قبل المغرب ثم قال في الثالثة: لمن شاء؛ دل على أنها مشروعة، وليست واجبة، إذا كان الإنسان جالسًا قبل المغرب، ثم أذن، يشرع له أن يقوم .. يصلي ركعتين؛ لهذا الحديث الصحيح، ولقوله ﷺ: بين كل أذانين صلاة، بين كل أذانين صلاة يعني: الأذان والإقامة، فإذا صلى ركعتين فقد امتثل وفعل هذا المشروع، لكن لم تكن راتبة يحافظ عليها النبي ﷺ إنما هي مشروعة لمن كان في المسجد حين الأذان، يقوم ويصلي ركعتين، أو دخل بعد الأذان، يصلي ركعتين تحية المسجد؛ لهذين الحديثين المعروفين نعم. وكان الصحابة يفعلونها أيضًا، كان الصحابة يصلون قبل الصلاة ركعتين، إذا أذن المؤذن؛ قاموا وصلوا ركعتين، والنبي يراهم ﷺ ولم ينههم عن ذلك، بل أمر بهذا، قال: صلوا قبل المغرب، صلوا قبل المغرب، ثم قال في الثالثة: لمن شاء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10459/حكم-الصلاة-بعد-اذان-المغرب-قبل-الفرض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_449/44910.mp3","categories":["صلاة التطوع"]},{"id":12409,"question":"تقول: سنة الوضوء هل المشروع فيها أن تكون عقب الوضوء مباشرة، أم يجوز تأخيرها بسبب بعض الأشغال مع بقاء النية على تأديتها بعد الفراغ من الشغل؟ وما هو الأفضل في هاتين الحالتين؟ جزاكم الله خيرًا.","title":"هل يلزم المبادرة بسنة الوضوء أم يجوز تأخيرها؟","answer":"الجواب:  الأفضل البدار بالصلاة، الأفضل بعد الوضوء يبادر بصلاة ركعتين، وإن شغل عنها وصلاها بعد ذلك؛ فلا بأس كله طيب، لكن الأفضل البدار، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10622/هل-يلزم-المبادرة-بسنة-الوضوء-ام-يجوز-تاخيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40210.mp3","categories":["صلاة التطوع"]},{"id":12417,"question":"أيضًا تقول أختنا: ورد في الحديث أن سنة الضحى أقلها ركعتان، وأكثرها ثمان ركعات، هل يجوز لي أن أزيد على ثمان ركعات؟ وهل إذا صليت ركعتي طلوع الشمس أحسبها مع سنة الضحى لتكون ثمان ركعات، أم أنها مستقلة؟","title":"عدد ركعات صلاة الضحى","answer":"الجواب:  ليس في الحديث أن أكثره ثمان ركعات، إنما هذا من كلام بعض أهل العلم، من كلام بعض أهل العلم، يقولون: أكثرها ثمان ركعات، والصحيح أنه لا حد لأكثرها، يصلي ثمانًا، أو عشرًا، أو عشرين؛ لا بأس، أو أكثر، لكن أقلها ركعتان. وقد أوصى النبي ﷺ جماعة من الصحابة بركعتي الضحى، فأقلها ركعتان، وإذا صلى أربعًا، أو ستًا، أو ثمانًا، أو عشرًا، أو أكثر؛ يسلم من كل ثنتين، فكله طيب، كله مشروع، والحمد لله، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا: إذا صلت ركعتي الشروق -كما سمتها- وصلت أيضًا الضحى ثمان ركعات؛ فهي على صواب. الشيخ: أو أكثر. المقدم: أو أكثر. الشيخ: كله خير. المقدم: الحمد لله جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10621/عدد-ركعات-صلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40209.mp3","categories":["صلاة التطوع"]},{"id":12428,"question":"تسأل أختنا: هل يجوز أن أصلي صلاة الاستخارة لغيري، وأغير صيغة الدعاء بحيث يأتي على هذا النمط: (اللهم إن كنت تعلم أن هذا الأمر هو خير لها أو له في دينه أو دنياها) وهكذا؟","title":"حكم صلاة الاستخارة عن الغير","answer":"الجواب:  لا أعلم في هذا دليلًا، إنما جاءت السنة بمن أراد الشيء في الحديث: إذا هم أحدكم بأمر؛ فليصل ركعتين، ثم ليقل: اللهم فالسنة لمن هم بالأمر، وأشكل عليه يستخير هو. أما فلان يستخير لفلان ما أعلم له أصلًا، لا أعلم لهذا أصلًا، ولكن الرجل، أو المرأة كل منهما يستخير لنفسه، يدعو بالدعاء الذي يفهم، الذي يعرف، إذا كان ما يعرف الدعاء الوارد في الحديث؛ يسأل ربه، يقول: اللهم يسر لي الأصلح، اللهم اشرح صدري للأصلح الأحب إليك، لما فيه نفعي، لما فيه صلاحي، يدعو بالدعوات التي تتناسب، والحمد لله. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/10634/حكم-صلاة-الاستخارة-عن-الغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40303.mp3","categories":["صلاة التطوع"]},{"id":12487,"question":"بعد هذا رسالة وصلت إلى البرنامج من سوريا، بعث بها أحد الإخوة من هناك، يقول: طالب في الصف الثاني الثانوي العلمي في سوريا درعة، أخونا لم يذكر اسمه، إنما له سؤالان، في سؤاله الأول يقول: أصلي صلاة المغرب والعشاء في المسجد فرضًا، ولا أصلي السنة بسبب دراستي فهل يجوز هذا؟","title":"من يصلي الفريضة دون السنة","answer":"الجواب: السنة نافلة، السنة نافلة، من فعلها؛ فقد أحسن، وله الأجر، ومن تركها؛ فلا شيء عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10694/من-يصلي-الفريضة-دون-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_406/40605.mp3","categories":["صلاة التطوع"]},{"id":12500,"question":"بعد هذا رسالة وصلت إلى البرنامج من سوريا، بعث بها أحد الإخوة من هناك، يقول: طالب في الصف الثاني الثانوي العلمي في سوريا درعة، أخونا لم يذكر اسمه، إنما له سؤالان، في سؤاله الأول يقول: أصلي صلاة المغرب والعشاء في المسجد فرضًا، ولا أصلي السنة بسبب دراستي فهل يجوز هذا؟","title":"من يصلي الفريضة دون السنة","answer":"الجواب: السنة نافلة، السنة نافلة، من فعلها؛ فقد أحسن، وله الأجر، ومن تركها؛ فلا شيء عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10694/من-يصلي-الفريضة-دون-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_406/40605.mp3","categories":["صلاة التطوع"]},{"id":12509,"question":"يقول: أنا يا سماحة الشيخ أقوم كل ليلة قبل النوم بأداء ركعتي توبة من أي ذنب قمت به، وأستغفر الله، وأدعوه أن يغفر لي كل خطيئة، فهل هذا صحيح، أم لا؟","title":"هل صلاة التوبة مشروعة؟","answer":"الجواب:  هذا طيب، هذا عمل طيب، ومن أسباب التوبة. نعم، وسواء في آخر الليل، أو في وسط الليل، أو في الضحى، أو في الظهر، أو في أي وقت غير أوقات النهي، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ! هل هناك صلاة تسمى صلاة التوبة؟ الشيخ: .... هي هذه، كما رواها علي عن الصديق  رواه علي بن أبي طالب أمير المؤمنين  عن الصديق أبي بكر، عن النبي ﷺ أنه قال: ما من عبد يتطهر، فيحسن الطهور، ثم يصلي ركعتين، ثم يتوب إلى الله من ذنب إلا غفر الله له أو كما قال، عليه الصلاة والسلام. المقدم: جزاكم الله خيرًا، وأحسن إليكم، تدعون المسلم إلى أن يستغل هاتين الركعتين سماحة الشيخ؟  الشيخ: كل هذا طيب، سواء كان بالصلاة، أو بغير صلاة، الواجب التوبة، الله يقول سبحانه: يَا أَيُّهَا الَّذِينَ آمَنُوا تُوبُوا إِلَى اللَّهِ تَوْبَةً نَصُوحًا [التحريم:8] ويقول سبحانه: وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَا الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ [النور:31] والتوبة: هي الندم على الماضي من سيئات، والإقلاع من ذلك وتركه، والحذر منه؛ تعظيمًا لله، وخوفًا منه، مع العزم الصادق ألا يعود فيه، هذه التوبة، كون المؤمن يندم على ما مضى من سيئاته من زنا، أو عقوق، أو شرب مسكر، أو غير هذا، يندم ندمًا صادقًا، ويعزم ألا يعود في ذلك، ويقلع من ذلك، ويتركه؛ خوفًا من الله، وتعظيمًا لله، وإخلاصًا له، هذا يكون توبة، وإذا كان معها صلاة ركعتين؛ يكون أكمل وأكمل. نعم. وإذا كان الحق للناس؛ لا بد من تحللهم من ذلك، أو إعطائهم حقوقهم إذا كانت التوبة من ذنب يتعلق بالناس؛ ظلم للناس؛ فلا بد من أمر رابع: وهو أن يتحللهم من ذلك الشيء، أو يعطيهم حقوقهم، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10713/هل-صلاة-التوبة-مشروعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_407/40707.mp3","categories":["صلاة التطوع"]},{"id":12522,"question":"تسأل أختنا مع من يسأل عن صلاة التسبيح، وهل هي جائزة؟ جزاكم الله خيرًا.","title":"هل صلاة التسبيح جائزة؟","answer":"الجواب:  صلاة التسبيح غير صحيحة، وغير ثابتة، بل هي موضوعة، كذب، هذا هو الصواب، الذي عليه المحققون من أهل العلم: أنه لا أساس لها من الصحة، وإنما يصلي الإنسان الصلاة المعروفة بقراءة الفاتحة، وما تيسر معها إلى آخره في كل ركعة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10728/هل-صلاة-التسبيح-جاىزة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_408/40807.mp3","categories":["صلاة التطوع"]},{"id":12554,"question":"هل يعتبر ترك السنن القولية والفعلية عقوبة يعاقب عليها الإنسان، خصوصًا قيام الليل، أو صلاة الوتر؟ فإنني في كثير من الأحيان أترك صلاة الليل والوتر، فهل علي شيء في ذلك؟","title":"حكم ترك النوافل والسنن","answer":"الجواب:  الصواب لا شيء عليك، الصواب أنها نافلة، نعم، لكن ينبغي المداومة عليها، وعدم التساهل، نعم. المقدم: جزاكم الله خيرًا، وبقية السنن القولية. الشيخ: كلها نافلة، الفرائض خمس: الظهر والعصر والمغرب والعشاء والفجر والجمعة في محل الظهر، أما سنة الضحى والتهجد بالليل والرواتب كلها نافلة. نعم. المقدم: جزاكم الله خيرًا، هل من كلمة حول فوائدها يا شيخ عبدالعزيز ، فوائد النوافل؟  الشيخ: النوافل لها شأن عظيم، فيها أجر عظيم، ويكمل بها ما ينقص من الفرض، وهذه فائدة عظيمة، لصاحبها أجور عظيمة، وحسنات كثيرة، ومع ذلك يجبر بها ما قد يقع من النقص في الفرائض، نعم. المقدم: جزاكم الله خيرًا، كلمة أخرى أيضًا، أو ننتقل إلى رسالة أخرى؟ الشيخ: يكفي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10761/حكم-ترك-النوافل-والسنن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_410/41006.mp3","categories":["صلاة التطوع"]},{"id":12670,"question":"يسأل سؤالًا آخر سماحة الشيخ فيقول: حدثونا عن النوافل -الرواتب- عن عددها، وعن التنبيه إلى أهميتها، جزاكم الله خيرًا.","title":"رواتب الفرائض القبلية والبعدية","answer":"الجواب:  الرواتب المحفوظة عن النبي ﷺ أنه كان يداوم عليها، ويحافظ عليها: اثنتا عشرة ركعة في الليل والنهار، هذه يقال لها رواتب مع الفرائض: أربع قبل الظهر، وثنتان بعدها، وثنتان بعد المغرب، وثنتان بعد صلاة العشاء، وثنتان قبل صلاة الصبح، هكذا جاءت الأحاديث الدالة على ذلك من حديث عائشة، وابن عمر، وأم حبيبة وغيرهم. أربع قبل الظهر تسليمتين، ركعتان بعد الظهر تسليمة واحدة، وإن صلى أربعًا بعد الظهر؛ فهو أفضل لقوله ﷺ: «من حافظ على أربع قبل الظهر، وأربع بعدها؛ حرمه الله على النار» خرجه الإمام أحمد، وأهل السنن بإسناد حسن عن أم حبيبة -رضي الله عنها- وثنتان بعد المغرب، وثنتان بعد العشاء، وثنتان قبل صلاة الصبح، ذكر ذلك ابن عمر في الصحيحين متفق عليه من حديث ابن عمر، وذكر ذلك غير ابن عمر كعائشة وغيرها. ويستحب أيضًا أن يصلي أربعًا قبل العصر، كما في الحديث: رحم الله امرأً صلى أربعًا قبل العصر ويروى عن النبي ﷺ أنه فعل ذلك، وقد ثبت عنه أنه فعل ذلك في بعض الأحيان، عليه الصلاة والسلام. فالمقصود: أنه يستحب أن يصلي أربعًا قبل العصر بتسليمتين، وإن لم تسم راتبة، وهكذا بين الأذانين بعد أذان المغرب ركعتين، بعد أذان العشاء ركعتين، هذه مستحبة إذا أذن وهو في المسجد؛ قام وصلى ركعتين، وهكذا مع أذان العشاء، أو دخل المسجد بعد الأذان، وصلى ركعتين تحية المسجد، وإن زاد عليها؛ فلا بأس قبل الصلاة. أما الفجر فالسنة ركعتان قبلها فقط لا زيادة، ركعتان قبل الفجر، إن صلاهما في البيت؛ فهو أفضل، وإذا أتى المسجد؛ صلى ركعتي التحية قبل الصلاة، إذا جاء والإمام لم يقم الصلاة؛ صلى ركعتين تحية المسجد، وإن صلاهما في المسجد؛ كفتا عن تحية المسجد، إن صلاهما في المسجد؛ كفتا عن تحية المسجد لقوله ﷺ: لا صلاة بعد طلوع الفجر إلا ركعتي الفجر فإن فاتت؛ صلاهما بعد الصلاة، إن فاتتا لم يتيسر له أداؤهما قبل الفجر؛ صلاهما بعد الفجر، أو بعد طلوع الشمس، نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10880/رواتب-الفراىض-القبلية-والبعدية","audio":"","categories":["صلاة التطوع"]},{"id":12673,"question":"يسأل سماحتكم: هل يجب أن نقضي الفوائت من الرواتب؛ وذلك لأمور قد تعرض على المسلم، فلا يصلي الراتبة قبل الصلاة، أو بعدها؟ جزاكم الله خيرًا.","title":"حكم قضاء الصلوات الراتبة","answer":"الجواب:  لا يستحب قضاء الرواتب، إذا فاتت؛ فات وقتها، فات وقتها، فاتت، إلا الفجر فإن سنتها تقضى، إذا فاتته قبل الفجر؛ فالسنة أن يصليها بعد الفجر، أو بعد طلوع الشمس؛ لأن الرسول ﷺ أرشد إلى ذلك، وفعل ذلك، لما نام عن صلاة الفجر حتى طلعت الشمس؛ صلى الفجر مع سنتها. أما سنة الظهر لو فاتت، ولم ينتبه إلا بعد خروج الوقت؛ فإنها سنة فات محلها، لكن لو فاتته الراتبة الأولى قبل الظهر؛ صلاها بعد الظهر، والحمد لله، وهكذا سنة العشاء لو نسيها حتى طلع الفجر؛ سقطت، كذلك سنة المغرب لو نسيها وشغل عنها حتى غاب الشفق؛ سقطت...","link":"https://binbaz.org.sa/fatwas/10883/حكم-قضاء-الصلوات-الراتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41702.mp3","categories":["صلاة التطوع"]},{"id":12684,"question":"أؤدي صلاة الضحى ثماني ركعات ما بين السابعة والثامنة صباحًا، فهل ما فعلته صحيح؟","title":"وقت صلاة الضحى وعدد ركعاتها","answer":"الجواب:  نعم، قد فعلها النبي ﷺ صلى يوم الفتح سبحة الضحى ثماني ركعات، ويروى عن عائشة -رضي الله عنها- أنها قالت: إنه دخل بيتي في الضحى، فصلى ثماني ركعات. وصلاة الضحى موسع فيها، ثمان، أو عشر، أو أكثر، وأقلها ركعتان، وقد ثبت عنه ﷺ أنه أوصى أبا هريرة، وأبا الدرداء بركعتي الضحى، وكان يزور قباء في المدينة، فيصلي ركعتين ضحىً، عليه الصلاة والسلام. فالمقصود: أن ركعتي الضحى سنة مؤكدة، وأقلها ركعتان، وإذا صلى أربعًا، أو ستًا، أو ثمانًا، أو أكثر، فكل ذلك لا بأس به، قالت عائشة -رضي الله عنها-: \"كان النبي ﷺ يصلي الضحى أربعًا، ويزيد ما شاء الله\" قالت أم هانئ بنت أبي طالب -رضي الله عنها-: \"إنها شهدت النبي ﷺ صلى يوم الفتح سبحة الضحى ثماني ركعات\" نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10894/وقت-صلاة-الضحى-وعدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41712.mp3","categories":["صلاة التطوع"]},{"id":12789,"question":"آخر سؤال له يقول: حدثوني عن راتبة العشاء، جزاكم الله خيرًا؟","title":"ما صفة راتبة العشاء والتنفل بعدها؟","answer":"الجواب:  راتبة العشاء ركعتان، هكذا كان النبي يفعل -عليه الصلاة والسلام- ركعتان فقط، وإن صلى أربعًا، أو ثمانًا، أو أكثر؛ فلا بأس، الليل كله محل صلاة، لكن الراتبة اثنتان، ثم يصلي ما يشاء الله، له في أول الليل، أو في وسطه، أو في آخره، ثم يختم بواحدة وهي الوتر ركعة واحدة يختمها، ويقرأ فيها الحمد، وقل هو الله أحد، هذا هو السنة، سواءً في أول الليل، أو في وسطه، أو في آخره، يصلي ما كتب الله له، ثنتين، ويوتر بواحدة، يصلي أربعًا، ويوتر بواحدة، يصلي أكثر، ويوتر بواحدة. وكان النبي ﷺ في الغالب يصلي عشرًا، ويوتر بواحدة الحادي عشرة، وربما صلى ثنتي عشرة، وأوتر بواحدة وهي الثالثة عشر، يسلم من كل ثنتين -عليه الصلاة والسلام- ومن صلى أكثر، صلى مائة ركعة، وأوتر بواحدة، أو خمسين ركعة، وأوتر بواحدة؛ فلا حرج في ذلك، لكن يسلم من كل ثنتين يقول النبي ﷺ: صلاة الليل مثنى مثنى هكذا قال ﷺ: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح؛ صلى ركعة واحدة، توتر له ما قد صلى هذا السنة، يصلي ثنتين ثنتين في أول الليل، أو في وسطه، أو في آخره، ثم يختم بواحدة، يقرأ فيها الحمد، وقل هو الله أحد. وإذا أحب أن يقنت بعد الركوع؛ قنت بما يسر الله له بالدعاء الذي علمه النبي ﷺ الحسن اللهم اهدني فيمن هديت وإذا زاد معه بعض الدعوات طيب، بعد الركوع، هذا هو الأفضل، وإن صلى إحدى عشرة، أو ثلاث عشرة؛ فهو أفضل، مثل فعل النبي ﷺ إحدى عشرة، أو ثلاث عشرة، وإن صلى أقل، أو أكثر؛ فلا حرج في ذلك، والأمر واسع بحمد الله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11003/ما-صفة-راتبة-العشاء-والتنفل-بعدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_461/46109.mp3","categories":["صلاة التطوع"]},{"id":12820,"question":"مستمع من الجمهورية العراقية هو (أ. ن. ج. البياتي) بعث برسالة عرضنا بعضًا من أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول: ما هي صفة صلاة الضحى؟ وكم عدد ركعاتها؟ وما وقتها؟ وما هي أيضًا صفة صلاة تحية المسجد؟","title":"ما صفة صلاة الضحى وتحية المسجد؟","answer":"الجواب:  صلاة الضحى ركعتان هذا أقلها، وإن صلى أربعًا، أو أكثر؛ فلا بأس، ليس لها حد محدود، وأكثر ما وقع عن النبي ﷺ ثمان ركعات -عليه الصلاة والسلام- صلاها يوم الفتح هذا هو الأفضل، إذا صلى ثنتين، أو صلى أربعًا تسليمتين، أو صلى ستًا ثلاث تسليمات، أو صلى ثمانًا أربع تسليمات، أو صلى عشرًا خمس تسليمات؛ لا بأس كله طيب، وليس لها حد محدود. قال بعض أهل العلم: إن أكثرها ثمان، ولكن ليس عليه دليل، فليصل الإنسان ما يسر الله له، ثنتين، أو أربعًا، أو أكثر، يسلم من كل ثنتين، هذا هو الأفضل، يخشع فيها، ويطمئن، ويبدأ وقتها من ارتفاع الشمس قيد رمح، إلى وقوفها قبل الزوال بنحو ربع ساعة، أو ثلث ساعة تقريبًا، هذا وقت الضحى، والأفضل إذا اشتد الضحى قبل الظهر بساعة ساعتين هذا هو الأفضل، وهي صلاة الأوابين، حين ترمض الفصال كما قال النبي ﷺ فإذا صلاها قبل الظهر بساعة، أو ساعتين هذا أفضل، وإن صلاها بعد ارتفاع الشمس؛ كفى ذلك، وليس لها عدد محصور يصلي ما يسر الله له ثمانًا، أو أكثر، أو أقل. أما تحية المسجد فهي ركعتان فقط إذا دخل المسجد في أي وقت يصلي ركعتين، حتى ولو كان الإمام يخطب يوم الجمعة لا يجلس حتى يصلي ركعتين، وحتى في وقت النهي، هذا هو الصواب، إذا دخل بعد العصر يريد الجلوس في المسجد لصلاة المغرب، أو للدرس؛ صلى ركعتين، أو بعد الفجر، جاء للدرس، أو ليجلس في المسجد إلى طلوع الشمس؛ صلى ركعتين، هذا هو الصواب، نعم. المقدم: جزاكم الله خيرًا، يسأل أيضًا عن تحية المسجد سماحة الشيخ. الشيخ: تقدم الجواب عنه. المقدم: جزاكم الله خيرًا.  الشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/11034/ما-صفة-صلاة-الضحى-وتحية-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_463/46308.mp3","categories":["صلاة التطوع"]},{"id":12839,"question":"المستمع (ع. م. ع) مقيم في مكة المكرمة يسأل عدة أسئلة، من بينها سؤال يقول: أرجو أن توضحوا لي عدد النوافل بعد وقبل كل صلاة مفروضة؟","title":"ما عدد السنن الرواتب والنوافل للصلوات المفروضة؟","answer":"الجواب:  نعم، النوافل التي حافظ عليها النبي ﷺ مع الفرائض: اثنتا عشرة ركعة، هذه يقال لها: الرواتب، ويقال لها: النوافل التي حافظ عليها النبي ﷺ: وهي أربع قبل الظهر، تسليمتان قبل الظهر، تسليمتان قبل الظهر بعد الزوال، وركعتان بعد الظهر، وركعتان بعد المغرب، وركعتان بعد العشاء، وركعتان قبل صلاة الصبح، هذه الرواتب التي حافظ عليها المصطفى -عليه الصلاة والسلام- أربعًا قبل الظهر تسليمتان، ثنتان بعد الظهر، ثنتان بعد المغرب، ثنتان بعد العشاء، ثنتان قبل صلاة الصبح، والأفضل في البيت، وإن صلاها في المسجد؛ فلا حرج، هذه يقال لها: الرواتب، وهي سنة مؤكدة في الحضر. أما في السفر فالأفضل تركها، في السفر الأفضل تركها إلا سنة الفجر، وإلا الوتر؛ فإن الوتر ..... في السفر ويصلي سنة الفجر، أما سنة الظهر والمغرب والعشاء، فالأفضل تركها، ويستحب قبل العصر أربعًا لكن ما هي براتبة، .. قبل العصر يستحب أربعًا، وقبل المغرب ثنتين، وقبل العشاء ثنتين، لكنهن غير رواتب، يقول النبي ﷺ: رحم الله امرأً صلى أربعًا قبل العصر ويقول: صلوا قبل المغرب، صلوا قبل المغرب، ثم قال في الثالثة: لمن شاء وقال: بين كل أذانين صلاة، بين كل أذانين صلاة وهذا يشمل المغرب والعشاء.  فيستحب أن يصلي قبل المغرب ركعتين بعد غروب الشمس، وقبل العشاء ركعتين بعد الأذان، يصلي قبل العصر أربعًا هذه مستحبة، لكن ما هي براتبة، لم يراتب عليها النبي ﷺ ولكنها مستحبة؛ لأمره ﷺ نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11053/ما-عدد-السنن-الرواتب-والنوافل-للصلوات-المفروضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46405.mp3","categories":["صلاة التطوع"]},{"id":12842,"question":"المستمع محمد علي صالح مقيم في العراق يسأل ويقول: ما رأيكم في صلاة التسابيح، هل الرسول ﷺ صلاها؟ وكيف كان يصليها، جزاكم الله خيرًا؟","title":"ما صحة أحاديث صلاة التسابيح؟","answer":"الجواب:  صلاة التسابيح غير صحيحة عند أهل التحقيق، قد تأملنا أحاديث طرقها فهي ضعيفة غير صحيحة، ومخالفة للصلاة الشرعية، فالسنة للمؤمن أن يتطوع بالصلاة الشرعية التي يفعلها في نوافله في صلاة الضحى، وفي الرواتب، وفي الفريضة، يصلي كما صلى النبي ﷺ يصلي.... يقرأ في القيام الفاتحة، وما تيسر معها، ويركع ويسبح: سبحان ربي العظيم، سبحان ربي العظيم، ويقول: سبحانك اللهم ربنا وبحمدك اللهم اغفر لي، سبوح قدوس... مثلما يصلي في بقية الصلوات، أما الصلاة الواردة في صلاة التسبيح التي يروى أنه علمها عمه العباس هذه لا صحة لها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11056/ما-صحة-احاديث-صلاة-التسابيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46408.mp3","categories":["صلاة التطوع","الحكم على الأحاديث"]},{"id":12846,"question":"المستمع (ف. م) من الدمام بعث برسالة يقول فيها: أكثر الأحيان أصلي ركعتي الفجر في البيت، ثم أذهب إلى المسجد لأصلي الفرض مع الجماعة، ولكنني أحيانًا أصل إلى المسجد قبل أن تقام الصلاة، فهل في هذه الحالة أصلي ركعتين بنية تحية المسجد، أم أجلس إلى أن تقام الصلاة؟","title":"هل يصلي تحية المسجد من صلى راتبة الفجر في بيته؟","answer":"الجواب:  المشروع لك أن تصلي ركعتين، إذا صليت الراتبة في البيت، ثم جئت المسجد، والصلاة لم تقم، صل ركعتين قبل أن تجلس؛ لقوله ﷺ: إذا دخل أحدكم المسجد؛ فلا يجلس حتى يصلي ركعتين وهذا يعم الفجر، وغيرها، فلا ينبغي لك الجلوس إلا بعد الركعتين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11060/هل-يصلي-تحية-المسجد-من-صلى-راتبة-الفجر-في-بيته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46412.mp3","categories":["صلاة التطوع"]},{"id":12981,"question":"تقول هذه السائلة: رأيت الكثير من النساء -هداهن الله- داخل مكان زمزم في الحرم يصلين على الدرج المقابل لمواسير التبريد على ما يبدو لي، ويقلن بأن ذلك سنة، سنة زمزم، وعندما نهيتهن عن ذلك لم يستجبن، وربما تطاولن في الكلام، فهل ذلك صحيح فضيلة الشيخ؟","title":"هل توجد صلاة تسمى سنة زموز؟","answer":"الجواب:  ليس بصحيح، وليس لزمزم سنة، ليس لها سنة، والواجب أن يصلين خلف الرجال في أي مكان من المسجد الحرام، يلتمسن مكانًا خلف الرجال، ويصلين فيه، ولا يصلين في زمزم، ولا يضايقن الناس، وليس لزمزم صلاة معينة كل هذا باطل لا أصل له، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/11198/هل-توجد-صلاة-تسمى-سنة-زموز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_503/50312.mp3","categories":["صلاة التطوع"]},{"id":13072,"question":"هذا سائل يقول في هذا السؤال بخصوص صلاة الاستخارة: كيف تكون علامات انشراح الصدر، وهل يجوز أن أستخير الله  في كل الأمور، أو أمور معينة، وجهونا يا سماحة الشيخ؟","title":"علامات انشراح الصدر بعد صلاة الاستخارة","answer":"الجواب:  صلاة الاستخارة في الأمور التي يشتبه عليك أمرها، هل من المصلحة فعلها أو تركها، هذا محل الاستخارة، أما الشيء المعروف أنه طيب ما فيه استخارة، ما عليك استخارة، هل تصلي، أو ما تصلي، ما فيه استخارة، صلاة الفريضة مطلوبة ومشروعة، كذلك الزكاة .. الصيام .. الحج .. صيام الإثنين ... والخميس ما فيه استخارة كونه شيئًا معروفًا، لكن شيئًا مشتبهًا مثل: أردت أن تتزوج بنت فلان، وعندك تردد؛ تستخير، أو السفر، تحب أن تسافر إلى محل معين، وعندك تردد هل من المصلحة السفر، أم لا؛ تستخير، كذلك عندك تردد هل تتجر في الملابس .. هل تتجر في العقار، عندك تردد؛ تستخير، وهكذا الشيء الذي فيه تردد؛ تستخير ربك. فإذا صليت ركعتي الاستخارة، وسألت ربك؛ تعمل بما يميل إليه قلبك، ينشرح صدرك، إذا مال صدرك إلى أحد الأمرين؛ افعل، هذا هو الأفضل، ويستحب لك أن تستشير.. يستحب لك أن تشاور الناس الطيبين الذي تثق بهم مع الاستخارة بعد الاستخارة، تشاور إخوانك .. أصدقاءك .. والديك، تستشير من تثق به، وترى أنه أهل للاستشارة حتى يساهم في هذا الشيء، وإذا انشرح صدرك؛ افعل. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11288/علامات-انشراح-الصدر-بعد-صلاة-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_507/50704.mp3","categories":["صلاة التطوع"]},{"id":13112,"question":"دخلت المسجد قبل صلاة المغرب، فهل أصلي تحية المسجد، أم أجلس؟","title":"حكم صلاة تحية المسجد بعد العصر","answer":"الجواب:  السنة أن تصلي تحية المسجد، إن كان قبل الغروب؛ فهذه من ذوات الأسباب، تصلي على الصحيح، ثم تجلس، أما إن كان بعد الغروب؛ فليس في ذلك إشكال، تصلي تحية المسجد، ثم تجلس؛ لأنه زال وقت النهي، لكن الخلاف فيما إذا دخلت قبل الغروب، هذا هو محل الخلاف بين العلماء، هل تصلي، أم لا؟ والصواب: أنه يشرع للداخل أن يصلي ركعتين إذا دخل بعد العصر قبل غروب الشمس، ثم يجلس؛ لأن هذه الصلاة يقال لها: إنها من ذوات الأسباب، تسمى من ذوات الأسباب، يعني: لها سبب، وهو الدخول، فيصليها، ثم يجلس. وهكذا لو كسفت الشمس بعد العصر؛ فإنها تصلى صلاة الكسوف؛ لأنها من ذوات الأسباب، وهكذا لو طاف بعد العصر في مكة، طاف طوافًا بالكعبة؛ صلى ركعتي الطواف بعد العصر، أو بعد الصبح؛ لأنها من ذوات الأسباب، نعم.","link":"https://binbaz.org.sa/fatwas/11330/حكم-صلاة-تحية-المسجد-بعد-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47310.mp3","categories":["صلاة التطوع"]},{"id":13124,"question":"يسأل ويقول: هل كان الرسول ﷺ يصلي قبل المغرب ركعتين، أم بعد الصلاة؟","title":"سنة المغرب القبلية والبعدية","answer":"الجواب:  المعروف عنه ﷺ أنه كان يصلي بعد المغرب ركعتين راتبة، وروي عنه ﷺ أنه صلى قبل المغرب ركعتين رواه ابن حبان، ولكن المشهور عنه ﷺ إنما هو الصلاة بعد المغرب ركعتين، هذه ثابتة عنه في الصحيحين وغيرهما.  وثبت عن الصحابة أنهم فعلوها بأمره ﷺ وبإقراره، كان الصحابة يصلون ركعتين وهو ينظر إليهم، وقد أمرهم بقوله: صلوا قبل المغرب، صلوا قبل المغرب ثم قال في الثالثة: لمن شاء فكانوا يفعلونها وهو ينظر -عليه الصلاة والسلام- فدل ذلك على سنيتها بعد الأذان، فهي ثابتة.. من قوله وتقريره، ثابتة من قوله وتقريره. أما فعله فهو محل نظر، وإن صححه ابن حبان، لكن محل نظر، لكنها ثابتة من قوله، قوله: صلوا قبل المغرب ومن تقريره للصحابة -رضي الله عنهم وأرضاهم- نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11347/سنة-المغرب-القبلية-والبعدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_474/47402.mp3","categories":["صلاة التطوع"]},{"id":13151,"question":"يقول هذا السائل: بالنسبة لنافلة الظهر، هل لها تشهد أوسط، أم تكون أربع ركعات متصلة؟ أفيدونا أفادكم الله.","title":"صفة صلاة راتبة الظهر","answer":"الجواب:  السنة ركعتان ركعتان، يصلي ركعتين، ثم يسلم، ثم ركعتين، ثم يسلم؛ لقول النبي ﷺ: صلاة الليل والنهار مثنى مثنى فأربع قبل الظهر بتسليمتين، وأربع بعدها بتسليمتين، وإن صلى بعدها ركعتين فقط الراتبة؛ فلا بأس، وإن زاد صلى أربعًا بعدها، فهو أفضل لقوله ﷺ: من حافظ على أربع قبل الظهر، وأربع بعدها؛ حرمه الله على النار وكان ﷺ يصلي أربعًا قبلها، وثنتين بعدها هذه الراتبة. فمن زاد، وصلى أربعًا قبلها، وأربعًا بعدها؛ صار ثمانًا، قبلها أربع، وبعدها أربع؛ كان ذلك أفضل، وله هذا الخير: من حافظ على أربع قبل الظهر، وأربع بعدها؛ حرمه الله تعالى على النار نعم، لكن يكون ثنتين ثنتين، يسلم من كل ثنتين، هذا هو السنة. المقدم: نعم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11405/صفة-صلاة-راتبة-الظهر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_510/51011.mp3","categories":["صلاة التطوع"]},{"id":13309,"question":"السائل إبراهيم عبدالعزيز أبو حامد الحقيقة له مجموعة من الأسئلة من الرياض يقول: البعض من الناس إذا أذن المؤذن ليوم الجمعة في مكة، أو المدينة الأذان الأول يقوم بعده ويصلي ركعتين، فما حكم ذلك، وهل هذا مشروع؟","title":"حكم صلاة ركعتين بعد الأذان الأول يوم الجمعة","answer":"الجواب: لا أعلم له أصلًا؛ لأن الأذان هذا مما أحدثه عثمان  في خلافته، ووافق عليه الصحابة لينبه به الناس على أن اليوم يوم الجمعة؛ ليتقدموا، فهو غير داخل في قوله ﷺ: بين كل أذانين صلاة فإن المراد بالأذانين يعني: الأذان والإقامة، أما هذا فهو أذان للتنبيه على أنه يوم الجمعة.  فالأظهر والأقرب ترك ذلك، ترك القيام للصلاة بعد هذا الأذان الأول، وبعض أهل العلم رأى أنه يدخل في العموم، وأنه لو قام وصلى لا بأس، فالأمر في هذا، فيه سعة -إن شاء الله- لكن ترك ذلك فيما أرى أفضل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11595/حكم-صلاة-ركعتين-بعد-الاذان-الاول-يوم-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_521/52109.mp3","categories":["صلاة التطوع"]},{"id":13329,"question":"السائل عبدالرحمن من المدينة النبوية يقول: سماحة الشيخ! أنا من سكان المدينة النبوية، والحمد لله على هذه النعمة، إذ أديت صلاة الفريضة في المسجد النبوي، فسؤالي عن الراتبة البعدية، فأنا في حيرة بين الحديثين: الأول: صلاة في مسجدي هذا خير من ألف صلاة الحديث، والآخر: صلاة الرجل في بيته أفضل إلا المكتوبة وجهونا سماحة الشيخ.","title":"هل فضل النافلة في البيت يشمل الحرمين؟","answer":"الجواب: السنة للمؤمن أن يصلي الراتبة في بيته، هذا هو الأفضل؛ لقوله ﷺ في الحديث الصحيح: أفضل صلاة المرء في بيته إلا المكتوبة هكذا علم أصحابه في المدينة في مسجده الشريف، ولك في صلاتك في البيت أفضل من صلاتك في المسجد، لك أجر عظيم؛ لأنك امتثلت أمر الرسول ﷺ وأطعت توجيهه -عليه الصلاة والسلام- فإذا صليت الفريضة في المسجد؛ فالرواتب تكون في البيت أفضل، إذا كانت في المسجد بألف صلاة، ففي البيت أكثر؛ لأنك أطعت الرسول ﷺ وامتثلت السنة. وهكذا في مكة، هكذا في كل مكان، ويلحق بالمكتوبة ما شرعت له الجماعة، مثل صلاة التراويح في المسجد أفضل، مثل صلاة الكسوف، صلاة الجنازة، في المساجد، وفي المصلى أفضل من البيت. نعم. المقدم: شكر الله لكم يا سماحة الشيخ، وبارك الله فيكم، وفي علمكم، ونفع بكم المسلمين.","link":"https://binbaz.org.sa/fatwas/11615/هل-فضل-النافلة-في-البيت-يشمل-الحرمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_541/54112.mp3","categories":["شروح الحديث","صلاة التطوع"]},{"id":13349,"question":"يقول هذا السائل في سؤاله: هل هناك صلاة لتفريج الهم، وتكون بركعتين، ثم يدعو الإنسان بدعاء: اللهم فارج الهم، وكاشف الغم أجب دعوتي، أو أجب دعوة المضطرين إذا دعاك؟","title":"هل توجد صلاة لتفريج الهم؟","answer":"الجواب: لا أعلم في هذا شيئًا خاصًا، صلاة خاصة، لكن مثلما قال الله -جل وعلا-: وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلاةِ [البقرة:45] فإذا استعان بالصلاة، صلى، وسأل ربه في سجوده، وفي جلسته للسلام بعد التحيات؛ فهذا طيب، من أسباب الخير.  الله -جل وعلا- أمر بالاستعانة بالصبر والصلاة، والنبي ﷺ كان إذا حزبه أمر؛ فزع إلى الصلاة، فإذا صلى الإنسان ركعتين، الضحى، أو في الليل، ودعا ربه في سجوده، وفي ما قبل السلام، إذا فرغ من التحيات، أو بعد الصلاة؛ رفع يديه، ودعا، هذا كله من أسباب الخير، ومن أسباب التوفيق. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11635/هل-توجد-صلاة-لتفريج-الهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_523/52306.mp3","categories":["صلاة التطوع"]},{"id":13352,"question":"يقول هذا السائل من الأردن في سؤاله: أرجو التفضل يا سماحة الشيخ بتوضيح صلاة الاستخارة، وهل عدم تغيير نية الإنسان، وعدم تغيير الظروف المحيطة يعني: أن هذا الموضوع فيه خير للإنسان؟","title":"مشروعية صلاة الاستخارة","answer":"الجواب:  الاستخارة تشرع عندما يهم الإنسان بشيء عنده فيه تردد، فَيَهِم بأن يتزوج.. يهم بالسفر.. يهم بالتجارة في أشياء معينة ويتردد، فهذا يستخير الله، يصلي ركعتين كما أمره النبي ﷺ ثم يدعو ربه، يرفع يديه ويدعو: اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنك تعلم ولا أعلم، وتقدر ولا أقدر، وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر يسميه باسمه، اللهم إن كنت تعلم أن زواجي بفلانة بنت فلان، اللهم إن كنت تعلم أن سفري إلى البلد الفلانية، وما أشبه ذلك، يعين المطلوب خير لي في ديني ودنياي، وعاقبة أمري أو قال: عاجل أمري وآجله فاقدره لي، ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر  ويسميه شر لي في ديني ودنياي وعاقبة أمري فاصرفه عني واصرفني عنه وقدر لي الخير حيث كان ثم أرضني به فهذا دعاء الاستخارة.  وإذا كان ما يعرف هذا الدعاء؛ يدعو بمعناه، يقول: اللهم إن كان هذه الحاجة فيها خير لي، فيها مصلحة لي، ومنفعة؛ فيسرها لي، وإن كان خلاف ذلك؛ فاصرفها عني، واصرفني عنها. المقصود: يدعو بهذا المعنى، بالدعاء الذي يعرفه، والمعنى الذي يعرفه، ولا بأس، هذا مسنون مشروع، بعدما يسلم من الركعتين.  وإن دعا من دون صلاة، أو دعا بعد صلاة النافلة المعتادة، بعد سنة الظهر، أو سنة المغرب، أو سنة العشاء، أو غير ذلك؛ لا بأس، أو دعا وهو جالس دعاء عاديًا ..... ربه، لا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11638/مشروعية-صلاة-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_523/52309.mp3","categories":["صلاة التطوع"]},{"id":13370,"question":"السائل علي من الكويت علي مطلق له الحقيقة مجموعة من الأسئلة يقول في هذا  سماحة الشيخ! ورد عن النبي ﷺ عدة أحاديث تفيد بتقديم الطعام على الصلاة، منها على سبيل الذكر لا الحصر: ما رواه الشيخان عن أنس  أن رسول الله ﷺ قال: إذا قدم العشاء؛ فابدؤوا به قبل أن تصلوا المغرب وكذلك ما رواه مسلم عن عائشة -رضي الله عنها- قول النبي ﷺ: لا صلاة بحضرة طعام، ولا هو يدافعه الأخبثان وكذلك ورد عن النبي ﷺ في الحديث المتفق عليه، عن أبي قتادة  قال: قال رسول الله ﷺ: إذا دخل أحدكم المسجد؛ فلا يجلس، حتى يصلي ركعتين.والسؤال يا سماحة الشيخ: في حالة كوني صائمًا، ودخلت المسجد حين الأذان، هل أصلي تحية المسجد، أم أذهب لتناول الفطور، علمًا بأن فطوري داخل المسجد؟ أفتونا في ذلك مأجورين.","title":"الصائم إذا دخل المسجد هل يبدأ بالفطر أم يصلي التحية؟","answer":"الجواب: أما ما يتعلق بمدافعة الحدث، وما يتعلق بالبداءة بالطعام، هذا هو السنة؛ لأنه يتفرغ للصلاة حتى يصليها بخشوع، فلا صلاة بحضرة الطعام، والحديث الآخر: إذا حضر الطعام، وحضر العشاء؛ فابدؤوا بالعشاء والحديث الآخر: إذا حضر العشاء، وحضرت المغرب؛ فابدؤوا به قبل أن تصلوا المغرب يبدأ بالعشاء؛ حتى يستريح؛ حتى يطمئن قلبه .. حتى يؤدي الصلاة بخشوع وطمأنينة، لا يصلي وقلبه مشغول بالطعام، أو بمدافعة الأحدثين. هذا هو الواجب عليه .. هذا هو المشروع للمؤمن، والأحاديث في هذا صريحة لا صلاة بحضرة الطعام، ولا هو يدافعه الأخبثان وكذلك الأمر بتقديم العشاء قبل أن يصلي؛ لأنه بهذا يطمئن. أما إذا دخل المسجد على المغرب، وهو صائم؛ فإنه يبدأ بتحية المسجد، ولو صائمًا؛ يبدأ بالركعتين، ثم يفطر، والحمد لله؛ لأن المدة قليلة، دقيقتان ثلاث، الحمد لله، الرسول ﷺ قال: إذا دخل أحدكم المسجد؛ فلا يجلس حتى يصلي ركعتين وفي اللفظ الآخر: فليركع ركعتين قبل أن يجلس فليبدأ بالركعتين إذا كان على طهارة، يبدأ بالركعتين، ثم يجلس يفطر، الحمد لله. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11659/الصاىم-اذا-دخل-المسجد-هل-يبدا-بالفطر-ام-يصلي-التحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_515/51504.mp3","categories":["المساجد ومواضع السجود","صلاة التطوع"]},{"id":13404,"question":"إذا تأخر المسلم عن صلاة الضحى، ولم يصلها لظروف معينة، فهل يلزمه القضاء، أم لا؟ وأيضًا: هل لصلاة الضحى صورة معينة، وأداء معين يجب الإتيان به؟ أم أنها عبارة عن صلاة عادية؟","title":"حكم قضاء صلاة الضحى","answer":"الجواب: صلاة الضحى سنة قربة، نافلة، من صلاها؛ فله أجر، ومن ترك؛ فلا شيء عليه، وإذا فاتت؛ فلا تقضى، إذا صلى ثنتين، أو أربعًا، أو ست ركعات، أو ثمانًا، أو أكثر كله طيب، وقد أوصى النبي ﷺ أبا هريرة، وأبا الدرداء: بصلاة الضحى.  في رواية: ركعتي الضحى، وبصيام ثلاثة أيام من كل شهر، وأن يوتر قبل النوم. فهذا سنة .. كله سنة، كونه يوتر كل ليلة .. كونه يصلي الضحى، يصوم ثلاثة أيام من كل شهر، كل هذا سنة، ومن ترك؛ فلا حرج عليه، وإذا استطاع أن يكون وتره في آخر الليل؛ فهو أفضل؛ لأحاديث أخرى دلت على ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11694/حكم-قضاء-صلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_516/51604.mp3","categories":["صلاة التطوع"]},{"id":13442,"question":"ما حكم صلاة التسابيح، وهل الحديث الوارد فيها صحيح؟","title":"ما حكم صلاة التسابيح؟ وما صحة الحديث الوارد فيها؟","answer":"الجواب: صلاة التسابيح غير صحيحة، والأحاديث الواردة فيها كلها ضعيفة، كما نبه على ذلك أهل العلم، فهي غير صحيحة، ولا يجوز الاعتماد عليها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11742/ما-حكم-صلاة-التسابيح-وما-صحة-الحديث-الوارد-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_516/51613.mp3","categories":["صلاة التطوع","الحكم على الأحاديث"]},{"id":13489,"question":"السائل: (إبراهيم . أ) من الرياض له مجموعة من الأسئلة يقول: هل هناك فوارق بين صلاة الفرض والنافلة؟","title":"ما الفرق بين صلاة الفريضة والنافلة؟","answer":"الجواب: نعم، في فرق، النافلة مستحبة، والفرض واجب، والنافلة إذا تركها لا يأثم، لو ترك صلاة الضحى، أو صلاة الوتر، أو الراتبة في الظهر أو الفجر، أو المغرب والعشاء لم يأثم، والفريضة يأثم إذا تركها يأثم، بل يكفر إذا ترك الفريضة، وتعمد تركها. والنافلة في الصلاة يجوز له أن يصليها جالسًا ولو كان صحيحًا، والفريضة ليس له أن يصليها جالسًا إلا عند العذر، عند المرض والعجز، أما النافلة لو صلى جالسًا فلا بأس، كما كان النبي ﷺ يصلي جالسًا في صلاة الليل، ويقول: صلاة الرجل جالس على النصف من صلاة القائم ﷺ فإذا صلى في الليل، أو في النهار جالسًا للنافلة؛ فلا حرج، أما في الفريضة فلا، لابد يصلي قائمًا؛ لقوله ﷺ في حديث عمران: صل قائمًا يقول لعمران بن الحصين : صل قائمًا، فإن لم تستطع؛ فقاعدًا، فإن لم تستطع؛ فعلى جنب، فإن لم تستطع فمستلقيًا هذا في حق الفريضة، أما النافلة فلا حرج، يصلي جالسًا إذا تكاسل، وجلس فلا حرج، نعم.","link":"https://binbaz.org.sa/fatwas/11792/ما-الفرق-بين-صلاة-الفريضة-والنافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_518/51803.mp3","categories":["صلاة التطوع"]},{"id":13553,"question":"من صلى سنة الفجر في المسجد بنية سنة الفجر وتحية المسجد، ما حكم ذلك يا شيخ؟","title":"حكم صلاة ركعتين بنية الراتبة وتحية المسجد","answer":"الجواب: يكفي، نعم يكفي. المقدم: يكفي هذا يا شيخ. الشيخ: إذا نواها تحية المسجد؛ كفى، لا يصلي ... يصلي بنية الراتبة، ونية التحية لا مانع، الحمد لله. نعم. المقدم: الحمد لله.","link":"https://binbaz.org.sa/fatwas/11899/حكم-صلاة-ركعتين-بنية-الراتبة-وتحية-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53218.mp3","categories":["صلاة التطوع"]},{"id":13557,"question":"يقول: هل يأثم من ترك ركعتين قبل الفجر؟ وصلاة الوتر؟ جزاكم الله خيرًا.","title":"هل يأثم من ترك الرواتب وصلاة الوتر؟","answer":"الجواب: جميع السنن لا يأثم فيها، سنة الفجر، وسنة الظهر والمغرب والعشاء، وسنة الجمعة كلها نوافل، لكن ترك الأفضل، فوت أجرًا كبيرًا، وإلا لا إثم عليه في جميع النوافل الرواتب وغيرها. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11895/هل-ياثم-من-ترك-الرواتب-وصلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53217.mp3","categories":["صلاة التطوع","الوتر وقيام الليل"]},{"id":13640,"question":"متى يكون وقت صلاة الضحى؟ ومتى ينتهي وقته؟","title":"متى وقت صلاة الضحى؟ ومتى ينتهي؟","answer":"الجواب: صلاة الضحى من ارتفاع الشمس قيد رمح إلى وقوفها، كما بينه النبي ﷺ في حديث عمرو بن عبسة إذا ارتفعت الشمس قيد رمح يصلي ما بدا له حتى تقف الشمس، إلى وقوف الشمس، فإذا زالت دخل وقت العبادة إلى أن يصلي العصر. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11978/متى-وقت-صلاة-الضحى-ومتى-ينتهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_542/54211.mp3","categories":["صلاة التطوع"]},{"id":13662,"question":"من أسئلة هذه السائلة تقول: ما هي صلاة الأوابين؟ وهل كان الرسول ﷺ يداوم على صلاتها، وماذا كان يقرأ فيها؟","title":"صلاة الأوابين وحكم المداومة عليها","answer":"الجواب: صلاة الأوابين صلاة الضحى إذا اشتد الضحى، هذه صلاة الأوابين، إذا اشتد الضحى؛ سن لكل أحد أن يصلي صلاة الضحى ركعتين، وإن زاد فلا بأس، النبي ﷺ أوصى أبا هريرة وأوصى أبا الدرداء بركعتي صلاة الضحى، وقال -عليه الصلاة والسلام-: يصبح على كل سلامى من أحدكم صدقة، فكل تسبيحة صدقة، وكل تهليلة صدقة، وكل تحميدة صدقة، أمر بالمعروف صدقة، ونهي عن المنكر صدقة، ويكفي من ذلك ركعتان تركعهما من الضحى أو كما قال، عليه الصلاة والسلام. فجعل الركعتين تقومان مقام هذه الصدقات، وهذه التسبيحات والتكبيرات، وربما صلى الضحى ﷺ أربعًا، وربما صلاها ثمان -عليه الصلاة والسلام- صلاها يوم الفتح ثمان ركعات، أربع تسليمات، قالت عائشة: كان يصليها أربعًا، ويزيد ما شاء الله يعني: بعض الأحيان، عليه الصلاة والسلام. وما كان يداوم عليها؛ لئلا يشق على أمته، بل يترك العمل وهو يحب أن يعمله؛ مخافة المشقة على أمته، لكن دلت السنة القولية على أن المواظبة عليها، والمحافظة عليها سنة مؤكدة، كونه سيحافظ على صلاة الضحى، سنة مؤكدة من وصية النبي ﷺ فإنه أوصى بها -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11999/صلاة-الاوابين-وحكم-المداومة-عليها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52905.mp3","categories":["فضائل الأعمال","صلاة التطوع"]},{"id":13669,"question":"هذا السائل يقول: إذا صليت سنة العصر، أو أي فرض القبلية قبل الأذان، وعندما أذن العصر صليت أربع ركعات فرض العصر، فهل السنة القبلية تكتب لي قبلية العصر، أم يجب أن أصليها بعد الأذان، أرجو التوضيح؟","title":"وقت سنة العصر القبلية","answer":"الجواب: السنة نافلة ما هي بفرض، يستحب أربع بعد دخول وقت العصر تسليمتين، وإذا صليت قبل الأذان بين الظهر والعصر صلوات ولو مائة ركعة؛ لا بأس، وقت، الحمد لله، وقت واسع، ولا فيه منع، لو صلى الإنسان ... الظهر ركعات يسيرة، عشر ركعات، عشرين ركعة، ثلاثين ركعة، ما فيه شيء، الحمد لله يسلم من كل ثنتين. ويستحب له بعد أذان العصر بعد دخول وقت العصر أن يصلي أربعًا تسليمتين؛ لقول النبي ﷺ: رحم الله امرأً صلى أربعًا قبل العصر مستحبة ما هي بواجبة، الواجب صلاة الفرض الخمس: الظهر، العصر، المغرب، العشاء، الفجر، هذه الفرائض، أما سنة الظهر والعصر والمغرب والعشاء والضحى والوتر كلها نوافل، غير واجبة، لو تركها ما عليه إثم، لكن له الأجر في فعلها، له الأجر العظيم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12013/وقت-سنة-العصر-القبلية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52912.mp3","categories":["صلاة التطوع"]},{"id":13672,"question":"السائلة أم عبدالله تسأل في هذا السؤال وتقول: هل يجوز لي أن أصلي ركعتين سنة المغرب قبل الأذان، أم أنه يعتبر من الوقت المنهي عنه؟","title":"حكم صلاة سنة المغرب قبل الأذان","answer":"الجواب: الصلاة بعد الأذان بعد غروب الشمس، أما قبل غروب الشمس وقت نهي، إلا إذا كان الإنسان دخل المسجد ينتظر المغرب؛ فلا بأس أن يصلي ركعتي التحية، تحية المسجد، أو دخل مكة، وطاف بعد العصر؛ يصلي صلاة الطواف. أما أن الإنسان يصلي قبل الغروب وهو في بيته، أو جالس في المسجد لا، هذا وقت نهي، لكن إذا جاء بعد صلاة العصر ينتظر المغرب، يصلي ركعتين تحية المسجد، ويجلس، أو طاف بعد العصر في مكة يصلي ركعتي الطواف؛ لأنها سنة لها سبب؛ فلا بأس. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12016/حكم-صلاة-سنة-المغرب-قبل-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52914.mp3","categories":["صلاة التطوع"]},{"id":13710,"question":"أخونا يقول: صلاة الضحى هل يجوز أن أؤخرها حتى العاشرة صباحًا مثلًا؟","title":"هل يجوز تأخير صلاة الضحى حتى العاشرة صباحًا؟","answer":"الجواب: كل الضحى محل صلاة من حين ارتفاع الشمس قيد رمح إلى قرب الزوال كله محل صلاة، وأفضلها عند شدة الضحى الساعة العاشرة هذه الأيام، أو العاشرة والنصف، أو الحادية عشر كلها محل صلاة، صلاة الضحى، يقول النبي ﷺ: صلاة الأوابين حين ترمض الفصال يعني: حين يشتد الحر على أولاد الإبل. فالحاصل: أن صلاة الضحى وقتها واسع من ارتفاع الشمس قيد رمح إلى وقوف الشمس قبل الظهر بنحو ربع ساعة، أو ثلث ساعة، كل هذا محل صلاة ضحى، وإذا كان في وقت شدة الضحى، وارتفاع الضحى يكون أفضل. نعم.. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12077/هل-يجوز-تاخير-صلاة-الضحى-حتى-العاشرة-صباحا ","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48105.mp3","categories":["صلاة التطوع"]},{"id":13738,"question":"هذه السائلة تقول في سؤالها -رمزت لاسمها بـ (ع. س. ن)-: هل يجب على الرجل أن يصلي تحية المسجد كلما ذهب إلى المسجد للصلوات المفروضة، أي: يؤدي تحية المسجد في اليوم خمس مرات؟ وجزاكم الله خيرًا.","title":"حكم تحية المسجد كلما دخل المصلي المسجد","answer":"الجواب: تحية المسجد سنة، ما هي بواجبة، فإذا وصل المسجد صلى ركعتين، إن كان مثل الظهر يصلي الراتبة، وتكفيه عن تحية المسجد، راتبة الظهر أربع ركعات، تسليمتان قبل الظهر، فإذا صلاهما؛ كفتا عن تحية المسجد، وهكذا العصر، يستحب قبلها أربع، تسليمتان؛ لقوله ﷺ: رحم الله امرأ صلى أربعًا قبل العصر تكفي عن تحية المسجد، سواء نواها تحية، أو ما نواها تحية. وهكذا إذا جاء المسجد، أذان المغرب أو قبل المغرب؛ يصلي ركعتين تحية المسجد، وهكذا العشاء إذا جاء إلى المسجد؛ يصلي ركعتين تحية المسجد، بعد الأذان، أو قبل الأذان، وبين الأذانين يسن أن يصلي ركعتين؛ لقوله ﷺ: بين كل أذانين صلاة، بين كل أذانين صلاة، لمن شاء. فإذا جاء إلى المسجد بعد أذان العشاء، أو بعد أذان المغرب، أو قبل ذلك؛ يصلي تحية المسجد، فإذا أذن؛ يستحب له أن يقوم فيصلي ركعتين بين الأذانين أيضًا، في المغرب والعشاء، أما الفجر فراتبتها قبلها ركعتان، إذا صلاها في البيت، أو في المسجد فالحمد لله، وإن صلاها في المسجد؛ كفت عن تحية المسجد. وهكذا راتبة الظهر تسليمتان، إذا جاء إلى المسجد قبل الظهر، وصلى الراتبة تسليمتين؛ كفتا عن تحية المسجد، وسنة العصر أربعًا إذا صلاها؛ كفتا عن تحية المسجد. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12113/حكم-تحية-المسجد-كلما-دخل-المصلي-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_535/53512.mp3","categories":["صلاة التطوع"]},{"id":13769,"question":"عن دعاء الاستخارة - سماحة الشيخ - يقول هذا السائل: متى يكون دعاء الاستخارة؟ هل يكون في السجود أم بعد السلام من صلاة الركعتين؟ وهل لا بد لذلك الدعاء أن يبدأ بالحمد والثناء على المصطفى ﷺ؟","title":"متى يكون دعاء الاستخارة؟","answer":"الجواب: هذا هو الأفضل بلا شك، هذا هو الأفضل يبدأ بالصلاة والسلام على النبي ﷺ.\nالشيخ: أعد سؤاله.\nالمقدم: متى يكون دعاء الاستخارة؟ هل يكون في السجود أم بعد السلام من صلاة الركعتين؟وهل لا بد لذلك الدعاء أن يبدأ بالحمد والثناء على الرسول ﷺ؟\nالشيخ: يكون بعد السلام، ويبدأ بالحمد والثناء، يقول النبي ﷺ: إذا هم أحدكم بأمر فليركع ركعتين من غير الفريضة، ثم يقول: اللهم إني أستخيرك بعلمك.. إلى آخره، فالسنة أن يرفع يديه ويدعو بعد الركعتين، يدعو ويرفع يديه ويبدأ بحمد الله والصلاة على النبي ﷺ؛ لقوله ﷺ: إذا دعا أحدكم فليبدأ بتحميد ربه، والثناء عليه ثم يصلي على النبي ﷺ ثم يدعو بما شاء فالذي يستخير أولاً: يصلي ركعتين في وقت الصلاة .. ضحى وإلا في الليل وإلا بعد الظهر، ثم إذا سلم يرفع يديه ويستخير، يحمد الله ويصلي على النبي ﷺ، ثم يقول : اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنك تعلم ولا أعلم، وتقدر ولا أقدر، وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر - ويسميه باسمه - اللهم إن كنت تعلم أن هذا الأمر، - يعني: أن هذا الزواج بفلانة، أو شرائي للعقار الفلاني، أو سفري إلى كذا، يعيِّن - خير لي في ديني ودنياي ومعاشي وعاقبة أمري فيسره لي ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر - ويسميه باسمه - شر لي في ديني ومعاشي وعاقبة أمري فاصرفه عني واصرفني عنه، وقدر لي الخير حيث كان ثم أرضني به هكذا جاء في الحديث الصحيح في الاستخارة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12157/متى-يكون-دعاء-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_536/53610.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":13821,"question":"دخل شخص المسجد قبل أذان المغرب بحوالي ربع ساعة أو عشر دقائق أو أقل من ذلك فهل على هذا الشخص أن يصلي ركعتين تحية للمسجد؟ أم يظل واقفًا حتى يؤذن للمغرب؟","title":"حكم صلاة تحية المسجد قبل المغرب","answer":"الجواب: السنة أن يصلي الإنسان ركعتين متى دخل ولو قبيل الغروب؛ لعموم قوله ﷺ: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين، وهاتان الركعتان من ذوات الأسباب ليس لهما وقت نهي كسجود التلاوة، وكصلاة الكسوف، فإن الشمس متى كسفت صلى الناس للكسوف ولو بعد العصر، فهكذا ركعتا التحية حكمهما حكم ذوات الأسباب ليس لهما وقت نهي. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12189/حكم-صلاة-تحية-المسجد-قبل-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53705.mp3","categories":["صلاة التطوع","المساجد ومواضع السجود"]},{"id":13880,"question":"سماحة الشيخ! هذا سائل يقول: هل تسقط السنن الرواتب في السفر من غير ركعتي الفجر والوتر، حيث أنني أرغب المحافظة عليها في سفري، فإذا صليت السنن الرواتب وحافظت عليها في السفر هل في ذلك بأس؟","title":"حكم أداء السنن الرواتب في السفر","answer":"الجواب: الأولى تركها في السفر إلا سنة الفجر تأسيًا بالنبي ﷺ فيصلي سنة الفجر معها، أما سنة الظهر والمغرب والعشاء والعصر فهذه الأفضل تركها؛ لأن الله خفف عن المسافر نصف الصلاة، فيترك التطوعات التي مع الفريضة.\nأما كونه يصلي صلاة الضحى أو سنة الوضوء أو التهجد بالليل هذا باقي يفعله المسافر وغيره، كان النبي ﷺ يتهجد من الليل، يصلي الضحى وهو مسافر، لا بأس بذلك، لكن سنة الظهر القبلية والبعدية، وسنة العصر قبلها، سنة المغرب بعدها، سنة العشاء بعدها الأفضل تركها في السفر، نعم.\nالمقدم: هناك أيام محددة يا شيخ في السفر؟\nالشيخ: إذا كان محكوم بالسفر، إذا كان ..... له القصر، مسافة ثمانين كيلو فأكثر، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12291/حكم-اداء-السنن-الرواتب-في-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50619.mp3","categories":["صلاة التطوع"]},{"id":13881,"question":"يقول السائل: ما هو وقت صلاة الضحى؟ وهل هناك آيات بعينها كان يقرؤها الرسول ﷺ في هذه الصلاة؟","title":"ما وقت صلاة الضحى؟ وماذا يقرأ فيها؟","answer":"الجواب: صلاة الضحى ما بين ارتفاع الشمس قيد رمح إلى أن تقف الشمس قرب الظهر كله ضحى، فإذا صلاها بعد الشروق بعد ارتفاع الشمس فقد صلى صلاة الضحى مبكرًا، والأفضل أن تكون عند شدة الضحى، الأفضل أن يصليها حين يشتد الضحى قبل الظهر بساعتين ساعة ونصف، ساعة، أكثر لا بأس، هذا هو الأفضل، يعني: قبل الظهر بساعة ساعتين يكون أفضل عند شدة الضحى، وإن صلاها بعد ارتفاع الشمس إذا كان جالسًا في المسجد حتى ارتفعت الشمس حصل بذلك صلاة الضحى مبكرًا، وهكذا لو كان في البيت وصلاها بعد ارتفاع الشمس كل ذلك حسن، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12264/ما-وقت-صلاة-الضحى-وماذا-يقرا-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50603.mp3","categories":["صلاة التطوع"]},{"id":13971,"question":"السائل أسعد عبد الله يقول: أيهما أفضل بالنسبة للمسافر أن يؤدي السنن الرواتب أو يتركها وكذلك النوافل؟","title":"هل تؤدى الرواتب والنوافل في السفر؟","answer":"الجواب: المسافر السنة له أن يدع الرواتب لا يأتي بها كما كان النبي يفعل عليه الصلاة والسلام؛ فإنه كان عليه الصلاة والسلام إذا سافر يترك سنة الظهر .. سنة المغرب .. سنة العشاء، أما سنة الفجر فكان يأتي بها عليه الصلاة والسلام، كان يصلي الفجر ويصلي راتبتها سفرًا وحضرًا، أما سنة الظهر والمغرب والعشاء فكان يترك ذلك عليه الصلاة والسلام في السفر، أما العصر فليس لها راتبة لكن كان يصلي قبلها أربعًا بعض الأحيان وربما صلى قبلها ثنتين بعض الأحيان عليه الصلاة والسلام، ويقول ﷺ: رحم الله امرءًا صلى أربعًا قبل العصر فالأفضل في السفر تركها؛ لأنها تشبه الراتبة. أما النوافل الأخرى فالأفضل فعلها مثل: سنة الضحى .. التهجد بالليل الوتر، هذا سنة في السفر والحضر، سنة الوضوء إذا توضأ هذه نوافل مشروعة في السفر والحضر، كان النبي ﷺ يصلي سنة الضحى في السفر، صلاها عام الفتح ثمان ركعات عليه الصلاة والسلام، وكان يتهجد بالليل في السفر ويصلي على بعيره بعض الأحيان عليه الصلاة والسلام النافلة في السفر، ويوتر على بعيره أيضا عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12387/هل-تودى-الرواتب-والنوافل-في-السفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_539/53902.mp3","categories":["صلاة التطوع"]},{"id":14000,"question":"أيهما أفضل في صلاة الراتبة أن تؤدى في البيت أم في المسجد؟","title":"أفضلية صلاة الراتبة في البيت على المسجد","answer":"الجواب: ...... السنة أن يصلي هذه الرواتب وهذه النوافل في البيت هذا هو الأفضل، وإن صلاها في المسجد فلا حرج، ولكن في البيت أفضل، وسمعت أنه  قال: من صلى ثنتي عشرة ركعة في يومه وليلته بنى له الله بيتًا في الجنة، وهذا فضل عظيم ينبغي للمؤمن والمؤمنة ألا يفرطا في هذا الخير العظيم. نعم.","link":"https://binbaz.org.sa/fatwas/12412/افضلية-صلاة-الراتبة-في-البيت-على-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_540/54001.mp3","categories":["صلاة التطوع"]},{"id":14097,"question":"أسأل عن حكم صلاة التطوع للقادر جالسًا هل يجوز ذلك، أو لا؟","title":"حكم صلاة النافلة جلوسًا","answer":"الجواب: نعم يجوز، لكن له النصف نصف الأجر، جاء في الحديث عن النبي ﷺ أنه قال: صلاة القاعد على النصف من صلاة القائم، يعني: إذا صلى من غير عذر، أما إذا تطوع عن عذر أو صلى فريضة عن عذر جالسًا؛ لأنه مريض لا يستطيع القيام فهذا معذور له الأجر كاملاً، وهكذا في التطوع إذا صلى جالسًا لا حرج عليه، لكن يكون له النصف إذا كان قادرًا يكون له النصف. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12520/حكم-صلاة-النافلة-جلوسا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48412.mp3","categories":["صلاة التطوع"]},{"id":14105,"question":"سمعت بأن من قرأ سورة تبارك عند النوم وواظب عليها حتى الموت فهو شهيد، هل هذا صحيح؟ أرجو الإفادة وفقكم الله وسدد خطاكم؟","title":"هل من واظب على قراءة سورة تبارك شهيد؟","answer":"الجواب: لا أعلم لهذا صحة، هي سورة مباركة وعظيمة فيها فضل كبير، لكن هذا الذي قلته لا أعلم له أصلًا. نعم.","link":"https://binbaz.org.sa/fatwas/12532/هل-من-واظب-على-قراءة-سورة-تبارك-شهيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61408.mp3","categories":["القرآن وعلومه","الحكم على الأحاديث","صلاة التطوع"]},{"id":14107,"question":"إذا أقيمت الصلاة وأنا في النافلة هل أقطعها لأدرك التكبيرة مع الإمام؟","title":"ماذا يُشرع لمن أقيمت الصلاة وهو في النافلة؟","answer":"الجواب: هذا هو الأفضل قطعها، لقوله ﷺ: إذا أقيمت الصلاة فلا صلاة إلا المكتوبة، فتقطعها وتشتغل بالتكبير مع الإمام، الدخول في الصلاة إلا إذا كنت في آخرها، بعد الركوع في الثانية تكملها لأنه ما بقي صلاة، ما بقي إلا قليل، أقل الصلاة ركعة، فإذا كنت قد صليت الركعتين وركعت في الركوع الثاني ما بقي إلا السجود أو التحيات، فالأظهر والله أعلم أنه لا حرج عليك أن تكملها لأنه ما بقي إلا جزء من الركعة، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12543/ماذا-يشرع-لمن-اقيمت-الصلاة-وهو-في-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_484/48415.mp3","categories":["صلاة التطوع","صلاة الجماعة"]},{"id":14129,"question":"صلاة الاستخارة متى يكون الدعاء فيها؟ هل هو مثل الوتر أو بعد نهايتها؟","title":"موضع دعاء الاستخارة","answer":"الجواب: إذا صلى الركعتين يدعو، إذا صلى وسلم من الركعتين يرفع يديه ويدعو؛ لأن النبي ﷺ أرشده إلى أن يصلي ركعتين ثم يدعو. نعم.\nالمقدم: إذًا بعد التسليم؟\nالشيخ: بعد التسليم. نعم.\nالمقدم: بعد التسليم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12574/موضع-دعاء-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61510.mp3","categories":["صلاة التطوع"]},{"id":14135,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلينا من مدينة المرج في ليبيا، وبعثت بها إحدى المستمعات من هناك اسمها نوارة سالم محمد، نوارة عرضنا بعض أسئلتها في حلقة مضت، وها نحن في هذه الحلقة نستأنف عرض أسئلتها فتسأل هذا السؤال وتقول: ثبت عن سيد المرسلين قوله ﷺ: رحم الله امرأ صلى قبل العصر أربعًا وحرم الله النار على رجل صلى أربعًا قبل الظهر وأربعًا بعد الظهر، أو كما قال ﷺ، فهل هذه الثمان الركعات التي هي قبل الظهر وبعده هي الراتبة، وهل الأربع ركعات التي قبل العصر هي التي تصلى بعد سماع الأذان وقبل الفريضة؟ أم تصلى قبل ذلك كله، أرجو إفادتنا بذلك بارك الله فيكم؟","title":"ما الراتبة القبلية والبعدية للظهر ونافلة العصر؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالأربع الركعات التي قبل العصر تصلى بعد دخول الوقت، لقوله ﷺ: رحم الله امرأً صلى أربعًا قبل العصر، فظاهر الحديث أنها قبله يعني: بعد دخول الوقت، وهذه ليست راتبة ولكنها مشروعة؛ لأن الرسول ندب إليها عليه الصلاة والسلام ودعا لصاحبها، فهي سنة وقربة وطاعة بعد دخول الوقت.\nوتصلى ثنتين ثنتين هذا هو السنة لقوله ﷺ: صلاة الليل والنهار مثنى مثنى، يعني: ثنتين ثنتين هذا هو السنة.\nأما أربع قبل الظهر وأربع بعدها فإنه يدخل فيها الراتبة، الراتبة المحفوظة عنه ﷺ أربع قبل الظهر وثنتان بعدها، جاء ذلك من حديث عائشة ومن حديث أم حبيبة ومن أحاديث أخرى، والمعنى: تسليمتان قبل الظهر وتسليمة واحدة بعدها.\nوجاء في حديث أم حبيبة بنت أبي سفيان رضي الله تعالى عنها عن النبي ﷺ أنه قال: من حافظ على أربع قبل الظهر وأربع بعدها حرمه الله تعالى على النار، وفي لفظ: من صلى أربعًا قبل الظهر وأربعًا بعدها حرمه الله تعالى على النار، فهذه الثمان يدخل فيها الراتبة، الست التي هي الراتبة داخلة فيها إذا صلى أربعًا قبل الظهر وصلى أربعًا بعدها حصل بذلك المقصود، الراتبة وزيادة ركعتين وكلها فيها فضل عظيم وخير كبير. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12576/ما-الراتبة-القبلية-والبعدية-للظهر-ونافلة-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_485/48501.mp3","categories":["صلاة التطوع"]},{"id":14178,"question":"يقول في ثالث أسئلته: هل هناك صلاة تسمى بصلاة الحاجة؟","title":"هل توجد صلاة تسمى صلاة الحاجة؟","answer":"الجواب: لا أعلم إلا صلاة التوبة وصلاة الاستخارة، إذا كان الإنسان قد فعل ذنبًا شرع له التوبة وجبت عليه التوبة، وإذا تطهر وصلى ركعتين وتاب كان أكمل وأقرب إلى النجاح، وهكذا صلاة الاستخارة إذا هم بأمر وأشكل عليه يصلي ركعتين ثم يستخير الله.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12621/هل-توجد-صلاة-تسمى-صلاة-الحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54713.mp3","categories":["صلاة التطوع"]},{"id":14179,"question":"يقول: هل الركعتين التي تصلى وقت شروق الشمس تسمى بركعتي الشروق أم بصلاة الشروق؟","title":"هل صلاة الضحى هي صلاة الشروق؟","answer":"الجواب: يسميها العامة صلاة الشروق وهي صلاة الضحى، صلاة الضحى المبكرة إذا ارتفعت الشمس تسمى صلاة الضحى لكنها مبكرة، وأفضلها عند اشتداد الضحى، هذا أفضل صلاة الضحى، وإذا صلاها بعد ارتفاع الشمس هي صلاة ضحى ويسميها العامة صلاة الشروق. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12622/هل-صلاة-الضحى-هي-صلاة-الشروق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_547/54714.mp3","categories":["صلاة التطوع"]},{"id":14246,"question":"السائل سالم من خميس مشيط يقول في هذا  بالنسبة يا سماحة الشيخ إلى جمع سنة الوضوء وسنة الفرض وسنة تحية المسجد في ركعتين هل يحصل على ثواب الست ركعات أم لا؟","title":"هل صلاة ركعتين بنية أكثر من نافلة يجمع ثوابها؟","answer":"الجواب: نرجو أن يحصل له هذا الخير إذا صلى ركعتين بعدما توضأ ودخل المسجد صلى ركعتين ناويًا سنة الوضوء وسنة التحية والراتبة -راتبة الظهر- مثلًا نرجو أن يجمع الله له الخير كله؛ لأن الركعتين مشروعة لتحية المسجد ومشروعة للوضوء ومشروعة للراتبة قبل الظهر، فإن الراتبة قبل الظهر أربع ركعات يسلم من كل ركعتين، فإذا نواها راتبة وتحية للمسجد وسنة الوضوء نرجو أن يجمع الله له ذلك كله، ولا أعلم مانعاً من ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/12703/هل-صلاة-ركعتين-بنية-اكثر-من-نافلة-يجمع-ثوابها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_530/53016.mp3","categories":["صلاة التطوع"]},{"id":14264,"question":"رسالة وصلت إلى البرنامج من المستمعة سمية من الأردن تسأل عن صلاة الضحى في أي وقت بالضبط تقام، وكم عدد ركعاتها، وهل لها دعاء خاص بها؟","title":"وقت صلاة الضحى وعدد ركعاتها","answer":"الجواب: صلاة الضحى مستحبة، وتبتدئ من ارتفاع الشمس قيد رمح إلى وقوف الشمس وأفضلها إذا اشتد الضحى، لقوله ﷺ: صلاة الأوابين حين ترمض الفصال فالأفضل عند شدة الضحى قبل الظهر بساعة أو ساعتين هذا هو الأفضل، وإذا صلاها المسلم في أول النهار بعد ارتفاع الشمس قيد رمح أو في بقية أجزاء الضحى كل ذلك حسن، والحمد لله.\nوأقلها ركعتان ولا حد لأكثرها، وبعض أهل العلم قال: أكثرها ثمان، ولكن لا دليل عن ذلك إذا صلى ثمان أو أكثر أو أقل كل ذلك لا حرج فيه والحمد لله، وقد صلى النبي ﷺ صلاة الضحى يوم الفتح ثمان ركعات عليه الصلاة والسلام، وكان يصلي ركعتين إذا زار قباء يوم السبت ضحى عليه الصلاة والسلام. فالحاصل أن أقلها ركعتان ولا حد لأكثرها، وإذا صلاها ثمان يسلم من كل ثنتين هذا حسن موافق لفعل النبي ﷺ لما صلاها بمكة المكرمة حين الفتح، ولو صلى ثنتي عشرة أو صلى عشرين أو صلى أكثر فإنه يسلم من كل ركعتين؛ لقوله ﷺ: صلاة الليل والنهار مثنى مثنى رواه الإمام أحمد وأهل السنن بإسناد حسن من حديث ابن عمر رضي الله تعالى عنهما.\nفالحاصل أن صلاة الضحى مشروعة وسنة، قربة عظيمة، قد أوصى بها النبي ﷺ بعض أصحابه، فهي سنة مؤكدة تبتدئ من ارتفاع الشمس قيد رمح إلى وقوف الشمس، يعني: إلى ما قبل الزوال بنحو ثلث ساعة أو نصف ساعة تقريبًا. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12761/وقت-صلاة-الضحى-وعدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_621/62109.mp3","categories":["صلاة التطوع"]},{"id":14279,"question":"الأخت المستمعة نادية عبد السلام بعثت تسأل وتقول: هل صلاة الأوابين صحيحة؟ وهي ست ركعات بعد صلاة المغرب؟","title":"هل صلاة الأوابين هي ست ركعات بعد المغرب؟","answer":"الجواب: هذا ليس بصحيح وليس بثابت؛ لكن تستحب الصلاة بين المغرب والعشاء ولو أكثر من ست ركعات، لكن ما تسمى صلاة الأوابين، صلاة الأوابين: صلاة الضحى هذه صلاة الأوابين، إذا اشتد الضحى فالصلاة ذاك الوقت يقال لها: صلاة الأوابين، قال النبي عليه الصلاة والسلام: صلاة الأوابين حين ترمض الفصال يعني: حين يشتد الحر ضحى فهذه صلاة الأوابين، وصلاة الضحى عند شدة الحر يعني: عند علو النهار قبل الزوال بساعة أو ساعتين يقال لها: صلاة الأوابين. أما ما بين المغرب والعشاء فالحديث فيها ضعيف تسميتها صلاة الأوابين ضعيف، ولكن يستحب للمؤمن أن يصلي فيها والمؤمنة ما يسر الله له غير سنة المغرب، أما سنة المغرب فهي مؤكدة سنة مؤكدة ركعتان بعد المغرب، وإذا صلى زيادة ركعتين أخريين أو أربع ركعات أو ست ركعات أو عشر ركعات كله طيب، ما بين صلاة المغرب والعشاء كله محل عبادة، ولو صلى كثيرًا كله محل تطوع، وهكذا بعد العشاء كله محل تطوع، والحمد لله. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12741/هل-صلاة-الاوابين-هي-ست-ركعات-بعد-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_486/48612.mp3","categories":["صلاة التطوع","الحكم على الأحاديث"]},{"id":14354,"question":"في ثاني أسئلتها تسأل عن صلاة الضحى وصلاة الليل متى تبدأ ومتى تنتهي؟","title":"وقت صلاة الضحى وصلاة الليل","answer":"الجواب: صلاة الليل بين المغرب والعشاء وبعد العشاء كلها صلاة ليل، والأفضل بعد العشاء في وسط الليل في آخره، ثم تختم الصلاة بوتر واحدة ركعة واحدة، يستحب للمؤمن أن يجتهد في الليل بعد العشاء أو في جوف الليل أو في آخر الليل يجتهد ويصلي ركعتين ركعتين، مع الخشوع والطمأنينة، والضراعة إلى الله، والدعاء، ويختم بواحدة، لقوله ﷺ في الحديث: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعة واحدة، توتر له ما قد صلى .\nوإذا صلى بين العشاءين فهو محل صلاة أيضًا، بين العشاءين محل صلاة، إذا صلى فيها ما تيسر من الركعات هذا طيب أيضًا، محل عبادة. وهكذا في النهار، يتعبد في النهار في الضحى في الظهر، صلاة الضحى سنة بعد ارتفاع الشمس، والأفضل إذا اشتد الضحى يصلي ركعتين، يصلي أربع، يصلي أكثر من ذلك، كله طيب، بعد العشاء بعد الظهر يصلي أربعًا قبل الظهر وأربعًا بعدها، يستحب؛ لقول النبي ﷺ: من حافظ على أربع قبل الظهر، وأربع بعدها حرمه الله على النار ولو صلى بين الظهر والعصر ركعات كثيرة كله عبادة طيب، أو صلى في الضحى ركعات كثيرة كلها طيب، لكن أقل شيء ركعتان في الضحى، وأقل شيء بعد الظهر أربعًا بعد الظهر بتسليمتين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12825/وقت-صلاة-الضحى-وصلاة-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_551/55103.mp3","categories":["صلاة التطوع"]},{"id":14419,"question":"السائل الذي أرسل بهذه الرسالة السائلة رمزت لاسمها بـ (س. م. ش) من مدينة النومة تقول في السؤال الأول: هل يجوز لي أن أصلي السنن الرواتب قبل الأذان؟","title":"هل تصلى السنن الرواتب قبل الأذان؟","answer":"الجواب: سنة الراتبة بعد الأذان، سنة الظهر قبلها أربع، وبعدها ثنتين أو أربع، والفجر بعد طلوع الفجر سنة الراتبة ركعتين، أما المغرب والعشاء سنتهما بعدهما، بعد المغرب ركعتين، وبعد العشاء ركعتين، وإذا صلى قبل العصر يصليها بعد دخول الوقت أربع ركعات أفضل تسليمتين، إذا أذن المؤذن إذا دخل وقت العصر يصلي أربع ركعات بتسليمتين أفضل. أما صلاتها قبل الوقت فلا، ما تمت، ما تصير راتبة، إذا صلاها قبل الوقت صلاها قبل العشاء، قبل أذان العشاء تكون تبع الصلاة بين المغرب والعشاء، أو صلى قبل الظهر قبل وقت الظهر إذا كان قبل وقوف الشمس تبع صلاة الضحى، وإن كانت عند وقوف الشمس هذا وقت نهي، لا يصلى فيه الصلاة العادية إلا ذات الأسباب، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12901/هل-تصلى-السنن-الرواتب-قبل-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_553/55315.mp3","categories":["صلاة التطوع"]},{"id":14449,"question":"السائلة في هذا السؤال تقول سماحة الشيخ: ما حكم تأدية صلاة الضحى بعد الأذان الأول من يوم الجمعة؟","title":"حكم صلاة الضحى بعد الأذان الأول للجمعة","answer":"الجواب: صلاة الضحى سنة في يوم الجمعة وغيره، وأداء ذلك بعد الأذان الأول لا بأس به؛ لأن الشمس لم تقف، ويوم الجمعة الصواب أنه ليس فيها وقت نهي عند الزوال؛ لأن الرسول ﷺ شرع للناس إذا دخلوا المسجد أن يصلوا ما قدر الله لهم، ولم يقل لهم: إلا إذا وقفت الشمس، فدل ذلك على أن يوم الجمعة الصلاة فيها مستمرة إلى دخول الخطيب، وليس فيها وقت نهي في وسط النهار، هذا هو الأرجح، فإذا صلى المسلم في المسجد ما يسر الله له من الركعات حتى يدخل الخطيب فلا بأس، وإذا صلت المرأة في بيتها الضحى ما يسر الله لها قبل الأذان الأول أو بعده فلا بأس. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12916/حكم-صلاة-الضحى-بعد-الاذان-الاول-للجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55407.mp3","categories":["صلاة التطوع"]},{"id":14451,"question":"ما كيفية صلاة الاستخارة؟ وما هو دعاؤها؟ وفي أي وقت تصلى؟","title":"كيفية صلاة الاستخارة والدعاء الوارد فيها","answer":"الجواب: صلاة الاستخارة ركعتان، النبي ﷺ قال: إذا هم أحدكم بأمر فليصل ركعتين، ثم ليقل: اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنك تعلم ولا أعلم، وتقدر ولا أقدر، وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر ويسميه باسمه يقول: هذا الأمر، زواجي بفلانة، أو سفري إلى محل كذا، أو شراء كذا، أو ما أشبه ذلك، يعين حاجته اللهم إن كنت تعلم أن هذا الأمر خير لي في ديني ومعاشي وعاقبة أمري، فيسره لي، ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر شر لي في ديني ومعاشي وعاقبة أمري فاصرفه عني واصرفني عنه، وقدر لي الخير حيث كان، ثم رضني به هذه السنة هذا دعاء الاستخارة.  وإذا كان لا يعرف هذا الدعاء يدعو بما تيسر، يقول: اللهم قدر لي الخير، اللهم يسر لي الخير، اللهم اشرح صدري لهذا السفر إن كان خيرًا، اللهم اشرح صدري لهذا الزواج إن كان خيرًا، يدعو بما يفهم بما يعرف بعد السلام، يرفع يديه ويدعو بعد الصلاة الركعتين، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12919/كيفية-صلاة-الاستخارة-والدعاء-الوارد-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_554/55409.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":14476,"question":"أرى بعض المصلين يصلون أربع ركعات في صلاة الفجر، فهل هذا جائز؟","title":"هل يجوز صلاة أربع ركعات قبل صلاة الفجر؟","answer":"الجواب: السنة ركعتان تسده وتكفيه عن تحية المسجد، وعن الراتبة، بعض الناس يظن أنه يجمع بين الأمرين، يصلي تحية المسجد، ثم يصلي الراتبة، وهذا لا حاجة إليه؛ لأن في الحديث: لا صلاة بعد طلوع الفجر إلا ركعتي الفجر ولم يكن النبي ﷺ يصلي بعد طلوع الفجر إلا ركعتين وهي سنة الفجر. فالسنة لمن دخل المسجد وهو لم يصل الراتبة فإنه يصلي ركعتين بنية الراتبة، وإن نوى مع ذلك سنة التحية كله حسن، تكفيه ركعتان السنة الراتبة، وتقوم مقام تحية المسجد، وإذا نواهما جميعًا، نوى التحية مع الراتبة فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12975/هل-يجوز-صلاة-اربع-ركعات-قبل-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62504.mp3","categories":["صلاة التطوع"]},{"id":14482,"question":"أرى بعض أئمة المساجد إذا دخل المسجد يوم الجمعة يشرع في الصلاة، فيصلي تحية المسجد، ثم يصعد إلى المنبر، فهل هذا جائز؟","title":"حكم صلاة الخطيب تحية المسجد قبل صعود المنبر","answer":"الجواب: لا نعلم لهذا أصلًا، كان النبي ﷺ إذا دخل يقصد المنبر مباشرة، ولا يصلي تحية المسجد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12970/حكم-صلاة-الخطيب-تحية-المسجد-قبل-صعود-المنبر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62503.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":14488,"question":"صلينا المغرب والعشاء جماعة في المسجد لوجود مطر وبرد، و متى نصلي الرواتب إذا جمعنا، وكم يصبح عددها، وهل يصلى الشفع والوتر في نفس الوقت أم لا بد من تأخيره؟","title":"متى تصلى الرواتب والوتر عند الجمع بين الصلاتين؟","answer":"الجواب: إذا صليت العشاء مع المغرب جمع تقديم فإنك تصلي سنة المغرب وسنة العشاء بعد ذلك، وتصلي الوتر بعد ذلك، ولو في وقت المغرب؛ لأن العشاء متى قدمت دخل وقت الوتر وسنة العشاء، ولو كانت مجموعة مع المغرب جمع تقديم. وهكذا الظهر والعصر إذا جمعا وأنت مقيم للمطر أو للمرض تصلي سنة الظهر... ، لا، ليس بهذا، ليس في هذا قضاء؛ لأن صلاة العصر ليس بعدها صلاة؛ لأنها وقت نهي، إذا جمعت الظهر مع العصر فإنها تسقط حينئذٍ راتبة الظهر البعدية التي بعدها؛ لأن الأفضل أن تضم إليها العصر قبل أن تصلي الراتبة، فحينئذٍ تسقط الراتبة البعدية في الظهر عند الجمع في حال المرض والمطر ونحو ذلك، وتصلي الراتبة القبلية، وهي أربع قبل الظهر، وتصلي العصر بعد الظهر متصلة من دون حاجز من دون فصل براتبة الظهر البعدية. أما المغرب والعشاء فإنهما تقعان في غير وقت نهي، فلهذا إذا صليت العشاء تصلي سنة المغرب ركعتين وتصلي بعدها سنة العشاء ركعتين، وإذا أردت الوتر أوترت، أو أجلت ذلك إلى وسط الليل، أو آخر الليل، الأمر في هذا واسع، والحمد لله، نعم. المقدم: الحمد لله، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12966/متى-تصلى-الرواتب-والوتر-عند-الجمع-بين-الصلاتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62502.mp3","categories":["صلاة التطوع","الوتر وقيام الليل"]},{"id":14617,"question":"أحد الإخوة المستمعين من المملكة الأردنية الهاشمية، ممن يسأل عن السنة القبلية لصلاة الجمعة، هل لها سنة؟ أو لًا؟","title":"هل للجمعة سنة قبلية؟","answer":"الجواب: تقدم أنه لا سنة لها قبلية، ولكن يصلي ما كتب الله له، يصلي ثنتين أو تسليمتين، أو ثلاث تسليمات، يعني: ركعتين ركعتين حسب ما يسر الله له، إذا وصل إلى المسجد، يصلي ما قدر الله له، كما قال النبي ﷺ ثم يجلس ينتظر خروج الإمام، وسماع الخطبة والصلاة.  فالحاصل: أنه ليس لها سنة راتبة قبلية، ولكن يصلي ما يسر الله له، وإذا صلى ركعتين تحية المسجد كفى، وإذا صلى معهما ركعات أخرى كان أفضل وأكمل؛ لأنه يوم عظيم، ويوم فاضل، ويوم عيد، فإذا صلى قبلها ركعات يسلم من كل ثنتين كان ذلك أفضل، ثم يجلس ينتظر مسبحًا ومهللًا أو قارئًا أو مستغفرًاً أو ساكتًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13115/هل-للجمعة-سنة-قبلية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_636/nour_63606.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":14663,"question":"أم معاذ من المدينة المنورة أرسلت بمجموعة من الأسئلة، تقول في السؤال الأول: دعاء الاستخارة قبل السلام أم بعد السلام من الصلاة سماحة الشيخ؟","title":"متى يكون دعاء الاستخارة؟","answer":"الجواب: السنة أن يكون بعد السلام؛ لأن النبي ﷺ قال: إذا هم أحدكم بأمر فليصل ركعتين، ثم ليقل فجعل الدعاء بعد الصلاة، نعم.","link":"https://binbaz.org.sa/fatwas/13150/متى-يكون-دعاء-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56004.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":14665,"question":"تقول السائلة أم معاذ من المدينة المنورة: ما حكم صلاة التسبيح؟ وهل هي واردة أم لا؟","title":"عدم مشروعية صلاة التسابيح","answer":"الجواب: صلاة التسبيح غير ثابتة، حديثها ضعيف، ولا يجوز استعمالها؛ لأنها خلاف الصلاة المشروعة الثابتة عن النبي ﷺ، فحديثها غير صحيح، نعم.","link":"https://binbaz.org.sa/fatwas/13156/عدم-مشروعية-صلاة-التسابيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56006.mp3","categories":["صلاة التطوع","البدع والمحدثات"]},{"id":14667,"question":"هل هناك حديث صحيح يدل على وجود صلاة لمنع نسيان القرآن يا شيخ؟","title":"هل توجد صلاة تمنع من نسيان القرآن؟","answer":"الجواب: لا أعلم شيئًا في ذلك، أقول: لا أعلم شيئًا في ذلك، نعم.\nإنما الدعاء، يسأل ربه، الإنسان يسأل ربه أن الله يعينه ويوفقه لحفظ كتاب الله، يسأل ربه، يروى عن علي ، لكنه حديث ضعيف. المقصود: أنه يسأل ربه، ويضرع إلى الله أن يحفظه القرآن، وأن يعينه على حفظ القرآن، والعمل به، يضرع إلى الله، الله يقول: ادْعُونِي أَسْتَجِبْ لَكُمْ [غافر:60] ، نعم.","link":"https://binbaz.org.sa/fatwas/13160/هل-توجد-صلاة-تمنع-من-نسيان-القران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56007.mp3","categories":["صلاة التطوع","الحكم على الأحاديث"]},{"id":14673,"question":"ما حكم صلاة الحاجة سماحة الشيخ؟","title":"ما حكم صلاة الحاجة؟","answer":"الجواب: صلاة الحاجة ما ورد فيها، صلاة الاستخارة وصلاة التوبة هذا الذي نعلم، إذا أراد أن يتوب من ذنب تطهر وصلى ركعتين، ثم سأل ربه أن يتوب عليه، وأن يغفر له، هذا لا بأس به.  جاء في الحديث الصحيح عن الصديق أبي بكر عن النبي ﷺ أنه قال: إذا أذنب أحدكم ثم تطهر وصلى ركعتين ثم استغفر الله، تاب الله عليه وليس من شرط التوبة الصلاة إذا تاب وندم وأقلع تاب الله عليه إذا صدق في ذلك، وإذا صلى ركعتين وتاب بعد هذا زيادة خير من باب أسباب صحة التوبة وكمالها.","link":"https://binbaz.org.sa/fatwas/13163/ما-حكم-صلاة-الحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_560/56008.mp3","categories":["صلاة التطوع"]},{"id":14742,"question":"هل يشترط في النوافل أن تكون سرية؟ مع العلم أنني أصلي النوافل الليلية جهرًا والنوافل النهارية سرًّا.","title":"حكم الجهر بالقراءة في النوافل","answer":"الجواب: لا يشترط كونها سرية، يشرع للرجل أن يتنفل جهرة وسرًّا، وإذا كان سرًّا في بعض الأحيان كان أكمل في الإخلاص، ولكن ليس ممنوعًا أن يصلي جهرًا كما يصلي بعض الرواتب في المسجد كسنة الظهر أو المغرب أو العشاء أو الفجر لا بأس، ولا بأس أن يصلي الضحى في المسجد أيضًا، ولا بأس أن يصلي في بيته وعنده من يراه من أهله أو ضيوفه لا بأس، لكن إذا كان في محل خاص بينه وبين ربه في النوافل كان هذا أكمل في الإخلاص، ولا حرج أن يصلي جهرة عند الناس، لا حرج في ذلك إذا كان قصده الإخلاص وليس قصده الرياء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13243/حكم-الجهر-بالقراءة-في-النوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63720.mp3","categories":["صلاة التطوع"]},{"id":14797,"question":"رأيت بعض الناس إذا دخل المسجد يصلي أربع ركعات متواصلة، بتسليمة واحدة تحية المسجد، فهل هذا صحيح، أم تحية المسجد ركعتان فقط؟","title":"حكم صلاة تحية المسجد أربع ركعات","answer":"الجواب: هذا خلاف السنة، السنة ركعتان فقط، أما أن يصلي أربعًا جميعًا فهذا خلاف السنة، والنبي  قال: صلاة الليل والنهار مثنى مثنى فالسنة إذا دخل المسجد أن يصلي ركعتين، ويسلم منهما، وإذا أحب أن يصلي زيادة فلا بأس، لكن يسلم من كل ركعتين هذا هو الأفضل، في النهار، وفي الليل، يتأكد ذلك، ولا يجوز أن يجمع أربعًا بسلام واحد، بل يسلم من كل ثنتين، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13294/حكم-صلاة-تحية-المسجد-اربع-ركعات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63811.mp3","categories":["صلاة التطوع"]},{"id":14799,"question":"أسأل أيضًا عن الصلاة وقت الغروب، وعند بزوغ الشمس صباحًا، ولا سيما عندما يكون نصفها ظاهرًا، والنصف الآخر قد اختفى، أو ما زال مخفيًا، هل في هذه الأوقات الصلاة محرمة أو مكروهة، أو هل هناك شروط أخرى؟ أرجو التوضيح، جزاكم الله خيرًا.","title":"حكم الصلاة عند الشروق والغروب","answer":"الجواب: أوقات النهي عن الصلاة خمسة، بيَّنها النبي -عليه الصلاة والسلام-.  أولها: من طلوع الفجر إلى أن تطلع الشمس فلا يصلى في هذا الوقت إلا الفجر وسنتها، لا يصلى بعد طلوع الفجر إلا الفجر، فريضة الفجر، ويصلي أيضًا سنتها ركعتين قبلها في السفر والحضر.  الثاني: بعد طلوع الشمس إلى أن ترتفع قيد رمح، وهذا وقت ضيق.  والثالث: بعد صلاة العصر إلى أن تصفر الشمس.  والرابع: بعد اصفرارها إلى أن تغيب.  والخامس: عند قيام الشمس قبل الظهر، عند وقوف الشمس قبل الزوال، وهو وقت قصير إلى أن تزول، فهذه أوقات النهي، لا يصلى فيها النوافل إلا ما له سبب في أصح قولي العلماء. المقدم: إلا ما له؟\nالشيخ: إلا الشيء الذي له سبب كصلاة الكسوف، أو صلاة الطواف إذا طاف بعد العصر، أو بعد الصبح، أو تحية المسجد، فهذه صلوات لها أسباب، والصحيح من قولي العلماء: أنه لا بأس بذوات الأسباب، إذا دخل المسجد بعد صلاة العصر ليجلس فيه للتعلم، أو لقراءة القرآن، أو لينتظر صلاة المغرب، فإن السنة أنه يصلي ركعتين قبل أن يجلس؛ لأنها ذات سبب، وكذلك لو دخل بعد الفجر يصلي ركعتين، وهكذا لو طاف في مكة طاف بالكعبة بعد العصر، أو بعد الصبح يصلي ركعتي الطواف، وهكذا لو كسفت الشمس عند طلوعها، أو كسفت بعد العصر يصلي صلاة الكسوف؛ لأنها من ذوات الأسباب، وقد قال ﷺ في الحديث الصحيح: إن الشمس والقمر آيتان من آيات الله، لا ينخسفان لموت أحد ولا لحياته، فإذا رأيتم ذلك فافزعوا إلى الصلاة وفي اللفظ الآخر: فصلوا وادعوا ولم يقل: إلا في وقت النهي، وهكذا قوله ﷺ: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين فهذا يعم أوقات النهي وغيرها، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13317/حكم-الصلاة-عند-الشروق-والغروب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63814.mp3","categories":["صلاة التطوع"]},{"id":14878,"question":"المستمع علي ناصر الزيد، من مدينة حائل، بعث يسأل ويقول: عند دخولي المسجد للصلاة وأداء تحية المسجد بدون أن أنوي هل هي تحية المسجد أم سنة الفريضة، مثلاً أدخل المسجد لصلاة الفجر، وأصلي ركعتين بدون أن أنوي، هل تدمج تحية المسجد مع سنة الفريضة، أم أن الأفضل أن أؤدي كل واحدة على حدة؟","title":"هل تكفي سنة الراتبة عن ركعتي تحية المسجد؟","answer":"الجواب: إذا نويت سنة التحية وسنة الفجر كفت، وهكذا الظهر إذا نويت بالركعتين الأوليين سنة التحية وسنة الراتبة كفت، وهكذا العصر إذا صليت أربعًا قبلها ركعتين ركعتين، قامتا مقام التحية، والحمد لله، فالنية تشمل الجميع، نعم.\nالمقدم: وإذا لم ينو سماحة الشيخ؟ الشيخ: سدت ولو لم ينو، إذا نوى سنة الفجر سدت عن التحية كفت، وهكذا إذا صلى بنية الراتبة الظهر القبلية كفت عن التحية، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13374/هل-تكفي-سنة-الراتبة-عن-ركعتي-تحية-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_645/nour_64517.mp3","categories":["صلاة التطوع"]},{"id":14910,"question":"يقول السائل: هل للمغرب سنة قبلية أو بعدية؟","title":"هل للمغرب سنة قبلية وبعدية؟","answer":"الجواب: الراتبة بعد المغرب وبعد العشاء، أما الركعتان قبل المغرب فهي سنة ليست راتبة، لكن إذا كان في المسجد يستحب له بعد الأذان أن يصلي ركعتين -بعد أذان المغرب- وهكذا بعد أذان العشاء؛ لقوله ﷺ: بين كل أذانين صلاة، بين كل أذانين صلاة، بين كل أذانين صلاة قال في الثالثة: لمن شاء فيستحب أن يصلي ركعتين بعد الأذان، أذان المغرب وأذان العشاء؛ لهذا الحديث، وحديث آخر: صلوا قبل المغرب، صلوا قبل المغرب ثم قال في الثالثة: لمن شاء فدل ذلك على أنهما مستحبتان، وليستا واجبتين، نعم.","link":"https://binbaz.org.sa/fatwas/13408/هل-للمغرب-سنة-قبلية-وبعدية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56210.mp3","categories":["صلاة التطوع"]},{"id":14999,"question":"تقول السائلة: يغير بعض الناس أماكنهم بعد الانتهاء من الصلاة لأداء السنة زعمًا منهم أن المكان سيشهد لهم يوم القيامة؟","title":"حكم تحول المصلي عن مكانه لأداء السنة","answer":"الجواب: هذا أفضل إذا تيسر، وإلا ما هو بلازم، إن تيسر وإلا فما هو بلازم، إذا صلى في مكانه فلا بأس، الحمد لله، ليس فيه سنة ثابتة كونه يغير المكان، لكن إذا تحول عن مكانه فلا حرج في ذلك، نعم. المقدم: جزاكم الله خيرًا يا شيخ.","link":"https://binbaz.org.sa/fatwas/13499/حكم-تحول-المصلي-عن-مكانه-لاداء-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_562/56223.mp3","categories":["صلاة التطوع"]},{"id":15012,"question":"أيضًا يقول: إذا دخل الإنسان المسجد والمؤذن يؤذن، هل يمكث حتى يفرغ المؤذن فيصلي تحية المسجد، أم يصليها والمؤذن يؤذن؟","title":"هل تُصلى تحية المسجد والمؤذن يؤذن؟","answer":"الجواب: الأفضل أنه يقف حتى يكمل الأذان؛ لقول النبي ﷺ: إذا سمعتم المؤذن فقولوا مثلما يقول وهذا أمر، وأقل أحواله: التأكد والسنية؛ ولأنه ﷺ كان إذا سمع الأذان أجاب المؤذن، كلمةً كلمة، إلا في الحيعلة فيقول: لا حول ولا قوة إلا بالله وجاء في حديث عمر : أن العبد إذا أجاب المؤذن في كلماته، إلا في الحيعلة يقول: لا حول ولا قوة إلا بالله، ثم يكبر، ثم يقول مثله: لا إله إلا الله، من قلبه، دخل الجنة. وهذا فضل عظيم، ما ينبغي له أن يفوته، فإذا فرغ من إجابة المؤذن، يصلي تحية المسجد، هذا هو الأفضل، وهذا هو السنة، حتى يجمع بين السنتين، سنة الإجابة للمؤذن، وسنة تحية المسجد، نعم.","link":"https://binbaz.org.sa/fatwas/13512/هل-تصلى-تحية-المسجد-والموذن-يوذن","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_652/nour_65203.mp3","categories":["صلاة التطوع"]},{"id":15060,"question":"يقول: نحن في قريتنا ندخل المسجد قبل المغرب، لكني ألاحظ أن الناس لا يصلون تحية المسجد قبل المغرب، فهل هذا صحيح؟","title":"حكم صلاة تحية المسجد قبل المغرب","answer":"الجواب: الصواب شرعية الصلاة ولو كان في العصر، بعض أهل العلم يرى أن أوقات النهي لا تفعل فيها صلاة التحية، والصواب: أنه لا حرج في ذلك؛ لأن النبي ﷺ عمم، قال: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين وفي اللفظ الآخر: فليركع ركعتين قبل أن يجلس وهذا عام لأوقات النهي وغيرها. وهكذا صلاة الكسوف، لو كسفت الشمس بعد العصر شرعت الصلاة؛ لأنها من ذوات الأسباب. وهكذا الطواف لو طاف بعد العصر في مكة شرع له أن يصلي ركعتين، ركعتي الطواف؛ لأنها من ذوات الأسباب، ولقول النبي ﷺ: لا تمنعوا أحدًا طاف بهذا البيت وصلى أية ساعة شاء من ليل أو نهار. فالمقصود: أن تحية المسجد من ذوات الأسباب، وصلاة الكسوف من ذوات الأسباب، وصلاة الطواف من ذوات الأسباب، فإذا دخل المسجد بعد العصر أو بعد الفجر ليسمع العلم أو ليجلس في المسجد ويستريح، فإنه يصلي ركعتين إذا كان طاهرًا، يصلي ركعتين قبل أن يجلس، ولو كان في وقت النهي، هذا هو المعتمد؛ لعموم الأحاديث، وهي مخصصة لأحاديث النهي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13547/حكم-صلاة-تحية-المسجد-قبل-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_493/49314.mp3","categories":["صلاة التطوع"]},{"id":15102,"question":"سؤالها الأخير تقول: هل توجد صلاة لكل يوم وليلة، أي: نوافل؟ وهل كان النبي محمد ﷺ يصليها؟ وهذا السؤال في الحقيقة يتكرر كثيرًا من بعض المستمعين، وخاصة في العراق، وفي جمهورية مصر العربية، ونرجو توضيح ذلك لهم، وفقكم الله.","title":"ما السنن الرواتب والنوافل في اليوم والليلة؟","answer":"الجواب: النبي ﷺ كان يحافظ على ثنتي عشرة ركعة في يومه وليلته -عليه الصلاة والسلام-، يحافظ عليها مع الصلوات اثنتي عشرة ركعة: أربع قبل الظهر، وثنتين بعدها، وثنتين قبل صلاة الصبح، وثنتين بعد المغرب، وثنتين بعد العشاء، هذه اثنتا عشرة ركعة، كان النبي ﷺ يحافظ عليها -عليه الصلاة والسلام- في يومه وليلته، وصح عنه -عليه الصلاة والسلام- أنه قال: من صلى ثنتي عشرة ركعة في يومه وليلته تطوعًا بنى الله له بيتًا في الجنة ثم بينها قال: أربعًا قبل الظهر، وثنتين بعدها، وثنتين بعد المغرب، وثنتين بعد العشاء، وثنتين قبل صلاة الصبح هذه ثنتا عشرة ركعة، كان النبي ﷺ يحافظ عليها في يومه وليلته، مع الصلوات الأربع: الظهر والمغرب والعشاء والفجر، وجاء عنه ﷺ أنه حث على أربع قبل العصر قال: رحم الله امرأً صلى أربعًا قبل العصر. أما التي حافظ عليها -عليه الصلاة والسلام- في الحضر والإقامة، وهي ثنتا عشرة ركعة كما تقدم، وهي: أربع قبل الظهر، وثنتان بعدها، وثنتان بعد المغرب، وثنتان بعد العشاء، وثنتان قبل صلاة الصبح، والأفضل فعلها في البيت، هذا هو الأفضل؛ لقول النبي ﷺ: أفضل صلاة المرء في بيته إلا المكتوبة. وشرع للناس أيضًا -عليه الصلاة والسلام- التهجد والوتر، كان يحافظ عليه التهجد بالليل والوتر بالليل كان يحافظ عليه حتى في السفر، مع سنة الفجر كان يحافظ على هذا في السفر والحضر، الوتر في الليل، وسنة الفجر قبل الفريضة ركعتين، كان يحافظ على ذلك سفرًا وحضرًا.  أما سنة الظهر، سنة المغرب، سنة العشاء فكان يتركها في السفر -عليه الصلاة والسلام-، ويأتي بها في الحضر. ومما شرعه -عليه الصلاة والسلام- للناس سنة الضحى ركعتان فأكثر، ثبت عنه ﷺ أنه أوصى أبا هريرة، وأوصى أبا الدرداء بسنة الضحى، وصيام ثلاثة أيام من كل شهر، والإيتار قبل النوم، وكان أسباب ذلك -والله أعلم- أنهما يشتغلان بالحديث في أول الليل؛ فأوصاهما بالوتر أول الليل، أما من كان يطمع أن يقوم آخر الليل فالوتر من آخر الليل أفضل، كما هو فعله ﷺ، وكما أوصى به النبي ﷺ حيث قال: من خاف أن لا يقوم من آخر الليل فليوتر أوله، ومن طمع أن يقوم آخر الليل فليوتر آخر الليل؛ فإن صلاة آخر الليل مشهودة؛ وذلك أفضل رواه مسلم في الصحيح. فالإيتار في آخر الليل أفضل لمن طمع في ذلك، وقدر عليه، أما من خاف أن لا يقوم من آخر الليل فليوتر في أول الليل، هذا هو الأفضل له، فهذه الأشياء التي كان يحافظ عليها النبي ﷺ ويدعو إليها -عليه الصلاة والسلام- بيناها في جواب السائلة. فينبغي للمسلم أن يحافظ على هذه الأشياء، وأن يعتني بها كما اعتنى بها نبينا ﷺ، وحافظ عليها -عليه الصلاة والسلام-، وحث عليها الأمة، اللهم صل عليه وسلم، نعم.","link":"https://binbaz.org.sa/fatwas/13604/ما-السنن-الرواتب-والنوافل-في-اليوم-والليلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_656/nour_65605.mp3","categories":["صلاة التطوع"]},{"id":15106,"question":"فضيلة الشيخ عبدالعزيز، هذه رسالة وردتنا من المستمعة تقول: أختكم في الله أم كلثوم من العراق، تقول: هل توجد سنة لصلاة العشاء، أي: تؤدى قبل فرض العشاء، أو نؤدي قبل فرض العشاء ركعتين؟","title":"هل توجد سنة قبل صلاة العشاء؟","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فإنه يشرع قبل كل صلاة ركعتان: قبل العشاء، قبل المغرب، قبل العصر، قبل الظهر، قبل صلاة الفجر، يقول النبي ﷺ: صلوا قبل المغرب، صلوا قبل المغرب ثم قال في الثالثة: لمن شاء فدل على سنية الصلاة قبل المغرب ركعتين، وكان الصحابة يصلوا ركعتين قبل المغرب، يعني: بعد الأذان وقبل الإقامة ركعتين، هذا هو الأفضل، وهكذا العشاء إذا أذن المؤذن يصلي ركعتين؛ لقول النبي ﷺ: بين كل أذانين صلاة، بين كل أذانين صلاة وبين الأذانين صلاة بينها النبي ﷺ ينتظر فيها العشاء، فإذا أذن العشاء شرع للجالسين في المسجد أو الوافدين أن يصلوا ركعتين سنة قبل العشاء في حق المقيمين في المسجد، وسنة لمن دخل تحية المسجد، وفعل هذه السنة بين الأذانين يجمع بين الصلاة بين الأذانين وبين كونه أدى التحية.  وهكذا الظهر إذا دخل إذا كان جالسًا في المسجد وأذن يقوم يصلي ركعتين أو أربع، وهو أفضل، أربع ركعات أفضل في الظهر، تقول عائشة -رضي الله عنها-: \"كان النبي ﷺ لا يدع أربعًا قبل الظهر\" بعد دخول الوقت، يعني: أربع ركعات بـتسليمتين، وهكذا قبل العصر أربع ركعات، يقول النبي ﷺ: رحم الله امرأً صلى أربعًا قبل العصر وإن صلى ركعتين قبل العصر فحسن للحديث السابق: بين كل أذانين صلاة وإن جعلها أربعًا فهو أفضل للحديث السابق أيضًا: رحم الله امرأً صلى أربعًا قبل العصر. \nفهذه سنن قبل هذه الصلوات: قبل الظهر ثنتان، أو أربع، وهو أفضل أربع، قبل العصر أربع، وإن صلى ركعتين كفى أيضًا، قبل المغرب ركعتان، قبل العشاء ركعتان، كل هذه سنن، قبل الفجر ركعتان أيضًا سنة راتبة قبل الفجر، نعم. المقدم: لكن الإقامة هل تعتبر أذان يا شيخ؟ الشيخ: نعم تسمى أذان؛ لقول النبي ﷺ: بين كل أذانين صلاة سماها أذان -عليه الصلاة والسلام-، نعم. المقدم: إذن إذا كانت تعتبر الإقامة أذان؛ فالرسول ﷺ أمرنا أن نقول مثل ما يقول المؤذن، وطبعًا نقول مثل ما يقول المقيم؟\nالشيخ: نعم. المقدم: لكن كثير من الناس إذا أقيمت الصلاة قال: اللهم أقمها وأدمها، أقامها الله وأدامها، ويأتون بـغير إجابة.\nالشيخ: الأفضل أن يجيبوا المقيم كالمؤذن، يكبروا معه، ويتشهدوا معه، وإذا جاء: حي على الصلاة، يقول: لا حول ولا قوة إلا بالله، إذا قال: قد قامت الصلاة، يقول: قد قامت الصلاة، قد قامت الصلاة، مثله مثل المقيم، الله أكبر، الله أكبر، لا إله إلا الله، ثم يأتي بعد هذا بالصلاة على النبي ﷺ، ثم بقوله: اللهم رب هذه الدعوة التامة، كالأذان سواء.\nالمقدم: كالأذان سواء. الشيخ: هذا هو الأفضل، أما قول بعض الناس: أقامها الله وأدامها، أو اللهم أقمها وأدمها، هذا لم يصح عن النبي ﷺ، جاء في حديث ضعيف لا يصح، فالسنة والأولى أن يفعلوا في الأذان والإقامة مثل ما يفعلوا في الأذان، سواءً بسواء، إلا عند الإقامة يقول: قد قامت الصلاة مثل المؤذن، مثل ما يقول في أذان الفجر: الصلاة خير من النوم، الصلاة خير من النوم، مثل المؤذن سواء، نعم؛ لأنه  قال: إذا سمعتم المؤذن فقولوا مثل ما يقول اللهم صل عليه وسلم، نعم.\nالمقدم: كثير من الناس إذا سمع مؤذن الفجر يقول: الصلاة خير من النوم، يقول: حقًا الصلاة خير من النوم، فيزيد حقًا؟\nالشيخ: لا، ما لها أصل. المقدم: ما لها أصل. الشيخ: بعضهم يقول: صدق الله ورسوله، بعضهم يقول: صدقت وبررت، والصواب أن يقول مثل المؤذن سواء: الصلاة خير من النوم، ولا يزيد شيئًا، هذا هو الأفضل؛ عملًا بقوله ﷺ: إذا سمعتم المؤذن فقولوا مثل ما يقول اللهم صل عليه وسلم، نعم.","link":"https://binbaz.org.sa/fatwas/13596/هل-توجد-سنة-قبل-صلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_656/nour_65601.mp3","categories":["صلاة التطوع"]},{"id":15168,"question":"متى يقرأ الشخص دعاء الاستخارة في صلاته؟ هل عندما ينتهي من التشهد قبل التسليم، أو أن ذلك من الممكن أن يكون بعد التسليم؟","title":"موضع دعاء الاستخارة","answer":"الجواب: دعاء الاستخارة يكون بعد التسليم، يشرع له أن يصلي ركعتين، وبعد التسليم يرفع يديه ويدعو ويستخير، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13662/موضع-دعاء-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56418.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":15174,"question":"متى يقرأ الشخص دعاء الاستخارة في صلاته؟ هل عندما ينتهي من التشهد قبل التسليم، أو أن ذلك من الممكن أن يكون بعد التسليم؟","title":"موضع دعاء الاستخارة","answer":"الجواب: دعاء الاستخارة يكون بعد التسليم، يشرع له أن يصلي ركعتين، وبعد التسليم يرفع يديه ويدعو ويستخير، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13662/موضع-دعاء-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56418.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":15183,"question":"أيضاً يسأل أو في سؤاله الأخير يقول: أيهما أفضل سنة المغرب هل هي في المنزل أم في المسجد؟","title":"هل الأفضل صلاة جميع النوافل في البيت؟","answer":"الجواب: الأفضل في المنزل، هذا هو الأفضل سنة المغرب، سنة العشاء، سنة الفجر يتأكد فعلها في البيت، كان النبي يفعلها في البيت -عليه الصلاة والسلام-، وهكذا سنة الظهر الأفضل فعلها في البيت أيضًا، وهكذا جميع التطوعات فعلها في البيت أفضل؛ لقول النبي ﷺ: أفضل صلاة المرء في بيته إلا المكتوبة هكذا قال -عليه الصلاة والسلام- في الصحيحين. المقدم: شكرًا، أثابكم الله.","link":"https://binbaz.org.sa/fatwas/13691/هل-الافضل-صلاة-جميع-النوافل-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_666/nour_66606.mp3","categories":["صلاة التطوع"]},{"id":15197,"question":"وردتنا رسالة من سوريا، محافظة حلب، من المستمع علي السعيد، يقول فيها: صلاة سنة العشاء والعصر والظهر أربع ركعات، شاهدت بعض الناس في المسجد يصلون سنة العشاء والعصر والظهر أربع ركعات أولًا يصلون ركعتين، ثم يتمون ويسلمون ويمشون خطوة نحو اليمين أو اليسار، أو الخلف ويصلون الركعتين الباقيتين، هل هذه الصلاة صحيحة وكان الرسول ﷺ يفعلها أم لا؟","title":"عدد السنن الرواتب وحكم تغيير المكان بين كل ركعتين","answer":"الجواب: أما الظهر فقد ثبت عن عائشة -رضي الله عنها- أنها قالت: \"كان النبي ﷺ لا يدع أربعًا قبل الظهر\" رواه البخاري في الصحيح، وجاء أيضًا في حديث أم حبيبة أم المؤمنين -رضي الله عنها- عند الترمذي أنه ذكر -عليه الصلاة والسلام- من صلى ثنتي عشر ركعة في اليوم والليلة، وذكر منها أربعًا قبل الظهر، فأربع قبل الظهر مستحبة، والأفضل أن تكون ركعتين ركعتين؛ للحديث الصحيح: صلاة الليل والنهار مثنى مثنى. أما التقدم والتأخر، عن اليمين والشمال، فهذا جاء في بعض الأحاديث الضعيفة، ولا أعلم في الباب ما يدل على السنية، وإنما جاء في بعض الأحاديث الضعيفة أن يتقدم أو يتأخر، أو يأخذ يمينه أو شماله، قال بعض أهل العلم: لأجل شهادة البقاع بهذه العبادة، ولكن لا أعلم أنه ثبت في هذا شيء عن النبي -عليه الصلاة والسلام-، فإذا صلى الراتبة والعبادة في محل واحد فلا بأس بهذا، ولا أعلم دليلًا يدل على استحباب التحول من مكانه للركعتين الأخريين، لا عن يمين ولا عن شمال، ولا أمام ولا خلف، فإن فعل فلا حرج إن فعل فلا حرج، ولا أعلم بأسًا في ذلك، لكن لا أعلم دليلًا يدل على أن هذا مستحب وأنه قربة. وهكذا الصلوات الأخرى إذا صلى أربعًا قبل العصر فهي سنة؛ لأنه ثبت عنه  أنه قال: رحم الله امرأ صلى أربعًا قبل العصر خرجه أحمد -رحمه الله- والترمذي وجماعة، ولا بأس بإسناده. أما المغرب فالسنة بعدها ركعتان فقط، هذا السنة، كان النبي ﷺ يصلي بعدها ركعتين، وهكذا العشاء السنة بعدها ركعتين راتبة، ومن صلى زيادة فلا بأس، من صلى كثيرًا بعد المغرب فهي محل صلاة، لو صلى عشرًا أو عشرين أو أكثر لا حرج في ذلك، لكن السنة الراتبة التي كان يحافظ عليها النبي ﷺ ركعتان فقط بعد المغرب، وركعتان بعد العشاء، هذا المحفوظ عنه -عليه الصلاة والسلام- والذي كان يحافظ عليه. وهكذا الفجر ركعتان قبل الفجر، كان يركعهما في بيته، ثم يخرج إلى الصلاة -عليه الصلاة والسلام-، وقد ثبت عنه -عليه الصلاة والسلام- أنه قال: من صلى ثنتي عشرة ركعة في يوم وليلة تطوعًا، بنى الله له بيتًا في الجنة رواه مسلم في الصحيح، ورواه الترمذي وزاد: أربعًا قبل الظهر، وثنتين بعدها، وثنتين بعد المغرب، وثنتين بعد العشاء، وثنتين قبل صلاة الصبح وهذه تسمى: الرواتب، رواها ابن عمر عشرًا، وذكر قبل الظهر ركعتين، وذكرت عائشة وغيرها ما يدل على أنها ثنتا عشرة ركعة، وأن قبل الظهر أربع، وبهذا تكون الرواتب ثنتي عشر ركعة. ولعل وجه الجمع بين الحديثين: أنه ﷺ كان ربما صلى قبل الظهر ركعتين، كما قال ابن عمر فتكون الرواتب عشرًا، وربما صلى قبلها أربعًا كما قالت عائشة وغيرها فلا منافاة بين الحديثين، ولا خلف في الحقيقة. المقدم: شكرًا، أثابكم الله.","link":"https://binbaz.org.sa/fatwas/13703/عدد-السنن-الرواتب-وحكم-تغيير-المكان-بين-كل-ركعتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_667/nour_66703.mp3","categories":["صلاة التطوع"]},{"id":15207,"question":"سماحة الشيخ هذا سائل للبرنامج يقول: إذا أقيمت صلاة الفريضة وأنا أصلي التطوع، هل أقطع التطوع بسلام أو من غير سلام؟","title":"كيف يكون قطع النافلة عند إقامة الصلاة؟","answer":"الجواب: ما يحتاج سلام تقطعه وبس؛ لقول النبي ﷺ: إذا أقيمت الصلاة فلا صلاة إلا المكتوبة رواه مسلم في الصحيح، إذا أقيمت الصلاة فلا صلاة إلا المكتوبة هكذا قال ﷺ، فإذا أقيمت بطلت الصلاة التي أنت فيها، وعليك أن تدخل مع الإمام، إلا إن كنت في آخرها في السجود أو التحيات تكملها؛ لأنها انتهت، أما إذا كان بقي عليك ركعة اقطعها بالنية، ويكفي.","link":"https://binbaz.org.sa/fatwas/13704/كيف-يكون-قطع-النافلة-عند-اقامة-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56425.mp3","categories":["صلاة التطوع"]},{"id":15220,"question":"نبدأ أولًا برسالة عبدالله بن صالح العبدالله، الذي يسأل عن صلاة الضحى من القصيم، بريدة، يقول: ما حكم صلاة الضحى؟ فقد سألت عنها شخصيًا أكثر من طالب علم، فأجابوني بعدة إجابات مختلفة، فمنهم من قال: إن الأحاديث التي وردت فيها غير صحيحة فتترك، ومنهم من قال: بل تصلى، ومنهم من قال: يصليها من شاء متى شاء بالعدد الذي يريد، ومنهم من قال: تصلى يومًا وتترك يومًا؛ لذا لجأت إلى برنامج نور على الدرب.أرجو أن ينير الله لنا الطريق، وأرجو أيضًا أن لا ألتمس الإجابة من غيره، وفقكم الله، وبارك في أعماركم.","title":"حكم صلاة الضحى وعدد ركعاتها","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، والصلاة والسلام على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: صلاة الضحى سنة مؤكدة، وأقلها ركعتان، وأفضلها ثمان، وإن زاد فلا بأس، لو صلى عشرًا، أو ثنتي عشرة، أو أكثر من ذلك فلا بأس، وقد ثبت عنه ﷺ أنه صلاها ثمان ركعات يوم الفتح، وثبت عنه ﷺ أنه أوصى بذلك أبا الدرداء وأبا هريرة، فقد جاء في الصحيح عن النبي ﷺ \"أنه أوصى أبا هريرة وأبا الدرداء بثلاث: صلاة الضحى، وصيام ثلاثة أيام من كل شهر، والوتر قبل النوم\". وثبت أيضًا في الصحيح من حديث أبي ذر  أن النبي ﷺ لما سئل عن صدقة أهل الدثور أهل الأموال وأنهم سبقوا بالصدقة من أموالهم قال: أوليس قد جعل الله لكم ما تصدقون به؟ إن لكم بكل تسبيحة صدقة، وبكل تهليلة صدقة، وبكل تحميدة صدقة، وبكل تكبيرة صدقة، وأمر بالمعروف صدقة، ونهي عن المنكر صدقة إلى أن قال: ويكفي من ذلك ركعتان يركعهما من الضحى. هذا يدل على أن ركعتين من الضحى تقوم مقام هذه الصدقات التي يشرع للمؤمن أن يدفعها عن مفاصله وأعضائه، فدل ذلك على تأكدها، وأنها صلاة عظيمة مؤكدة فيها خير عظيم. ويستحب فعلها كل يوم، قال بعض السلف: إنها تفعل يومًا بعد يوم، ولكن الصواب: أنها تفعل كل يوم؛ لأن الرسول ﷺ أوصى بها، الرسول ﷺ أوصى بها، وحث عليها، فدل ذلك على أنها سنة، كل يوم إذا تيسر ذلك، ولكنها غير واجبة من تركها بعض الأيام فلا بأس، ولو تركها دائمًا فلا بأس؛ لأنها سنة مؤكدة مثل الوتر، ومثل رواتب الفريضة، مثل سنة الظهر والمغرب والعشاء والفجر كلها سنن كلها نوافل، لو تركها العبد لا إثم عليه. لكن الأفضل والأولى أن يحافظ عليها، وأن يعتني بها؛ لأن فيها أجرًا عظيمًا؛ ولأنها تكمل بها الفرائض، وصلاة الضحى من ذلك فهي سنة مؤكدة في جميع الأوقات. أما كون النبي ﷺ ما كان يحافظ عليها؛ فلعله فعل ذلك لئلا يشق على أمته؛ لأنه لو حافظ عليها لازداد تأكدها وربما شق على بعض الناس ذلك؛ ولمشاغله الكثيرة -عليه الصلاة والسلام-؛ ولأن السنة لها وجوه ثلاثة: سنة تثبت بالقول، وتثبت بالفعل، وتثبت بالتقرير، فالنبي ﷺ فعلها، وأقر عليها، وأوصى بها -عليه الصلاة والسلام-، كل هذا فعله -عليه الصلاة والسلام-، فعلها في يوم الفتح، وفعلها في أوقات أخرى، قالت عائشة -رضي الله عنها-: \"كان النبي ﷺ يصلي الضحى أربعًا ويزيد ما شاء الله\" رواه مسلم، وفعلها الصحابة  وأرضاهم، فدل ذلك على أنها سنة مؤكدة، أقر عليها، وأوصى بها، وفعلها -عليه الصلاة والسلام-، نعم.","link":"https://binbaz.org.sa/fatwas/13715/حكم-صلاة-الضحى-وعدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_668/nour_66801.mp3","categories":["صلاة التطوع"]},{"id":15231,"question":"المستمع (أ. خ) من السودان بعث يسأل ويقول: إذا رغبت في الزواج من امرأة، فهل لي أن أستخير الله في شأنها في الحال. علماً بأني سأؤخر هذا الزواج لعدة سنوات؛ لعدم استطاعتي عليه حاليًا؛ لأني أريد أن أتقدم لهم ببعض الهدايا إلى حين أن أتقدم لزواجها؟ ثم ما هي كيفية انشراح الصدر التي وردت في شرح دعاء الاستخارة؟","title":"ما الذي تُشرع فيه الاستخارة؟","answer":"الجواب:  إذا أردت أن تتزوج من امرأة وأنت مطمئن إليها، تعرف فضلها ودينها وخلقها، وأنك لست في شك منها، فلا حاجة للاستخارة، الاستخارة في الشيء الذي تشك فيه، إذا كنت تشك في صلاحها لك تستخير الله، فإذا صليت الركعتين، ورفعت يديك، وطلبت الله بدعاء الاستخارة، ثم انشرح صدرك فاستقم، وبادر إلى خطبتها، ولو تأخر الدخول بها اخطبها، واتفق مع أهلها، ولو تأخر العقد أو الدخول. أما إذا كنت منشرح الصدر، عارف قد عرفتها تمام المعرفة ليس عندك شك في أمرها، فلا يظهر هناك حاجة للاستخارة؛ لأن الاستخارة إنما تفعل في الأمور التي قد يقع فيها اشتباه، أو يخشى من عاقبتها.  أما الشيء الواضح الذي ما فيه اشتباه، ليس فيه استخارة، لا تستخير الله تصلي الضحى ركعتين لا، صل ولا تحتاج استخارة، تزور أقاربك الطيبين، وصلة الرحم، ما فيه استخارة، إذا كان ما عندهم محذور، تبر والديك ما فيه استخارة، تصلي الظهر ما فيها استخارة، العصر ما فيها استخارة المغرب ما فيه استخارة، العشاء ما فيه استخارة، الفجر ما فيها استخارة، الجمعة كل هذه ما فيها استخارة، تحج والطريق آمن، وأنت قادر ما فيه استخارة، أما إذا كان الطريق غير آمن، تخاف، تستخير الله، هل تحج هذا العام من أجل خوف الطريق؟ ما هو من أجل الحج. فالمقصود: الاستخارة في الشيء الذي فيه أدنى اشتباه، أما الشيء الواضح الذي ما فيه اشتباه، وأنت قادر عليه، وهو خير محض، فليس فيه استخارة، مثلما أنك ما تستخير، هل نتغدى أو ما تتغدى؟ تتعشى أو ما تتعشى؟ هل تجامع زوجتك؟ ما فيه استخارة؛ لأنها أمور معروفة مصلحتها، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13734/ما-الذي-تشرع-فيه-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_497/49704.mp3","categories":["صلاة التطوع"]},{"id":15240,"question":"فضيلة الشيخ عبدالعزيز، لدينا رسالة بعث بها كل من الطالب حامد شرف محمد، وسلطان عيسى بدري ومحمد يوسف صائغ، والأستاذ عثمان عثمان السبيعي، والأستاذ رشاد (ق. م).كل هؤلاء يقولون: نرجو عرض رسالتنا هذه على فضيلة الشيخ عبدالعزيز بن عبدالله بن باز إن تمكن ذلك.نقول: نعم يتمكن ونحن الآن نعرضها.يسألون عن صلاة التسبيح، يقولون: ما حكم صلاة التسبيح، حيث أننا قد قرأنا في مجلة مدرسية مقالًا يقول كاتبه باختصار: أيها القارئ الكريم، ألق سمعك وأنت شاهد؛ لما قال ﷺ لعمه العباس وابن عمه جعفر -رضي الله عنهما- عن عكرمة  عن ابن عباس -رضي الله عنهما- قال: قال رسول الله ﷺ للعباس بن عبد المطلب: «يا عماه، ألا أعطيك، ألا أمنحك، ألا أحبوك، ألا أفعل بك عشر خصال، إذا أنت فعلت ذلك غفر الله لك ذنبك، أوله وآخره، وقديمه وحديثه، وخطأه وعمده، وصغيره وكبيره، وسره وعلانيته، عشر خصال: أن تصلي أربع ركعات تقرأ في كل ركعة فاتحة الكتاب وسورة، فإذا فرغت من القراءة في أول ركعة فقل وأنت قائم: سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر، خمس عشرة مرة، ثم اركع وقل وأنت راكع عشرًا، ثم ترفع رأسك من الركوع فتقول عشرًا، ثم تهوي ساجدًا فتقولها عشرًا، ثم ترفع رأسك من السجود فتقولها عشرًا، ثم تسجد فتقولها عشرًا، ثم ترفع رأسك من السجود فتقولها عشرًا، فذلك خمس وسبعون في كل ركعة، تفعل ذلك في كل أربع ركعات، فإن استطعت أن تفعلها في كل يوم مرة فافعل، فإن لم تستطع ففي كل جمعة مرة، فإن لم تستطع ففي كل شهر مرة، فإن لم تستطع ففي كل سنة مرة، فإن لم تستطع ففي عمرك مرة» وقالوا: رواه أبو داود، أو قال الكاتب: رواه أبو داود وابن ماجه وابن خزيمة، وإبراهيم بن الحكم، والطبراني، وقال: «تغفر ذنوبك وإن كانت مثل رمل عالج، وعدد زبد البحر» ويقول الكاتب: إذا علمنا صحة هذا الحديث، فعلينا عدم تركها، بل علينا أن نفعل بها ولو مرة واحدة في العمر، ويقول أيضًا الكاتب: وقد فعلت أنا هذه الصلاة عدة مرات، فوجدت من الفرح ولذة المناجاة، وطمأنينة النفس، وانشراح الصدر، ما لا أقدر، ولا أتمكن من التعبير عنه، فجرب -يا أخي- تجد -إن شاء الله- ما وجدت، وما عند الله خير وأبقى.نرجو توضيح هذه الصلاة، وصحة حديثها، وموقف المسلمين منها، وقد ضاعت. علمًا أنها بدأت تنتشر بين الأوساط في مجتمعنا في المملكة، بفضل هذا الكاتب الذي أحياها، وفقه الله، وشكرًا لكم.","title":"حكم صلاة التسبيح والحديث المروي فيها","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، والصلاة والسلام على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فهذه الصلاة المنوه عنها في هذا السؤال قد اختلف أهل العلم في صحة حديثها على قولين، والأرجح في ذلك أنه غير صحيح، وأنه موضوع، وليس صحيحًا عن النبي -عليه الصلاة والسلام- هذا هو المعتمد في هذه الصلاة، وجميع الأحاديث الثابتة عن رسول الله -عليه الصلاة والسلام- في بيان صلاة التطوع، والحث عليها، والترغيب فيها، كلها تخالف ما جاء في هذا الحديث، وتدل على أنه منكر، وليس له صحة، هذا هو المعتمد عند المحققين من أهل العلم. والنبي ﷺ لم يحفظ عنه ولا مرة واحدة أنه فعلها -عليه الصلاة والسلام-، ولم تحفظ أيضًا عن بقية الصحابة  وأرضاهم، ولو كان النبي ﷺ قال هذا لانتشرت هذه الصلاة بين الصحابة  وأرضاهم؛ ولعرفها الصحابة ورووها. فالمقصود: أن هذه الرواية عند المحققين من أهل العلم غير صحيحة، وحديثها موضوع، كما نبه على ذلك جماعة من أهل العلم، ولنا عودة -إن شاء الله- في هذه المسألة في ليلة آتية نشرح فيها كل شيء عما يتعلق بهذه الصلاة.\nالمقدم: -إن شاء الله-. الشيخ: -إن شاء الله-، نعم.","link":"https://binbaz.org.sa/fatwas/13737/حكم-صلاة-التسبيح-والحديث-المروي-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_669/nour_66901.mp3","categories":["صلاة التطوع","الحكم على الأحاديث"]},{"id":15326,"question":"يقول أيضًا: صلاة التطوع إذا اعتاد عليها الإنسان هل تكون واجبة؟","title":"هل تجب صلاة التطوع على من اعتادها؟","answer":"الجواب: لا، ما تكون واجبة، التطوع يكون دائمًا تطوع، لا يكون واجبًا أبدًا، لكن نفس الحج والعمرة إذا أحرم بهما وجبتا؛ لقول الله تعالى: وَأَتِمُّوا الْحَجَّ وَالْعُمْرَةَ لِلَّهِ [البقرة:196] هذا شيء خاص بالحج والعمرة متى أحرم بهما وجبا حتى يكملهما، وأما ما سواهما كالصلاة والصوم والصدقة ونحو ذلك هذه التطوعات تبقى على حالها تطوعًا، فلو شرع في الصلاة جاز له قطعها، أو شرع في الصوم نافلة جاز له قطعه، ولكن الأفضل أن يتمم ويكمل، ولو أخرج مالًا ليتصدق جاز له أن يرجع حتى يسلم ذلك للفقير. فالمقصود: أن جميع النوافل على حالها في تطوع حتى ينتهي منها إلا الحج والعمرة، فإنهما إذا شرع فيهما وجبا حتى يكملهما، نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13839/هل-تجب-صلاة-التطوع-على-من-اعتادها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_677/nour_67709.mp3","categories":["صلاة التطوع"]},{"id":15537,"question":"يقول السائل: يا سماحة الشيخ، هل يجوز أن نؤخر سنة العشاء البعدية إلى ما بعد الصلاة بساعتين أو ثلاث؟","title":"حكم تأخير سنة العشاء","answer":"الجواب: لا بأس أن تؤخرها قبل نصف الليل، الأفضل أن تؤديها قبل نصف الليل؛ لأن وقت العشاء إلى نصف الليل، نعم.","link":"https://binbaz.org.sa/fatwas/14084/حكم-تاخير-سنة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69120.mp3","categories":["صلاة التطوع"]},{"id":15539,"question":"السائل: (ش. ش) يقول سماحة الشيخ، حفظكم الله: كيف كان يصلي رسول الله ﷺ سنة الفجر؟ هل هو بعد سماع المؤذن؟","title":"متى كان النبي ﷺ يصلي سنة الفجر؟","answer":"الجواب: كان إذا طلع الفجر، إذا أذن المؤذن، وتحقق طلوع الفجر صلاها، يصليها بعد الأذان  في بيته، ثم يأتي فتقام الصلاة -عليه الصلاة والسلام-، يصلي ركعتي الفجر، ويضطجع بعدها على جنبه الأيمن بعض الشيء، ثم يتوجه للصلاة -عليه الصلاة والسلام-، ويقول: إن بلالًا يؤذن بليل، فكلوا واشربوا حتى يؤذن ابن أم مكتوم كان إذا طلع الفجر، وأذن المؤذن صلى ركعتين -عليه الصلاة والسلام- خفيفتين، ثم يضطجع بعدها ضجعة خفيفة، ثم يتوجه إلى المسجد -عليه الصلاة والسلام-، نعم.","link":"https://binbaz.org.sa/fatwas/14080/متى-كان-النبي-ﷺ-يصلي-سنة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69118.mp3","categories":["صلاة التطوع"]},{"id":15553,"question":"السائلة أم عبدالله من الرس تقول: بالنسبة لصلاة الفجر يا سماحة الشيخ، تفوتني حتى يخرج الناس من المسجد بسبب النوم، وأترك السنة، وأصلي السنة مع صلاة الضحى، فهل يصح ذلك، أم الأحسن أن أصلي السنة مع الفرض حتى لو تأخرت الصلاة؟","title":"وقت سنة الفجر لمن تأخر عن أداء الفريضة","answer":"الجواب: نعم، السنة أن تصلي ركعتين قبل الفرض، ولو تأخرت، ولو صليت بعد الناس قبل طلوع الشمس، كان النبي ﷺ يصليها ولو نام عنها، لو نام عن الصبح، في بعض أسفاره نام فلم يستيقظوا إلا بعد طلوع الشمس، فلما استيقظوا أمر بالأذان، وأذن المؤذن، وصلوا الركعتين -سنة الفجر- ثم صلى الفريضة، فإذا استيقظت وتوضأت صلي السنة ركعتين، ثم صلي الفريضة، قبل طلوع الشمس، نعم.","link":"https://binbaz.org.sa/fatwas/14090/وقت-سنة-الفجر-لمن-تاخر-عن-اداء-الفريضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69126.mp3","categories":["صلاة التطوع"]},{"id":15560,"question":"تقول السائلة أختكم أم عبدالرزاق: أسمع عن وقت الزوال يا سماحة الشيخ، فما هو هذا الوقت؟ وهل صحيح أن صلاة الضحى اثنا عشر ركعة وإن وقت صلاة الضحى إلى قبل صلاة الظهر بربع ساعة؟","title":"بيان وقت الزوال والضحى وعدد ركعاتها","answer":"الجواب: الزوال ميل الشمس إلى جهة الغرب، الشمس تسير من المشرق إلى المغرب، فإذا زالت إلى جهة المغرب، هذا هو الزوال، وإذا توسطت هذا هو الوقوف، وقت النهي، وإذا زالت إلى جهة الغروب قليلًا هذا الزوال، دخول وقت الظهر. وصلاة الضحى أقلها ركعتان، وليس لأكثرها حد، أقلها ركعتان، وإذا صلى ستًا أو ثمان أو عشر أو اثنا عشر أو عشرين، فلا بأس، ما بين وقوف الشمس وارتفاعها، إذا ارتفعت الشمس بعد طلوعها إلى وقوفها كله ضحى، وصلاة الضحى ركعتان، أو أربع، أو ست أو ثمان، الأمر فيه واسع، الحمد لله، النبي ﷺ أوصى أبا هريرة وأبا الدرداء بركعتي الضحى، وصلى يوم الفتح صلاة الضحى ثمان ركعات -عليه الصلاة والسلام-.","link":"https://binbaz.org.sa/fatwas/14104/بيان-وقت-الزوال-والضحى-وعدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_691/nour_69133.mp3","categories":["صلاة التطوع"]},{"id":15672,"question":"صلاة سنة الفجر إذا فاتت، متى يكون قضاؤها، وكذلك الوتر؟","title":"وقت قضاء سنة الفجر","answer":"الجواب: سنة الفجر إذا فاتت صلاها بعد الفجر في المسجد أو في البيت، وإن أجلها إلى طلوع الشمس وارتفاعها كان أفضل، كل هذا جاءت به السنة عن النبي ﷺ، فإن صلاها بعد الصلاة في المسجد أو البيت فلا بأس، وإن أخرها حتى تطلع الشمس وصلاها في المسجد أو في البيت فلا بأس، كله طيب كله، جاءت به السنة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14216/وقت-قضاء-سنة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_706/nour_70603.mp3","categories":["صلاة التطوع","قضاء الفوائت"]},{"id":15708,"question":"تقول السائلة أم سليمان: بالنسبة لصلاة الفجر، سماحة الشيخ، عندما يستيقظ الشخص قبل شروق الشمس بدقائق، فهل يصلي الفريضة أولًا أم يصلي النافلة أولًا؟","title":"مىى تُصلى راتبة الفجر لمن استيقظ متأخرًا؟","answer":"الجواب: المشروع له أن يصلي النافلة أولًا، ولو عند طلوع الشمس، يصلي ركعتين، ثم يصلي الفريضة، هذه السنة؛ ولما نام النبي ﷺ وأصحابه في بعض أسفاره أمر بالأذان، ثم أذنوا، ثم صلى الراتبة، ثم أقام، وصلى الفريضة. المقصود: أن السنة أن يصلي الراتبة قبل الفريضة، ولو كان قد تأخر بالنوم، في الفجر وغير الفجر، نعم.","link":"https://binbaz.org.sa/fatwas/14266/مىى-تصلى-راتبة-الفجر-لمن-استيقظ-متاخرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57317.mp3","categories":["صلاة التطوع"]},{"id":15723,"question":"هل المشروع أن أرفع يدي أثناء الاستخارة؟","title":"حكم رفع الأيدي في دعاء الاستخارة","answer":"الجواب: نعم؛ إذا صلى ركعتين يرفع يديه، ويدعو، هذا هو الأفضل؛ لأن رفع اليدين من أسباب الإجابة. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/14282/حكم-رفع-الايدي-في-دعاء-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_574/57411.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":15742,"question":"من أسئلة هذا السائل سماحة الشيخ من الأردن يقول: هناك أناس يصلون بعد سنة المغرب ست ركعات، اثنتين اثنتين، ويقولون: بأنها صلاة الأوابين، فما حكمها؟","title":"حكم صلاة ست ركعات بعد المغرب","answer":"الجواب: هذه ليس لها أصل، يسمونها مؤنسات أيضًا، وليس لها أصل، صلاة الأوابين: صلاة الضحى إذا اشتد الضحى، سماها النبي ﷺ صلاة الأوابين صلاة الضحى إذا اشتد الضحى. وأما الصلاة بعد المغرب: إذا صلى ستًّا أو عشرًا أو عشرين، يسلم من كل ثنتين، كله طيب، يقول النبي ﷺ: صلاة الليل مثنى مثنى فإذا أحب أن يصلي بعد سنة المغرب أربع ركعات، تسليمتين أو ست ركعات ثلاث تسليمات أو ثمان ركعات أربع تسليمات، أو أكثر؛ ما في شيء.  لكن تخصيص ست يرى أنها خاصة: لا أصل لها، ويسميها بعضهم المؤنسات، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14325/حكم-صلاة-ست-ركعات-بعد-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_575/57505.mp3","categories":["صلاة التطوع"]},{"id":15746,"question":"بعد هذا رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات، تقول المرسلة (م. م. م) أختنا لها عدد من الأسئلة في أحدها تقول: قرأت في كتاب (زاد المعاد في هدي خير العباد) أن سنة الضحى مختلف عليها، هل هي سنة أم لا؟ وقال بعضهم: إنها بدعة، فما هو الأرجح؟جزاكم الله خيرًا، وهل الأفضل أن تصلى كل يوم، أم في يوم بعد يوم؟جزاكم الله خيرًا.","title":"صلاة الضحى سنة مؤكدة","answer":"الجواب: صلاة الضحى سنة مؤكدة، وقد أوصى بها النبي ﷺ أبا هريرة، وأبا الدرداء، وصلاها ﷺ في بعض الأحيان، وتقول عائشة -رضي الله عنها-: \"كان ﷺ يصلي الضحى أربعًا، ويزيد ما شاء الله\" رواه مسلم في الصحيح، وصلاها يوم الفتح ضحى ثمان ركعات، يسلم من كل ثنتين -عليه الصلاة والسلام-، وقال -عليه الصلاة والسلام-: يصبح على كل سلامى من الناس صدقة والسلامى: المفصل، يصبح على كل سلامى من الناس صدقة، فكل تسبيحة صدقة، وكل تحميدة صدقة، وكل تكبيرة صدقة، وكل تهليلة صدقة، والأمر بالمعروف صدقة، والنهي عن المنكر صدقة، ويكفي من ذلك ركعتان تركعهما من الضحى هذا فضل عظيم، ركعتان من الضحى تؤديان هذه الصدقات. فصلاة الضحى سنة مؤكدة كل يوم، ومن قال: إنها بدعة أو لا تفعل إلا بعض الأحيان فقد غلط، الصواب: أنها سنة تفعل في البيت أفضل، ركعتان، أقلها ركعتان، ولو صلى أربعًا، أو ستًا، أو ثمانًا، أو أكثر، فكله طيب، لكن أقلها ركعتان، وإن زاد وسلم من كل ثنتين؛ فهذا خير؛ ولهذا ثبت عنه ﷺ أنه صلاها أربع ركعات، وصلاها ثمان ركعات، يسلم من كل ثنتين -عليه الصلاة والسلام-. فالمشروع للمؤمن والمؤمنة المحافظة على صلاة الضحى، هذا هو السنة، وأقل ذلك ركعتان، نعم. والأفضل عند شدة الضحى؛ لقوله ﷺ: صلاة الأوابين إذا رمضت الفصال الأوابين يعني: الرجاعين إلى الله، أهل العبادة، صلاتهم عند شدة الضحى، عند ارتفاع الضحى، إذا اشتد حر الأرض على فصال الإبل، يعني: أولاد الإبل، صلاة الأوابين إذا رمضت الفصال يعني: قبل الظهر بساعتين، بساعة ونصف، ثلاث ساعات، هذا هو الأفضل، وأول وقتها عند ارتفاع الشمس، فإذا صلاها بعد ارتفاع الشمس حصل المقصود، وإذا صلاها إذا رمضت الفصال؛ فهذا أفضل، وإن صلى في وقتين فكله خير، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14335/صلاة-الضحى-سنة-موكدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_707/nour_70705.mp3","categories":["صلاة التطوع"]},{"id":15754,"question":"تسأل أختنا فتقول: هل السنن الرواتب لا تؤدى بين الصلاة والإقامة، أم يجوز أن تؤدى بعد الإقامة كراتبة الظهر؟ هل يجوز أن تؤدى بعد الإقامة، ثم بعد ذلك تؤدى الفريضة، أم لا بد أن تؤدى الفريضة إذا تمت الإقامة؟جزاكم الله خيرًا.","title":"حكم صلاة الراتبة أثناء الإقامة أو بعدها","answer":"الجواب: يقول النبي ﷺ: إذا أقيمت الصلاة فلا صلاة إلا المكتوبة بعد الإقامة ما في نافلة، إذا أحرم قبل الإقامة، ثم أقيمت يقطع الصلاة.  فالمقصود: بعد الإقامة لا نافلة، يتهيأ للفريضة؛ ولهذا يقول ﷺ: إذا أقيمت الصلاة فلا صلاة إلا المكتوبة فإذا أقيمت الصلاة وهو في النافلة فإنه يقطعها، ويتهيأ للفريضة، إلا إذا كان في آخرها، قد انتهى من الركوع الثاني، قد ركع الركوع الثاني، كمّلها؛ لأنها انتهت حينئذٍ، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14344/حكم-صلاة-الراتبة-اثناء-الاقامة-او-بعدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_707/nour_70707.mp3","categories":["صلاة التطوع"]},{"id":15764,"question":"بعد هذا ننتقل إلى رسالة وصلت إلى البرنامج من المستمع (ع. أ) أخونا يقول: كنت أصلي ركعتين قبل صلاة المغرب وبعد الأذان، وبعض الناس يقولون: إن هذا بدعة، فما هو توجيهكم؟جزاكم الله خيرًا.","title":"حكم صلاة ركعتين بعد أذان المغرب","answer":"الجواب: صلاة الركعتين بعد الأذان مستحبة، أمر بها النبي ﷺ قال: صلوا قبل المغرب، صلوا قبل المغرب، ثم قال في الثالثة: لمن شاء، وكان الصحابة  إذا أذن المؤذن قاموا وصلوا ركعتين، فهي سنة، بعد الأذان، يسن لمن كان في المسجد أن يصلي ركعتين قبل الإقامة، ومن أنكر ذلك فقد جهل السنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14352/حكم-صلاة-ركعتين-بعد-اذان-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_707/nour_70711.mp3","categories":["صلاة التطوع"]},{"id":15769,"question":"رسالة بعث بها مستمع رمز إلى اسمه بالحروف (أ. س) يقول: دائمًا عندما أذهب للمسجد لصلاتي الفجر والعصر أجد المؤذن يقيم الصلاة، أو أجد المصلين قد دخلوا في الصلاة، فهل أصلي السنة بعد الفجر والعصر في هذه الحالة، وماذا عن تحية المسجد؟","title":"حكم قضاء سنن الصلاة القبلية بعد الصلاة","answer":"الجواب: إذا جئت والإمام في الصلاة، أو المؤذن يقيم، فادخل معهم في الصلاة، ولا تصل تحية المسجد ولا الراتبة؛ لقول النبي ﷺ: إذا أقيمت الصلاة فلا صلاة إلا المكتوبة رواه مسلم في الصحيح إذا أقيمت الصلاة فلا صلاة إلا المكتوبة فإذا جئت والمؤذن يقيم فَصُف معهم، وكبَّر معهم في الصلاة، ولا تصل النافلة لا سنة الفجر ولا التحية، وهكذا إذا جئت من باب أولى وهم في الصلاة ادخل في الصلاة، ولا تصل تحية ولا راتبة، وإذا فرغت من الصلاة -الظهر- صليت الراتبة القبلية، ثم البعدية، والفجر كذلك إذا فرغت من صلاة الفجر تصلي السنة الراتبة ثنتين بعدها، أو بعد طلوع الشمس، أما سنة المغرب فهي بعدها، وسنة العشاء بعدها، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14359/حكم-قضاء-سنن-الصلاة-القبلية-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_741/nour_74112.mp3","categories":["صلاة التطوع"]},{"id":15809,"question":"رسالة بتوقيع أحد الإخوة يقول: سوداني، مقيم في المملكة، له جمع من الأسئلة يقول في أحدها: لقد تعودت أن أقرأ في ركعتي الضحى آيتي الشكر؛ الآية من سورة النمل فَتَبَسَّمَ ضَاحِكًا مِنْ قَوْلِهَا وَقَالَ رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ[النمل:19] الآية، وأيضًا الآية من سورة الأحقاف: وَوَصَّيْنَا الإِنسَانَ بِوَالِدَيْهِ إِحْسَانًا حَمَلَتْهُ أُمُّهُ كُرْهًا وَوَضَعَتْهُ كُرْهًا وَحَمْلُهُ وَفِصَالُهُ ثَلاثُونَ شَهْرًا حَتَّى إِذَا بَلَغَ أَشُدَّهُ وَبَلَغَ أَرْبَعِينَ سَنَةً[الأحقاف:15] الآية، هل عملي هذا -يا سماحة الشيخ- يعد مبتدعًا، أم أني مخير في أن أقرأ ما أريد من كتاب الله؟جزاكم الله خيرًا.","title":"حكم قراءة آيات محددة في صلاة الضحى","answer":"الجواب: لا حرج عليك أن تقرأ ما تيسر، ما لم تعتقد أن هذا فيه سنة خاصة؛ هذا لا أصل له، ولكن مثلما قال ربك -جل وعلا-: فَاقْرَءُوا مَا تَيَسَّرَ مِنْهُ[المزمل:20] فإذا قرأت ما تيسر فلا حرج عليك، أما أن تتعمد آيتين مخصوصتين ترى أنهما سنة وحدهما، فهذا لا أصل له؛ لأن البدعة لا تجوز في الشرع، ولا أحد يقول: هذا سنة، أو هذا بدعة إلا بدليل، يقول النبي ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد فإذا كنت إنما أردت أنها آيتان عظيمتان، فأحببت القراءة بهما، فلا بأس بهما، أو بغيرهما من دون أن تعتقد أنها سنة دون غيرها، سنة خاصة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14397/حكم-قراءة-ايات-محددة-في-صلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_743/nour_74312.mp3","categories":["صلاة التطوع"]},{"id":15928,"question":"السائل يقول: هناك أناس يصلون بعد سنة المغرب ست ركعات، اثنتان اثنتان يسلمون بعد كل اثنتين، ويقولون: بأنها صلاة الأوابين، فما حكمها؟","title":"حكم صلاة ست ركعات بعد المغرب","answer":"الجواب: هذا ليس له أصل، صلاة الأوابين صلاة الضحى إذا اشتد الضحى، هذه صلاة الأوابين، كما جاء في الحديث الصحيح، أما بين المغرب والعشاء فالإنسان يستحب له أن يصلي ما تيسر، لكن الست التي يظنها الناس ليس لها أصل، الراتبة ثنتان، السنة أن يصلي بعد المغرب ثنتين، والأفضل في بيته، هذه يقال لها: راتبة، كان النبي يحافظ عليها -عليه الصلاة والسلام-، وهكذا بعد العشاء ركعتان، يصلي ركعتين بعد العشاء. أما كونه يصلي ستًا بعد المغرب أو أكثر فلا بأس، يصلي ستًا أو عشرًا أو عشرين أو مائة، لا حرج يسلم من كل ثنتين؛ لأن الرسول ﷺ قال: صلاة الليل مثنى مثنىفمن تطوع بين المغرب والعشاء فصلى ستًا، أو ثمانًا، أو عشرًا، أو أكثر لا بأس، لكن اعتقاد أن هناك ستًا خاصة ليس عليه دليل صحيح. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14525/حكم-صلاة-ست-ركعات-بعد-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57718.mp3","categories":["صلاة التطوع"]},{"id":15937,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من البحرين باعثها مستمع من هناك رمز إلى اسمه بالحروف (أ. ح) مصري مقيم في البحرين، أخونا عرضنا جزءًا من أسئلته في حلقة مضت، وفي هذه الحلقة يسأل سماحتكم عن حكم من فاتته السنة القبلية؟ وهل توافونا بالسنن الراتبة؟جزاكم الله خيرًا.","title":"السنن الرواتب وحكم من فاته شيء منها","answer":"الجواب: بسم الله الرحمن الرحيم.  الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فمن فاتته السنة القبلية للظهر مثلًا، يشرع له أن يصليها بعد الصلاة، ثم يصلي السنة البعدية، والراتبة في الظهر أربع قبلها تسليمتان، وثنتان بعدها، كما كان النبي يفعل -عليه الصلاة والسلام-، وإن صلى أربعًا قبلها وأربعًا بعدها؛ فهو أفضل لقوله ﷺ: من حافظ على أربع قبل الظهر وأربع بعدها؛ حرمه الله على النار.   والسنن الرواتب اثنتا عشرة ركعة، ثنتان قبل الفجر سنة راتبة قبلها؛ فإذا فاتت تقضى بعدها، أو بعد طلوع الشمس، أربع قبل الظهر تسليمتان، ثنتان بعدها، ثمان، ثنتان بعد المغرب هذه عشر، ثنتان بعد العشاء هذه اثنا عشر يقال لها الرواتب، وقد صح فيها عن أم حبيبة -رضي الله عنها- عن النبي ﷺ أنه قال: من صلى ثنتي عشرة ركعة في يومه وليلته بنى الله له بيتًا في الجنة، من صلى ثنتي عشرة ركعة بني له بهن بيت في الجنة يعني: في اليوم والليلة، وفي رواية تطوعًا رواه مسلم في الصحيح، في رواية أخرى للترمذي وجماعة تفسرها أربعًا قبل الظهر وثنتين بعدها، وثنتين بعد المغرب، وثنتين بعد العشاء، وثنتين قبل صلاة الصبح هذه يقال لها: الرواتب، وهي سنة مؤكدة. ويسن للمؤمن أيضًا صلاة الضحى ركعتان، وإن زاد فهو أفضل صلى أربع أو أكثر فهو أفضل، كان النبي ﷺ يصلي الضحى أربعًا، ويزيد ما شاء الله، كما روى ذلك مسلم في صحيحه عن عائشة -رضي الله عنها-، وصلاها في يوم فتح مكة ثمان ركعات في الضحى -عليه الصلاة والسلام-، وقال: صلاة الأوابين حين ترمض الفصال، يعني: حين شدة الضحى لو صليت عند شدة الضحى قبل الظهر بساعة أو بساعة ونصف أو نحو ذلك كان هذا أفضل. ومن ذلك: التهجد بالليل من النوافل التهجد بالليل، ومن جملة ذلك الوتر بركعة واحدة، سواء كان بعد العشاء قبل النوم، أو في وسط الليل، أو في آخر الليل، والأفضل في آخر الليل إذا تيسر ذلك؛ فإن خاف أن لا يقوم من آخر الليل؛ صلى في أول الليل بعد العشاء: ثلاث ركعات، أو خمس ركعات، أو سبع ركعات، أو تسع ركعات، أو إحدى عشرة ركعة، أو ثلاث عشرة ركعة، أو أكثر من ذلك.\nوكان النبي ﷺ في الغالب يصلي إحدى عشرة ركعة، يسلم من كل ثنتين ويوتر بواحدة، ومن أوتر بواحدة فقط في أول الليل أو في آخره؛ أجزأته، وإن أوتر بأكثر فهو الأفضل، كل ما زاد من الخير فهو خير له، وأفضل ذلك إحدى عشرة، أو ثلاث عشرة هذا تأسٍ بالنبي -عليه الصلاة والسلام-، ومن زاد فأوتر بثلاثة وعشرين في رمضان أو في غيره أو بأكثر من ذلك؛ فكله لا حرج فيه، ولكن الأفضل إحدى عشرة أو ثلاث عشرة؛ لأن هذا أكثر ما ورد عن النبي ﷺ، يسلم من كل ثنتين ويوتر بواحدة، والأفضل في آخر الليل، وإن أوتر في أول الليل فلا بأس، وإن كان يخاف أن لا يقوم من آخر الليل فالأفضل أن يوتر في أول الليل.   ويسن في رمضان أن تصلى التراويح أول الليل؛ لأن ذلك أنشط للناس، وخشية أن لا يقوم من آخر الليل، فإذا أوتروا وصلوا التراويح أول الليل فهو أفضل، كما كان أصحاب النبي يفعلون ذلك -عليه الصلاة والسلام-، وكما فعله النبي ﷺ في بعض الليالي بالصحابة، ثم ترك ذلك مخافة أن يفرض عليهم، فإنه صلى بهم في ليلة إلى ثلث الليل، وفي ليلة إلى نصف الليل، وفي ليلة إلى آخر الليل؛ ثم ترك ذلك خشية أن يفرض عليهم -عليه الصلاة والسلام-، وقال -عليه الصلاة والسلام-: من قام مع الإمام حتى ينصرف؛ كتب الله له قيام ليلة هذا فضل عظيم.\nفيستحب للمؤمن أن يقوم مع الإمام حتى ينصرف في التراويح وفي الليالي الأخيرة، يحصل له هذا الفضل العظيم. والسنة للنساء التهجد في البيت؛ لأن صلاتهن في بيوتهن أفضل، ومن خرجت وصلت مع الناس في المساجد فلا بأس؛ إذا خرجت متسترة متحجبة، غير متطيبة، فلا بأس، وبيتها خير لها، لكن إذا خرجت للنشاط أو لسماع المواعظ، فكل هذا حسن مع التحفظ والتستر والحذر من الفتنة، ومن الطيب الذي يسبب الفتنة؛ ولهذا قال -عليه الصلاة والسلام-: لا تمنعوا إماء الله مساجد الله، وبيوتهن خير لهن نعم.\n  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14542/السنن-الرواتب-وحكم-من-فاته-شيء-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_710/nour_71001.mp3","categories":["صلاة التطوع"]},{"id":15965,"question":"يقول: هل يمكن قضاء السنة القبلية بعد الصلاة إن فاتتنا قبلها بسبب التأخر مثلًا؟","title":"حكم قضاء السنن القبلية","answer":"الجواب: نعم، إذا فاتته السنة القبلية سنة الظهر، فالسنة يصليها بعد الظهر، وقد ثبت عنه ﷺ أنه فاتته سنة الظهر القبلية في بعض الأوقات فصلاها بعد الظهر -عليه الصلاة والسلام- صلى ستًا أربعًا السنة القبلية، وثنتين السنة البعدية. المقصود: أنه إذا فاتته جاء والإمام قد أقام الصلاة إذا فرغ من الصلاة يصلي أربعًا السنة القبلية، ثم يصلي ثنتين السنة البعدية، هذا هو الأفضل، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14577/حكم-قضاء-السنن-القبلية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74618.mp3","categories":["صلاة التطوع"]},{"id":15967,"question":"يسأل يقول: ما هو رأي سماحتكم في الشخص الذي لا يحافظ على السنن، ولا يصليها في كثير من الأحيان؟","title":"حكم من ترك سنن الصلاة","answer":"الجواب: إذا كان يؤدي الواجبات، ويدع المحرمات، فالحمد لله، هو بر ومؤمن، وفاته فضل المسارعة إلى الخيرات والمندوبات، فاته فضل المسابقة، فهو من أصحاب اليمين، وليس من السابقين، حتى يكون عنده نشاط في المندوبات والمسارعة إلى الخيرات، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14581/حكم-من-ترك-سنن-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74620.mp3","categories":["صلاة التطوع"]},{"id":16051,"question":"يسأل عن صلاتي الضحى، وصلاة الليل فيقول: ما هو وقت صلاة الضحى بالساعات؟ وهل يجوز أن نصلي صلاة الليل في أول الليل بعد صلاة العشاء إذا لم نستطع صلاتها في آخره؟","title":"وقت صلاة الضحى وقيام الليل","answer":"الجواب: صلاة النهار في الضحى، وفي الظهر كلها وقت صلاة، بعد ارتفاع الشمس قيد رمح، نحو ربع ساعة، بعد طلوع الشمس إلى زواله، إلى وقوف الشمس قبل الظهر، بنحو ثلث ساعة، أو ربع ساعة؛ لأن وقوف الشمس وقته قصير، وهو توسطها في كبد السماء قبل أن تميل إلى المغرب، هذا يقال له: وقت الوقوف وقت نهي، والضحى كله وقت صلاة. والأفضل عند شدة الضحى، إذا اشتد الضحى يكون أفضل قبل الظهر بساعة، أو ساعتين، هذا أفضل ما يكون لصلاة الضحى. وإذا صلى بعد العشاء إذا كان يخشى ألا يقوم من آخر الليل كان هذا أفضل، النبي ﷺ أوصى أبا هريرة، وأوصى أبا الدرداء بالإيتار قبل النوم، والظاهر -والله أعلم- أنهما كانا يخشيان ألا يقوما من آخر الليل؛ لأنهما يدرسان الحديث في أول الليل، فإذا أوتر الإنسان أول الليل؛ فهو أفضل إذا خاف ألا يقوم من آخر الليل. أما إذا طمع أن يقوم آخر الليل ووثق من نفسه أنه يقوم؛ فالوتر في آخر الليل أفضل، كونه يؤخر إلى آخر الليل، هذا هو الأفضل؛ لقول النبي ﷺ: من خاف ألا يقوم من آخر الليل؛ فليوتر أوله، ومن طمع أن يقوم آخر الليل؛ فليوتر آخر الليل، فإن صلاة آخر الليل مشهودة، وذلك أفضل رواه مسلم في صحيحه. ولقوله ﷺ: ينزل ربنا إلى سماء الدنيا كل ليلة حين يبقى ثلث الليل الآخر، فيقول: من يدعوني؛ فأستجيب له؟ من يسألني؛ فأعطيه؟ من يستغفرني؛ فأغفر له؟ حتى ينفجر الفجر. وفي اللفظ الآخر يقول -جل وعلا-: هل من تائب فيتاب عليه؟ هل من سائل؛ فيعطى سؤله؟ هل من مستغفر؛ فيغفر له حتى ينفجر الفجر وهذا الحديث عظيم، حديث عظيم متواتر عن النبي ﷺ وهو نزول الرب -جل وعلا- آخر الليل في الثلث الأخير. فينبغي لك يا عبدالله! أن تكون ممن يعبد الله هذا الوقت بالصلاة والاستغفار، وقراءة القرآن والذكر، وقت عظيم، الثلث الأخير، وهكذا جوف الليل، السدس الرابع كان يقومه داود، يقوم نصف الليل، كان ينام نصف الليل، ويقوم ثلثه، يقوم السدس الرابع، والسدس الخامس، وهذا وقت عظيم أيضًا، جمع بين جوف الليل، وبين أول الثلث الأخير. والله سبحانه رغب عباده في العبادة في هذا الوقت، والدعاء، والضراعة إليه -جل وعلا- فجدير بأهل الإيمان من الرجال والنساء أن يتحروا هذا الوقت، وأن يجتهدوا في قيام الليل، ولاسيما في السدس الرابع والخامس، وفي جميع الثلث الأخير بالدعاء، والضراعة، والصلاة، والقراءة، والاستغفار كما أرشد إليه . وهذا النزول يليق بجلال الله، ليس من جنس نزول المخلوقين، فهو نزول يليق بالله لا يشابه خلقه في نزولهم  قال تعالى: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] وقال سبحانه: وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ [الإخلاص:4] وقال : فَلا تَضْرِبُوا لِلَّهِ الأَمْثَالَ [النحل:74] فنزوله يليق به، لا يشابه خلقه. وهكذا استواؤه على عرشه، وهكذا رحمته وغضبه وضحكه، كله يليق بالله لا يشابه خلقه  وهكذا جميع الصفات كلها تليق بالله، لا يشابه فيها خلقه  عملًا بقوله -جل وعلا-: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11]. وهذا قول أهل السنة والجماعة، وهم أصحاب النبي ﷺ وأتباعهم بإحسان، فالزمه يا عبدالله! الزم هذا القول، وعض عليه بالنواجذ، واحذر أقوال المبتدعة المحرفين لكتاب الله، المؤولين لصفات الله، أو المشبهين الله بخلقه، احذر أقوالهم فكلها باطلة. والحق قول أهل السنة والجماعة، وهو قول أصحاب النبي ﷺ وأتباعهم بإحسان، وهو قول الأنبياء جميعًا والرسل جميعًا، وهو الإيمان بأسماء الله وصفاته الواردة في القرآن العظيم، والسنة المطهرة الصحيحة، وإمرارها كما جاءت من غير تحريف، ولا تعطيل، ولا تأويل، ولا تكييف، ولا تمثيل. بل يجب أن نؤمن بها كما جاءت، ونمرها كما جاءت، مع الإيمان بأنها حق، وأن نزوله حق، وأن استواءه حق، وأن رحمته حق، وأن غضبه حق، وأن رضاه حق، وأن رحمته حق، وهكذا بقية صفاته، من يد وقدم وسمع وبصر وعلم وكلام، كلها حق، كلها صفات تليق بالله، لا يشابه فيها خلقه . فكلامه ليس من جنس كلام خلقه، وغضبه ليس من جنس غضبهم، وضحكه ليس من جنس ضحكهم، ورضاه ليس من جنس رضاهم، وهكذا، كل صفاته تليق به  لا يشابه فيها خلقه، لا يعرف كيفيتها إلا هو . قال بعض الناس لمالك بن أنس، إمام دار الهجرة في زمانه، الإمام المشهور، والعالم العظيم -رحمه الله- قال له بعض الناس يا أبا عبدالله! يقول الله سبحانه: الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى [طه:5] فأطرق طويلًا، ثم قال: الاستواء معلوم، والكيف مجهول، والإيمان به واجب، والسؤال عنه بدعة، يعني السؤال عن الكيفية بدعة. فالاستواء معلوم وهو العلو، الاستواء هو العلو والفوقية فوق العرش، هو العلو فوق العرش، والارتفاع هذا معلوم، والكيف مجهول، كيف استوى؟ ما نعلم كيف استوى، لا نعلم كيف يرضى، كيف يغضب، كيف ينزل لا، لا نعلم، لكن نؤمن بأنه ينزل إلى سماء الدنيا كل ليلة في الثلث الأخير، نعلم أنه استوى على العرش، نعلم أنه يضحك ويرضى ويغضب، لكن لا نعلم كيفية ذلك، بل نقول كما قال سبحانه: لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ [الشورى:11] فهو سبحانه لا يماثل عباده في صفاتهم، ولا يعلم الناس كيفية صفاته، هذا هو الحق الذي عليه أهل السنة والجماعة، نسأل الله أن يوفق الجميع لما يرضيه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14700/وقت-صلاة-الضحى-وقيام-الليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_802/nour_80208.mp3","categories":["صلاة التطوع"]},{"id":16086,"question":"يسأل سماحتكم عن حكم تأخير النوافل قبيل الفجر بنصف ساعة؟","title":"حكم تأخير النوافل إلى قبيل الفجر","answer":"الجواب: لا مانع، لكن كونك تتقدم حتى يتسع الوقت، وحتى تصلي ما يسر الله لك بهدوء، وتصلي إحدى عشرة ركعة، كما كان النبي يفعل -عليه الصلاة والسلام- تسلم من كل ثنتين، تجتهد في القراءة، وفي إطالة الركوع والسجود، هذا أفضل؛ لأن الوقت الضيق قد لا تتمكن معه من المطلوب... الصلاة المطلوبة، والدعوات المطلوبة، لكن لو أخرت إلى آخر الليل، وصليت ما يسر الله لك؛ فلا حرج، والحمد لله، نعم.","link":"https://binbaz.org.sa/fatwas/14721/حكم-تاخير-النوافل-الى-قبيل-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_711/nour_71112.mp3","categories":["صلاة التطوع"]},{"id":16159,"question":"هذا سائل مقيم في المملكة العربية السعودية، يقول -سماحة الشيخ-: صلاة تحية المسجد هل يصليها الإنسان كلما يدخل المسجد أي: بعد كل صلاة؟ أم مرة واحدة في اليوم؟ وهذه الصلاة، هل تكفي عن السنة، أم لا؟ جزاكم الله خيرًا.","title":"حكم تحية المسجد لكل دخول إلى المسجد","answer":"الجواب: السنة لمن دخل المسجد وهو على طهارة أن يصلي ركعتين تحية المسجد؛ لقول النبي ﷺ: إذا دخل أحد المسجد؛ فلا يجلس حتى يصلي ركعتين وفي اللفظ الآخر: فليركع ركعتين قبل أن يجلس هذا السنة في أي وقت: في وقت الضحى، في الظهر، في العصر، في المغرب.. في أي وقت، ليس لها وقت نهي على الصحيح، حتى ولو بعد العصر إذا دخل لا يجلس، ينتظر المغرب، يصلي ركعتين، أو دخل بعد الفجر لحضور حلقات العلم، أو ليجلس في المسجد يصلي ركعتين إذا كان على طهارة قبل أن يجلس، ليس لها وقت نهي، هذا هو المشروع للمسلم، وهي سنة مؤكدة. ولو دخل إلى المسجد مرات؛ صلى كلما دخل، لو دخل الضحى مرتين، أو ثلاثًا، أو الظهر، أو العصر، أو الليل، كلما دخل وهو على طهارة؛ يصلي ركعتين، ولو دخل وصلى الراتبة راتبة الظهر سدت عن تحية المسجد، لو صلى راتبة الظهر ركعتين، أو أربع ركعات، الراتبة قبل الظهر السنة أربع تسليمتين، فإذا صلاهما؛ سدت عن تحية المسجد، وهكذا إذا دخل الفجر وهو ما صلى الراتبة في بيته، صلى الراتبة في المسجد؛ كفته عن تحية المسجد، ركعتين سنة الفجر تكفي عن تحية المسجد.. والحمد لله. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14822/حكم-تحية-المسجد-لكل-دخول-الى-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_580/58004.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":16193,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من القصيم يقول: بالنسبة لصلاة الرواتب ما هو عددها؟ وما كيفية أدائها؟ وهل النافلة التي بعد الظهر يمتد وقتها إلى دخول أذان العصر، أم لا؟ وهل بعد أذان العصر يمكن التنفل قبل الفريضة، أم لا؟ كذلك بالنسبة للنافلة التي بعد صلاة المغرب هل يمتد وقتها إلى دخول أذان العشاء، أم لا؟ وهل بعد أذان العشاء يمكن التنفل قبل صلاة الفريضة، أم لا؟ وضحوا لنا هذه الأمور حول النوافل، جزاكم الله خيرًا.","title":"ما هي السنن الرواتب؟ وما أوقاتها؟","answer":"الجواب:  الرواتب التي شرعها الله -جل وعلا- مع الصلوات الخمس، وكان النبي يحافظ عليها -عليه الصلاة والسلام- في الحضر اثنتا عشرة ركعة، منها أربع قبل صلاة الظهر بعد الزوال، يسلم من كل ثنتين، وثنتان بعد الظهر، تسليمة واحدة، هذه ست: ثنتان بعد المغرب.. ثنتان بعد صلاة العشاء.. ثنتان قبل صلاة الفجر، هذه هي الرواتب التي كان يحافظ عليها -عليه الصلاة والسلام- في الحضر، أما في السفر فكان يتركها ﷺ إلا سنة الفجر، كان في السفر لا يصلي هذه الرواتب إلا سنة الفجر، فإنه كان يحافظ عليها سفرًا وحضرًا. ويشرع للمؤمن مع الصلوات الخمس -سوى هذه الرواتب- أن يصلي أربعًا قبل العصر، بعد دخول الوقت، أربعًا، تسليمتين؛ لقوله ﷺ: رحم الله امرأ صلى أربعًا قبل العصر وهذه ليست راتبة، يروى عن النبي ﷺ كان ربما صلى ثنتين قبل العصر، ربما صلى أربعًا قبل العصر، لكن ليست راتبة، ولكنها مستحبة إذا صلاها المؤمن والمؤمنة فهو أفضل، أربع قبل العصر تسليمتين، وثنتان قبل المغرب، هذه مستحبة بعد الأذان، وقبل الإقامة ثنتان، كذلك بعد أذان العشاء يصلي ركعتين قبل صلاة العشاء أفضل، وليست من الرواتب، لكن يستحب إذا أذن المؤذن وهو جالس في المسجد أن يقوم، فيصلي ركعتين بعد المغرب، بعد أذان المغرب، وبعد أذان العشاء، وإن صلى أكثر فلا بأس. وكذلك يستحب له أن يتهجد بالليل بعد صلاة العشاء إلى آخر الليل، يتهجد بما يسر الله له ولو بركعة واحدة يوتر بها، وكل ما زاد فهو أفضل، أوتر بثلاث، أو بخمس، أو بسبع، أو بأكثر، يسلم من كل ثنتين فهذا هو الأفضل، والأفضل إحدى عشرة، أو ثلاث عشرة، وإن نقص، أو زاد فلا بأس، يسلم من كل ثنتين تأسيًا بالنبي ﷺ في ذلك. ولا بأس أن يتأخر في أداء الراتبة بعد الظهر، يمتد وقتها إلى أذان العصر، يصليها قبل العصر، ولو تأخر، لكن قبل العصر، قبل دخول وقت العصر، هكذا المغرب لو أخرها.. لو أخر الراتبة لم يصلها إلا قرب غروب الشفق، يعني: قرب العشاء فلا بأس، لكن الأفضل أن يبادر بها قبل العوائق، هذا هو الأفضل، وإلا فوقتها يمتد إلى أن يغيب الشفق الأحمر من جهة المغرب .... دخول وقت العشاء. كما أن سنة الظهر البعدية يمتد إلى دخول وقت العصر، لكن إذا بادر بهذه وهذه قبل دخول وقت الذي بعدها؛ فهو الذي أولى له؛ حتى لا يعرض له عارض، والأفضل في بيته، إذا صلاها في البيت؛ فهو أفضل، وإن صلاها في المسجد؛ فلا بأس، لكن في البيت أفضل، نعم. المقدم: جزاكم الله خيرًا، يستوي هذا الحكم سماحة الشيخ، وهذا التوجيه، يستوي في حق الرجال، وحق النساء ؟ الجواب: نعم عام للرجال والنساء جميعًا، الحكم عام للرجال والنساء، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14870/ما-هي-السنن-الرواتب-وما-اوقاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75102.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":16280,"question":"سماحة الشيخ! كثر السؤال عن صلاة التسبيح، وممن يسأل صاحب هذه الرسالة الأخ موسى، يقول: في صلاة التسبيح هل هي صلاة رباعية؟ وهل لهذه الصلاة مواعيد معينة تصلى فيها، أو يمكن أن تصلى في أي وقت؟ وهل بعد قراءة التشهد الأول أسلم، أم آتي بالركعتين الأخيرتين، وأسلم؟","title":"الصواب في صلاة التسبيح","answer":"الجواب: صلاة التسبيح غير ثابتة، وغير صحيحة، وغير مشروعة، هذا هو الصواب، تصلي كما تصلي، وكما يصلي المسلمون، أما صلاة التسبيح فهي غير ثابتة، وغير مشروعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14966/الصواب-في-صلاة-التسبيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_809/nour_80902.mp3","categories":["صلاة التطوع"]},{"id":16290,"question":"تقول: سمعت أن الأفضل لمن صلى ركعتي الفجر أن يقرأ في الأولى بسورة الكافرون، والثانية بسورة قل هو الله أحد فهل ما سمعت صحيح؟","title":"المشروع قراءته في راتبة الفجر","answer":"الجواب: نعم، هذه هي السنة للرجل والمرأة أن يقرأ في سنة الفجر بهاتين السورتين بعد الفاتحة، في الأولى: قُلْ يَاأَيُّهَا الْكَافِرُونَ [الكافرون: 1] بعد الفاتحة، وفي الثانية: قُلْ هُوَ اللَّهُ أَحَدٌ [الصمد: 1] بعد الفاتحة للرجل والمرأة، والسنة أن تؤدى في البيت للرجل، وإن أداها في المسجد؛ فلا بأس، وإن قرأ فيهما أيضًا آية البقرة: قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنْزِلَ إِلَيْنَا [البقرة:136] ... الآية، بعد الفاتحة، وفي الثانية آية آل عمران: قُلْ يَاأَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ [آل عمران:64] فذلك سنة أيضًا. النبي فعل هذا وهذا -عليه الصلاة والسلام- تارة يقرأ السورتين، وهما قُلْ يَاأَيُّهَا الْكَافِرُونَ [الكافرون: 1] وقُلْ هُوَ اللَّهُ أَحَدٌ  [الإخلاص: 1] وتارة يقرأ الآيتين: قُولُوا آمَنَّا بِاللَّهِ وَمَا أُنزِلَ إِلَيْنَا [البقرة:136] في الأولى يعني: بعد الفاتحة، وفي الثانية: قُلْ يَا أَهْلَ الْكِتَابِ [آل عمران:64] بعد الفاتحة، كله سنة، وإن قرأ بغير ذلك فلا حرج، والحمد لله، لكن كونه يقرأ هاتين الآيتين، أو هاتين السورتين هذا هو الأفضل؛ تأسيًا بالنبي، نعم. المقدم: اللهم صل وسلم عليه. جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14976/المشروع-قراءته-في-راتبة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_752/nour_75212.mp3","categories":["صلاة التطوع"]},{"id":16368,"question":"السائلة التي رمزت لاسمها (م. ع) تقول: سماحة الشيخ! ورد في الأثر أن النبي ﷺ كان يصلي أربع ركعات قبل الظهر، وأربع ركعات قبل العصر، فهل تكون ذلك قبل الأذان أم بعده؟","title":"حكم صلاة نافلة الظهر والعصر قبل الأذان","answer":"الجواب: هذا ثابت عن النبي ﷺ في أحاديث صحيحة أنه كان يصلي أربعًا قبل الظهر بعد الزوال، يعني بعد الأذان، راتبة تسمى راتبة، تسليمتين، وبعدها ركعتين تسليمة، وهذه راتبة، وإن صلى بعدها أربعًا؛ كان أفضل، لقوله ﷺ: من حافظ على أربع قبل الظهر، وأربع بعدها؛ حرمه الله على النار يعني: بعد الزوال، وهكذا قبل العصر يصلي أربعًا، جاء عنه ﷺ أنه كان يصلي أربعًا، وفي الحديث الصحيح أنه قال: رحم الله امرأً صلى أربعًا قبل العصر يعني: بتسليمتين، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/15068/حكم-صلاة-نافلة-الظهر-والعصر-قبل-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58114.mp3","categories":["صلاة التطوع"]},{"id":16415,"question":"من الأخت (م. م. س) من المدينة المنورة رسالة ضمنتها سؤالًا تقول فيه: ما مدى صحة الصلوات الآتية، وهل هي واردة عن رسولنا الكريم ﷺ أم أنها من الأمور المبتدعة: صلاة التسبيح، وصلاة الحاجة، والتي جاء في صفتها نصوص مختلفة في كتب المأثورات، والأدعية ونحوها، ومن أمثلة تلك النصوص، أنه ورد عن الرسول ﷺ: \"أن اثنتي عشرة ركعة تصليهن من ليل، أو نهار، وتتشهد بين كل ركعتين، فإذا تشهدت في آخر صلاتك، فاثن على الله  وصل على النبي  واقرأ وأنت ساجد فاتحة الكتاب سبع مرات، وآية الكرسي سبع مرات، وقل: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير عشر مرات، ثم قل: اللهم إني أسألك بمعاقد العز من عرشك، ومنتهى الرحمة من كتابك واسمك الأعظم، وجدك الأعلى، وكلماتك التامة، ثم سل حاجتك، ثم ارفع رأسك، ثم سلم يمينًا وشمالًا، ولا تعلموها السفهاء، فإنهم يدعون بها فيستجابون!\" ما مدى صحة هذا الحديث؟ وهل يلزمنا العمل به؟ جزاكم الله خيرًا.","title":"الحكم على حديث صلاة التسبيح","answer":"الجواب: هذا الحديث غير صحيح، وقد نبهنا عليه غير مرة، فهو حديث لا يصح عن النبي ﷺ والرسول نهى عن القراءة في الركوع والسجود -عليه الصلاة والسلام- فالحديث هذا غير صحيح، ولا ينبغي أن يغتر به، وصلاة التسبيح كذلك غير صحيحة.  والمشروع للمؤمن أن يصلي كما شرع الله، يصلي ركعتين، أو أكثر في الضحى، أو في الليل، يصلي ما قسم الله له، ولا يقرأ في السجود، ولا في الركوع، ويصلي كما هو معروف، يسبح الله، يقول: سبحان ربي العظيم في الركوع، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، ويقول: سبحان ربي الأعلى في السجود، يقول: سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، ويدعو في السجود بما قسم الله له، على الصلاة المعروفة، الثابتة عن النبي ﷺ. أما صلاة التسبيح فهي غير ثابتة، وكذلك هذا الحديث الذي ذكر اثنا عشر ركعة، وفيها الدعاء، وفيها القراءة في السجود، كل هذا غير صحيح، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15163/الحكم-على-حديث-صلاة-التسبيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_812/nour_81209.mp3","categories":["صلاة التطوع","الحكم على الأحاديث"]},{"id":16485,"question":"يقول: هل راتبة الفجر قبل الأذان، أم بعد الأذان؟ وإذا كان بعد الأذان، فهل لي إذا دخلت المسجد، والمؤذن يؤذن، أو انتهى من الأذان أن أصلي تحية المسجد والراتبة؟ أم أصلي راتبة الفجر فقط؟","title":"وقت راتبة الفجر وحكمها مع تحية المسجد","answer":"الجواب: سنة الفجر تكون بعد طلوع الفجر، سواء كان أذن المؤذن، أو ما أذن المؤذن، إذا صليتها بعد طلوع الفجر؛ فقد حصل المقصود في بيتك، أو في المسجد، وإذا صليتها بعد الأذان كذلك، قد أديت السنة، المهم أن تكون بعد طلوع الفجر، فلو أذن المؤذن قبل طلوع الفجر، وصليتها بعد الأذان قبل طلوع الفجر ما تكون أديت السنة، لابد أن تكون بعد طلوع الفجر، أو بعد الأذان إذا كان المؤذن يؤذن على طلوع الفجر. وإذا جئت المسجد، وأنت لم تصل الراتبة؛ فإنك تصلي ركعتين، تنوي بهما الراتبة، وتكفيان عن تحية المسجد، وإذا نويتهما جميعًا: الراتبة، وتحية المسجد؛ فلا حرج في ذلك، ولا حاجة إلى تكرار الصلاة، تكفي ركعتان فقط، ركعتان تنوي بهما سنة الفجر، وسنة التحية، والحمد لله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15219/وقت-راتبة-الفجر-وحكمها-مع-تحية-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_756/nour_75607.mp3","categories":["صلاة التطوع"]},{"id":16492,"question":"هذا سائل لم يذكر الاسم في هذه الرسالة، يقول: سماحة الشيخ! ماحكم صلاة الاستخارة؟ وكيف يكون الدعاء فيها، هل هو في السجود الأخير، أو قبل السلام، أو يكون بعد نهاية الصلاة؟","title":"حكم صلاة الاستخارة وكيفيتها","answer":"الجواب: صلاة الاستخارة سنة، ندب إليها النبي ﷺ فإذا هم الإنسان بشيء من الأمور التي أشكل عليه أمرها، وحار فيها؛ يصلي ركعتين، ثم يرفع يديه بعد الصلاة، ويستخير الله، حتى ينشرح صدره لأحد الأمرين، أو الأمور، وهي ركعتان يقرأ فيها الفاتحة، وما تيسر، ثم بعد السلام يرفع يديه، ويستخير: اللهم إني أستخيرك بعلمك.. إلى آخره، فإذا اطمأن قلبه إلى أحد الأمرين، أو الأمور فعل ذلك، ويستحب له أن يستشير أهل الخير، وأهل النصح بعد الصلاة، يستشيرهم حتى ينشرح صدره لأحد الأمرين، أو الأمور المشكلة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15204/حكم-صلاة-الاستخارة-وكيفيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58219.mp3","categories":["صلاة التطوع"]},{"id":16495,"question":"السائل يقول: هناك أناس يصلون بعد سنة المغرب ست ركعات، اثنتان اثنتان يسلمون بعد كل اثنتين، ويقولون: بأنها صلاة الأوابين، فما حكمها؟","title":"حكم صلاة ست ركعات بعد صلاة المغرب","answer":"الجواب: هذا ليس له أصل، صلاة الأوابين صلاة الضحى، إذا اشتد الضحى، هذه صلاة الأوابين كما جاء في الحديث الصحيح، أما بين المغرب والعشاء فالإنسان يستحب له أن يصلي ما تيسر، لكن الست التي يظنها الناس ليس لها أصل، الراتبة ثنتان، السنة أن يصلي بعد المغرب ثنتين، والأفضل في بيته، هذه يقال لها: راتبة، كان النبي يحافظ عليها -عليه الصلاة والسلام- وهكذا بعد العشاء ركعتان، يصلي ركعتين بعد العشاء. أما كونه يصلي ستًا بعد المغرب، أو أكثر؛ فلا بأس، يصلي ستًا، أو عشرًا، أو عشرين، أو مائة، لا حرج، يسلم من كل ثنتين؛ لأن الرسول  قال: صلاة الليل مثنى مثنى فمن تطوع بين المغرب والعشاء، وصلى ستًا، أو ثمانًا، أو عشرًا، أو أكثر لا بأس، لكن اعتقاد أن هناك ستًا خاصة ليس عليه دليل صحيح.","link":"https://binbaz.org.sa/fatwas/15209/حكم-صلاة-ست-ركعات-بعد-صلاة-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58222.mp3","categories":["صلاة التطوع"]},{"id":16527,"question":"هل النافلة في المكتب الذي يعمل فيه الموظف لمدة سبع ساعات يوميًّا أفضل من المسجد، ويعد كالبيت، أم لا؟","title":"حكم صلاة النافلة في محل العمل","answer":"الجواب: إذا كانت صلاته في المكتب لا تعطل عملًا، بل هو عنده فراغ... فهو مستحب... صلاة الضحى هذا أمر طيب، أما إن كانت صلاته قد تعطل عملًا، أو تنقص العمل؛ فلا، يستمر في عمله، ويكفي، وصلاته في مكتبه تشبه صلاته في البيت، إذا كان ذلك لا يعطل عملًا، ولا يضر عملًا، ولا ينقص عملًا، بل عنده فراغ، هذا عمل طيب، انتهاز الفرص في الخير، والحرص على الخير أمر مطلوب، في المكتب، وفي السفر، وفي الحضر، وفي كل مكان، كون المؤمن ينتهز الفرص بالتسبيح، والتهليل، والتحميد، وقراءة القرآن، وصلاة النافلة، والدعوة إلى الله، والأمر بالمعروف والنهي عن المنكر... إلى غير ذلك، هذا شيء مطلوب أينما كان، بشرط أن يكون ذلك لا يضر عملًا لازمًا له، ولا يعطله، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15260/حكم-صلاة-النافلة-في-محل-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75706.mp3","categories":["صلاة التطوع"]},{"id":16555,"question":"يسأل عن الإمام الذي يخطب يوم الجمعة: هل يصلي ركعتين في بيته قبل أن ينصرف إلى المسجد؟","title":"حكم صلاة الخطيب قبل الخروج إلى المسجد","answer":"الجواب: لا نعلم في هذا شيئًا، لا نعلم في هذا شيئًا، إذا صلى في بيته صلاة الضحى طيب، ومشروعة، لكن ليست من أجل الجمعة، صلاة الضحى مشروعة في بيته كل يوم، فإذا صلى في بيته الضحى ركعتين، أو أكثر من ذلك، ثم جاء للجمعة فهذا حسن، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15311/حكم-صلاة-الخطيب-قبل-الخروج-الى-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81619.mp3","categories":["صلاة التطوع"]},{"id":16556,"question":"تسأل في سؤالها الثاني عن صلاة الاستخارة تقول: لقد سمعت أن من صلى صلاة الاستخارة لغرض معين؛ فإنه يرى في منامه إذا كان خيرًا له، هل ما قيل صحيح؟","title":"هل يرى المستخير في منامه ما كان خيرًا له؟","answer":"الجواب: لا أعرف لهذا صحة من جهة الرؤيا، ولكن صلاة الاستخارة سنة، إذا هم الإنسان بأمر أشكل عليه أمره، أو عاقبته يستخير ربه، يصلي ركعتين، ثم يدعو ربه بعد الصلاة، ويرفع يديه، ويدعو ربه، ويستخير بما جاء في دعاء الاستخارة وهو: اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنك تعلم ولا أعلم، وتقدر ولا أقدر، وأنت علام الغيوب، اللهم إن كان هذا الأمر ويسميه بعينه كما أمر النبي ﷺ مثل زواج، مثل سفر، مثل معاملة، إنسان يشك الإنسان في معاملته، أو شبه ذلك من الأمور التي يحصل فيها بعض التوقف. فيقول في دعائه: اللهم إن كان هذا الأمر يعني: زواجي بفلان، تقول المرأة، أو الرجل يقول: زواجي بفلانة، أو سفري إلى كذا، أو معاملتي لفلان خيرًا لي في ديني، ودنياي، وعاقبة أمري؛ فيسره لي، ثم بارك لي فيه، وإن كان ذلك ويسميه باسمه شرًا لي في ديني، ودنياي، ومعاشي، وعاقبة أمري؛ فاصرفه عني، واصرفني عنه، وقدر لي الخير حيث كان، ثم أرضني به هذا دعاء مشروع. ثم بعد ذلك يستشير من يرى من أهل الخير من أقربائه، وأصدقائه، يستشيرهم، فإذا انشرح صدره لأحد الأمرين يمضي، فإن استمر معه التردد أعاد الاستخارة ثانيًا، وثالثًا، وهكذا حتى يطمئن قلبه، وينشرح صدره لأحد الأمرين من الفعل، أو الترك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15285/هل-يرى-المستخير-في-منامه-ما-كان-خيرا-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81602.mp3","categories":["صلاة التطوع"]},{"id":16572,"question":"يسأل عن الإمام الذي يخطب يوم الجمعة: هل يصلي ركعتين في بيته قبل أن ينصرف إلى المسجد؟","title":"حكم صلاة الخطيب قبل الخروج إلى المسجد","answer":"الجواب: لا نعلم في هذا شيئًا، لا نعلم في هذا شيئًا، إذا صلى في بيته صلاة الضحى طيب، ومشروعة، لكن ليست من أجل الجمعة، صلاة الضحى مشروعة في بيته كل يوم، فإذا صلى في بيته الضحى ركعتين، أو أكثر من ذلك، ثم جاء للجمعة فهذا حسن، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15311/حكم-صلاة-الخطيب-قبل-الخروج-الى-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81619.mp3","categories":["صلاة التطوع"]},{"id":16574,"question":"تسأل في سؤالها الثاني عن صلاة الاستخارة تقول: لقد سمعت أن من صلى صلاة الاستخارة لغرض معين؛ فإنه يرى في منامه إذا كان خيرًا له، هل ما قيل صحيح؟","title":"هل يرى المستخير في منامه ما كان خيرًا له؟","answer":"الجواب: لا أعرف لهذا صحة من جهة الرؤيا، ولكن صلاة الاستخارة سنة، إذا هم الإنسان بأمر أشكل عليه أمره، أو عاقبته يستخير ربه، يصلي ركعتين، ثم يدعو ربه بعد الصلاة، ويرفع يديه، ويدعو ربه، ويستخير بما جاء في دعاء الاستخارة وهو: اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنك تعلم ولا أعلم، وتقدر ولا أقدر، وأنت علام الغيوب، اللهم إن كان هذا الأمر ويسميه بعينه كما أمر النبي ﷺ مثل زواج، مثل سفر، مثل معاملة، إنسان يشك الإنسان في معاملته، أو شبه ذلك من الأمور التي يحصل فيها بعض التوقف. فيقول في دعائه: اللهم إن كان هذا الأمر يعني: زواجي بفلان، تقول المرأة، أو الرجل يقول: زواجي بفلانة، أو سفري إلى كذا، أو معاملتي لفلان خيرًا لي في ديني، ودنياي، وعاقبة أمري؛ فيسره لي، ثم بارك لي فيه، وإن كان ذلك ويسميه باسمه شرًا لي في ديني، ودنياي، ومعاشي، وعاقبة أمري؛ فاصرفه عني، واصرفني عنه، وقدر لي الخير حيث كان، ثم أرضني به هذا دعاء مشروع. ثم بعد ذلك يستشير من يرى من أهل الخير من أقربائه، وأصدقائه، يستشيرهم، فإذا انشرح صدره لأحد الأمرين يمضي، فإن استمر معه التردد أعاد الاستخارة ثانيًا، وثالثًا، وهكذا حتى يطمئن قلبه، وينشرح صدره لأحد الأمرين من الفعل، أو الترك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15285/هل-يرى-المستخير-في-منامه-ما-كان-خيرا-له","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_816/nour_81602.mp3","categories":["صلاة التطوع"]},{"id":16650,"question":"ورد عن الرسول ﷺ: رحم الله امرأً صلى قبل العصر أربعًا هل تجب المداومة عليها للحصول على الرحمة، أم لا؟","title":"حكم المداومة على أربع ركعات قبل العصر","answer":"الجواب: هذا مستحب، يدل على الاستحباب، وهو حديث جيد، لا بأس به، حديث صحيح، يدل على شرعية صلاة أربع قبل العصر تسليمتين، هذا هو الأفضل، من فعل فقد أحسن، ومن لا فلا حرج، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15383/حكم-المداومة-على-اربع-ركعات-قبل-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_717/nour_71713.mp3","categories":["صلاة التطوع"]},{"id":16713,"question":"سماحة الشيخ، تقول السائلة: هل يجوز أن أصلي السنة القبلية، أو البعدية قبل أو بعد الصلاة بنصف ساعة، أو ساعة؟","title":"متى تؤدى السنن القبلية والبعدية للصلوات؟","answer":"الجواب: لا حرج، ما دام دخل الوقت، السنة القبلية، أو البعدية في الوقت لا بأس، ولو تأخرت عن الصلاة، أو تقدمت، إذا كان بعد الزوال لسنة الظهر، أو بعد الظهر قبل العصر كله طيب، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15448/متى-تودى-السنن-القبلية-والبعدية-للصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_584/58423.mp3","categories":["صلاة التطوع"]},{"id":16745,"question":"وجهوني إلى الكيفية الصحيحة لصلاة الاستخارة؟ جزاكم الله خيرًا.","title":"ما الكيفية الصحيحة لصلاة الاستخارة؟","answer":"الجواب: صلاة الاستخارة مثل بقية الصلوات، يستحب للمسلم إذا أراد أن يستخير: أن يصلي ركعتين مثل بقية الصلوات، يقرأ فيها بالفاتحة، وما تيسر مع الفاتحة، ثم يركع إلى آخره مثل بقية الصلوات، ثم بعد الفراغ يرفع يديه، ويسأل ربه أن يختار له ما هو الأفضل، يسأل ربه أنه يختار له ما هو الأفضل، والأنفع له من كذا وكذا، يبين حاجته، حاجته التي يريد إن كان زواجًا: اللهم اشرح صدري للزواج من فلانة إن كان خيرًا، وإن كان سفرًا: اللهم اشرح صدري للسفر إلى بلد كذا إن كان خيرًا لي.  وإن كان يحفظ الدعاء الذي جاء عن النبي ﷺ يقوله، النبي ﷺ قال علم المستخير الدعاء يقول: اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنك تقدر ولا أقدر، وتعلم ولا أعلم، وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر ويسميه زواجًا، أو سفرًا، أو معاملة يسمي به اللهم إن كنت تعلم أن هذا الأمر خير لي في ديني، ومعاشي، وعاقبة أمري؛ فيسره لي، ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر شر لي في ديني، ومعاشي، وعاقبة أمري؛ فاصرفه عني، واصرفني عنه، وقدر لي الخير حيث كان، ثم أرضني به. هذا الدعاء المشروع عن النبي ﷺ المحفوظ، إذا كنت تحفظه تقوله، وإلا تدعو بما تيسر، تقول: اللهم اشرح صدري لهذا السفر، أو لهذا الزواج إن كان خيرًا، اللهم اشرح صدري لمعاملة فلان، أو زيارة فلان، إن كنت تشك في فائدتها، ومصلحتها، وما أشبه ذلك، تسمي حاجتك، وتسأل ربك أنه يشرح صدرك لما هو الأصلح، والأحسن، والأنفع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15487/ما-الكيفية-الصحيحة-لصلاة-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_718/nour_71810.mp3","categories":["صلاة التطوع"]},{"id":16814,"question":"يسأل أخونا فيقول: السنة قبل، أو بعد الصلاة إذا لم يؤدها المصلي، هل عليه إثم؟","title":"حكم ترك السنن القبلية والبعدية للفرائض","answer":"الجواب: ليس عليه إثم، هي نافلة، سنة الظهر والمغرب والعشاء والعصر والفجر كلها نافلة، الواجب خمس صلوات فقط، هي الفرض: الفجر ركعتان، والظهر أربع ركعات في حق المقيم، والعصر أربع ركعات في حق المقيم، والمغرب ثلاث في حق الجميع: المقيم والمسافر، والفجر ثنتان في حق المقيم، والمسافر. أما ما معها من الصلوات فهي نافلة، سنة الظهر قبلها أربع، وبعدها ثنتان، وإن صلى أربعًا بعدها؛ فهو أفضل، وسنة العصر قبلها أربع؛ لقول النبي ﷺ: رحم الله امرءًا صلى أربعًا قبل العصر بتسليمتين. وسنة المغرب بين الأذانين ركعتان، والراتبة بعدها ركعتان، وسنة العشاء بعدها ركعتان، وسنة الفجر قبلها ركعتان، وما بين الأذانين من النوافل يقال له: سنة أيضًا، هذه كلها نوافل، كلها نوافل، من فعلها؛ فله أجر، ومن تركها؛ فلا إثم عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15558/حكم-ترك-السنن-القبلية-والبعدية-للفراىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76307.mp3","categories":["صلاة التطوع"]},{"id":16877,"question":"الرسالة التالية بعثت بها إحدى الأخوات تقول: أنا مستمعة (س. أ.أ) من صنعاء، تقول في رسالتها: أنا من ضمن الآلاف المستمعين للبرنامج المفيد (نور على الدرب) وأشكر كل من ساهم في تطوير هذا البرنامج، وأرجو منكم أن توضحوا لنا عنوان البرنامج في كل حلقة، ثم تسأل وتقول: أنا كنت أصلي ركعتين سنة بعد كل فرض، لكن قال لي بعض الأشخاص: بأن صلاة السنة بعد كل فرض يجب أن نقرأ فيها آيات معينة مثل سورة الكافرون، وغير ذلك، فأرجو من سماحة الشيخ إفادتي بشروط صلاة السنة، وأيضًا سنة الوتر، إذ أني دائمًا أحب أن أحافظ على هذه السنة، جزاكم الله خيرًا.","title":"ما المستحب في نوافل الصلاة والقراءة فيها؟","answer":"الجواب: المشروع للمؤمن، والمؤمنة بعد الصلوات الخمس اثنا عشر ركعة، كان النبي يحافظ عليها -عليه الصلاة والسلام-: أربع قبل الظهر، تسليمتين قبل الظهر، ثنتين بعد الظهر، ثنتين بعد المغرب، ثنتين بعد العشاء، ثنتين قبل صلاة الصبح، هذه الرواتب التي كان يحافظ عليها النبي ﷺ حال كونه مقيمًا في المدينة، ويشرع لكل مؤمن ومؤمنة المحافظة عليها: أربع قبل الظهر، تسليمتين، تسليمة بعد الظهر، تسليمة بعد المغرب، تسليمة بعد العشاء، تسليمة قبل صلاة الصبح، والأفضل في البيت، وإن فعلها في المسجد فلا بأس، وإن صلى أربعًا بعد الظهر؛ كان أفضل، لكن ليست راتبة، قال فيها النبي ﷺ: من حافظ على أربع قبل الظهر، وأربع بعدها؛ حرمه الله على النار.  فإذا صلى أربعًا بعد الظهر كان أفضل، وقبل العصر أربعًا، تسليمتين، لقول النبي ﷺ: رحم الله امرأً صلى أربعًا قبل العصر لكن ليست راتبة، ما كان النبي يحافظ عليها ﷺ لكنها مستحبة قبل العصر، تسليمتين؛ لقوله ﷺ: رحم الله امرأً صلى أربعًا قبل العصر ويقرأ فيها الفاتحة، وما تيسر، ليس فيها قراءة معينة، الفاتحة تكفي، ويقرأ معها ما تيسر، آيات، أو سور قصيرة، ما في بأس، ولا يتعين فيها سور معينة، ولا آيات معينة، يقرأ ما تيسر، الله يقول: فَاقْرَءُوا مَا تَيَسَّرَ مِنْهُ [المزمل:20]. والواجب الفاتحة -الحمد- والزائد سنة، إذا قرأ آيات، أو بعض السور بعد الفاتحة كله سنة، لكن بعد العصر ما يصلى بعدها، بعد الفجر لا يصلى بعدها، فأنت أيها السائل لا تصل بعد العصر، ولا بعد الفجر؛ لأنه وقت نهي؛ لأن العصر لا يصلى بعدها، والفجر لا يصلى بعدها، وفي السفر تسقط هذه الرواتب، إذا كان الإنسان مسافرًا، أو المرأة مسافرة، الأفضل عدم صلاة الرواتب هذه كلها، إلا سنة الفجر، المسافر حال سفره، الأفضل له ألا يصلي هذه الرواتب حال السفر، إلا سنة الفجر فإنه يصليها، كان النبي يصليها في السفر، والحضر -عليه الصلاة والسلام- سنة الفجر ركعتين قبلها. وهكذا الوتر، السنة أن يصليه في السفر، والحضر جميعًا، كان النبي يحافظ عليه ﷺ في الحضر، والسفر، وأقله ركعة واحدة، وإن صلى ثلاثًا أو خمسًا، أو أكثر كله طيب، وكان النبي ﷺ في الغالب يصلي إحدى عشرة، يسلم من كل ثنتين، ويوتر بواحدة، وربما صلى ثلاث عشرة في بعض الأحيان، يسلم من كل ثنتين، ويوتر بواحدة، ومن صلى أقل، أو أكثر فلا بأس. ويسن أيضًا صلاة الضحى في السفر، والحضر، صلاة الضحى سنة، ركعتين، أو أكثر، كان النبي يصليها ﷺ في بعض الأحيان، وأوصى بها بعض أصحابه، فصلاة الضحى سنة دائمًا، بعد ارتفاع الشمس إلى وقوفها، وقبل الزوال بقليل تترك، والأفضل عند شدة الضحى، الأفضل عند شدة الضحى، يعني: ارتفاع الضحى، وهي صلاة الأوابين، وفق الله الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15638/ما-المستحب-في-نوافل-الصلاة-والقراءة-فيها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_825/nour_82504.mp3","categories":["صلاة التطوع"]},{"id":16892,"question":"يقول أخونا: إنني قرأت في أحد الكتب أنه من يصلي الضحى ثنتي عشرة ركعة؛ يبنى له قصر في الجنة، فهل هذا الحديث صحيح؟ ومتى تكون صلاة الضحى؟","title":"الحكم على حديث: \"من صلى الضحى ثنتي عشرة ركعة...\"","answer":"الجواب: صلاة الضحى سنة وقربة، من ارتفاع الشمس قيد رمح إلى قرب الزوال، إلى وقوفها، وإذا اشتد الضحى يكون أفضل، وهي صلاة الأوابين كما في الحديث الصحيح، يقول النبي ﷺ: صلاة الأوابين حين ترمض الفصال يعني: حين يشتد الضحى، أو تحتر الشمس على أولاد الإبل. وهي ثنتان فأكثر، أقلها ركعتان، وإن صلى أربعًا، أو ستًا، أو ثمانًا، أو أكثر كله طيب، ليس فيها حد محدود، وقد ورد في اثنتي عشرة ركعة حديث في سنده ضعف: أن من صلاها بنى الله له قصرًا في الجنة، لكن ليس لهذا حد محدود، صلِ عشرًا، أو اثنتي عشرة، أو أربع عشرة، أو ست عشرة كله -بحمد الله- خير، ولو صلى مائة ليس فيه حد محدود والحمد لله، لكن مثنى مثنى، الأفضل مثنى مثنى؛ للحديث الصحيح عن ... يقول ﷺ: صلاة الليل والنهار مثنى مثنى اللهم صل على محمد. المقدم: اللهم صل على سيدنا محمد، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15651/الحكم-على-حديث-من-صلى-الضحى-ثنتي-عشرة-ركعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76509.mp3","categories":["صلاة التطوع","الحكم على الأحاديث"]},{"id":17084,"question":"هل يجوز للمرء أن يصلي تحية المسجد، ولو كانت الشمس مستوية في كبد السماء؟","title":"ما حكم تحية المسجد والشمس في كبد السماء؟","answer":"الجواب: نعم، متى دخل المسجد يصلي، في وقت قيام الشمس، أو بعد العصر، أو بعد الصبح؛ لأن هذين الركعتين متعلقة بدخول المسجد، ومن أسبابها دخول المسجد، فإذا دخل المسجد صلى ركعتين قبل أن يجلس مطلقًا في أي وقت، هذا هو الصواب، وهكذا لو طاف بالكعبة في مكة صلى ركعتي الطواف، ولو بعد العصر، ولو بعد الصبح؛ لأنها من ذوات الأسباب؛ لقوله ﷺ يا بني عبد مناف! لا تمنعوا أحدًا طاف بهذا البيت وصلى أية ساعة شاء من ليل أو نهار. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15911/ما-حكم-تحية-المسجد-والشمس-في-كبد-السماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83105.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":17097,"question":"هذا السائل: صادق نصر الدين مقيم في دولة الإمارات العربية المتحدة يقول: سماحة الشيخ! متى يبدأ وقت صلاة الضحى في أي وقت؟ ومتى ينتهي؟ وهل هناك أدعية معينة في هذه الصلوات؟","title":"وقت ابتداء صلاة الضحى وانتهائه","answer":"الجواب: وقت الضحى يبدأ من ارتفاع الشمس قيد رمح، إذا ارتفعت الشمس قيد رمح إلى وقوفها كلها ضحى، كلها صلاة ضحى، والأقرب والأفضل أن يصلي عند اشتداد الضحى لقوله ﷺ: صلاة الأوابين حين ترمض الفصال يعني: حين يشتد الحر على أولاد الإبل. فالمقصود: أن ما بين ارتفاع الشمس قيد رمح إلى وقوفها هذا صلاة الضحى، سواء صلى في أول الوقت، أو في آخره، أو في وسطه قبل أن تقف الشمس. المقدم: يقول: هل هناك أدعية في هذه الصلوات معينة يا شيخ؟ الشيخ: ما في شيء دعاء معين، يدعو في سجوده بما يسر الله، وهكذا يدعو في التحيات قبل أن يسلم بما يسر الله، يتخير من الدعاء أعجبه إليه، لقوله ﷺ: أما السجود فاجتهدوا في الدعاء وقوله ﷺ: أقرب ما يكون العبد من ربه وهو ساجد، فأكثروا الدعاء ومن دعاء النبي ﷺ: اللهم اغفر لي ذنبي كله، دقه وجله، وأوله وآخره، وعلانيته وسره هذا من الدعاء العظيم، ومن الدعاء الذي أرشد إليه عائشة -رضي الله عنها-: اللهم إنك عفو تحب العفو فاعف عني ومن الدعاء الحسن: اللهم إني أسألك رضاك والجنة، وأعوذ بك من سخطك والنار، اللهم إني أسألك الجنة وما قرب إليها من قولٍ وعمل، وأعوذ بك من النار وما قرب إليها من قول وعمل. يكون في السجود، أو قبل السلام، بعد التحيات، بعدما يقرأ التشهد، ويصلي على النبي ﷺ ويتعوذ بالله من أربع، يدعو بما تيسر من الدعاء قبل أن يسلم، لقوله ﷺ لما علمهم التشهد، قال: ثم ليتخير من الدعاء أعجبه إليه فيدعو وفي اللفظ الآخر: ثم ليختر من المسألة ما شاء يعني: قبل أن يسلم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15893/وقت-ابتداء-صلاة-الضحى-وانتهاىه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58902.mp3","categories":["صلاة التطوع"]},{"id":17099,"question":"إذا دخلنا المسجد، ونحن في انتظار أذان المغرب، هل نصلي تحية المسجد قبل الأذان؟ أم نجلس؟","title":"ما حكم صلاة تحية المسجد قبل أذان المغرب؟","answer":"الجواب: الأفضل الصلاة، هذا هو الصحيح؛ لأنها من ذوات الأسباب، فالسنة لمن دخل المسجد ولو في وقت النهي أن يصلي ركعتين قبل المغرب، وقبل طلوع الشمس، كل ذلك لا حرج فيه، لقول النبي ﷺ: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين متفق على صحته، ولما دخل رجل المسجد، والنبي يخطب -عليه الصلاة والسلام- وجلس قال: قم فصل ركعتين مع أن الإمام يخطب. فالحاصل: أن السنة لمن دخل المسجد، ولو في وقت النهي كالعصر، أو قبل ... الشمس.. السنة له أن يصلي ركعتين، هذا هو الصحيح من أقوال العلماء؛ لأنها من ذوات الأسباب. بخلاف الجالس في المسجد لا يقوم يصلي بعد العصر، أو الجالس بعد الفجر، لا يقوم يصلي حتى تطلع الشمس، أما الذي دخل.. جاء بعد الصلاة بعد صلاة العصر ليجلس في المسجد إلى المغرب، أو يسمع الدرس أو بعد صلاة الفجر ليسمع الدروس، هذا يصلي ركعتين قبل أن يجلس، هذا هو الصواب لعموم الأحاديث الصحيحة عن رسول الله -عليه الصلاة والسلام- ولأنه لم يقصد التشبه بالكفار، إنما صلى لأمر النبي ﷺ لصلاة الركعتين، هذا هو المعتمد، وهذا هو الصواب. نعم. وهكذا الكسوف، لو كسفت الشمس بعد العصر صلوا الناس ولو بعد العصر، في وقت النهي؛ لأن الكسوف من ذوات الأسباب، صلاة الكسوف من ذوات الأسباب، لقول النبي ﷺ: إن الشمس والقمر آيتان من آيات الله لا ينخسفان لموت أحد من الناس، ولا لحياته، فإذا رأيتم ذلك فصلوا وادعوا فأمر بالصلاة عند رؤيتهما، وهذا يعم وقت النهي، وغير وقت النهي، فإذا كسفت الشمس بعد العصر صلى الناس، هذا هو الصواب، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15909/ما-حكم-صلاة-تحية-المسجد-قبل-اذان-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_831/nour_83104.mp3","categories":["صلاة التطوع"]},{"id":17105,"question":"السائل من مصر- محافظة الغربية أبو رية زكي، يقول: سماحة الشيخ! إذا دخلت المسجد قبل أذان المغرب بقليل، فهل يجب علي صلاة ركعتين تحية للمسجد، وسنة الوضوء؟ أم الصلاة مكروهة في هذا الوقت؟","title":"هل تُشرع صلاة تحية المسجد في أي وقت؟","answer":"الجواب: الصواب أنه يستحب أن يصلي تحية المسجد، ولو كان دخوله قبل الغروب؛ لأن هذا الوقت للنهي، للصلاة المجردة، أما ذات الأسباب مثل: تحية المسجد، وسنة الوضوء.. صلاة الكسوف، لا بأس به، يصلي تحية المسجد. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15898/هل-تشرع-صلاة-تحية-المسجد-في-اي-وقت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58904.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":17111,"question":"هذه رسالة وصلت من السائل بشير حامد سوداني، ومقيم بالمملكة، يقول يا سماحة الشيخ: موضوعي هو عن صلاة التسابيح.. ما حكمها، وهل كان الرسول ﷺ يؤديها؟","title":"هل صلاة التسابيح ثابتة؟","answer":"الجواب: صلاة التسابيح غير صحيحة، غير ثابتة عن النبي ﷺ، حديثها ضعيف غير صحيح. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15917/هل-صلاة-التسابيح-ثابتة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58908.mp3","categories":["صلاة التطوع"]},{"id":17193,"question":"تقول السائلة: ما هو أول وقت لصلاة الضحى؟ وما هو آخر وقتٍ لها؟ علمًا بأنني أجهلها دائمًا، مأجورين.","title":"ما أول وقت الضحى وآخره؟","answer":"الجواب: يبدأ وقتها إذا ارتفعت الشمس قيد رمح، إذا ارتفعت الشمس قيد رمح في رأي الرائي فإنه يدخل وقت الضحى حتى تقف الشمس، يعني: حتى تتوسط السماء -الشمس- هذا الوقوف فتنتهي الصلاة حتى تزول، وقد نبه النبي ﷺ على هذا، عمرو بن عبسة وغيره. نعم. المقصود: أن وقت النهي يزول بارتفاع الشمس قيد رمح، وينتهي وقت الصلاة بوقوف الشمس في وسط السماء. نعم.","link":"https://binbaz.org.sa/fatwas/16012/ما-اول-وقت-الضحى-واخره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_590/59021.mp3","categories":["صلاة التطوع"]},{"id":17251,"question":"من أسئلتها تقول يا سماحة الشيخ: هل يجوز أن نقرأ دعاء صلاة الاستخارة في التشهد الأخير، وقبل السلام في سنن الرواتب؟","title":"وقت دعاء الاستخارة ومحله","answer":"الجواب: دعاء الاستخارة بعد الصلاة، النبي ﷺ أمر من أراد أن يستخير يصلي ركعتين، ثم يستخير، ولو قرأ عند الاستخارة في الدعاء قبل أن يسلم، أو قرأه من دون صلاة، لا حرج، لكن كونه يصلي ركعتين، ثم يأتي به أفضل، كما أمر النبي ﷺ. نعم. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16083/وقت-دعاء-الاستخارة-ومحله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59205.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":17252,"question":"هذه السائلة أختكم في الله (س. ص) من الرياض تقول سماحة الشيخ: نحن في المدرسة مجموعة من المعلمات نصلي تباعًا على سجادتين، فعندما أريد الصلاة يكون خلفي من ينتظر الانتهاء من الصلاة، فأقوم بترك بعض السنن خاصةً صلاة الظهر، وقد لا أصلي السنن حتى تستطيع الزميلات الأخريات الصلاة بعدي، فكيف أقضي هذه السنن؟ وهل أكون آثمة في ذلك؟","title":"حكم ترك السنة الراتبة لضيق مساحة المصلى","answer":"الجواب: السنن نوافل: سنة الظهر، وسنة المغرب، والعشاء، والفجر، والعصر كلها نوافل، ما في إثم، الحمد لله، لكن السنة المحافظة عليها لو صليتيها في محلك كان أحسن، ثم أختك في الله تصلي مثلك، لا تعجلي صلي الفريضة والراتبة، ثم أختك في الله كذلك تفعل مثلك، ولا تعجلي، والوقت -والحمد لله- واسع من الظهر، هذا فيه خير عظيم، ولا يشرع التساهل في هذا، بل السنة أن تصلي قبل الظهر أربع ركعات تسليمتين، وبعد الظهر تسليمة واحدة، وإن صليت تسليمتين بعد الظهر كان أفضل، لقوله ﷺ: من حافظ على أربع قبل الظهر، وأربع بعدها؛ حرمه الله على النار هذا فضل عظيم, فالأفضل أن يصلي تسليمتين قبل الظهر، وتسليمتين بعدها، الرجل والمرأة، وإذا صليتي في مكانك، ثم بعد ذلك تصلي أختك في الله، كل هذا طيب، والحمد لله. نعم. المقدم: أحسن الله إليكم وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16084/حكم-ترك-السنة-الراتبة-لضيق-مساحة-المصلى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_592/59206.mp3","categories":["صلاة التطوع"]},{"id":17330,"question":"الحاج ما هي السنن التي يستحب له أن يتقرب بها إلى الله في الصلاة في الحج؟ وهل منها صلاة السنن الرواتب، وصلاة قيام الليل، خاصة أيام منى؟","title":"المشروع من النوافل للحاج والمسافر","answer":"الجواب: أيام منى يصلي الفريضة فقط النبي ﷺ كان يصلي الفريضة، ولا يزيد عليها، إلا الفجر كان يصلي سنتها ثنتين قبلها، وإلا التهجد في الليل لا بأس التهجد بالليل المسافر، وغير المسافر، والحاج، وغير الحاج، أما بقية التطوعات تركها أفضل في أيام الحج، في يوم عرفة، وفي أيام التشريق. نعم. المقدم: وفي السفر سماحة الشيخ؟ الشيخ: والسفر كذلك الأفضل ترك الرواتب: سنة الظهر، والمغرب، والعشاء، والعصر، إلا سنة الفجر، لكن له أن يصلي الضحى سنة الضحى باقية في السفر، والتهجد بالليل كذلك، النبي صلى الضحى وهو مسافر في يوم الفتح -عليه الصلاة والسلام- صلاة الضحى مشروعة في السفر، والحضر، والوتر، كذلك التهجد بالليل، نعم، سنة الفجر كذلك. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16188/المشروع-من-النوافل-للحاج-والمسافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76909.mp3","categories":["صلاة التطوع"]},{"id":17380,"question":"سماحة الشيخ هذه السائلة تقول: هل يجوز أن أقوم بصلاة السنة وأنا جالسة؛ لأنني ربة بيت، وعندي أطفال، وأشعر بالكسل في صلاة السنة من التعب؟","title":"جواز صلاة النافلة جلوسًا","answer":"الجواب: لا حرج أن يصلي المسلم النافلة جالسًا، ولو أنه صحيح، لا بأس يصلي وهو قاعد في النافلة، أما في الفرض لا، إذا كان يستطيع يصلي قائمًًا، أما في صلاة الليل .. صلاة الضحى .. الرواتب لا بأس أن يصليها وهو جالس، ولو أنه صحيح، وإذا كان معه كسل أو ضعف وصلاها جالسًا لا بأس تقول عائشة -رضي الله عنها-: كان النبي ﷺ في آخر حياته يصلي النافلة جالسًا عليه الصلاة والسلام. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16243/جواز-صلاة-النافلة-جلوسا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_770/nour_77015.mp3","categories":["صلاة التطوع","القيام في الصلاة"]},{"id":17384,"question":"يقول هذا السائل: يا سماحة الشيخ حفظكم الله! هل يجوز قراءة الأذكار المشروعة بعد الفراغ من الصلاة، أي: بعد الراتبة، وليس بعد الفريضة مباشرة؟","title":"ما حكم قول أذكار الصلاة بعد النوافل؟","answer":"الجواب: لا. السنة بعد الفريضة، السنة أن يأتي بالأذكار الشرعية بعد الفريضة، ثم الراتبة بعد ذلك، النبي كان يفعلها إذا سلم -عليه الصلاة والسلام- هذا هو المشروع. نعم.","link":"https://binbaz.org.sa/fatwas/16240/ما-حكم-قول-اذكار-الصلاة-بعد-النوافل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59404.mp3","categories":["صلاة التطوع","الأدعية والأذكار","نصائح وتوجيهات"]},{"id":17420,"question":"ما حكم تغيير مكان السجود أثناء الصلاة؟","title":"حكم التحول بعد الفريضة لأجل صلاة النافلة","answer":"الجواب: إذا تحول بعد الفريضة عن يمينه، أو شماله لا حرج في ذلك، لكن ما عليه دليل واضح، لكن لا حرج في ذلك، وإن صلى في مكانه؛ فلا بأس، نعم.","link":"https://binbaz.org.sa/fatwas/16285/حكم-التحول-بعد-الفريضة-لاجل-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_771/nour_77116.mp3","categories":["صلاة التطوع"]},{"id":17513,"question":"ما هو قولكم -وفقكم الله- في صلاة التسابيح، هل نؤديها أم نكف عن أدائها؟","title":"صلاة التسابيح، هل نؤديها أم لا؟","answer":"الجواب: صلاة التسابيح جاء فيها أحاديث ضعيفة، والصواب أنها لا تشرع، وإنما يصلي الإنسان كالصلاة العادية التي يعرفها من فعل النبي ﷺ، وأما صلاة التسابيح كونه له يسبح فيها وهو قائم خمسة عشر مرة، يقول: سبحان الله والحمد لله، لا إله إلا الله، والله أكبر، وإذا ركع سبح عشر مرات، وإذا رفع سبح عشر مرات، وإذا سجد سبح، إلى آخره، هذه غير مشروعة؛ لأنها غير ثابتة، والصواب أن طرقها كلها ضعيفة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16443/صلاة-التسابيح-هل-نوديها-ام-لا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_837/nour_83705.mp3","categories":["صلاة التطوع"]},{"id":17532,"question":"ما حكم صلاة الحاجة؛ لأنني سمعت من بعض الإخوة بأنها سنة للحديث الوارد عن النبي ﷺ: من توضأ فأسبغ الوضوء ثم صلى ركعتين يتمها أعطاه الله ما سأل معجلًا أو مؤخرًا؟","title":"هل صلاة الحاجة سنة؟","answer":"الجواب: لا أعرف في هذا إلا صلاة التوبة، وصلاة الاستخارة، صلاة التوبة إذا أذنب ذنبًا ثم تطهر وصلى ركعتين وسأل ربه أن يغفر له وعده الله بالمغفرة، وصلاة الاستخارة إذا همَّ بأمر وأشكل عليه يستخير ربه يصلي ركعتين ثم يستخير بعد السلام يرفع يديه ويقول: اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنك تعلم ولا أعلم، وتقدر ولا أقدر، وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر ويسميه: زواج أو سفر أو نحوه خير لي في ديني، ومعاشي، وعاقبة أمري؛ فيسره لي، ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر شر لي في ديني، ومعاشي، وعاقبة أمري؛ فاصرفه عني، واصرفني عنه، وقدر لي الخير حيث كان، ثم أرضني به، هذا هو المعروف في صلاة الاستخارة، أما في كل حاجة فلا أذكر في هذا شيئًا ثابتًا. نعم.\nالمقدم: أحسن الله إليكم وأثابكم الله.","link":"https://binbaz.org.sa/fatwas/16457/هل-صلاة-الحاجة-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_775/nour_77510.mp3","categories":["صلاة التطوع"]},{"id":17573,"question":"تسأل عن صلاة التسابيح، تقول: أنا أصليها يوميًا بعد صلاة العشاء وقبل الذهاب للنوم، فهل هذا الوقت مناسب؟","title":"ما حكم صلاة التسابيح؟","answer":"الجواب: الصحيح أنها غير صحيحة، صلاة التسابيح الصحيح غير صحيحة، صلي كما كان النبي يصلي عليه الصلاة والسلام، صلى الركعات على القاعدة الشرعية، تقرأين الفاتحة وما تيسر معها، ثم تركعين وتأتين بـ سبحان ربي العظيم.. سبحان ربي العظيم، سبحانك اللهم ربنا وبحمدك، اللهم اغفر لي، سبوح قدوس رب الملائكة والروح، ثم ترفعين سمع الله لمن حمده، ربنا ولك الحمد حمدًا كثيرًا طيبًا مباركًا فيه ملء السموات وملء الأرض وملء ما بينهما وملء ما شئت من شيء بعد، ثم تسجدين، وإن زدت بعد الركوع: أهل الثناء والمجد أحق ما قال العبد وكلنا لك عبد، اللهم لا مانع لما أعطيت ولا معطي لما منعت ولا ينفع ذا الجد منك الجد، فذلك أفضل إذا تيسر ذلك؛ لأن النبي كان يفعله بعض الأحيان عليه الصلاة والسلام، المقصود أن صلاة التسبيح غير صحيحة، هذا هو الصواب فيها. نعم.\nالمقدم: جزاكم الله خيرًا، إذًا صلاة التسابيح غير صحيحة؟\nالجواب: هذا هو الصواب، نعم. كما حققه جمع من أهل العلم. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16506/ما-حكم-صلاة-التسابيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_839/nour_83907.mp3","categories":["صلاة التطوع"]},{"id":17579,"question":"رسالة من إحدى الأخوات المستمعات من الأردن رمزت إلى اسمها بالحروف (ف. ع) تسأل جمعًا من الأسئلة من بينها سؤال تقول فيه: أنا أصلي الصلاة المفروضة، أي: الفرض والسنة، وبعد الانتهاء من الصلاة المفروضة فإني أصلي أربع ركعات أو ما زاد عنها نفلًا في كل صلاة مباشرة، فهل تصلح صلاة النفل بعد الانتهاء مباشرة من الصلاة المفروضة؟ وقد ورد في كتاب فقه السنة استحباب الفصل بين الفريضة والنافلة بمقدار ختم الصلاة، نرجو توضيح ذلك مع الشكر.","title":"مقدار الفصل بين صلاة الفرض والنفل","answer":"الجواب: السنة فصل النافلة عن الفريضة، النبي ﷺ قال: إذا صلى أحدكم فلا يصل صلاة بصلاة، حتى يتكلم أو يخرج، فالأفضل للمسلم والمسلمة بعد السلام من الفريضة يقول: أستغفر الله ثلاثًا، اللهم أنت السلام ومنك السلام، تباركت يا ذا الجلال والإكرام، ثم يأتي بالذكر الشرعي لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة وله الفضل وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد، هذا مستحب بعد كل الصلوات الخمس: الظهر والعصر والمغرب والعشاء والفجر، للرجل والمرأة جميعًا. ويستحب مع هذا أيضًا أن يقول: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد يحيي ويميت وهو على كل شيء قدير، عشر مرات، بعد صلاة الفجر وبعد صلاة المغرب، هذه زيادة خاصة بهاتين الصلاتين، ويستحب له بعد ذلك في الخمس الصلوات كلها أن يقول: سبحان الله والحمد لله والله أكبر ثلاثة وثلاثين مرة، سبحان الله والحمد لله والله أكبر ثلاثًا وثلاثين مرة، الجميع تسعة وتسعون، ثم يقول تمام المائة لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، جاء في الحديث: أن العبد إذا قالها غفرت خطاياه ولو كانت مثل زبد البحر، وهذا فضل عظيم، يشرع للمؤمن والمؤمنة المحافظة على ذلك. ويستحب بعد هذا أن يقرأ آية الكرسي: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ لَهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ وَلا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255]، هذه آية الكرسي، هذه آية واحدة، آخرها: وَهُوَ الْعَلِيُّ الْعَظِيمُ وأولها: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ يستحب للمؤمن والمؤمنة أن يأتي بها بعد كل صلاة. ويستحب له أيضًا أن يقرأ قل هو الله أحد والمعوذتين بعد كل صلاة، قل هو الله أحد، قل أعوذ برب الفلق، قل أعوذ برب الناس هذه الثلاث السور، يستحب أن يقرأها المؤمن والمؤمنة بعد كل صلاة: الظهر والعصر والمغرب والعشاء والفجر، ويكررها ثلاثًا بعد الفجر وبعد المغرب، يكررها ثلاثًا بعد الفجر خاصة وبعد المغرب، ويكررها ثلاثًا عند النوم، إذا اضطجع على فراشه يقرأ التسبيح والتحميد والتهليل ثلاثًا وثلاثين مرة، ويختمها بالله أكبر مائة مرة تمامها أربعة وثلاثين تكبيرة، ثلاثة وثلاثين تحميدة، ثلاثة وثلاثين تسبيحة عند النوم، بدل (لا إله إلا الله) في آخرها (الله أكبر )، يكمل المائة بـ (الله أكبر ) أما بعد الصلاة فيكملها بـ (لا إله إلا الله) أفضل. وعند النوم يأتي بآية الكرسي أيضًا ويأتي بالسور الثلاث مكررة ثلاث مرات عند النوم، هذا أفضل، وإذا أحب أن يصلي بعد الذكر نافلة فلا بأس، لا يقوم مباشرة من يوم يسلم لا، بعد الذكر يأتي بالنافلة، والأفضل بعد الظهر أربع، وإن صلى ثنتين راتبة كفت، وإن صلى أربعًا بعد الظهر فذلك فيه فضل عظيم، لقوله ﷺ: من حافظ على أربع قبل الظهر وأربع بعدها حرمه الله على النار، وهذا فضل كبير، أما الراتبة فهي أربع قبل الظهر يعني تسليمتين، وتسليمة بعد الظهر، هذه الراتبة، ست ركعات، أربع قبلها وثنتين بعدها، يعني: تسليمتين قبلها وتسليمة واحدة بعدها، هذه يقال لها: الراتبة، كان النبي يحافظ عليها عليه الصلاة والسلام في الحضر، وإن زاد وصلى أربعًا بعد الظهر صلى تسليمتين بعد الظهر فذلك فيه فضل عظيم، لقوله ﷺ: من حافظ على أربع قبل الظهر وأربع بعدها حرمه الله على النار، رواه أهل السنن بإسناد صحيح عن أم حبيبة رضي الله عنها.\nأما بعد العصر فليس بعدها صلاة، بعد الفجر ما بعدها صلاة، لا يصلي بعدها لا ثنتين ولا أربعًا، بعد صلاة العصر وبعد صلاة الفجر ليس بعدها صلاة. أما بعد المغرب يصلي ثنتين هذا الأفضل، راتبة، وبعد العشاء ثنتين راتبة، وإن صلى أكثر فلا بأس، الراتبة ثنتان تسليمة واحدة بعد المغرب، وثنتان بعد العشاء تسليمة واحدة، للرجل والمرأة جميعًا، هذه راتبة كان يحافظ عليها النبي ﷺ، وإن صلى أكثر بعد المغرب أو بعد العشاء فالأمر واسع والحمد لله، يصلي ما شاء، لكن الراتبة ثنتان بعد المغرب وثنتان بعد العشاء. وإذا أحب أن يصلي بين المغرب والعشاء ركعات كثيرة فكله طيب، أو بعد العشاء يتهجد طويلًا كله طيب، لكن الراتبة ثنتين بعد العشاء وثنتين بعد المغرب، أما العصر فليس بعدها شيء والفجر ليس بعدها شيء، وأما الظهر فتقدم أنه يصلي بعدها ثنتين راتبة وإن صلى أربعًا فذلك أفضل كما تقدم، نسأل الله للجميع التوفيق. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا، هل تعلقون سماحتكم على قولها: الصلاة المفروضة وهي تعني السنة مع الفرض؟\nالشيخ: المفروضة: الظهر والعصر والمغرب والعشاء والفجر، هذه المفروضة، الظهر أربعًا في حق المقيم وثنتين في حق المسافر، والعصر أربع في حق المقيم وثنتين في حق المسافر، والمغرب ثلاث في حق الجميع، والعشاء ثنتين في حق المسافر وأربعًا في حق المقيم، والفجر ثنتان في حق الجميع، هذه الفرائض، والجمعة ثنتان كذلك في حق المقيمين. أما النوافل فلا حصر لها، لكن الرواتب التي يشرع أن يحافظ عليها المؤمن اثنا عشر، كان النبي يحافظ عليها عليه الصلاة والسلام في حال الحضر والإقامة: أربع قبل الظهر تسليمتين، وثنتين بعد الظهر، هذه ست، ثنتين بعد المغرب، هذه ثمان، وثنتين بعد العشاء، هذه عشر، وثنتين قبل صلاة الصبح، هذه اثنا عشر، هذه الرواتب يقال لها الرواتب، كان النبي يحافظ عليها عليه الصلاة والسلام في الحضر. أما في السفر فكان يتركها إلا سنة الفجر، كان في السفر يترك سنة الظهر والمغرب والعشاء، ولكن يصلي سنة الفجر في السفر والحضر عليه الصلاة والسلام. وأما صلاة أربع قبل العصر فهي مستحبة، ما هي براتبة لكن مستحبة، لقوله ﷺ: رحم الله امرأ صلى أربعًا قبل العصر، هذه مستحبة وليست راتبة، وإذا صلى قبل المغرب ثنتين.. قبل العشاء ثنتين أيضًا مستحبة، لقوله ﷺ: بين كل أذانين صلاة، بين كل أذانين صلاة، فإذا صلى بعد الأذان ركعتين أذان المغرب بعد أذان العشاء ركعتين أو أكثر كله مستحب طيب، لكن ليس راتب ليس من الرواتب. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16504/مقدار-الفصل-بين-صلاة-الفرض-والنفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_839/nour_83905.mp3","categories":["صلاة التطوع"]},{"id":17675,"question":"يقول السائل: بالنسبة لركعتي الوضوء هل تؤدى لكل وضوء مثل وضوء القرآن؟ أم وضوء الصلاة ...؟","title":"هل يُشرع صلاة ركعتين بعد كل وضوء؟","answer":"الجواب: إذا توضأ الإنسان يستحب له أن يصلي ركعتين سواء توضأ لقراءة القرآن أو للصلاة أو لغير ذلك، إذا توضأ يستحب له أن يصلي ركعتين في أي وقت. نعم.\nالمقدم: ولو هناك أوقات نهي يا شيخ؟\nالشيخ: ولو كان وقت نهي؛ لأنه من ذوات الأسباب، فإذا توضأ العصر أو بعد صلاة الفجر يصلي ركعتين؛ لأنها من ذوات الأسباب. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16606/هل-يشرع-صلاة-ركعتين-بعد-كل-وضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_595/59504.mp3","categories":["صلاة التطوع"]},{"id":17797,"question":"هذا السائل يقول: روى عكرمة عن ابن عباس رضي الله عنهما أن رسول الله ﷺ قال للعباس: يا عماه ألا أعطيك ألا أعلمك.. وذكر الحديث إلى أن قال: تصلي أربع ركعات.. إلى آخره حيث قال: فإن لم تفعل ففي عمرك مرة، فهل صلاة التسبيح جائزة، وهل صفتها هي ما ورد في هذا الحديث؟","title":"الحكم على حديث صلاة التسابيح","answer":"الجواب: هذا الحديث ضعيف ليس بصحيح، صلاة التسبيح حديثها ضعيف ولا يعول عليه ولا يعمل به، بل هو حديث ضعيف بسنده ومخالف ما في ذكر الأحاديث الصحيحة فلا يعول عليه ولا يعمل به كما صرح الحفاظ بذلك رحمة الله عليهم، كـأبي زرعة الرازي وأبي حاتم الرازي وغيرهم، أوضح الأئمة الحفاظ أنه غير صحيح، وأنه باطل. نعم.","link":"https://binbaz.org.sa/fatwas/16778/الحكم-على-حديث-صلاة-التسابيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59708.mp3","categories":["صلاة التطوع","الحكم على الأحاديث"]},{"id":17829,"question":"هذا سائل للبرنامج يقول: الأربع ركعات قبل صلاة العصر هل هي واردة في الحديث؟","title":"حكم صلاة أربع ركعات قبل العصر","answer":"الجواب: نعم مستحبة، لقوله ﷺ: رحم الله امرأً صلى أربعًا قبل العصر حديث لا بأس به جيد، حديث صحيح رحم الله امرأً صلى أربعًا قبل العصر تسليمتين، يسلم من كل ثنتين، هذا هو الأفضل، وهكذا أربعًا قبل الظهر، وهكذا أربعًا بعد الظهر أفضل، وإن اكتفى بعد الظهر بثنتين كفى، ولكن الأفضل أربعًا قبلها وأربعًا بعدها، لقوله ﷺ: من حافظ على أربع قبل الظهر وأربع بعدها؛ حرمه الله على النار.","link":"https://binbaz.org.sa/fatwas/16819/حكم-صلاة-اربع-ركعات-قبل-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59726.mp3","categories":["صلاة التطوع"]},{"id":17830,"question":"يقول السائل: أقوم قبل صلاة الفجر بنصف ساعة وأصلي في بيتي أربع تسليمات، تسليمتين تسليمتين، وأذهب إلى المسجد وأصلي تسليمتين ركعتي الفجر، هل هذا جائز؟","title":"حكم تحية المسجد لمن صلى راتبة الفجر في البيت","answer":"الجواب: صل في الليل ما يسر الله لك، ثنتين ثنتين، مثنى مثنى، ثم توتر بواحدة، وتصلي الراتبة في البيت أو في المسجد ثنتين، ثم الفريضة، إذا صليتها في المسجد؛ كفت عن تحية المسجد، وإن صليتها في البيت، إذا جئت المسجد تصلي تحية المسجد ثم تجلس.\nالمقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/16821/حكم-تحية-المسجد-لمن-صلى-راتبة-الفجر-في-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59727.mp3","categories":["صلاة التطوع"]},{"id":17883,"question":"هذا السائل (أ. ر. س) يقول سماحة الشيخ: إذا جاء الشخص إلى المسجد، وقت إقامة الصلاة للفجر مثلًا، فهل يصلي تحية المسجد ركعتين ويصلي ركعتين سنة الفجر بعد صلاة الفجر؟","title":"حكم صلاة سنة الفجر بعد الصلاة","answer":"الجواب: نعم. يصليها بعد الفجر أو بعد طلوع الشمس هو مخير، إن شاء صلاها بعد الفجر، وإن شاء صلاها بعد ارتفاع الشمس.","link":"https://binbaz.org.sa/fatwas/16889/حكم-صلاة-سنة-الفجر-بعد-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59813.mp3","categories":["صلاة التطوع"]},{"id":17889,"question":"هذا سائل يا فضيلة الشيخ أرسل بمجموعة من الأسئلة، يقول: ما حكم صلاة الضحى إذا صليت قبل الظهر بعشر دقائق، هل هي جائزة؟ وكم عدد الركعات لصلاة الضحى؟ ومتى يبدأ وقتها؟","title":"متى يبدأ وقت صلاة الضحى، وما عدد ركعاتها؟","answer":"الجواب: السنة إذا اشتد الضحى قبل وقوف الشمس، قبل وقوف الشمس يصليها عند شدة الضحى، هذا هو الأفضل، ودخول وقتها من حين ترتفع الشمس قيد رمح؛ دخل وقتها إلى وقوف الشمس، فلا يصلي ويذهب وقت الوقوف، والوقوف قبل الزوال بنحو ربع ساعة ثلث ساعة تقف الشمس توسط السماء، فيصليها عند شدة الضحى هذا هو الأفضل؛ لقوله ﷺ: صلاة الأوابين حين ترمض الفصال والفصال: أولاد الإبل، (حين ترمض): حين تشتد عليها الرمضاء، هذا هو الأفضل، وهي سنة؛ لأن الرسول أوصى بها أبا الدرداء وأبا هريرة ... وفعلها عليه الصلاة والسلام فهي سنة. نعم.\nالمقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16903/متى-يبدا-وقت-صلاة-الضحى-وما-عدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_598/59817.mp3","categories":["صلاة التطوع"]},{"id":18012,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمعة سارة صلاح الدين من مصر، أختنا تسأل وتقول: ما هي الفترة الزمنية التي يمكننا فيها صلاة الضحى؟","title":"الفترة الزمنية لصلاة الضحى","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالفترة التي تشرع فيها صلاة الضحى هي ما بين ارتفاع الشمس قيد رمح إلى وقوفها في وسط السماء، هذا هو وقت صلاة الضحى، والأفضل إذا اشتد الضحى؛ لقول النبي ﷺ: صلاة الأوابين حين ترمض الفصال، يعني: حين تشتد الشمس وتجد الفصال -وهي أولاد الإبل- حرارة الشمس، وإذا صلاها بعد ارتفاع الشمس مبكرًا فقد أدرك صلاة الضحى، وله أن يصليها في جميع أجزاء وقت الضحى، إلى وقوف الشمس، قبل الزوال بنحو نصف ساعة أو قريبًا من ذلك، هذا هو وقت وقوف الشمس في عين الناظر، وذلك إذا توسطت في كبد السماء، قبل أن تميل إلى الغرب، هذا يسمى وقت الوقوف، ولا يجوز للمسلم أن يتطوع فيه بالصلاة من غير ذوات الأسباب. أما ذوات الأسباب: كصلاة الكسوف وتحية المسجد وصلاة الطواف بمكة، فهذه وأشباهها من ذوات الأسباب، الصواب فيها أنه لا حرج في فعلها في وقت النهي، هذا هو الأصح من قولي العلماء، فإذا طاف بعد العصر بالكعبة المشرفة، أو بعد الصبح قبل الشمس، فلا بأس أن يصلي ركعتين، وهكذا لو كسفت الشمس عصرًا؛ شرع للمسلمين صلاة الكسوف في أصح قولي العلماء، وهكذا إذا دخل المسجد بعد الفجر أو بعد العصر للجلوس فيه لطلب العلم أو غير ذلك؛ فإن السنة أن يصلي ركعتين قبل أن يجلس؛ لقول النبي ﷺ: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين ولم يستثن وقتًا دون وقت عليه الصلاة والسلام، هذا هو الأرجح، والله ولي التوفيق. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17032/الفترة-الزمنية-لصلاة-الضحى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_599/59901.mp3","categories":["صلاة التطوع"]},{"id":18091,"question":"رسالة بعث بها أحد الإخوة المستمعين، من الرياض، يقول: مصري الجنسية، له جمعٌ من الأسئلة، في أحدها يقول: يوجد مسجدٌ قريبٌ من مسكني، أصلي فيه المغرب، والعشاء، والفجر يوميًا، ولله الحمد، فهل في كل مرة تجب علي تحية المسجد؟","title":"هل تُشرع تحية المسجد ولو تكرر الدخول قريبًا؟","answer":"الجوب: نعم، كلما دخلت المسجد، فعليك التحية، سواءً للظهر، أو العصر، أو المغرب، أو العشاء، تحية المسجد سنة مؤكدة، إذا دخلت المسجد، وأنت على وضوء، لكن إذا صليت الراتبة، راتبة الظهر مثلاً؛ تقوم مقام التحية، سنة الظهر، سنة الفجر، تجزئ عن التحية، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17126/هل-تشرع-تحية-المسجد-ولو-تكرر-الدخول-قريبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73015.mp3","categories":["صلاة التطوع"]},{"id":18095,"question":"تسأل سماحتكم التحدث عن صلاة الحاجة، هل هي مشروعة؟ وما كيفيتها؟ وهل وردت عن الرسول ﷺ؟ جزاكم الله خيرًا.","title":"هل صلاة الحاجة مشروعة؟ وما كيفيتها؟","answer":"الجواب: لا أعلم في صلاة الحاجة حديثًا يعتمد عليه، وإنما جاء الحديث في صلاة التوبة، صلاة الاستخارة: إذا هم الإنسان بأمر، واشتبه عليه أمره، يستخير الله فيه، ويصلي ركعتين، ثم يدعو الله يرفع يديه، ويدعو الله، ويستخيره بالدعاء المشهور: اللهم إني أستخيرك بعلمك، وأستقدرك بقدرتك إلى آخر الحديث. وهكذا صلاة التوبة، إذا كان عنده ذنوب، أراد يطهر، يصلي ركعتين، ثم يتوب إلى الله توبةً صادقة، والتوبة ليس من شرطها الصلاة، لكن مستحب إذا تطهر، وصلى ركعتين، وتاب توبةً صادقة، كان أقرب إلى القبول، ولو تاب وهو يمشي، أو في الطريق، أو في البيت، أو راقد، أو أي حال، التوبة مقبولة إذا تمت شروطها، إذا ندم على الماضي، وأقلع من السيئة، وعزم أن لا يعود فيها، فالله يقبلها منه، سواءً كان ماشيًا، أو واقفًا، أو راقدًا مضطجعًا في البيت، أو في الطريق، أو في أي مكان، لكن إذا توضأ، وأحسن الطهور، ثم صلى ركعتين، ثم رفع يديه إلى ربه يسأله أن يمن عليه بالتوبة، هذا أكمل وأحسن. نعم. المقدم: ما شاء الله، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17130/هل-صلاة-الحاجة-مشروعة-وما-كيفيتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_730/nour_73019.mp3","categories":["صلاة التطوع"]},{"id":18133,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من المنطقة الشرقية، تقول: (م. م. ن)، أختنا لها بعض الأسئلة، تقول في أحدها: هل تجوز صلاة النافلة بعد الفرض مباشرة؟ أو أنه يستحسن أن أسبح وأهلل، وبعد ذلك أصلي النافلة؟ وجهوني جزاكم الله خيرًا.","title":"حكم صلاة النافلة بعد الفرض مباشرة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فالسنة أن تكون النافلة بعد الذكر، إذا صلى المسلم، أو المسلمة الفريضة، يأتي بالذكر، يقول: أستغفر الله، أستغفر الله، أستغفر الله، اللهم أنت السلام، ومنك السلام، تباركت يا ذا الجلال والإكرام، لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، وإن كررها ثلاثًا فهو أفضل. ويقول: لا حول ولا قوة إلا بالله، لا إله إلا الله، ولا نعبد إلا إياه، له النعمة وله الفضل، وله الثناء الحسن، لا إله إلا الله مخلصين له الدين ولو كره الكافرون، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد، بعد كل فريضة، إلا في المغرب والفجر، يزيد مع هذا زيادة عشر مرات: لا إله إلا الله وحده لا شريك له، له الملك وله الحمد يحيي ويميت وهو على كل شيءٍ قدير عشر مرات، زيادة بعد المغرب، وبعد الفجر. وبعد هذا كله يسبح الله، ويحمده، ويكبره ثلاثًا وثلاثين، يقول: سبحان الله، والحمد لله، والله أكبر ثلاثًا وثلاثين مرة، الجميع تسعة وتسعون، ثم يقول تمام المائة: لا إله إلا الله وحده لا شريك له، له الملك، وله الحمد، وهو على كل شيءٍ قدير، كل هذا مستحب، بعد كل فريضة، ثم يأتي بآية الكرسي، يقرؤها: اللَّهُ لا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ لا تَأْخُذُهُ سِنَةٌ وَلا نَوْمٌ لَهُ مَا فِي السَّمَوَاتِ وَمَا فِي الأَرْضِ مَنْ ذَا الَّذِي يَشْفَعُ عِنْدَهُ إِلَّا بِإِذْنِهِ يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ وَلا يُحِيطُونَ بِشَيْءٍ مِنْ عِلْمِهِ إِلَّا بِمَا شَاءَ وَسِعَ كُرْسِيُّهُ السَّمَوَاتِ وَالأَرْضَ وَلا يَئُودُهُ حِفْظُهُمَا وَهُوَ الْعَلِيُّ الْعَظِيمُ [البقرة:255]، هذه آية الكرسي. ثم يقرأ: قُلْ هُوَ اللَّهُ أَحَدٌ [الإخلاص:1] و قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ [الفلق:1]، و قُلْ أَعُوذُ بِرَبِّ النَّاسِ [الناس:1]، بعد الظهر، والعصر، والعشاء مرة واحدة، بعد المغرب والفجر ثلاث مرات يقرأ السور الثلاث، ثلاث مرات، بعد المغرب والفجر، كل هذا مستحب، ثم يقوم للإتيان بالراتبة، يصلي الراتبة، سنة المغرب، سنة العشاء، سنة الظهر، بعد هذا كله، أما العصر سنتها قبلها، أربع ركعات قبلها تسليمتين، والفجر سنتها قبلها تسليمة واحدة، ركعتان، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم. الشيخ: وإياكم.","link":"https://binbaz.org.sa/fatwas/17167/حكم-صلاة-النافلة-بعد-الفرض-مباشرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73101.mp3","categories":["صلاة التطوع"]},{"id":18160,"question":"من ضمن أسئلة السائلة أم محمد من الرياض تقول: هل هناك صلاة تسمى صلاة التسبيح، وإذا كان الجواب بنعم، ما هي صفة هذه الصلاة، حيث أنني قرأت بأنها أربع ركعات هل هي ركعتان أم أكثر؟ هل هي متصلة مع بعضها أم لا؟ أفتونا مأجورين.","title":"هل صلاة التسابيح مشروعة؟","answer":"الجواب: صلاة التسبيح بدعة، أحاديثها غير صحيحة، فلا يجوز الاشتغال بها، يصلي الإنسان على ما شرع الله كما هو معروف، إذا أحب يتنفل بالصلاة المعروفة، يقرأ بالفاتحة وما تيسر معها ويركع ويسجد، يسلم من كل ركعتين في الليل والنهار هذا هو المشروع، أما صلاة التسبيح فحديثها ضعيف لا يصح. المقدم: أحسن الله إليكم، وبارك فيكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17205/هل-صلاة-التسابيح-مشروعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_781/nour_78122.mp3","categories":["صلاة التطوع","البدع والمحدثات"]},{"id":18219,"question":"تقول السائلة: هل يجوز أن نؤدي صلاة النافلة جماعة؟","title":"حكم صلاة النافلة جماعة","answer":"الجواب: نعم إذا فعله بعض الأحيان لا بأس، فقد زار النبي ﷺ بعض أصحابه، وصلى بهم جماعة عليه الصلاة والسلام، فإذا فعل إنسان زار إنسان بعض إخوانه، وصلى بهم جماعة الضحى -مثلًا- فلا بأس. أما اتخاذه عادة جماعة مرتبة لا، لكن إذا زار بعض إخوانه، وصلى بهم جماعة، أو زار بعض إخوانه، وصلوا جماعة؛ لا بأس. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17264/حكم-صلاة-النافلة-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_782/nour_78208.mp3","categories":["صلاة التطوع","صلاة الجماعة"]},{"id":18266,"question":"صلاة الاستخارة هل تصلى في حالة عزم الشخص على أمر معين؟ أو في حالة أنه لم يستقر على أي الأمرين يفعل ويستخير؟ أرجو التوضيح.","title":"وقت شرعية صلاة الاستخارة","answer":"الجواب: صلاة الاستخارة إذا صار عنده تردد في أحد الأمرين أيهما أصلح، فهذا هو وقت الاستخارة كأن يتردد هل يتزوج فلانة، أو ما يتزوجها، هل يسافر إلى كذا أم لا يسافر، هل يتجر مع فلان أو يشارك فلان أم لا، ونحو ذلك، فيصلي ركعتين ثم يدعو بعد ذلك، ويسأل ربه، أن يختار له ما هو أصلح بالدعاء المشهور الثابت عن النبي ﷺ وهو: اللهم إني أستخيرك بعلمك وأستقدرك بقدرتك، وأسألك من فضلك العظيم، فإنك تعلم ولا أعلم وتقدر ولا أقدر وأنت علام الغيوب، اللهم إن كنت تعلم أن هذا الأمر -ويسميه بعينه، أن هذا الأمر يعني: أن هذه الزوجة فلانة، أن زواجي بها- خير لي في ديني ودنياي ومعاشي وعاقبة أمري فيسر ذلك لي، ثم بارك لي فيه، وإن كنت تعلم أن هذا الأمر شر لي في ديني ودنياي ومعاشي وعاقبة أمري -أو قال: في عاجل أمري وآجله- فاصرفه عني واصرفني عنه، وقدر لي الخير حيث كان، ثم رضني به. هذا هو دعاء الاستخارة، فيقول هذا ثم يستشير من يرى أنه أهل للاستشارة في أحد الأمرين، سواء كان زواجًا أو سفرًا أو اشتراكًا.. أو غير ذلك من الأمور التي تهمه ولا يجزم فيها بشيء بل يتردد، هذا محل الاستخارة وهي سنة، والسنة مع ذلك أن يستشير أيضًا من يراه أهلًا للاستشارة بعدما يستخير، فإذا انشرح صدره لأحد الأمرين فعل ذلك، وإن لم يزل معه التردد أعاد الاستخارة مرة ثانية وثالثة .. وهكذا، حتى ينشرح صدره لأحد الأمرين. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17315/وقت-شرعية-صلاة-الاستخارة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91002.mp3","categories":["صلاة التطوع"]},{"id":18274,"question":"ما هي الأدلة على صلاة ركعتين بعد أذان المغرب، وقبل إقامة الصلاة إن كان هناك أدلة؟","title":"مشروعية صلاة ركعتين بعد أذان المغرب","answer":"الجواب: نعم، ثبت عن النبي ﷺ في صحيح مسلم من حديث عقبة بن عامر قال: «كنا نصلي قبل الإقامة ركعتين في المغرب، قال: كنا نصليها في عهد النبي ﷺ ركعتين بعد الأذان وقبل الصلاة »، وثبت في صحيح مسلم أيضًا عن أنس  قال: «كان الصحابة يصلون ركعتين بعد غروب الشمس وقبل الصلاة، وكان النبي ﷺ يراهم، ولم يأمرهم ولم ينههم». وثبت في صحيح البخاري أنه أمرهم فقال عليه الصلاة والسلام: صلوا قبل المغرب، صلوا قبل المغرب ثم قال في الثالثة: لمن شاء ليعلموا أنها غير واجبة، هذه الأحاديث الصحيحة كلها دالة على شرعية الصلاة قبل الفريضة في المغرب، يعني: بعد الأذان بعد غروب الشمس، وقبل أن تقام الصلاة، ثبت هذا من قول النبي ﷺ، ومن تقريره، أقر الصحابة على ذلك، وأمر بذلك عليه الصلاة والسلام. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17323/مشروعية-صلاة-ركعتين-بعد-اذان-المغرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91010.mp3","categories":["صلاة التطوع"]},{"id":18275,"question":"هل صلاة التسابيح سنة أم بدعة؟","title":"الصواب في حكم صلاة التسابيح","answer":"الجواب: الصواب فيها أنها غير صحيحة، وأنها بدعة غير صحيحة، قد استحبها بعض أهل العلم، وظن الحديث فيها صحيحًا، والصواب: أن الحديث ليس بصحيح، بل هو موضوع، ومنكر المتن وضعيف الإسناد لا يصح الإسناد عن النبي ﷺ ولهذا جزم جماعة من أهل العلم من الحفاظ من أئمة الحديث بأنها موضوعة غير صحيحة عن النبي ﷺ وهذا هو المعتمد، أنها غير صحيحة، بل موضوعة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17324/الصواب-في-حكم-صلاة-التسابيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91011.mp3","categories":["صلاة التطوع","البدع والمحدثات"]},{"id":18290,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول -أميمة- أختنا لها مجموعة من الأسئلة في سؤالها الأول تسأل عن القضية التالية تقول: هل يجوز أن أصلي أثناء الأذان أقصد صلاة السنة القبلية، أو صلاة الفرض دون أن أنتظر المؤذن حتى ينتهي؟","title":"حكم أداء الراتبة القبلية أثناء الأذان","answer":"الجواب: إذا دخل الوقت جازت الصلاة حتى ولو لم يؤذن، إذا دخل الوقت وعرف المؤمن أو المؤمنة دخول الوقت بزوال الشمس مثلًا أو بغروب الشمس مثلًا، أو بطلوع الفجر الفجر، صلى، ولو لم يسمع أذانًا، لكن إذا كان هناك اشتباه، فلا ينبغي التعجل، بل ينبغي التأخر حتى يتحقق دخول الوقت حتى يؤذن المؤذنون، وليس هناك حاجة إلى العجلة، يبقى الإنسان -ذكرًا كان أو أنثى- لا يستعجل حتى يتحقق، دخول الوقت أو يغلب على ظنه دخوله لأسباب واضحة، ولا ينبغي التعجل في هذا، والمرأة بحمد الله عندها سعة تبقى في بيتها ولا تعجل حتى يؤذن المؤذنون يمضي وقت بعد الأذان أيضًا حتى تحتاط لدينها، وليست مربوطة بالرجال، لكن تحتاط لدينها بالتأخر بعض الوقت بعد الأذان. أما الرجل فإنه يصلي مع الناس، ويذهب إلى المساجد فإذا كان لا يستطيع لمرضه أو كونه مقعدًا يصلي في البيت، فهذا مثل المرأة لا يعجل، حتى إن يتحقق الوقت أو يغلب على ظنه دخول الوقت بالعلامات الدالة على ذلك، ولا يستعجل. نعم. المقدم: جزاكم الله خيرًا، بالنسبة للرجل إذا دخل المسجد سماحة الشيخ أثناء تأدية الأذان هل ينتظر الأذان حتى ينتهي أو يؤدي تحية المسجد؟ الشيخ: الأفضل ينتظر، حتى يجيب المؤذن ثم يصلي ركعتين، حتى يجمع بين السنتين، يجيب المؤذن وهو واقف، فإذا أجاب المؤذن وكمل ذلك صلى ركعتين، أما إن كان يشق عليه الوقوف، يصلي ركعتين والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17341/حكم-اداء-الراتبة-القبلية-اثناء-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_912/nour_91205.mp3","categories":["صلاة التطوع"]},{"id":18297,"question":"رسالة وصلت إلى البرنامج من الجمهورية العراقية، وباعثتها الأخت: أحلام إبراهيم محمد، أختنا عرضنا مجموعة من أسئلتها في حلقة مضت، وفي هذه الحلقة تسأل وتقول: ما حكم أدائي لصلاة السنة وأنا جالسة؟","title":"حكم صلاة السنة جلوسًا","answer":"الجواب: يجوز للمسلم والمسلمة أداء النوافل عن جلوس، لكن على النص من أجر القائم كما جاءت به السنة عن النبي عليه الصلاة والسلام، فيجوز أن يصلي التهجد بالليل أو السنن الرواتب أو سنة الضحى عن جلوس، وإن كان قادرًا، لكن يكون له نصف الأجر. أما الفرائض فلابد أن يصليها قائمًا، إذا كان يستطيع إلا إذا عجز لمرض، فإنه لا بأس أن يصلي قاعدًا، وإلا فالواجب أن يصلي قائمًا، لقوله جل وعلا: وَقُومُوا لِلَّهِ قَانِتِينَ [البقرة:238]، يعني: صلوا قيامًا؛ ولقوله ﷺ في الحديث الصحيح من حديث عمران بن حصين: صل قائمًا، فإن لم تستطع فقاعدًا، فإن لم تستطع فعلى جنب، فإن لم تستطع فمستلقيًا هذا هو الترتيب في حق القادر يصلي قائمًا، فإن عجز صلى قاعدًا، فإن عجز صلى على جنبه، فإن عجز صلى مستلقيًا، هذا في الفريضة. أما في النفل فله أن يصلي قاعدًا مع القدرة، لكن يكون له النصف. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17348/حكم-صلاة-السنة-جلوسا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_912/nour_91212.mp3","categories":["القيام في الصلاة","صلاة التطوع"]},{"id":18364,"question":"يقول السائل في فقرته الأخيرة: هل تحية المسجد مشروعة في جميع الأوقات، وفي أوقات النهي يا سماحة الشيخ؟","title":"حكم تحية المسجد في جميع الأوقات","answer":"الجواب: نعم، تحية المسجد مشروعة في جميع الأوقات؛ لأنها من ذوات الأسباب، فإذا دخل المسجد بعد العصر ليجلس حتى ينتظر المغرب، أو للدروس، أو لأسباب أخرى يصلي تحية المسجد، هكذا لو جاء بعد الفجر يصلي تحية المسجد؛ لأنها من ذوات الأسباب، النبي ﷺ يقول: إذا دخل أحدكم المسجد فلا يجلس حتى يصلي ركعتين وفي اللفظ الآخر: فليركع ركعتين قبل أن يجلس. وهكذا لو كسفت الشمس بعد العصر صلي لها، نعم؛ لأنها من ذوات الأسباب، وهكذا لو طاف في مكة، طاف بالكعبة بعد العصر أو بعد الفجر فإنه يصلي ركعتين لقوله ﷺ: يا بني عبد مناف! لا تمنعوا أحدًا طاف بهذا البيت وصلى أية ساعة شاء من ليل أو نهار. نعم المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17434/حكم-تحية-المسجد-في-جميع-الاوقات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_783/nour_78325.mp3","categories":["صلاة التطوع","أوقات النهي"]},{"id":18424,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: المرسلة (س. م. م) من الرياض: أختنا مجموع أسئلتها في الواقع سماحة الشيخ يدل على ما وصل إليه شقائق الرجال من الثقافة والاهتمام بأمور الدين.كنت أستحسن أن أقرأ الأسئلة جميعًا ثم أعرضها سؤالًا سؤالًا مرة واحدة، حتى يكتشف سماحتكم ما وصل إليه شقائق الرجال في هذا البلد من الاهتمام بأمور دينهن.تسأل وتقول: ما رأيكم في الفصل بين صلاة الفريضة والنافلة لمدة قد تزيد عن النصف ساعة للذكر ولتلبية بعض أغراض الوالدين؟","title":"حكم إطالة الفصل بين صلاتي الفريضة والراتبة","answer":"الجواب: ليس في هذا بأس، كون الرجل أو المرأة يفصل بين الفريضة والنافلة، سواء كانت النافلة قبلها أو بعدها، ليس من شرط ذلك أن تتصل، إذا صلى مثلًا الظهر وأخر الراتبة نص ساعة أو ساعة فلا بأس ما دام الوقت موجودًا، وهكذا لو صلى سنة الفجر بعد الأذان بعد طلوع الفجر ثم تأخر بعض الوقت في حاجات ثم صلى الفريضة إذا كان في البيت لمرض أو امرأة، أما الرجل لا، الرجل لابد يخرج يصلي النافلة ويعتني بالجماعة، إذا كانت النافلة قبلها لا يتأخر عن الجماعة، مثل راتبة الظهر لو صلاها في البيت فليس له أن يتأخر حتى يفوت الفريضة مع الجماعة، لو صلاها في البيت أو صلاها في المسجد فالأمر واسع، لكن ليس له أن يتأخر تأخرًا يفوته الفريضة. نعم. وهكذا في البيت المرأة والمريض، ليس له أن يؤخر الفريضة تأخرًا يخرجها عن الوقت، أما تأخر لا يخرجها عن الوقت بل لحاجة فلا بأس بذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17503/حكم-اطالة-الفصل-بين-صلاتي-الفريضة-والراتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_914/nour_91401.mp3","categories":["صلاة التطوع"]},{"id":18426,"question":"هل إذا نادى علي أحد والدي وأنا في صلاة النافلة، هل أقطعها مع العلم بأنه يعلم أني أصلي؟","title":"حكم إجابة الوالدين أثناء أداء صلاة النافلة","answer":"الجواب: إذا كان الوالد أو الوالدة لا يتأثر بذلك، يعني إذا صبرت حتى تكملي فلا حاجة إلى القطع، أما إذا كانت حاجة ضرورية ويخشى من التأخير فوات المطلوب، فاقطعي النافلة، وفي قصة جريجًا عبرة، فإن جريجًا كان عابدًا من بني إسرائيل فجاءته أمه ذات يوم وهو يصلي فقالت: يا جريج ! فقال: يا رب أمي وصلاتي، ثم استمر في صلاته ولم يقطعها فذهبت أمه، ثم جاءته في يوم آخر، وهو يصلي قالت: يا جريج ! فقال: يا رب أمي وصلاتي ثم استمر في صلاته، ولم يقطعها وذهبت أمه، ثم جاءته اليوم الثالث فقالت: يا جريج ! فقال: يا رب أمي وصلاتي، ثم مضى في صلاته ولم يقطعها فذهبت وقالت عند ذلك: اللهم لا تمته حتى ينظر في وجوه المومسات، يعني: الزانيات، فأجيبت دعوتها، والنبي أقرها، ولم يستنكر هذا عليه الصلاة والسلام، ولم يقل: إنها أخطأت، ولم يقل: إنه.. بل أقرها. فدل ذلك على أن المشروع له قطعها؛ لأن النافلة تقطع عند الحاجة، بر الوالدة واجب، فإذا دعت الحاجة إلى قطعها قطعها وأجاب الوالدة أو الوالد ثم رجع إلى صلاته من أولها، النافلة أمرها أوسع، والحمد لله. فإن هذه أم جريج أجيبت دعوتها فابتلي جريج وتسلط عليه جماعة من سفهاء بني إسرائيل وقالوا لامرأة بغي أن تذهب إليه لتفتنه، فذهبت إليه وعرضت عليه نفسها للزنا، فعصمه الله منها ولم يلتفت إليها، فذهبت إلى راع فمكنته من نفسها فحملت، فلما ولدت سألوها قالوا: من أين هذا الولد؟ قالت: من جريج، كذبت عليه وقذفته بالزنا، فجاءوا وهدموا صومعته التي كان يتعبد فيها، وضربوه، فقال: ما شأنكم؟ قالوا: إنك زنيت بهذه، فقال: هاتوا الصبي، فأتوا بالصبي قال: أمهلوني وصلى ركعتين ودعا ربه أن الله ... براءته، فجاء إلى الصبي وطعن في بطنه وقال: من أبوك يا غلام؟ فقال: أبوي فلان الراعي، فأنطقه الله وهو في المهد، وهو أحد الثلاثة الذين نطقوا في المهد كما قال النبي عليه الصلاة والسلام، فبرأ الله ساحته واعتذروا إليه، وقالوا: نعيد لك صومعة من ذهب، فقال: لا، بل أعيدوها إلي من تراب -من طين- كما كانت أولًا. فالمقصود أنه وقع في هذه المصيبة بسبب أنه استمر في عدم الاستجابة لأمه، فدل ذلك على أن المشروع أن يستجيب لها، وألا يستمر لأنها قد تكون حاجتها ما ينبغي تأخيرها، فإذا وقع منه هذا اليوم فدعا رجل ولده أو امرأة ولدها وهو في النافلة فإنه إذا كان يخشى أن يغضبا عليه أو الحاجة مستعجلة فإنه يقطع. أما إذا كان يعرف أنهما لا يغضبان ولا يتأثران فإنه يتمها ثم يلبي حاجتهما. نعم. المقدم: بارك الله فيكم، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17505/حكم-اجابة-الوالدين-اثناء-اداء-صلاة-النافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_914/nour_91402.mp3","categories":["صلاة التطوع"]},{"id":18440,"question":"حسن الزهراني من جدة له مجموعة من الأسئلة، يقول في هذا  سماحة الشيخ! الأربع ركعات التي قبل العصر التي قال ﷺ فيها: رحم الله رجلًا صلى أربعًا قبل العصر هل هي قبل دخول وقت صلاة العصر؟ أم قبل الإقامة لصلاة العصر يا شيخ؟","title":"وقت الأربع ركعات التي قبل العصر","answer":"الجواب: هذه الأربع بعد دخول الوقت، وقبل الصلاة: رحم الله امرأً صلى أربعًا قبل العصر يعني: قبل صلاة الفريضة يصليها بعد دخول الوقت، بعد دخول وقت العصر يصليها قبل الصلاة، قبل الإقامة، أربع.. تسليمتين. نعم.","link":"https://binbaz.org.sa/fatwas/17525/وقت-الاربع-ركعات-التي-قبل-العصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78503.mp3","categories":["صلاة التطوع"]},{"id":18484,"question":"المستمع (ع. م. ع. الشهري) من النماص بعث برسالة ضمنها عددًا من الأسئلة، في سؤاله الأول يقول: من الملاحظ عند انتهاء الصلاة خروج بعض المصلين دون أن يؤدوا ركعتين بعد الصلاة، ويعتبرونها غير مهمة أو غير جزء من الصلاة، فما الحكم في ذلك؟","title":"حكم ترك صلاة الراتبة في المسجد","answer":"الجواب: ليس كل صلاة بعدها ركعتان، إنما هذا يشرع بعد الظهر، وبعد المغرب، وبعد العشاء، هذه الأوقات الثلاثة يشرع فيها ركعتان بعد الظهر، وركعتان بعد المغرب، وركعتان بعد العشاء، وإذا خرج من المسجد وصلاها في البيت فهو أفضل، إذا خرج من المسجد وصلاها في البيت كان أفضل؛ لأن الرسول عليه الصلاة والسلام كان يصليها في البيت، ويقول: أفضل صلاة المرء في بيته إلا المكتوبة. فإذا خرج وصلاها في البيت فهذا أفضل، أما إن تركها بالكلية فقد ترك سنة ليست واجبة فلا شيء عليه، لكنه ترك المنافسة في الخير، وترك هذه السنة التي حافظ عليها النبي عليه الصلاة والسلام. فالمشروع للمؤمن أن يأتي بهذه السنة إما في المسجد وإما في البيت، وفي البيت أفضل، أما أن يتركها بالكلية فهذا لا ينبغي من المؤمن، ولا يشرع له، بل المشروع له والأفضل له أن يعتني بهذه النوافل المتأكدة، وأن يحافظ عليها كما حافظ عليها المصطفى عليه الصلاة والسلام، وإن صلى بعد الظهر أربعًا فهو أفضل، أما المغرب فراتبتها اثنتان والعشاء كذلك، وكلها في البيت أفضل كما تقدم. نعم.","link":"https://binbaz.org.sa/fatwas/17576/حكم-ترك-صلاة-الراتبة-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_866/nour_86612.mp3","categories":["صلاة التطوع"]},{"id":18486,"question":"السائل الذي بعث بمجموعة من الأسئلة محمد عوض له هذا السؤال، يقول في سؤاله الأول: هل يجوز جمع النوافل في ركعتين مثل أن نقول: أنوي صلاة ركعتين قبل صلاة العشاء، وتحية المسجد، وسنة الوضوء؟","title":"حكم جمع النوافل في ركعتين بنية واحدة","answer":"الجواب: نعم، إذا صلى ركعتين سنة تحية المسجد سدت عن الوضوء، إذا توضأ وصلى ركعتين تحية المسجد أو الراتبة حصل المطلوب والحمد لله، وكذلك الفجر، لو توضأ لصلاة الفجر ثم صلى سنة الفجر سدت عن سنة الوضوء يكفي؛ لأنها سدت عن الوضوء وعن سنة الفجر. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17584/حكم-جمع-النوافل-في-ركعتين-بنية-واحدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_785/nour_78524.mp3","categories":["صلاة التطوع"]},{"id":18602,"question":"السائلة التي رمزت لاسمها بـ (ع. ع) تقول: هل تجوز الاستخارة بدون صلاة ركعتين أو بدون وضوء؟ وهل يجوز للحائض والنفساء أن تستخير؟","title":"حكم الاستخارة بدون صلاة وكيفيتها للحائض والنفساء","answer":"الجواب: نعم، تجوز الاستخارة، تستحب، تستحب الاستخارة ولو بدون صلاة، كونه يسأل ربه، ويستخير ربه، سواء كانت امرأة أو رجل، سواء كانت حائض أو ما هي بحائض كل ذلك لا بأس به، لكن إذا كان بعد الصلاة يكون أفضل، تكون الاستخارة بصلاة عملًا بالسنة، فيصلي ركعتين، ثم يسأل ربه، ويستخير ربه، سواء رجل أو امرأة، لكن إذا كانت حائضًا، أو كان الأمر مستعجلًا واستخار بدون صلاة فلا بأس، يسأل ربه، والحمد لله، الله يقول: ادْعُونِي أَسْتَجِبْ لَكُمْ[غافر:60] والاستخارة دعاء، توجه إلى الله، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17725/حكم-الاستخارة-بدون-صلاة-وكيفيتها-للحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78705.mp3","categories":["صلاة التطوع","قضايا المرأة"]},{"id":18604,"question":"السائلة التي رمزت لاسمها بـ (ع. ع) تقول: هل تجوز الاستخارة بدون صلاة ركعتين أو بدون وضوء؟ وهل يجوز للحائض والنفساء أن تستخير؟","title":"حكم الاستخارة بدون صلاة وكيفيتها للحائض والنفساء","answer":"الجواب: نعم، تجوز الاستخارة، تستحب، تستحب الاستخارة ولو بدون صلاة، كونه يسأل ربه، ويستخير ربه، سواء كانت امرأة أو رجل، سواء كانت حائض أو ما هي بحائض كل ذلك لا بأس به، لكن إذا كان بعد الصلاة يكون أفضل، تكون الاستخارة بصلاة عملًا بالسنة، فيصلي ركعتين، ثم يسأل ربه، ويستخير ربه، سواء رجل أو امرأة، لكن إذا كانت حائضًا، أو كان الأمر مستعجلًا واستخار بدون صلاة فلا بأس، يسأل ربه، والحمد لله، الله يقول: ادْعُونِي أَسْتَجِبْ لَكُمْ[غافر:60] والاستخارة دعاء، توجه إلى الله، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17725/حكم-الاستخارة-بدون-صلاة-وكيفيتها-للحاىض-والنفساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_787/nour_78705.mp3","categories":["صلاة التطوع","قضايا المرأة"]},{"id":18743,"question":"رسالة أخرى وصلت إلى البرنامج من أبها، وبعثت بها إحدى الأخوات من هناك تقول: أختكم السائلة (م.ع) سألت في حلقة مضت بعضًا من الأسئلة، وفي هذه الحلقة تسأل وتقول: قرأت في كتاب تنزيه الشريعة المرفوعة: \"صلاة التسبيح\" وهي أربع ركعات، ويقرأ في كل ركعة الفاتحة، وسورة صغيرة، ثم يسبح في الركعة الأولى خمسًا وسبعين تسبيحة في القيام، وفي الركوع والسجود، وفي الركعة الثانية هكذا، وفي الأربع الركعات ثلاثمائة تسبيحة، هل هذا حديث صحيح؟ وما رأيكم فيما أورده صاحب ذلكم الكتاب؟","title":"ما مدى صح حديث صلاة التسبيح؟","answer":"الجواب: صلاة التسبيح مشهورة عند أهل العلم، وقد تنازع العلماء في صحتها، فمن أهل العلم من عمل بها وصححها؛ لما في ذلك من الأجر العظيم الذي ذكره النبي ﷺ وغفران السيئات، ومن أهل العلم من ضعف الرواية، ولم يصححها، وذكر أنها رواية شاذة، وحديث شاذ مخالف للأحاديث الصحيحة، وهذا القول الثاني هو أصح، أن صلاة التسبيح حديثها شاذ غير صحيح، وأن المعتمد قول من قال: إنها غير صحيحة، وأنها موضوعة لا أساس لها من الصحة، وأسانيدها كلها معلولة، ومتنها شاذ منكر مخالف للأدلة الشرعية الثابتة عن رسول الله -عليه الصلاة والسلام-. فإن صلاته في الليل والنهار محفوظة -عليه الصلاة والسلام- وقد رواها الثقات والأثبات في الصحيحين وغيرهما، ولم يحفظ عنه -عليه الصلاة والسلام- أن صلى هذه الصلاة؛ فوجب على أهل الإيمان أن يردوا ما خالف الأدلة المعروفة إلى الأدلة المعروفة، فالأدلة المعروفة الثابتة دالة على صفة صلاته -عليه الصلاة والسلام- وأن ليس فيها هذه التسبيحات المذكورة، بل هذه انفردت بها هذه الرواية، فالصواب أنها شاذة المتن ضعيفة الأسانيد؛ فلا ينبغي التعويل عليها، ولا العمل بها، وإن صححها بعض المتقدمين، وبعض المتأخرين، لكن العمدة في هذا أن كل متن يخالف الأحاديث الصحيحة -وإن صح سنده- فإنه يعتبر شاذًا، فكيف إذا كان الإسناد معلولًا. قد قال الأئمة في مصطلح الحديث: إن الأحاديث المختلفة يرجع فيها أولًا إلى الجمع -إذا تيسر الجمع- فإذا أمكن الجمع جمع بينها، وقبلت كلها، فإن لم يتيسر الجمع ولم تتوافر شروطه؛ رجع إلى النسخ إذا علم النسخ، إذا علم الناسخ، إذا علم الأخير من المتقدم؛ صار الأخير ناسخًا للمتقدم عند تعذر الجمع، فإذا لم يعلم المتأخر من المتقدم، ولم تتوافر شروط النسخ، ولا شروط الجمع؛ انتقل إلى أمر ثالث، وهو الترجيح. وهذه الصلاة ليس فيها ما يدل على التأريخ، وأنها متأخرة عن غيرها، وليس فيها ما يدل على أنها سنة استعملها النبي ﷺ سابقًا ولاحقًا، وليس فيها ما يقتضي الجمع بينها وبين غيرها؛ فتعين الأمر الثالث وهو: أنها غير صحيحة، وأنها شاذة مخالفة للأحاديث الصحيحة الثابتة عن رسول الله ﷺ، ومخالفة لسنته المعروفة عنه -عليه الصلاة والسلام- في ليله ونهاره مدة حياته -عليه الصلاة والسلام-، فلم يحفظ عنه أنه فعلها مرة واحدة -عليه الصلاة والسلام- ولم يعرف عنه -عليه الصلاة والسلام- ما يدل على أنها سنة متبعة في أحاديث صحيحة؛ فعلم بذلك أنها شاذة، وأنها مختلقة، وأنه لا أساس لها في الأحاديث الصحيحة الثابتة عن رسول الله -عليه الصلاة والسلام-، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17872/ما-مدى-صح-حديث-صلاة-التسبيح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87503.mp3","categories":["صلاة التطوع","البدع والمحدثات"]},{"id":18786,"question":"ننتقل إلى رسالة أخرى وصلت من العراق، وباعثتها إحدى الأخوات المستمعات، تقول: أحلام إبراهيم محمد، أختنا عرضنا جزءًا من أسئلتها في حلقة مضت، وفي هذه الحلقة تسأل وتقول: هل يجوز أن أصلي سنة قبلية قبل الأذان بنصف ساعة أو ربع ساعة أو أكثر أو أقل؟أرجو توجيهي، جزاكم الله خيرًا، ولا سيما في صلاة المغرب.","title":"حكم صلاة السنن القبلية للفرائض قبل الأذان","answer":"الجواب: السنة القبلية تكون بعد دخول الوقت، سنة المغرب القبلية، والعصر القبلية، والظهر القبلية، والفجر والعشاء كلها بعد دخول الوقت، أما الصلاة قبل دخول الوقت، فهذه من باب التطوع، الصلاة قبل دخول الوقت، هذا من باب التطوع، فلا بأس أن يصلي الإنسان في أوقات ليس فيها نهي كما لو صلى الضحى قبل وقوف الشمس، أو صلى قبل العصر قبل دخول الوقت هذا يكون تطوعًا. أما الصلاة قبل المغرب فهذا وقت نهي لا يصلي قبل المغرب تطوعًا إلا لأسباب مثل صلاة الكسوف، مثل صلاة الطواف لمن طاف بعد العصر، أو تحية المسجد، كذلك الصلاة قبل العشاء تطوع لا بأس به؛ لأنه ليس وقت نهي، وإنما تكون سنة العشاء إذا كان بعد دخول الوقت بعد غروب الشفق تكون من سنة العشاء القبلية، وهي ليست راتبة، السنة قبل المغرب وقبل العشاء لا تسمى راتبة، ولكنها سنة؛ لأن الرسول ﷺ قال: صلوا قبل المغرب، صلوا قبل المغرب ثم قال في الثالثة: لمن شاء وقال: بين كل أذانين صلاة بين كل أذانين صلاة وقال في الثالثة: لمن شاء فدل ذلك على استحباب الصلاة قبل المغرب لهذه الأحاديث، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17913/حكم-صلاة-السنن-القبلية-للفراىض-قبل-الاذان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_906/nour_90606.mp3","categories":["صلاة التطوع"]},{"id":18867,"question":"يسأل سماحتكم عن الفاصل الزمني بين فريضة الصبح وسنتها، جزاكم الله خيرًا، وهل هناك أمر محظور فيما إذا قدم الفرض على النافلة؟","title":"الفاصل الزمني بين فريضة الصبح وراتبتها","answer":"الجواب: السنة أن يقدم النافلة بعد طلوع الفجر، ركعتين سنة الفجر، ولو طال الفصل بينها وبين الفريضة لا يضر، سواءً قربت من الفريضة أو بعدت، ما دام بعد طلوع الفجر، السنة أن يصلي ركعتين، ثم يصلي الفريضة، فلو أخرها صلاها بعد الفريضة، أو بعد طلوع الشمس، لكن السنة أن يقدمها، السنة للمؤمن أن يقدم سنة الفجر، كما كان النبي يفعل -عليه الصلاة والسلام-، ثم يصلي الفريضة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18007/الفاصل-الزمني-بين-فريضة-الصبح-وراتبتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_736/nour_73611.mp3","categories":["صلاة التطوع"]},{"id":18913,"question":"من الجمهورية العربية السورية، هذه رسالة بعث بها أحد الإخوة من هناك يقول: راوي العبد الله من دير الزور أخونا له مجموعة من الأسئلة في سؤاله الأول يقول: كثيرًا من الناس في قريتنا متجادلون على سنة العشاء القبلية، بعضهم يقول: مؤكدة والآخر يقول: إنها غير مؤكدة، فأرجو من سماحة الشيخ توضيح هذا الأمر.","title":"حكم السنة القبلية لصلاة العشاء","answer":"الجواب: غير مؤكدة، والحمد لله، من شاء صلى، ومن شاء ترك بين الأذان والإقامة، يقول النبي ﷺ: بين كل أذانين صلاة، بين كل أذانين صلاة لمن شاء فمن شاء صلاهما، ومن شاء تركهما بين الأذان والإقامة في العشاء، وهكذا في المغرب. أما بين الأذان والإقامة في الظهر فهي مؤكدة، يصلي أربع ركعات تسليمتين؛ لأن الرسول ﷺ كان يصلي أربع ركعات قبل الظهر، يصلي ثنتين ثنتين -عليه الصلاة والسلام- وهي من الرواتب، أربع ركعات قبل الظهر من الرواتب. أما العصر فمستحبة، وليست مؤكدة، في الحديث: رحم الله امرأً صلى أربعًا قبل العصر والسنة أن يصلي ثنتين ثنتين صلاة الليل والنهار مثنى مثنى قاله النبي -عليه الصلاة والسلام- ولا ينبغي التجادل في هذا، هذه أمور مستحبة ونوافل، لا ينبغي فيها التجادل، بل ينبغي فيها المذاكرة والبحث بين الإخوان، مع طلبة العلم حتى يستفيدوا، فالرسول -عليه الصلاة والسلام- قال: بين كل أذانين صلاة، بين أذانين صلاة فإذا صلى ركعتين بين أذان المغرب وصلاة المغرب، بين أذان العشاء وصلاة العشاء، بين أذان العصر وصلاة العصر، أو صلى أربعًا كل ذلك لا بأس به. أما الظهر فلها راتبة قبلها، وهي أربع ركعات، تقول عائشة -رضي الله عنها-: «كان النبي ﷺ لا يدع أربعًا قبل الظهر» يعني: تسليمتين، وأما بعد الظهر فركعتان راتبة كان يحافظ عليها -عليه الصلاة والسلام- ومن صلى أربعًا فهو أفضل بعد الظهر أيضًا، وهكذا بعد العشاء ركعتين، وبعد المغرب ركعتين، وقبل صلاة الفجر ركعتين، يعني: يصلي ركعتين قبل صلاة الفجر، هذه كلها رواتب، كان الرسول يحافظ عليها -عليه الصلاة والسلام- فالجميع اثنا عشر ركعة هذه رواتب كان المصطفى -عليه الصلاة والسلام- يحافظ عليها، وهي أربع قبل الظهر وثنتان بعدها، وثنتان بعد المغرب، وثنتان بعد صلاة العشاء، وثنتان قبل صلاة الصبح، والأفضل فعلها في البيت، وإن فعلها في المسجد فلا بأس، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18053/حكم-السنة-القبلية-لصلاة-العشاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_923/nour_92313.mp3","categories":["صلاة التطوع"]},{"id":18945,"question":"هذا السائل أحمد من اليمن يقول: هل يصح تأخير سنة العشاء مع الوتر إلى ما قبل الفجر؟","title":"حكم تأخير سنة العشاء مع الوتر إلى قبل الفجر","answer":"الجواب: الأفضل أن يصليها قبل نصف الليل، فإن أخرها صح؛ لأنه وقت ضرورة، لكن الأفضل أن يصليها قبل نصف الليل.","link":"https://binbaz.org.sa/fatwas/18140/حكم-تاخير-سنة-العشاء-مع-الوتر-الى-قبل-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88240.mp3","categories":["صلاة التطوع"]},{"id":18968,"question":"سائل للبرنامج يقول: سماحة الشيخ، هناك البعض من الناس بعد الصلاة -صلاة الفريضة في المساجد- يتبادل المسلمون الأماكن، حتى يصلوا السنة أو النافلة، حيث يعتقد البعض أن هذا لأجل أن تشهد له الأرض، هل هذا وارد؟","title":"حكم تبادل الأماكن بعد الفريضة لأداء السنة","answer":"الجواب: ليس له أصل صحيح يعتمد، فيه حديث ضعيف، لكن يصلي في محله، والحمد لله، يصلي الراتبة في محله، والحمد لله.","link":"https://binbaz.org.sa/fatwas/18098/حكم-تبادل-الاماكن-بعد-الفريضة-لاداء-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_882/nour_88222.mp3","categories":["صلاة التطوع"]},{"id":19067,"question":"سماحة الشيخ الأخت السائلة تقول: أرجو من سماحتكم بيان السنن الراتبة وغير الراتبة والنوافل وتوضيح هذا الأمر؛ لأنه يلتبس علينا ما عدد هذه الصلوات مأجورين؟","title":"ما السنن الراتبة وغير الراتبة؟","answer":"الجواب: السنة الراتبة اثنا عشر: ثنتين قبل صلاة الصبح، وأربع قبل الظهر، وثنتين بعدها، وثنتين بعد المغرب، وثنتين بعد العشاء، اثنا عشر، وإن صلى بعد الظهر أربعًا كما صلى قبلها أربع فهو أفضل؛ لقوله ﷺ: من حافظ على أربع قبل الظهر وأربع بعدها حرمه الله على النار ويستحب له أن يصلي أربعًا قبل العصر تسليمتين؛ لقول النبي ﷺ: رحم الله امرأً صلى أربعًا قبل العصر، ويستحب أن يصلي ركعتين بين الأذان والإقامة بعد أذان المغرب وبعد أذان العشاء ركعتين قبل الإقامة؛ لقوله ﷺ: بين كل أذانين صلاة بين كل أذانين صلاة، ثم قال في الثالثة لمن شاء، قال: صلوا قبل المغرب صلوا قبل المغرب ثم قال في الثالثة لمن شاء. ويستحب صلاة الضحى ركعتين أو أكثر أو أربع أو ست أو ثمان أو أكثر سنة صلاة الضحى والتهجد بالليل يصلي ما تيسر من الليل ثلاث أو خمس أو سبع أو أكثر، والأفضل إحدى عشرة، أو ثلاث عشرة كما فعل النبي ﷺ في الليل يسلم من كل ثنتين كما فعل النبي ﷺ لقوله ﷺ: صلاة الليل مثنى مثنى، فإذا خشي أحدكم الصبح صلى ركعة واحدة توتر له ما قد صلى، وفق الله الجميع. نعم. المقدم: اللهم آمين، أحسن الله إليكم يا شيخ.","link":"https://binbaz.org.sa/fatwas/18263/ما-السنن-الراتبة-وغير-الراتبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88327.mp3","categories":["صلاة التطوع"]},{"id":19071,"question":"من أسئلتها يا سماحة الشيخ! حفظكم الله: تقول: صلاة قضاء الحاجة هل تصلى بالدعاء المذكور؟ أم هي بدعة؟ وما هو التناسب بين صلاة الحاجة، وحديث الرسول ﷺ بأنه إذا أخذ أمر لجأ إلى الصلاة، وهل تصلى قضاء الحاجة؟","title":"صلاة قضاء الحاجة هل هي بدعة؟","answer":"الجواب: كان النبي ﷺ إذا حزبه أمر فزع إلى الصلاة، كما قال الله جل وعلا: وَاسْتَعِينُوا بِالصَّبْرِ وَالصَّلاةِ [البقرة:45]، فإذا صلى الإنسان واستعان بربه في سجوده أو في آخر الصلاة على الحاجات التي تهمه كله طيب. ولا أعلم حديثًا صحيحًا باسم صلاة الحاجة، لكن هذا يظهر من قوله جل وعلا: اسْتَعِينُوا بِالصَّبْرِ وَالصَّلاةِ [البقرة:45]، ومن الحديث كان النبي ﷺ إذا حزبه أمر فزع إلى الصلاة، وقال ﷺ: ما من عبد يتوضأ فيحسن الطهور، ثم يستغفر من ذنبه إلا غفر الله له،  ما من عبد يتوضأ فيحسن الطهور ثم يصلي ركعتين ثم يستغفر الله غفر الله له. فالمقصود أنه إذا استعان بالصلاة في طلب ربه الحاجة أو في التوبة إلى الله كان هذا من أسباب المغفرة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18257/صلاة-قضاء-الحاجة-هل-هي-بدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88324.mp3","categories":["صلاة التطوع"]},{"id":19073,"question":"نستعرض رسالة السائلة أختكم في الله الشيماء من جمهورية مصر العربية لها مجموعة من الأسئلة تقول يا سماحة الشيخ: هل صلاة التسابيح لا تصلى؛ لأن حديث هذه الصلاة مرفوع عن الرسول ﷺ أم يصح لنا أن نصليها، ولقد صليت ذلك وأنا في المسجد الحرام، فهل أستمر في صلاتي؟ أم أتوقف عن ذلك مأجورين؟","title":"هل صلاة التسابيح مشروعة؟","answer":"الجواب: صلاة التسابيح حديثها ضعيف فلا ينبغي لك أن تفعليها، حديثها ضعيف لا يصح وصل كالصلاة العادة من غير زيادة بالحمد بالفاتحة وما تيسر من الآيات والركوع والسجود كما تفعلي في الفرائض. نعم.","link":"https://binbaz.org.sa/fatwas/18255/هل-صلاة-التسابيح-مشروعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_883/nour_88323.mp3","categories":["صلاة التطوع"]},{"id":19149,"question":"يقول: قرأت في بعض الكتب عن الرسول عليه الصلاة والسلام أنه أوصى بالصلاة قبل الظهر وقبل العصر أربعًا أربعًا، فهل هذا قوي، وكيف تكون هذه الركعات الأربع، هل تكون اثنتين اثنتين؟ أم أربع متصلة؟ وإذا كانت اثنتين اثنتين فهل تدخل فيها تحية المسجد؟ وجهوني جزاكم الله خيرًا.","title":"السنة القبلية في الظهر والعصر","answer":"الجواب: نعم، كان ﷺ يصلي قبل الظهر أربعًا، كان يصلي قبلها أربعًا ثنتين ثنتين يسلم من كل ثنتين، وبعد الظهر ركعتين راتبة، ومن صلى أربعًا فهو أفضل بعد الظهر؛ لقوله ﷺ: من حافظ على أربع قبل الظهر وأربع بعدها حرمه الله على النار، ويذكر عنه أنه يقول ﷺ: رحم الله امرأً صلى أربعًا قبل العصر. فالأفضل قبل العصر أربعًا، لكن ليست راتبة بل مستحبة، يسلم من كل ثنتين؛ لقول النبي ﷺ: صلاة الليل والنهار مثنى مثنى يعني: يسلم من كل ثنتين، هذا هو الأفضل هذا هو السنة. بل يتعين في الليل؛ لأن الأحاديث صحيحة: صلاة الليل مثنى مثنى، وهو في معنى الأمر، أما في النهار ففيه خلاف بين أهل العلم، والذي ينبغي أيضًا أن يصلي ثنتين ثنتين في النهار أيضًا؛ لأن زيادة: (والنهار) زيادة صحيحة، رواها الخمسة أهل السنن الأربع والإمام أحمد بإسناد جيد، عنه ﷺ أنه قال: صلاة الليل والنهار مثنى مثنى. وإذا صلى أربعًا قبل الظهر أو أربعًا قبل العصر كفت عن تحية المسجد، إذا صلى أربعًا قبل الظهر فقد أدى الراتبة، وتكفيه عن تحية المسجد، وهكذا إذا صلى أربعًا قبل العصر كفت عن تحية المسجد، وهكذا إذا صلى ركعتين قبل الفجر ناويًا بها الراتبة؛ كفت عن تحية المسجد. نعم. المقدم: جزاكم الله خيرًا وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18321/السنة-القبلية-في-الظهر-والعصر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_737/nour_73711.mp3","categories":["صلاة التطوع"]},{"id":19195,"question":"يسأل أخونا ويقول: هل صح عن النبي صلى الله عليه وآله وسلم صلاة سنة الوضوء، وما عدد ركعاتها؟ وهل إذا صلى المصلي نافلة الظهر مثلًا هل تسقط عنه ركعتا الوضوء؟ جزاكم الله خيرًا.","title":"أحكام سنة الوضوء","answer":"الجواب: ثبت عنه ﷺ أنه توضأ فأحسن الوضوء، ثم صلى ركعتين، ثم قال: من توضأ نحو وضوئي هذا ثم صلى ركعتين لا يحدث فيها نفسه غفر له ما تقدم من ذنبه، هذا ثابت عنه ﷺ من حديث عثمان، ومن أحاديث أخرى، وعددها ركعتان سنة الوضوء ركعتان. وثبت أيضًا أنه ﷺ رأى بلالًا أمامه في الجنة لما دخل الجنة لما عرج به إلى السماء فسأله ﷺ سأل بلالًا قال: إني سمعت صوت قدميك دف نعليك أمامي في الجنة فأي عملك أرجى؟ قال: ما أحدثت إلا توضأت، ولا توضأت إلا صليت ركعتين»  فصلاة الركعتين سنة وقربة بعد الوضوء. وإذا صلى تحية المسجد، أو راتبة الظهر، أو راتبة الفجر؛ قامت مقام سنة الوضوء حصل بها المقصود، تكون عن هذا وعن هذا توضأ، ثم صلى ركعتين سنة الفجر، أو تحية المسجد، أو سنة الضحى حصل بها المقصود عن هذا وعن هذا، والحمد لله. المقدم: الحمد لله جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18411/احكام-سنة-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_799/nour_79903.mp3","categories":["صلاة التطوع"]},{"id":19318,"question":"من الإمارات العربية المتحدة، الأخت عائشة عبد القادر، بعثت برسالة تسأل سماحتكم فيها وتقول: سمعت أن هناك صلاة تسمى صلاة التسبيح، والمؤدي لهذه السنة له أجر كبير ومغفرة للذنوب، وقرأت دليلًا على ذلك مما ورد عن الرسول عليه الصلاة والسلام، ولكن بعض الناس يقولون بأنها بدعة؛ فأرجو من سماحتكم بيان صحة القول، جزاكم الله خيرًا؟","title":"هل صلاة التسبيح بدعة؟","answer":"الجواب: صلاة التسبيح الصواب فيها أنها غير ثابتة وغير مشروعة، وحديثها ضعيف من جميع طرقه؛ فلا ينبغي للمؤمن أن يستعملها، وإن كان بعض إخواننا من طلبة العلم قد صححها، لكن الصحيح أنها ضعيفة غير صحيحة، حديثها ضعيف وهو شاذ ومنكر ومخالف للأدلة الشرعية؛ فلا يجوز استعمالها ولا الدعوة إليها ولا اعتقاد أنها سنة، بل هي بدعة مخالفة للأحاديث الصحيحة مخالفة لما شرعه الله .","link":"https://binbaz.org.sa/fatwas/18518/هل-صلاة-التسبيح-بدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_739/nour_73915.mp3","categories":["صلاة التطوع"]},{"id":19334,"question":"من الجمهورية التونسية هذه رسالة بعث بها أخونا محمد الصالح الغربي الأخ محمد يسأل ثلاثة أسئلة، في سؤاله الأول يقول: أيهما تصلي أولاً صلاة الصبح الفريضة أو سنة الفجر وذلك بعد طلوع الشمس إذا غلبك النوم مع العلم أن المصلي منفرد؟","title":"وقت راتبة الفجر قبل الفريضة أداء وقضاء","answer":"الجواب: إذا غلب النوم على الإنسان، ولم يستيقظ إلا بعد الشمس يبدأ بالسنة سنة الفجر، ثم يصلي الفريضة، وقد ثبت عن النبي عليه الصلاة والسلام أنه في بعض أسفاره نام هو وأصحابه عن الفجر فلم يستيقظوا إلا بحر الشمس، فلما استيقظوا أمرهم أن يقودوا رواحلهم عن مكانهم وقال: إنه موطن حضرنا فيه الشيطان وتوضأ، وتوضئوا، وأمر بلال فأذن، وصلى سنة الراتبة، ثم صلى الفريضة عليه الصلاة والسلام، فهذا هو السنة أن يبدأ بالسنة الراتبة ركعتين، ثم يصلي الفريضة. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18542/وقت-راتبة-الفجر-قبل-الفريضة-اداء-وقضاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_941/nour_94106.mp3","categories":["صلاة التطوع"]},{"id":19350,"question":"ما حكم الإمام الذي لا يصلي تحية المسجد؟","title":"حكم تحية المسجد للإمام","answer":"الجواب: الإمام تكفيه الفريضة، إذا جاء وشرع في الفريضة كفته، كان النبي ﷺ يأتي ويبدأ بالفريضة، ما يصلي تحية المسجد، ينصى محل الإمامة فيصلي عليه الصلاة والسلام، فالإمام إذا قصد الصلاة ولم يجلس في المسجد إنما جاء ليؤدي الفريضة بدأ بها وكفت، وهكذا الذي جاء والإمام قد دخل في الصلاة وقد أقيمت الصلاة تكفيه الفريضة عن تحية المسجد. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18543/حكم-تحية-المسجد-للامام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_941/nour_94107.mp3","categories":["صلاة التطوع"]},{"id":19363,"question":"ننتقل إلى رسائل أخرى ومواضيع أخرى رسالة وصلت إلى البرنامج من البحرين باعثها أحد الإخوة المستمعين يقول: أنا عبد النور إسماعيل علي يسأل سماحة الشيخ عن النوافل التي يستحب للمرء أن يلازمها قبل وبعد الفرائض، وهل هناك عدد معين جزاكم الله خيرًا، ذلكم أنه يصلي خمس ركعات أحيانًا قبل الظهر وأحيانًا أربع ركعات لكنه في هذه الرسالة يرجو التوجيه الرشيد؟ جزاكم الله خيرًا.","title":"ما السنن الراتبة والمستحبة للصلوات؟","answer":"الجواب: النوافل المشروعة مع الفرائض التي كان النبي يحافظ عليها عليه الصلاة والسلام ويلازمها اثنتا عشرة ركعة، هذه رواتب وتسمى نوافل كان الرسول ﷺ يحافظ عليها كما ثبت ذلك من حديث ابن عمر وعائشة وأم حبيبة وغيرهم، وهي أربع قبل الظهر تسليمتان قبل الظهر وثنتان بعد الظهر وثنتان بعد المغرب وثنتان بعد العشاء وثنتان قبل صلاة الصبح، هذه يقال لها: الرواتب، ويقال لها: النوافل المؤكدة، يقول ابن عمر: أنه حفظ من النبي ﷺ عشر ركعات: ثنتين قبل الظهر، وثنتين بعدها، وثنتين بعد المغرب، وثنتين بعد العشاء، وثنتين قبل صلاة الصبح، وثنتين بعد صلاة الجمعة في بيته، قال: فأما المغرب والعشاء والفجر والجمعة ففي بيته. وقالت عائشة رضي الله عنها: كان النبي ﷺ يصلي قبل الظهر أربعًا، كان لا يدع أربعًا قبل الظهر هذا مما حفظته عائشة وحفظته أم سلمة أيضًا، فدل ذلك على أن الأكمل أربع قبل الظهر وإن اقتصر على ثنتين كما قال ابن عمر كفى ذلك، ولكن الأفضل مثلما دل عليه حديث عائشة و أم حبيبة أنه يصلي أربعًا قبل الظهر تسليمتين فيكون الجميع ثنتي عشرة ركعة، هذا هو الكمال وهذا هو المحفوظ عن النبي ﷺ. وإن زاد على هذا فصلى بعد الظهر أربعًا بزيادة ثنتين بعد الظهر فهذا أيضًا مستحب، تقول أم حبيبة رضي الله عنها عن النبي ﷺ أنه قال: من صلى أربعًا قبل الظهر وأربعًا بعدها حرمه الله على النار وفي لفظ آخر: من حافظ على أربع قبل الظهر وأربع بعدها حرمه الله تعالى النار يعني: ثنتين ثنتين، كما في الحديث: صلاة اليل والنهار مثنى مثنى، وهكذا يستحب أن يصلي أربعًا قبل العصر وليست راتبة لكنها مستحبة، يقول النبي ﷺ: رحم الله امرأً صلى أربعاً قبل العصر. وهكذا يصلي ثنتين قبل المغرب بعد الأذان، وثنتين قبل العشاء بعد الأذان مستحبة أيضًا، يقول النبي ﷺ: بين كل أذانين صلاة.. بين كل أذانين صلاة.. بين كل أذانين صلاة ثم قال: لمن شاء ليعلم الناس أن هذا ليس بواجب ولكنه مستحب، فهذه هي مستحبات وليست رواتب ثنتين قبل المغرب وثنتين قبل العشاء أربع قبل العصر هذه مستحبة وليست راتبة؛ ثنتين بعد الظهر زيادة عن الراتبة تكون: أربع بعد الظهر مستحبة كما تقدم في الأحاديث. كذلك سنة الضحى مستحبة دائمًا ركعتان في الضحى يصلي ركعتين في الضحى هذه سنة مؤكدة، وكان النبي ﷺ أوصى بها جماعة من أصحابه سنة الضحى، وقال في حديث أبي ذر: يصبح على كل سلامى من الناس صدقة؛ فكل تسبيحة صدقة وكل تهليلة صدقة وكل تحميدة صدقة وكل تكبيرة صدقة وأمر بمعروف صدقة ونهي عن منكر صدقة، قال: ويكفي من ذلك ركعتان تركعهما من الضحى رواه مسلم في صحيحه. فدل ذلك على أهمية الركعتين وأنها تقوم مقام الصدقات التي على مفاصل الإنسان وقال أبو هريرة  وأبو الدرداء كل واحد منهم يقول: أوصاني رسول الله بصلاة الضحى وفي اللفظ الآخر: بركعتي الضحى قالت عائشة رضي الله عنها: كان الرسول ﷺ يصلي الضحى أربعًا ويزيد ما شاء الله. فالحاصل أن سنة الضحى سنة مؤكدة، الرسول ﷺ ربما فعلها وربما تركها لئلا يشق على أمته لكنه أوصى بها ووصيته آكد من فعله، فدل ذلك على أنها متأكدة في جميع الأيام من ارتفاع الشمس إلى وقوف الشمس، وإذا اشتد الضحى واشتدت الشمس يكون أفضل يقول النبي ﷺ: صلاة الأوابين حين ترمض الفصال يعني: حين يشتد الحر على أولاد الإبل، يعني في علو الضحى وفي شدة الضحى تكون أفضل، وإن صلاها بعد ارتفاع الشمس فلا بأس كفى.","link":"https://binbaz.org.sa/fatwas/18572/ما-السنن-الراتبة-والمستحبة-للصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_900/nour_90006.mp3","categories":["صلاة التطوع"]},{"id":19466,"question":"المستمع: أحمد حيدر من اليمن يقول: إذا دخلت المسجد بعد أذان الفجر، وصليت أربع ركعات، فقال لي بعض الناس: بأن ذلك لا يجوز إلا ركعتين، فهل هذا صحيح؟","title":"حكم الزيادة على الراتبة بعد أذان الفجر","answer":"الجواب: نعم، إذا دخلت تصلي ركعتي الفجر السنة فقط ويكفي، النبي ﷺ قال: لا صلاة بعد طلوع الفجر إلا ركعتي الفجر تصلي سنة الفجر ثنتين، ثم تجلس تنتظر الفريضة. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18714/حكم-الزيادة-على-الراتبة-بعد-اذان-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93908.mp3","categories":["صلاة التطوع"]},{"id":19483,"question":"هذا السائل ماهر، له مجموعة من الأسئلة يقول: في يوم الجمعة هل يصلي الإنسان الأربع الرواتب قبلها أي: الظهر والركعتين بعدها؟ أم يقتصر على ركعتين أو أربع بعد الجمعة، ويترك راتبتي الظهر يوم الجمعة دون سائر الأيام؟","title":"النوافل المشروعة قبل الجمعة وبعدها","answer":"الجواب: يوم الجمعة يصلي قبلها ما تيسر أربع وإلا ست وإلا ثمان وإلا عشر وإلا أكثر، النبي ﷺ ما حدد شيء قال:  صلى ما قدر له. أما بعدها فالسنة أن يصلي أربعًا تسليمتين، النبي عليه السلام قال: إذا صلى أحدكم الجمعة فليصل بعدها أربعًا يعني: تسليمتين. أما قبلها يقول ﷺ: ثم أتى المسجد فصلى ما قدر له صل ما تيسر قبلها ثنتين أو أربع تسليمتين أو ثلاث تسليمات، أو أربع تسليمات، أو خمس تسليمات أو أكثر ما في شيء محدود، والحمد لله. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18730/النوافل-المشروعة-قبل-الجمعة-وبعدها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93917.mp3","categories":["صلاة التطوع","صلاة الجمعة"]},{"id":19527,"question":"هذا سائل يقول يا سماحة الشيخ: أحمد المطيري يقول: هل يصح تأخير سنة العشاء مع الوتر إلى ما قبل صلاة الفجر؟","title":"حكم تأخير سنة العشاء إلى ما قبل الفجر","answer":"الجواب: الأحوط البدار بها قبل نصف الليل سنة العشاء؛ لأن وقت العشاء إلى نصف الليل، فالأحوط البدار بها قبل نصف الليل، وإن صلاها بعد نصف الليل فلا بأس؛ لأنه وقت ضرورة، لكن الأفضل البدار بها قبل نصف الليل. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18775/حكم-تاخير-سنة-العشاء-الى-ما-قبل-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93937.mp3","categories":["صلاة التطوع"]},{"id":19539,"question":"هل صلاة الاستخارة واجبة في كل شيء أم تترك في بعض الأحيان؟ وما حكم من يصلي صلاة الاستخارة في كل يوم إذا عزم على أمر معين؟","title":"حكم صلاة الاستخارة ومتى تشرع؟","answer":"الجواب: صلاة الاستخارة مستحبة عند الحاجة إليها، مستحبة عند الحاجة إليها، إذا هم بأمر وأشكل عليه هل هو رشد أم لا كزواج بفلانة أو سفر إلى فلان استخار ربه، فلا يفعلها إلا عند الحاجة.","link":"https://binbaz.org.sa/fatwas/18780/حكم-صلاة-الاستخارة-ومتى-تشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93941.mp3","categories":["صلاة التطوع"]},{"id":19577,"question":"يقول يا شيخ: هل هناك سنة للوضوء؟","title":"حكم سنة الوضوء","answer":"الجواب: إذا توضأ استحب له أن يصلي ركعتين سنة الوضوء، تسمى سنة الوضوء، في حديث عثمان  يقول ﷺ: إذا توضأ العبد فأحسن الوضوء، ثم صلى ركعتين لا يحدث فيهما نفسه؛ غفر له ما تقدم من ذنبه نعم.","link":"https://binbaz.org.sa/fatwas/18836/حكم-سنة-الوضوء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94902.mp3","categories":["صلاة التطوع"]},{"id":19672,"question":"يقول السائل: كم عدد صلاة الضحى؟ وهل هناك فرق بين صلاة الضحى وصلاة الشروق؟","title":"وقت صلاة الضحى وبيان عدد ركعاتها","answer":"الجواب: صلاة الشروق هي صلاة الضحى مبكرة، والأفضل عند شدة الضحى، أن تصلى حين ترمض الفصال حين يشتد الضحى، وليس لها عدد محصور أقلها ركعتان، وإن صلى أكثر فلا بأس، كان النبي ﷺ يصلي بعض الأحيان أربعًا، وربما صلى ثمان عليه الصلاة والسلام، وإن صلى أكثر فلا بأس. المقدم: حفظكم الله سماحة الشيخ.. الشيخ: لكن يسلم من كل ثنتين، السنة أن يسلم من كل ثنتين، مثنى مثنى. نعم.","link":"https://binbaz.org.sa/fatwas/18964/وقت-صلاة-الضحى-وبيان-عدد-ركعاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_950/nour_95025.mp3","categories":["صلاة التطوع"]}]
